function ciLayer(l,cut){
  const tf=l.t?` transform="${l.t}"`:'';
  if(l.grp)return`<g${tf}>${cut?l.grp.map(x=>ciLayer(x,1)).join(''):ciSVG(l.grp)}</g>`;
  if(l.g){
    const G=GI[l.g]||CI[l.g];if(!G)return'';
    const s=l.s||24,x=l.x||0,y=l.y||0,cx=x+s/2,cy=y+s/2;
    let inner,vb;
    if(CI[l.g]&&!GI[l.g]){vb='0 0 24 24';inner=cut?CI[l.g].map(z=>ciLayer(z,1)).join(''):ciSVG(CI[l.g])}
    else{vb=G[0];const w=parseFloat(vb.split(/\s+/)[2]);const sw=CUTW*2*w/s;inner=cut?`<g fill="#000" stroke="#000" stroke-width="${sw}" stroke-linejoin="round">${G[1]}</g>`:G[1]}
    return`<g transform="rotate(${l.r||0} ${cx} ${cy})"${tf}><svg x="${x}" y="${y}" width="${s}" height="${s}" viewBox="${vb}" overflow="visible">${inner}</svg></g>`;
  }
  if(l.sub&&!cut)return'';
  const st=l.st;
  if(cut)return`<path d="${l.p}"${tf} fill="${st?'none':'#000'}" stroke="#000" stroke-width="${(st||1.1)+(l.sub?0:CUTW*2)}" stroke-linecap="round" stroke-linejoin="round"/>`;
  const col=l.c||'currentColor';
  return`<path d="${l.p}"${tf} fill="${st?'none':col}" stroke="${col}" stroke-width="${st||1.1}" stroke-linecap="round" stroke-linejoin="round"/>`;
}
function ciSVG(L){
  let out='';
  for(const l of L){
    if(l.cut||l.sub){
      const id='m'+Math.random().toString(36).slice(2,9);
      out=`<mask id="${id}" maskUnits="userSpaceOnUse" x="-6" y="-6" width="36" height="36"><rect x="-6" y="-6" width="36" height="36" fill="#fff"/>${ciLayer({...l,cut:0},1)}</mask><g mask="url(#${id})">${out}</g>`;
    }
    if(!l.sub)out+=ciLayer(l,0);
  }
  return out;
}

