const domOn=()=>S&&S.house&&S.house.title>=2;
function ensureDom(){if(!domOn()){if(S&&S.house)delete S.house.dom;return null}if(!rules()&&!S.house.dom)S.house.dom={sat:58,tax:'normal',pol:[],built:{},riots:0};if(!rules())return S.house.dom;if(!S.house.dom)S.house.dom={sat:58,tax:'normal',pol:[],built:{},riots:0};return S.house.dom}
const domName=()=>S.house.title>=6?`${S.house.title===7?'Đế chế':'Vương quốc'} ${S.realm.replace(RPFX,'')}`:`Lãnh địa ${S.village}`;
const polSlots=()=>Math.max(1,S.house.title-1);
const domPop=()=>Math.round(POP[S.house.title]*(1+Object.keys(S.house.dom.built).length*.04));
function domCalc(){
  const D=S.house.dom,pop=domPop(),T=TAX[D.tax];
  let taxm=1,cost=0,ds=T.ds,guard=10+S.house.title*5;
  for(const k of D.pol){const P=POLICIES[k];taxm+=P.taxm||0;cost+=(P.cost||0)+Math.round((P.costp||0)*pop);ds+=P.ds||0;guard+=P.guard||0}
  for(const k in D.built){const B=BUILD[k];taxm+=B.taxm||0;ds+=B.ds||0;guard+=B.guard||0}
  const tax=Math.round(pop*T.r*taxm);
  let target=50+ds*2+Math.round((S.st.honor-50)/8);
  if(S.world&&S.world.cat)target-=15;
  if(S.flags.dark)target-=10;
  if(S.flags.saint||S.flags.legend)target+=8;
  return{pop,tax,cost,net:tax-cost,target:Math.max(0,Math.min(100,target)),guard:Math.min(100,guard)};
}
function satWord(v){return v<20?'Phẫn nộ':v<35?'Bất mãn':v<55?'Tạm chấp nhận':v<75?'Hài lòng':'Mến mộ'}
function domYear(){
  const D=ensureDom();if(!D)return 0;
  if(!rules()){D.sat=Math.round(Math.max(10,Math.min(95,D.sat+(60-D.sat)*.2+R(-4,4))));if(ch(.12))log(`${domName()} vẫn do ${holderName()} cai quản. Lòng dân: ${satWord(D.sat).toLowerCase()}.`);return 0}
  const c=domCalc();
  D.sat=Math.round(Math.max(0,Math.min(100,D.sat+(c.target-D.sat)*.35+R(-3,3))));
  for(const k of D.pol){const P=POLICIES[k];if(P.fx)mod(P.fx)}
  for(const k in D.built){const B=BUILD[k];if(B.fx)mod(B.fx);if(B.pres)S.house.prestige+=B.pres}
  S.house.prestige+=Math.round(D.sat/20);
  if(S.age<16){if(kdOn())return Math.round(TINC[S.house.title]/4);log(`Nhiếp chính cai quản ${domName()} thay bạn. Dân: ${satWord(D.sat).toLowerCase()} (${D.sat}).`);D.calm=0;return 0}
  log(`${domName()}: thu thuế ${c.tax} xu, chi chính sách ${c.cost} xu. Lòng dân: ${satWord(D.sat).toLowerCase()} (${D.sat}).`,D.sat<35?'bad':'');
  if(D.sat<35&&!S.pend.includes('domriot')){let p=(35-D.sat)/45*(1-c.guard/160);if(D.calm)p*=.4;if(ch(p))S.pend.push('domriot')}
  if(D.sat>=80&&ch(.2)){const g=Math.round(c.pop/100);S.money+=g;mod({honor:2});log(`Dân ${domName()} dâng lễ vật mừng tuổi bạn, trị giá ${g} xu.`,'good')}
  D.calm=0;
  return kdOn()?Math.round(TINC[S.house.title]/3):c.net;
}
function overthrow(){
  const D=S.house.dom,wasKing=S.house.title>=6;
  if(wasKing&&ch(.4)){die('bị dân nổi loạn kéo ra quảng trường xử tử');return['Đám đông phá cổng cung điện. Bạn bị kéo ra quảng trường.','bad']}
  const old=titleName(S.house.title,S.sex);
  S.house.title=0;S.flags.king=0;delete S.house.dom;S.own.manor=0;S.money=Math.floor(Math.max(S.money,0)/2);mod({honor:-20,happy:-15});
  addEnemy('Thủ lĩnh cuộc bạo loạn lật đổ bạn',{hate:R(60,80),cls:'serf'});
  announce('Bị lật đổ',`Dân chúng nổi dậy, tước bỏ danh hiệu ${old} của gia tộc ${S.house.name}. ${wasKing?'Bạn trốn khỏi kinh thành trong đêm, mang theo chút của cải.':'Lâu đài bị chiếm, đất phong bị chia cho dân.'}`,'banner');
  return[`Gia tộc ${S.house.name} mất tước ${old}.`,'bad'];
}
function domAct(a){
  const D=S.house.dom,c=domCalc();let t,tone='';
  if(a==='tour'){S.done.dtour=1;S.money-=10;D.sat=Math.min(100,D.sat+6);mod({honor:2,health:-2});t=`Bạn cưỡi ngựa đi khắp ${domName()}, ghé từng làng hỏi han dân tình.`;tone='good';if(ch(.2)){const g=R(20,60);S.money+=g;t+=` Bạn bắt quả tang một viên quản gia ăn chặn, thu lại ${g} xu.`}}
  if(a==='feast'){S.done.dfeast=1;const cost=Math.round(c.pop/100)*2;S.money-=cost;D.sat=Math.min(100,D.sat+10);mod({happy:4});t=`Bạn mở tiệc ba ngày cho toàn dân, tốn ${cost} xu. Rượu chảy như suối, dân reo hò tên bạn.`;tone='good'}
  if(a==='suppress'){S.done.dsup=1;D.calm=1;D.sat=Math.max(0,D.sat-4);mod({honor:-2});t='Lính tuần bắt giam những kẻ hay tụ tập kêu ca. Lãnh địa yên ắng hơn, nhưng dân nhìn bạn bằng ánh mắt khác.';tone='bad'}
  if(a.startsWith('tax:')){S.done.dtax=1;D.tax=a.slice(4);t=`Bạn ban lệnh đặt mức thuế ${TAX[D.tax].n.toLowerCase()}.`;tone=D.tax==='low'?'good':D.tax==='crush'?'bad':''}
  if(a.startsWith('pol:')){const k=a.slice(4),P=POLICIES[k];if(D.pol.includes(k)){D.pol=D.pol.filter(x=>x!==k);t=`Bạn bãi bỏ chính sách "${P.n}".`}else{S.done.dpol=1;D.pol.push(k);t=`Bạn ban hành chính sách "${P.n}".`;tone='good'}}
  if(a.startsWith('build:')){const k=a.slice(6),B=BUILD[k],cost=buildCost(k);S.money-=cost;D.built[k]=S.year;t=`Bạn cho xây ${B.n.toLowerCase()} với giá ${cost} xu.`;tone='good';S.house.prestige+=10}
  log(t,tone);note={t,tone};afterSheetAction();
}
const buildCost=k=>Math.round(BUILD[k].c*(S.house.title-1)*(S.house.dom.pol.includes('corvee')?.7:1));
