const BAGMAX=16;

let S=null,view=null,note=null,draft=null,sel=null;

function save(){try{localStorage.setItem(KEY,JSON.stringify(S));saveFailed=0}catch(e){saveFail()}}
function load(){try{const r=localStorage.getItem(KEY);return r?JSON.parse(r):null}catch(e){return null}}
function wipe(){try{localStorage.removeItem(KEY)}catch(e){}}

/* ---------- helpers ---------- */
function person(rel,sex,age,sur,race){race=race||(S&&S.race)||'human';const f=pick(nameList(sex,race));return{id:uid(),rel,sex,age,race,first:f,sur,name:f+' '+sur,alive:true,bond:R(45,85),d:0}}
function npc(kind,o={}){const sex=o.sex||pick(['m','f']),race=o.race||(ch(.7)&&!RACES[S.race].hidden?S.race:pick(RPUB())),cls=o.cls||pick(NPCLS),used=new Set([S.first,...S.fam.filter(x=>x.alive).map(x=>x.first),...(S.rel||[]).filter(x=>x.alive).map(x=>x.first)]),pool=nameList(sex,race).filter(n=>!used.has(n)),f=o.first&&!used.has(o.first)?o.first:pick(pool.length?pool:nameList(sex,race)),sur=o.sur||surFor(race,cls);return{id:uid(),kind,sex,race,cls,first:f,sur,name:f+' '+sur,age:o.age!=null?o.age:Math.max(4,S.age+R(-4,4)),bond:o.bond!=null?o.bond:R(40,70),hate:o.hate||0,alive:true,d:0,why:o.why||'',looks:o.looks||R(20,90)}}
const rels=k=>(S.rel||[]).filter(r=>r.alive&&r.kind===k);
const lover=()=>rels('lover')[0];
const canLove=()=>S.age>=15&&!spouse()&&!S.flags.saint&&!(S.job&&S.job.id==='church');
function addFriend(o){if(rels('friend').length>=8)return null;const r=npc('friend',o);S.rel.push(r);return r}
function addEnemy(why,o={}){const ex=o.id&&S.rel.find(x=>x.id===o.id);if(ex){ex.kind='enemy';ex.hate=Math.max(ex.hate,o.hate||R(45,75));ex.why=why;log(`${ex.name} trở thành kẻ thù của bạn.`,'bad');return ex}if(rels('enemy').length>=8)return null;const r=npc('enemy',{...o,why,hate:o.hate||R(45,75),age:o.age!=null?o.age:Math.max(14,S.age+R(-6,10))});S.rel.push(r);log(`${r.name} trở thành kẻ thù của bạn.`,'bad');return r}
function relYear(){
  for(const r of S.rel||[]){
    if(!r.alive)continue;r.age++;r.d=0;
    const a=r.age/lifeOf(r.race),d=a<40?.006:a<55?.025:a<65?.06:a<75?.14:.3;
    if(ch(d)){r.alive=false;if(r.kind==='enemy'){mod({happy:2});log(`Kẻ thù ${r.name} đã chết. Bạn thấy nhẹ nhõm lạ thường.`)}else{mod({happy:-Math.round(r.bond/8)});log(`${r.kind==='lover'?'Người yêu':'Bạn'} ${r.first} qua đời ở tuổi ${r.age}.`,'bad')}continue}
    if(r.kind==='friend'){r.bond-=R(0,4);if(r.bond<8){r.alive=false;r.gone=1;log(`Bạn và ${r.first} dần xa cách, không còn qua lại nữa.`)}else if(r.bond>=70&&ch(.08)){const g=R(5,25);S.money+=g;log(`${r.first} ghé thăm, mang theo ${g} xu và một giỏ táo.`,'good')}}
    if(r.kind==='lover'){r.bond-=R(1,5);if(r.bond<15){r.alive=false;r.gone=1;mod({happy:-8});log(`${r.first} chia tay bạn. Tình yêu đã nguội lạnh.`,'bad')}else if(r.bond>=85&&ch(.3)&&!S.pend.includes('loverask'))S.pend.push('loverask')}
    if(r.kind==='enemy'){r.hate-=R(0,3);if(r.hate<15){r.alive=false;r.gone=1;log(`Mối thù với ${r.first} đã nguôi ngoai theo năm tháng.`)}}
  }
  const es=rels('enemy').filter(e=>e.hate>=50);
  if(es.length&&S.age>=12&&!S.pend.includes('enemyact')){const e=pick(es);if(ch(.12+e.hate/600)){S.tmpE=e.id;S.tmpEA=pick(['rumor','arson','ambush',S.flags.her||S.flags.suspect?'accuse':'rumor']);S.pend.push('enemyact')}}
  if(S.rel.length>40)S.rel=S.rel.filter(r=>r.alive||r.kind==='enemy').slice(-40);
}
function spouse(){return S&&S.fam.find(p=>p.alive&&(p.rel==='Vợ'||p.rel==='Chồng'))}
function kids(alive=true){return S.fam.filter(p=>p.rel.startsWith('Con')&&!p.bast&&(!alive||p.alive))}
function mod(c){for(const k in c)if(S.st[k]!=null)S.st[k]=clamp(S.st[k]+c[k])}
function fine(n){if(S.money>0)S.money=Math.max(0,S.money-n)}
function entry(){S.log.push({age:S.age,year:S.year,items:[]});if(S.log.length>90)S.log.shift()}
function log(t,tone=''){S.log[S.log.length-1].items.push({t,tone})}
function die(cause){if(!S.alive)return;S.alive=false;S.cause=cause;S.pend=[];S.ann=[];log(`Bạn qua đời vì ${cause}.`,'bad')}
function healthCheck(){if(S.alive&&S.st.health<=0)die('vết thương và bệnh tật')}
function jt(){const j=S.job;if(!j||!JOBS[j.id])return'';const J=JOBS[j.id],L=(S.sex==='f'&&J.tf?J.tf:J.t);return L[Math.max(0,Math.min(j.rank,L.length-1))]}
function prefix(){const t=S.house.title,ru=rules();
  if(S.flags.dark)return t>=6&&ru?(S.sex==='m'?'Ma Vương ':'Ma Hậu '):'Hắc Ám '+(t>=2&&ru?titleName(t,S.sex)+' ':'');
  if(!ru&&t>=6)return firstInLine()&&S.sex==='m'?'Thái tử ':S.sex==='m'?'Hoàng tử ':'Công chúa ';
  if(ru&&t===7)return S.sex==='m'?'Hoàng đế ':'Nữ hoàng ';
  if(ru&&t===6)return S.flags.redpope?'Giáo chủ-vua ':S.sex==='m'?'Đức vua ':'Nữ hoàng ';
  if(ru&&t>=2)return titleName(t,S.sex)+' ';
  if(S.flags.saint)return'Thánh Nữ ';if(S.flags.knight)return S.sex==='m'?'Ngài ':'Phu nhân ';return''}
function roleOf(){
  if(!S.alive)return'đã khuất';
  if(S.house.title>=6&&rules())return S.house.title===7?(S.sex==='m'?'hoàng đế':'nữ hoàng đế'):S.sex==='m'?'quốc vương':'nữ vương';
  if(S.house.title>=6&&S.age>=6&&!S.job)return S.sex==='m'?(firstInLine()?'thái tử':'hoàng tử'):'công chúa';
  if(S.flags.saint)return'Thánh Nữ';
  if(S.ac&&S.ac.st==='student')return'học viên Tháp Bạc';
  if(S.kn&&!S.job)return knTitle().toLowerCase();
  if(S.job)return jt().toLowerCase();
  if(S.house.title>=2&&rules())return titleName(S.house.title,S.sex).toLowerCase();
  if(S.house.title>=2&&S.age>=6)return`con nhà ${TM[S.house.title].toLowerCase()}`;
  if(S.age<6)return'trẻ nhỏ';if(S.age<14)return'đứa trẻ';
  return CLASSES[S.cls].short.toLowerCase();
}
const hasItem=k=>S.bag.some(i=>i.k===k);
function gainItem(k){
  const I=ITEMS[k];
  if(S.bag.length>=BAGMAX){log(`Túi đồ đã đầy, bạn đành bỏ lại ${I.n.toLowerCase()}.`,'bad');return false}
  S.bag.push({id:uid(),k,origin:`Đời ${S.gen} · ${S.first} · năm ${S.year}`});
  if(I.now)mod(I.now);
  log(`Bạn có được bảo vật: ${I.n} (${RARE[I.r].toLowerCase()}).`,'item');return true;
}
function announce(title,sub,art,img){S.ann.push({title,sub,art,img})}
function grantTitle(r){
  if(!rules()){if(r>S.house.title){S.house.holder=null}else{if(r>(S.flags.ptitle||0)){S.flags.ptitle=r;log(`Bạn được phong tước ${titleName(r,S.sex)} riêng. Tước này sẽ truyền cho con cháu nhánh của bạn.`,'good')}return}}
  if(S.house.title>=r)return;
  S.house.title=r;S.cls='noble';S.house.prestige+=r*60;
  if(r>=6)S.flags.king=1;
  ensureDom();
  if(!hasItem('ring_sig'))gainItem('ring_sig');
  if(r>=6&&!hasItem('crown'))gainItem('crown');if(r>=5)ensureKd();
  const nm=titleName(r,S.sex);
  log(`Gia tộc ${S.house.name} được phong ${nm}. Tước vị sẽ truyền cho người thừa kế.`,'good');
  announce(r===7?'Đăng cơ Hoàng đế':r===6?'Đăng quang':'Phong tước',r>=6?`${S.first} ${S.surname} đội vương miện, trở thành ${nm} của ${S.realm}. Ngai vàng sẽ truyền cho con cháu gia tộc ${S.house.name}.`:`Gia tộc ${S.house.name} nay mang tước ${nm}, có đất phong và bổng lộc ${TINC[r]} xu mỗi năm. Tước vị được truyền lại cho đời sau.`,r>=6?'crown':'shield',r>=6?'coronation':'knighted');
}
function newHouse(sur,year){const c1=pick(TINCT.slice(0,7));return{name:sur,c1,c3:pick(TINCT.filter(c=>c!==c1)),div:pick(['plain','plain','pale','fess','chief','quarter']),c2:pick(METAL.slice(0,2)),charge:pick(CHARGES),motto:pick(MOTTOS),prestige:0,title:0,founded:year}}

/* ---------- new life ---------- */
function newLife(o){
  const cls=o.cls,sex=o.sex,race=o.race||'human',sur=(o.house||'').trim()||pick(SUR[cls]),by=(typeof COOP_BY!=='undefined'&&COOP_BY!=null)?COOP_BY:R(612,690);
  const st={};STATS.forEach(([k])=>st[k]=R(30,75));st.health=R(60,90);st.magic=R(5,40);
  for(const k in CLASSES[cls].st)st[k]=clamp(st[k]+CLASSES[cls].st[k]);
  for(const k in RACES[race].st)st[k]=clamp(st[k]+RACES[race].st[k]);
  S={v:4,first:o.name,surname:sur,name:o.name+' '+sur,sex,race,cls,by,age:0,year:by,realm:pick(REALMS),village:pick(VILL),st,money:0,own:{},job:null,fam:[],flags:{her:0},done:{},pend:[],ann:[],log:[],alive:true,gen:1,bag:[],tree:[],spHist:[],rel:[],house:newHouse(sur,by),hid:newTalents(race),world:{cat:null,last:by}};
  if(cls==='noble')S.house.title=2;if(cls==='royal'){S.cls='noble';S.house.title=6;S.flags.royalborn=1;S.house.prestige=300}
  const fa=person('Cha','m',R(20,42),sur,race),mo=person('Mẹ','f',R(17,36),sur,race);
  S.fam.push(fa,mo);if(S.house.title>=2)S.house.holder=fa.id;S.roots=`${fa.name} và ${mo.name}`;
  const n=R(0,3);
  for(let i=0;i<n;i++){const s=pick(['m','f']);S.fam.push(person(s==='m'?'Anh trai':'Chị gái',s,R(1,10),sur,race))}
  entry();
  log(`Bạn chào đời ở làng ${S.village}, ${S.realm}, năm ${by}.`);
  log(`Cha bạn là ${fa.first}, mẹ bạn là ${mo.first}. ${CLASSES[cls].born}`);
  if(S.house.title>=2)log(cls==='royal'?`Cha bạn là ${titleName(6,'m')} của ${S.realm}. Theo luật trưởng nam, ngai vàng sẽ truyền cho người con trai lớn nhất.`:`Cha bạn là ${titleName(S.house.title,'m')}, cai quản ${domName()}. Đất đai truyền cho trưởng nam.`,'good');
  const rl={elf:'Bạn mang dòng máu Tiên tộc: đôi tai nhọn và đôi mắt sáng như sương sớm. Bạn sẽ sống lâu hơn mọi người quanh mình.',dwarf:'Bạn là Người lùn, nặng gấp đôi một đứa bé loài người khi chào đời. Bà đỡ bảo bạn khỏe như con bê.',fiend:'Trên trán bạn nhú hai chiếc sừng nhỏ. Bà đỡ làm dấu thánh rồi vội vã bỏ đi.',orc:'Bạn chào đời với hai chiếc nanh nhỏ và tiếng khóc làm rung cả mái nhà. Người làng nhìn gia đình bạn bằng ánh mắt e dè.',beast:`Bạn sinh ra với ${pick(['đôi tai sói','đôi tai cáo đỏ','những vằn hổ trên lưng','đôi sừng nai non'])}. Bà đỡ bảo đó là dấu của các thần rừng cổ.`}[race];
  if(rl)log(rl,'magic');
  if(sex==='f'&&race==='human'&&ch(.2)){S.flags.blessed=1;log('Bạn chào đời đúng lúc chuông nhà thờ đổ chín tiếng dù không ai kéo. Bà đỡ bảo đó là dấu thánh.','magic')}
  if(n)log(`Bạn có ${n} anh chị trong nhà.`);
  log(`Gia tộc ${sur} lấy câu "${S.house.motto}" làm châm ngôn.`);
  save();render();
}

/* ---------- yearly cycle ---------- */
function ageUp(){
  if(!S||!S.alive||S.pend.length||S.ann.length)return;
  S.age++;S.year=S.by+S.age;S.done={};S.cands=null;S.flirtC=null;S.tmp=null;
  entry();
  const a=S.age,ea=a/lifeOf(S.race);
  mod({health:ea<16?R(0,2):ea<30?R(-1,1):ea<50?-R(0,2):ea<65?-R(1,4):-R(2,6)});
  if(ea>=40)mod({looks:-R(0,2)});
  for(const it of eqItems()){const I=ITEMS[it.k];if(I&&I.fx)mod(I.fx)}
  if(S.flags.were){mod({health:3,happy:-2});if(ch(.3))log('Đêm trăng tròn, bạn lại thức dậy giữa rừng, áo quần rách tả tơi và miệng đầy vị máu thỏ.','magic');S.flags.suspect=(S.flags.suspect||0)+1}
  if(S.own.dragon){mod({honor:1});if(ch(.35))log(pick(['Con rồng của bạn đã lớn bằng con ngựa và hay đốt nhầm đống rơm nhà hàng xóm.','Con rồng nằm cuộn tròn trên mái nhà sưởi nắng. Trẻ con cả làng kéo đến xem.','Con rồng tha về một con cừu béo. Không ai dám hỏi nó lấy ở đâu.']),'magic')}
  if(a===7)log(S.cls==='noble'?'Bạn bắt đầu học cưỡi ngựa và múa kiếm gỗ.':'Bạn bắt đầu phụ việc nhà: nhặt củi, đuổi quạ, cho lợn ăn.');
  if(a===12)log('Bạn đã đủ tuổi đi làm và phải chịu trách nhiệm trước tòa án trang viên.');
  if(a===16){const e=CLASSES[S.cls].money;const g=e?e+R(0,Math.round(e/2)):R(2,6);S.money+=g;log(`Bạn đã trưởng thành. Gia đình trao cho bạn ${g} xu để tự lập.`,'good')}
  if(lifeOf(S.race)>1&&a===Math.round(16*lifeOf(S.race))&&a!==16)log('Bạn bây giờ mới thực sự trưởng thành theo tuổi của tộc mình, trong khi bạn bè thuở nhỏ đã lên chức ông bà.','magic');
  economy();
  if(S.alive){famYear();relYear();extYear();extYear2();extYear3();S.house.prestige+=Math.max(0,Math.round(S.st.honor/25))+S.house.title*3;deathRoll()}
  if(a===6&&S.hid.arcane>=80)log('Đom đóm bay theo bạn mỗi tối. Nước giếng gợn sóng khi bạn cúi xuống nhìn.','magic');
  if(a===9&&S.hid.sword>=80)log('Bạn cầm cành cây vung một đường, lũ trẻ trong làng im bặt. Ông lão gác cổng nhìn bạn rất lâu.','magic');
  if(S.alive){worldYear();rollEvents();flavorYear();cohereYearEvents()}
  save();render();
  if(!S.alive)showDeath();else showNext();
}
function worldYear(){
  const w=S.world;
  if(!w.cat){if(S.age>=1&&S.year-w.last>=8&&ch(.06))startCat(pick(Object.keys(CATS)));return}
  if(w.cat.id==='player'){if(S.flags.dark){S.pend.push('darkyear');if(S.year-w.cat.y>=3&&ch(.35))S.pend.push('herocomes')}else if(S.flags.hcat){S.pend.push('hryear');if(S.year-w.cat.y>=2&&ch(.35))S.pend.push('hrhero')}else{S.world.cat=null;S.world.last=S.year}return}
  const yrs=S.year-w.cat.y;
  if(S.flags.hero&&S.flags.hero.cat===w.cat.y){S.fight=null;S.pend.push(S.flags.hero.train>0?'herotrain':'herobattle');return}
  if((yrs>=2&&ch(.22))||yrs>=8){endCat();return}
  if(w.cat.id==='heresy'&&S.flags.her>0){S.pend.push('heryear');return}
  if(heroEligible2()&&!S.flags['call'+w.cat.y])S.pend.push(S.flags.legend?'herorecall':'callhero');
  else S.pend.push(w.cat.id==='plague'?'plague':'catyear');
}
function startCat(id){
  S.world.cat={id,y:S.year};const C=CATS[id];
  announce('Thảm Họa: '+C.n,C.start,C.art,CATIMG[id]);
  log(`THẢM HỌA · ${C.n}. ${C.start}`,'bad');
  if(id==='heresy'&&S.flags.her>0){S.pend.push('herreveal');return}
  if(heroEligible2())S.pend.push(S.flags.legend?'herorecall':'callhero');
}
function endCat(){
  const C=CATS[S.world.cat.id],hero=pick(MN)+' '+pick(['Mắt Ưng','Tóc Bạc','xứ '+pick(VILL),'Người Mang Ánh Sáng']);
  announce('Thảm Họa chấm dứt',`Anh hùng ${hero} đã đánh bại ${C.boss}. Cả ${S.realm} mở hội ăn mừng suốt bảy ngày.`,'sword');
  log(`${C.n} đã chấm dứt nhờ anh hùng ${hero}.`,'good');
  S.world.cat=null;S.world.last=S.year;S.flags.hero=null;
}
function heroPower(){let p=S.hid.sword*.45+S.hid.arcane*.45+S.st.health*.25+S.st.magic*.25;p+=cbB()*.6;for(const[k,b]of[['tome',5],['starstaff',15],['holy_sword',5]])if(hasItem(k))p+=b;if(S.own.dragon)p+=10;return p}
function heroWin(sac){
  S.flags.legY=S.year;S.flags.cruB=0;
  const C=CATS[S.world.cat.id],it=S.hid.sword>=S.hid.arcane?'lightsword':'starstaff';
  if(S.world.cat.id==='dragon'&&!hasItem('h_dragon'))gainItem('h_dragon');
  S.flags.legend=1;S.house.prestige+=500;mod({honor:30,happy:20});
  if(!hasItem(it))gainItem(it);
  if(!hasItem('arm_holy'))gainItem('arm_holy');
  S.world.cat=null;S.world.last=S.year;S.flags.hero=null;
  grantTitle(Math.max(5,Math.min(6,S.house.title+1)));
  announce('Anh Hùng Trong Lời Tiên Tri',`${S.first} ${S.surname} đã ${sac?'hy sinh để phong ấn':'đánh bại'} ${C.boss}. Tên người được khắc lên cổng mọi thành trì của ${S.realm}, và gia tộc ${S.house.name} được ban tước cao quý.`,'sword','prophets');
}
const BOSSHP={demon:4,dragon:4,undead:3,heresy:3,plague:3};
const BOSSMOVE={demon:['triệu hồi một cơn mưa lửa địa ngục','vung lưỡi hái xương to bằng cột nhà','gầm lên khiến mặt đất nứt toác'],dragon:['phun một luồng lửa trắng','quật chiếc đuôi gai khổng lồ','vỗ cánh tạo cơn bão tro'],undead:['gọi xác sống trồi lên quanh chân bạn','phóng ra một luồng gió băng tử khí','vung thanh kiếm gỉ máu'],heresy:['niệm chú khiến máu bạn sôi lên','sai các tín đồ cuồng tín lao vào bạn','phóng ra một ngọn giáo trăng đỏ'],plague:['phun ra đám mây côn trùng độc','ném vạc thuốc độc sủi bọt','gọi bầy chuột đen tràn tới']};
function fightBase(){return Math.max(.12,Math.min(.56,.2+(heroPower()-100)/240+(S.flags.cruB||0)))}
function bossHit(lo,hi){const C=CATS[S.world.cat.id];const d=R(lo,hi);mod({health:-d});const m=pick(BOSSMOVE[S.world.cat.id]||['tấn công']);if(S.st.health<=0){die('trong trận chiến với '+C.boss);return` ${C.boss} ${m}. Bạn gục xuống, không đứng dậy được nữa.`}return` ${C.boss} ${m}, bạn mất ${d} sức khỏe.`}
function fightRound(kind){
  const F=S.fight,C=CATS[S.world.cat.id];F.round++;let p=fightBase()+(F.bonus||0);F.bonus=0;let t,tone='';
  if(kind==='blade')p+=(S.blade||0)/400+cbB()/400;
  if(kind==='spell'){p+=S.hid.arcane/400+S.st.magic/500;mod({magic:-8})}
  if(kind==='allin')p+=.08;
  if(ch(p)){F.hp-=kind==='allin'?F.hp:1;F.last='hit';
    t=kind==='spell'?pick([`Ngọn lửa sao trong tay bạn xuyên thủng lớp giáp của ${C.boss}.`,`Câu thần chú của bạn trói chặt ${C.boss} trong xích ánh sáng.`]):kind==='allin'?`Bạn dồn hết sức vào một nhát duy nhất. Lưỡi kiếm xuyên thẳng vào tim ${C.boss}.`:pick([`Lưỡi kiếm của bạn chém trúng ${C.boss}, máu đen phun ra.`,`Bạn lách qua đòn đánh và đâm sâu vào sườn ${C.boss}.`]);tone='good';
    if(F.hp<=0){S.fight=null;heroWin(false);return[t+` ${C.boss} gục ngã. Bóng tối tan đi như sương sớm.`,'good']}
    t+=` ${C.boss} còn ${F.hp}/${F.max} sinh lực.`;if(ch(.3))t+=bossHit(4,9);
  }else{F.last='miss';
    t=kind==='spell'?'Câu thần chú vỡ tan giữa không trung.':kind==='allin'?'Bạn lao tới nhưng đâm vào khoảng không.':pick(['Đòn đâm trượt! Lưỡi kiếm chỉ sượt qua lớp vảy.','Bạn chém hụt, mất thăng bằng.']);tone='bad';
    t+=kind==='allin'?bossHit(22,34):bossHit(10,20);
  }
  if(S.alive&&S.fight)S.pend.push('herofight');
  return[t,tone];
}
function heroFight(mode){
  const C=CATS[S.world.cat.id];
  let p=(heroPower()+(mode?S.st.smarts*.2:S.st.health*.1)-60)/100+.3;p=Math.max(.1,Math.min(.92,p));
  if(ch(p)){heroWin(false);return[`Sau ba ngày ba đêm giao chiến, ${C.boss} gục ngã. Bóng tối tan đi như sương sớm.`,'good']}
  if(ch(.4)){die('trong trận chiến với '+C.boss);return[`${C.boss} quá mạnh. Bạn ngã xuống, nhưng tên bạn sẽ được nhớ đến.`,'bad']}
  mod({health:-30});S.flags.hero.train=1;return['Bạn bị đánh bại và được đồng đội kéo ra khỏi chiến trường. Sau một năm hồi phục và luyện tập, bạn sẽ thử lại.','bad'];
}
function economy(){
  let inc=0;
  if(S.job){
    const J=JOBS[S.job.id];S.job.yr++;S.job.ry++;
    let p=J.pay[S.job.rank];
    if(J.vol){const m=Math.random()*1.6+.2;p=Math.round(p*m);if(m<.5)log('Một chuyến hàng bị cướp trên đường, năm nay buôn bán thua lỗ.','bad')}
    inc+=p;mod(J.fx);if(J.yr)J.yr(S);
    if(J.risk&&ch(J.risk)){if(ch(.15)){die(J.riskDie);return}mod({health:-R(10,25)});log(pick(J.riskMsg),'bad')}
    if(S.job.id==='mission'){const n=R(3,25)*(S.job.rank+1);S.flags.conv=(S.flags.conv||0)+n;S.house.prestige+=4;log(`Bạn rửa tội cho ${n} người ngoại đạo năm nay.`)}
    promote();
    S.job.perf=Math.max(0,(S.job.perf||40)-10);
  }
  for(const k in S.own){inc+=((ASSETS[k]&&ASSETS[k].inc)||0)*S.own[k]}
  if(domOn()){inc+=domYear();if(S.age>=16)mod({honor:1})}
  if(S.flags.saint){inc+=60;mod({piety:2,honor:2});S.house.prestige+=10}
  inc+=extIncome()+extIncome2();
  if(S.age>=16){
    const young=S.fam.filter(p=>p.alive&&p.rel.startsWith('Con')&&p.age<14).length;
    const cost=S.job&&S.job.id==='church'?0:5+(spouse()?3:0)+young*2+(S.cls==='noble'?25+S.house.title*15:S.cls==='merchant'?8:0);
    const tithe=Math.floor(inc/10);
    S.money+=inc-cost-tithe;
    if(inc>0)log(`Thu ${inc} xu, chi tiêu ${cost} xu, nộp thuế thập phân ${tithe} xu cho nhà thờ.`);
    if(S.money<0){mod({happy:-6,honor:-4});if(!S.flags.debtY||S.year-S.flags.debtY>=4){S.flags.debtY=S.year;log(pick(['Bạn đang mắc nợ người cho vay. Hàng xóm bắt đầu bàn tán.','Người cho vay lại đến gõ cửa đòi nợ.','Nợ nần chồng chất, bạn phải bán bớt đồ đạc trong nhà.']),'bad')}}
  }else if(inc){S.money+=inc;log(`Bạn kiếm được ${inc} xu.`)}
}
function promote(){
  const j=S.job,J=JOBS[j.id];
  if(j.rank>=J.t.length-1||j.ry<J.need[j.rank])return;
  if(J.gate){const g=J.gate(S,j.rank);if(g!==true){if(g)log(g,'bad');return}}
  if(!((J.sure&&J.sure[j.rank])||ch(.3+(j.perf||40)/200)))return;
  j.rank++;j.ry=0;mod({happy:6});log(`Bạn được thăng lên ${jt()}.`,'good');
  if(j.rank===J.t.length-1&&J.top)J.top(S);
  if(j.id==='knight'&&j.rank===2){S.flags.knight=1;mod({honor:15});log('Lãnh chúa đặt lưỡi kiếm lên vai bạn. Từ nay người ta gọi bạn là Ngài.','good')}
  if((j.id==='church'||j.id==='wizard')&&j.rank>=1)S.flags.literate=1;
  if(j.id==='mission'&&j.rank===2)announce('Giám mục truyền giáo',`Sau ${j.yr} năm rao giảng nơi rừng sâu, ${S.first} được Đức Thánh Tọa phong làm Giám mục truyền giáo.`,'cross');
}
function famYear(){
  for(const p of S.fam){
    if(!p.alive)continue;
    p.age++;p.d=0;p.bond=Math.max(0,p.bond-R(0,3));
    const a=p.age/lifeOf(p.race),d=a<5?.03:a<40?.008:a<55?.03:a<65?.07:a<75?.15:.3;
    if(ch(d)){
      p.alive=false;mod({happy:-Math.round(p.bond/5)});
      log(`${p.rel} ${p.first} qua đời ở tuổi ${p.age}.`,'bad');
      if((p.rel==='Cha'||p.rel==='Mẹ')&&S.age>=16){const g=Math.round(CLASSES[S.cls].money/4)+R(0,10);S.money+=g;log(`Bạn được thừa kế ${g} xu.`)}
    }
  }
}
function deathRoll(){
  const a=S.age/lifeOf(S.race);let d=a<5?.01:a<40?.003:a<55?.015:a<65?.05:a<75?.12:.25;
  if(S.st.health<15)d+=.12;if(S.st.health<=0)d=1;
  if(ch(d))die(a<10?'sốt cao':a>=60?'tuổi già':pick(['bệnh lao','kiết lỵ','nhiễm trùng vết thương','sốt rét đầm lầy']));
}
