function flavorYear(){
  if(!S.seenF)S.seenF=[];
  if(S.age>3&&!ch(.75))return;
  const pool=FLAV.filter(f=>!S.seenF.includes(f[0])&&f[1](S));
  if(!pool.length)return;
  const f=pick(pool);S.seenF.push(f[0]);
  log(typeof f[2]==='function'?f[2](S):f[2],'');if(f[3])mod(f[3]);
}

function rollEvents(){
  if(S.age<1)return;
  if(!S.evLast)S.evLast={};
  const el=EV.filter(e=>!e.queued&&acOK(e)&&(!e.c||e.c(S))&&!(S.evLast[e.id]!=null&&S.year-S.evLast[e.id]<(e.cd||(e.auto?12:6))));
  const chosen=el.filter(e=>e.force&&e.force(S));
  let pool=el.filter(e=>!chosen.includes(e));
  const r=Math.random();let n=r<.3?0:r<.85?1:2;
  while(n-->0&&pool.length){
    const tot=pool.reduce((a,e)=>a+e.w(S),0);let x=Math.random()*tot,i=0;
    for(;i<pool.length;i++){x-=pool[i].w(S);if(x<=0)break}
    const e=pool[Math.min(i,pool.length-1)];chosen.push(e);pool=pool.filter(z=>z!==e&&!(e.nui&&z.nui));
  }
  for(const e of chosen){
    if(!S.alive)break;
    S.evLast[e.id]=S.year;
    if(e.auto){const[t,tone]=arr(e.f(S));log(t,tone);healthCheck()}else S.pend.push(e.id);
  }
}

/* ---------- events ---------- */
function plagueHit(p,intro){
  const lost=[];
  for(const m of S.fam)if(m.alive&&ch(.28)){m.alive=false;lost.push(`${m.rel.toLowerCase()} ${m.first}`)}
  let t=intro+' ';
  if(lost.length){t+=`Dịch bệnh cướp đi ${lost.join(', ')}. `;mod({happy:-10*lost.length})}
  if(ch(p)){mod({health:-R(35,60)});if(S.st.health<=10||ch(.45)){die('dịch hạch');return[t+'Những hạch đen nổi lên dưới cánh tay. Bạn không qua khỏi.','bad']}return[t+'Bạn sốt mê man ba tuần nhưng rồi qua khỏi.','bad']}
  return[t+'Bạn sống sót mà không hề nhiễm bệnh.',lost.length?'bad':'good'];
}
function cand(){
  const sex=S.sex==='m'?'f':'m',rk=CLASSES[S.cls].rk;
  const crk=Math.max(0,Math.min(3,rk+pick([-1,0,0,0,1])));
  const cls=Object.keys(CLASSES).find(k=>CLASSES[k].rk===crk);
  const race=ch(.75)&&!RACES[S.race].hidden?S.race:pick(RPUB());
  const f=pick(nameList(sex,race)),sur=surFor(race,cls);
  return{sex,cls,race,first:f,sur,name:f+' '+sur,age:Math.max(14,S.age+R(-5,S.sex==='m'?2:8)),looks:R(20,90),dowry:sex==='f'?Math.round(CLASSES[cls].money/3)+R(2,15):0};
}
function marry(c){
  const p={id:uid(),rel:c.sex==='m'?'Chồng':'Vợ',sex:c.sex,age:c.age,race:c.race||S.race,first:c.first,sur:c.sur,name:c.name,alive:true,bond:R(55,85),d:0};
  S.fam.push(p);S.spHist.push(c.name);mod({happy:R(8,14)});
  let t=`Bạn thành hôn với ${c.name} trước cửa nhà thờ.`;
  if(c.dowry){S.money+=c.dowry;t+=` Nhà ${c.sex==='f'?'gái':'trai'} mang sang ${c.dowry} xu của hồi môn.`}
  return t;
}
