const ACCS=['sc_royal','sc_crystal','sc_moon','rg_ruby','rg_emerald','rg_arcane','br_gold','br_beads','br_rune'];
const MERPOOL=[['map',60],['gem',90],['flower',350],['elixir',260],['tome',220],['amulet',30],['sc_royal',300],['sc_crystal',320],['sc_moon',520],['rg_ruby',120],['rg_emerald',210],['rg_arcane',230],['br_gold',110],['br_beads',80],['br_rune',190]];
function merStock(){
  if(!S.mer||S.mer.y!==S.year){
    const acc=MERPOOL.filter(x=>ACCS.includes(x[0])),oth=MERPOOL.filter(x=>!ACCS.includes(x[0]));
    const sh=a=>a.slice().sort(()=>Math.random()-.5);
    const pickd=[...sh(acc).slice(0,R(3,4)),...sh(oth).slice(0,R(2,3))];
    S.mer={y:S.year,from:pick(['xứ Cát Vàng','quần đảo Ngọc Trai','đế chế phương Đông','vùng Băng Giá','sa mạc Gió Đỏ','thành Vạn Đèn']),items:pickd.map(([k,p])=>[k,Math.round(p*(.75+Math.random()*.6))])};
  }
  return S.mer;
}
/* --- titles & succession --- */
const rules=()=>!S.house.holder;
function holderP(){const h=S.house.holder;return h?S.fam.find(p=>p.id===h&&p.alive):null}
const SIBREL=/^(Anh trai|Em trai|Chị gái|Em gái)$/;
function lineOrder(){
  const me={id:'me',sex:S.sex,age:S.age,first:S.first,rel:'Bạn'};
  return[...S.fam.filter(p=>p.alive&&SIBREL.test(p.rel)),me].sort((a,b)=>a.sex===b.sex?b.age-a.age:(a.sex==='m'?-1:1));
}
const firstInLine=()=>!rules()&&lineOrder()[0].id==='me';
function succeed(dead){
  if(S.house.title<2)return;
  const L=lineOrder(),h=L[0],nm=titleName(S.house.title,h.sex===S.sex?S.sex:h.sex);
  if(h.id==='me'){
    S.house.holder=null;ensureDom();
    const mo=S.fam.find(p=>p.alive&&p.rel==='Mẹ'),reg=S.age<16?(mo?` Vì bạn còn nhỏ, mẹ ${mo.first} làm nhiếp chính.`:' Vì bạn còn nhỏ, một đại thần làm nhiếp chính cho đến khi bạn trưởng thành.'):'';
    log(`Theo luật trưởng nam, tước ${titleName(S.house.title,S.sex)} và đất đai của gia tộc truyền cho bạn.${reg}`,'good');
    announce(S.house.title>=6?'Tân vương đăng cơ':'Kế thừa tước vị',`${dead?dead+' qua đời. ':''}${S.first} ${S.surname} kế thừa ${S.house.title>=6?'ngai vàng '+S.realm:'tước '+titleName(S.house.title,S.sex)+' và '+domName()}.${reg}`,S.house.title>=6?'crown':'shield',S.house.title>=6?'coronation':'knighted');
  }else{
    S.house.holder=h.id;
    log(`${h.rel} ${h.first} kế thừa tước ${titleName(S.house.title,h.sex)} của gia tộc.${S.house.title>=6?' Bạn vẫn là thành viên hoàng tộc.':''}`,'');
  }
}
function holderCheck(){if(S.house.title>=2&&S.house.holder&&!holderP())succeed()}
function holderName(){const h=holderP();return h?`${h.rel.toLowerCase()} ${h.first}`:'người đứng đầu gia tộc'}
const vip=s=>!!(s.flags.saint||s.flags.legend||s.flags.hero||s.house.title>=2||s.flags.dark||s.flags.hcat);
const dsat=n=>{if(S.house.dom)S.house.dom.sat=Math.max(0,Math.min(100,S.house.dom.sat+n))};

/* ===== heresy: cult management, reveal, heresy catastrophe ===== */
function ensureCult(){if(!(S.flags.her>=2||S.flags.hcat))return null;if(!S.cult)S.cult={fol:R(60,140),sec:70,cells:1,zeal:20};return S.cult}
function herRank(){
  if(S.flags.her===1&&S.flags.herxp>=3){S.flags.her=2;if(!hasItem('dagger'))gainItem('dagger');ensureCult();log('Bạn được phong Pháp sư bóng tối, giờ có thể điều hành một chi hội Hồng Nguyệt.','magic')}
  if(S.flags.her===2&&S.flags.herxp>=8){S.flags.her=3;if(!hasItem('h_raven'))gainItem('h_raven');announce('Đại tư tế Hồng Nguyệt',`Giáo phái Hồng Nguyệt tôn ${S.first} làm Đại tư tế. Hàng nghìn tín đồ bí mật khắp ${S.realm} chờ lệnh người.`,'moon')}
}
function cultYear(){
  const C=ensureCult();if(!C)return;
  C.fol+=C.cells*R(10,30)+(S.world.cat&&S.world.cat.id==='heresy'?R(50,150):0);C.sec=Math.max(0,C.sec-R(1,4));
  if(C.sec<30&&ch((30-C.sec)/60)&&!S.pend.includes('inq')&&!S.flags.hcat)S.pend.push('inq');
}
const CULTA={
  preach:{n:'Truyền đạo bí mật',ic:'night',d:'Tín đồ tăng · bí mật giảm',f:C=>{const g=Math.round(R(40,110)*(1+C.cells*.3)*(1+S.st.smarts/200));C.fol+=g;C.sec=Math.max(0,C.sec-R(3,8));S.flags.herxp=(S.flags.herxp||0)+1;return[`Bạn giảng về Mặt Trăng Đỏ trong những căn hầm rượu. ${g} người mới thề trung thành.`,'magic']}},
  tithe:{n:'Thu tiền dâng cúng',ic:'coins',d:'Tiền tăng theo số tín đồ',f:C=>{const g=Math.round(C.fol/18);S.money+=g;C.sec=Math.max(0,C.sec-2);return[`Các tín đồ lén dâng ${g} xu vào hòm gỗ dưới bàn thờ đá.`,'good']}},
  cell:{n:'Lập chi hội ở làng mới',ic:'house-02',d:'60 xu · tín đồ tăng đều mỗi năm',cost:60,f:C=>{S.money-=60;C.cells++;C.fol+=R(20,50);return[`Một chi hội Hồng Nguyệt mới bí mật nhóm họp ở làng ${pick(VILL.filter(v=>v!==S.village))}. Giáo phái có ${C.cells} chi hội.`,'magic']}},
  purge:{n:'Thanh trừng kẻ phản bội',ic:'dagger',d:'Bí mật tăng mạnh · danh dự giảm',f:C=>{C.sec=Math.min(100,C.sec+R(12,20));C.fol=Math.max(0,C.fol-R(5,20));mod({honor:-4,piety:-3});return['Hai kẻ định tố giác giáo phái biến mất trong đêm. Những kẻ còn lại hiểu bài học.','bad']}},
  bribe:{n:'Mua chuộc quan tòa',ic:'sack',d:'80 xu · bí mật tăng',cost:80,f:C=>{S.money-=80;C.sec=Math.min(100,C.sec+R(15,25));S.flags.suspect=Math.max(0,(S.flags.suspect||0)-2);return'Viên quan tòa nhận túi bạc và xé bỏ ba lá đơn tố cáo.'}},
  zeal:{n:'Huấn luyện tín đồ cuồng tín',ic:'w-spear',d:'50 xu · sức mạnh khi bạo động',cost:50,f:C=>{S.money-=50;C.zeal=Math.min(100,C.zeal+R(8,14));return'Các tín đồ trẻ tập giáo mác dưới ánh trăng, hô vang tên Mặt Trăng Đỏ.'}}
};
function cultAct(k){const C=ensureCult(),A=CULTA[k];S.done['c_'+k]=1;const[t,tone]=arr(A.f(C));herRank();log(t,tone);note={t,tone};afterSheetAction()}
function riseUp(){
  const C=ensureCult();S.done.c_rise=1;
  S.flags.hcat=1;S.flags.revealed=1;S.world.cat={id:'player',y:S.year,kind:'heresy'};
  if(S.job&&['church','mission','scribe','knight','lady'].includes(S.job.id))S.job=null;
  mod({honor:-20,piety:-20,magic:10});
  announce('Thảm Họa: Dị giáo của '+S.first,`Đêm trăng đỏ, ${C.fol.toLocaleString('vi-VN')} tín đồ Hồng Nguyệt đồng loạt cầm đuốc nổi dậy theo hiệu lệnh của ${S.first} ${S.surname}. Nhà thờ khắp ${S.realm} bốc cháy. Từ nay, chính bạn là Thảm Họa.`,'moon','inquisition');
  log(`THẢM HỌA · ${S.first} phát động cuộc bạo động Hồng Nguyệt.`,'bad');
  afterSheetAction();
}
function heroNpcFight(bonus){return ch(.3+S.st.magic/350+S.hid.arcane/400+(S.blade||0)/500+cbB()/300+(bonus||0))}
const HERESY_EV=[
 {id:'herreveal',queued:true,big:true,art:'moon',c:s=>s.flags.her>0&&s.world.cat&&s.world.cat.id==='heresy',title:'Lộ diện thân thế',
  text:s=>`Giáo phái Hồng Nguyệt đã công khai nổi dậy. Không ai trong làng biết bạn là ${HER[s.flags.her]}. Các tín đồ đang chờ xem bạn sẽ đứng ở đâu.`,
  ch:[{t:'Lộ diện, đứng lên cùng Hồng Nguyệt',f:s=>{s.flags.revealed=1;s.flags.herxp=(s.flags.herxp||0)+3;mod({honor:-10,magic:5});if(s.job&&['church','mission'].includes(s.job.id))s.job=null;
      if(s.flags.her>=3){ensureCult();s.cult.fol+=R(800,1500);s.flags.hcat=1;s.world.cat={id:'player',y:s.year,kind:'heresy'};announce('Giáo chủ lộ diện',`${s.first} ${s.surname} bước ra trước đám đông, khoác áo choàng đỏ của Đại tư tế. Cuộc nổi loạn Hồng Nguyệt giờ mang tên bạn.`,'moon','inquisition');return['Hàng nghìn tín đồ quỳ xuống khi bạn bước ra.','magic']}
      herRank();return[`Bạn công khai thân phận ${HER[s.flags.her]}. Các tín đồ reo hò, còn hàng xóm đóng sầm cửa trước mặt bạn.`,'magic']}},
      {t:'Tiếp tục ẩn mình',f:s=>{s.flags.suspect=(s.flags.suspect||0)+1;return'Bạn vẫn đi lễ nhà thờ mỗi Chủ nhật, cúi đầu thấp hơn ai hết.'}},
      {t:'Phản bội giáo phái, tố giác với Giáo hội',f:s=>{s.flags.her=0;s.flags.revealed=0;delete s.cult;mod({honor:10,piety:10});addEnemy('Tín đồ Hồng Nguyệt bị bạn bán đứng',{hate:R(60,80)});return['Bạn dẫn lính tuần đến hang đá. Giáo hội tha tội cho bạn, nhưng giáo phái sẽ không quên.','good']}}]},
 {id:'heryear',queued:true,big:true,art:'moon',c:s=>s.flags.her>0&&s.world.cat&&s.world.cat.id==='heresy',title:'Hồng Nguyệt nổi dậy',
  text:s=>`Năm thứ ${s.year-s.world.cat.y+1} của cuộc nổi loạn. ${s.flags.revealed?`Bạn là ${HER[s.flags.her]} của giáo phái${s.cult?', '+s.cult.fol.toLocaleString('vi-VN')+' tín đồ theo lệnh bạn':''}.`:'Bạn vẫn giấu thân phận.'} Giáo hội treo thưởng cho đầu của mọi tín đồ, và nghe đồn một Anh Hùng của Thánh Quang đang lùng sục khắp vùng.`,
  ch:[{t:'Lộ diện thân thế',hide:true,req:s=>!s.flags.revealed,f:s=>{s.flags.revealed=1;s.flags.herxp=(s.flags.herxp||0)+3;herRank();mod({honor:-10});return[`Bạn công khai là ${HER[s.flags.her]}.`,'magic']}},
      {t:'Đốt phá nhà thờ và tu viện',req:s=>s.flags.revealed,f:s=>{s.flags.herxp=(s.flags.herxp||0)+2;const g=R(20,90);s.money+=g;mod({honor:-6,piety:-4});if(s.cult)s.cult.fol+=R(30,90);herRank();if(ch(.25)){mod({health:-R(10,22)});return[`Bạn cướp được ${g} xu đồ thờ bằng bạc, nhưng bị lính gác chém trúng vai.`,'bad']}return[`Tu viện ${pick(['Thánh Aldric','Đồi Chuông','Suối Bạc'])} cháy rực trong đêm. Bạn mang về ${g} xu đồ thờ bằng bạc.`,'magic']}},
      {t:'Săn lùng Anh Hùng của Giáo hội',req:s=>s.flags.revealed&&s.age>=16,f:s=>{if(heroNpcFight(s.flags.her*.05)){s.flags.herxp=(s.flags.herxp||0)+4;s.house.prestige+=40;mod({magic:6});if(!hasItem('arm_holy')&&ch(.35))gainItem('arm_holy');herRank();return['Bạn phục kích Anh Hùng của Thánh Quang ở đèo Sương Mù. Thanh kiếm sáng của hắn tắt lịm. Lời tiên tri phải chờ thêm một thế hệ.','magic']}if(ch(.3)){die('dưới lưỡi kiếm của Anh Hùng Thánh Quang');return['Ánh sáng từ thanh kiếm của Anh Hùng xuyên qua lớp phép của bạn.','bad']}mod({health:-30});return['Anh Hùng đánh bạn văng khỏi lưng ngựa. Các tín đồ kéo bạn chạy thoát vào rừng.','bad']}},
      {t:'Ám sát Giám mục',req:s=>s.flags.revealed&&s.age>=16,f:s=>{if(ch(.3+s.st.smarts/300+(s.cult?s.cult.zeal/400:0))){s.flags.herxp=(s.flags.herxp||0)+3;mod({honor:-8});if(s.cult)s.cult.fol+=R(100,300);herRank();return['Giám mục ngã gục trên bậc thềm nhà thờ lớn. Cả giáo phận rơi vào hỗn loạn.','magic']}if(ch(.3)){die('bị bắt và hỏa thiêu sau vụ ám sát Giám mục');return['Cận vệ của Giám mục tóm được bạn.','bad']}mod({health:-15,honor:-5});return['Vụ ám sát thất bại. Bạn phải trốn dưới cống ngầm suốt một tháng.','bad']}},
      {t:'Dẫn tín đồ lật đổ Chính thống giáo',req:s=>s.flags.her>=3&&s.flags.revealed,f:s=>{const C=ensureCult();const p=.22+C.fol/20000+C.zeal/350+s.st.magic/400+(s.own.dragon?.1:0);
        if(ch(p)){S.world.cat=null;S.world.last=S.year;s.flags.redpope=1;mod({honor:5,magic:10});s.house.prestige+=400;if(s.house.title<6)grantTitle(6);announce('Hồng Nguyệt thống trị',`Nhà thờ lớn của ${s.realm} giờ treo cờ trăng đỏ. ${s.first} ${s.surname} ngồi lên ngai vàng, vừa là vua vừa là Giáo chủ của tôn giáo mới.`,'moon','coronation');return['Cánh cổng thánh đường đổ sập. Mặt trăng đỏ mọc trên kinh thành.','magic']}
        if(ch(.45)){die('bị hỏa thiêu trước nhà thờ lớn');return['Đội hiệp sĩ Thánh Quang phá tan đoàn quân của bạn.','bad']}C.fol=Math.round(C.fol/2);mod({health:-25});const old=s.realm;s.realm=pick(REALMS.filter(r=>r!==old));return[`Cuộc tấn công thất bại. Bạn dẫn tàn quân trốn sang ${s.realm}.`,'bad']}},
      {t:'Rời bỏ giáo phái, ẩn mình',f:s=>{s.flags.her=0;s.flags.revealed=0;delete s.cult;s.flags.suspect=(s.flags.suspect||0)+2;mod({happy:-5});return'Bạn đốt áo choàng đỏ và trốn về một làng xa. Nhưng bóng ma của Hồng Nguyệt vẫn bám theo.'}}]},
 {id:'hryear',queued:true,big:true,art:'moon',c:s=>s.flags.hcat&&s.world.cat&&s.world.cat.id==='player',title:'Thảm Họa Hồng Nguyệt',
  text:s=>{const C=ensureCult()||{fol:0,zeal:0};return`Năm thứ ${s.year-s.world.cat.y+1} của cuộc bạo động do bạn cầm đầu. ${C.fol.toLocaleString('vi-VN')} tín đồ, độ cuồng tín ${C.zeal}/100. Giáo hội và nhà vua đang tập hợp hiệp sĩ chống lại bạn.`},
  ch:[{t:'Thiêu rụi nhà thờ lớn',f:s=>{const C=ensureCult();const g=R(60,180);s.money+=g;C.fol+=R(200,500);mod({honor:-6});if(ch(.2)){mod({health:-15});return[`Lửa lan quá nhanh, bạn bị bỏng nặng. Nhưng ${g} xu vàng bạc từ kho thánh đường đã về tay bạn.`,'bad']}return[`Nhà thờ lớn sụp đổ trong biển lửa. Bạn thu ${g} xu và thêm hàng trăm người theo về.`,'magic']}},
      {t:'Cưỡng ép cải đạo các làng',f:s=>{const C=ensureCult();C.fol+=R(300,700);C.zeal=Math.max(0,C.zeal-4);mod({honor:-8,piety:-3});return['Các làng phải chọn: đeo dấu trăng đỏ hoặc chịu lửa. Phần lớn chọn sống.','magic']}},
      {t:'Tiến quân về kinh thành',f:s=>{const C=ensureCult();const p=.18+C.fol/15000+C.zeal/300+s.st.magic/400+(s.own.dragon?.12:0);
        if(ch(p)){s.flags.hcat=0;s.flags.redpope=1;s.world.cat=null;s.world.last=s.year;s.house.prestige+=500;if(s.house.title<6)grantTitle(6);announce('Hồng Nguyệt thống trị',`Đoàn quân trăng đỏ tràn qua cổng kinh thành. ${s.first} ${s.surname} đội vương miện trong thánh đường vừa đổi màu cờ.`,'moon','coronation');return['Nhà vua cũ quỳ dưới chân bạn.','magic']}
        C.fol=Math.round(C.fol*.6);C.zeal=Math.max(0,C.zeal-10);if(ch(.25)){die('trong trận chiến trước cổng kinh thành');return['Mưa tên từ tường thành phủ kín bầu trời.','bad']}mod({health:-20});return['Tường thành quá vững. Bạn rút về rừng sâu, mất gần nửa đoàn quân.','bad']}},
      {t:'Ẩn mình, củng cố lực lượng',f:s=>{const C=ensureCult();C.zeal=Math.min(100,C.zeal+R(8,15));mod({health:6,magic:4});return'Bạn ở lại hang đá suốt mùa đông, rèn tín đồ thành đội quân.'}}]},
 {id:'hrhero',queued:true,big:true,art:'sword',c:s=>s.flags.hcat,title:'Anh Hùng của Thánh Quang',
  text:()=>`Một ${pick(['hiệp sĩ trẻ','nữ pháp sư'])} cầm thanh kiếm phát sáng dẫn đoàn quân Thánh Quang tiến về sào huyệt của bạn. Các nhà tiên tri gọi người đó là Anh Hùng trong Lời Tiên Tri.`,
  ch:[{t:'Đối đầu',f:s=>{if(heroNpcFight(.05)){mod({magic:5});s.house.prestige+=60;if(s.cult)s.cult.fol+=R(200,400);return['Thanh kiếm sáng gãy làm đôi. Anh Hùng ngã xuống, và tín đồ của bạn hát mừng suốt ba đêm.','magic']}die('dưới lưỡi kiếm của Anh Hùng trong Lời Tiên Tri');return['Ánh sáng xuyên qua tim bạn.','bad']}},
      {t:'Bỏ trốn qua biên giới',f:s=>{if(s.cult){s.cult.fol=Math.round(s.cult.fol/2)}s.money=Math.floor(Math.max(s.money,0)/2);const old=s.realm;s.realm=pick(REALMS.filter(r=>r!==old));mod({honor:-10});return[`Bạn trốn sang ${s.realm}, bỏ lại một nửa tín đồ và kho báu.`,'bad']}},
      {t:'Quỳ xuống sám hối',f:s=>{if(ch(.35+s.st.piety/200)){s.flags.hcat=0;s.flags.her=0;s.flags.revealed=0;delete s.cult;s.world.cat=null;s.world.last=s.year;mod({honor:10,piety:15,magic:-15});return['Anh Hùng hạ kiếm. Bạn bị giam trong tu viện, nhưng được sống.','good']}die('bị hỏa thiêu dù đã sám hối');return['Tòa Dị Giáo không chấp nhận lời sám hối của bạn.','bad']}}]}
];

