function extIncome(){
  let inc=0;
  if(S.flags.hero&&S.world.cat){inc+=90;log('Triều đình cấp 90 xu nuôi Anh Hùng và đoàn tùy tùng.','good')}
  else if(S.flags.legend&&S.age>=16){inc+=40}
  if(S.house.title>=2&&!rules()&&S.age>=16){const a=30+S.house.title*15+(S.house.title>=6?40:0);inc+=a}
  return inc;
}
function extYear(){
  holderCheck();kidsYear();cultYear();
  if(S.alive)kdYear();
  if(S.flags.saint&&S.saint&&S.saint.doubt>=60&&!S.pend.includes('s_fall1')&&!S.pend.includes('s_fall2')&&ch(.5))S.pend.push('s_fall1');
  if(S.kd&&S.kd.edicts&&S.kd.edicts.includes('roads'))S.kd.dip=Math.min(100,S.kd.dip+2);
  if(S.house.title>=2&&!rules()&&S.age===16)log(`Bạn trưởng thành trong gia tộc ${S.house.name}. Đất đai vẫn do ${holderName()} cai quản.`);
}
function titleHeirOf(o){
  if(!(o.house.title>=2&&!o.house.holder))return null;
  const k=o.fam.filter(x=>x.alive&&!x.bast&&/^Con /.test(x.rel)),pool=k.length?k:o.fam.filter(x=>x.alive&&/^Cháu /.test(x.rel));
  if(o.kd&&o.kd.heir){const h=pool.find(x=>x.id===o.kd.heir);if(h)return h}
  return pool.slice().sort((a,b)=>a.sex===b.sex?b.age-a.age:(a.sex==='m'?-1:1))[0]||null;
}
function heirPool(){const k=kids();return k.length?k:S.fam.filter(p=>p.alive&&/^Cháu /.test(p.rel))}
function inherit(id){
  const old=S,p=old.fam.find(x=>x.id===id),own={...old.own},notes=[];
  if(old.cls==='serf'&&old.house.title<2){const b=ANIMALS.find(k=>own[k]>0);if(b){own[b]--;notes.push([`Theo lệ heriot, lãnh chúa dắt đi con ${ASSETS[b].n.toLowerCase()} tốt nhất của gia đình.`,'bad'])}}
  const rec=genRecord();rec.heir=id;
  const race=p.race||old.race;
  const st={};STATS.forEach(([k])=>st[k]=R(30,75));st.health=R(55,90);st.magic=R(5,40);
  for(const k in RACES[race].st)st[k]=clamp(st[k]+RACES[race].st[k]);
  if(old.house.title>=2)st.honor=clamp(st.honor+10);
  const wasRuler=old.house.title>=2&&!old.house.holder;
  const kidsA=old.fam.filter(x=>x.alive&&!x.bast&&/^Con /.test(x.rel)),grand=!/^Con /.test(p.rel);
  const pool=grand?old.fam.filter(x=>x.alive&&x.pid===p.pid):kidsA;
  const order=pool.slice().sort((a,b)=>a.sex===b.sex?b.age-a.age:(a.sex==='m'?-1:1));
  const tHeir=titleHeirOf(old);
  const n=Math.max(1,pool.length),money=old.money>0?Math.floor(old.money/n):old.money;
  const REG=['crown','ring_sig'],bag=old.bag.slice().sort((a,b)=>ITEMS[b.k].r-ITEMS[a.k].r),mine=[];let given=0,ri=0;
  const rcp=[p,...order.filter(x=>x.id!==id)];
  for(const it of bag){
    if(REG.includes(it.k)&&tHeir){if(tHeir.id===id)mine.push(it);else given++;continue}
    const who=rcp[ri%rcp.length];ri++;if(who.id===id)mine.push(it);else given++;
  }
  let title=old.house.title,holder=null;
  if(old.house.title>=2){
    if(wasRuler){holder=tHeir&&tHeir.id!==id?tHeir.id:null}
    else{title=old.house.title>=6?5:old.house.title-1;if(title<2)title=0;notes.push([`Tước ${titleName(old.house.title,'m')} vẫn thuộc dòng trưởng của gia tộc. Nhánh của bạn ${title>=2?'nhận tước '+titleName(title,p.sex)+' với đất phong riêng':'trở thành quý tộc không đất'}.`,''])}
  }
  if(old.flags.ptitle&&old.flags.ptitle>title&&(!holder)){title=old.flags.ptitle;notes.push([`Bạn thừa hưởng tước ${titleName(title,p.sex)} mà cha mẹ được phong riêng.`,'good'])}
  const house={...old.house,title,holder};if(title<2)delete house.dom;
  S={v:4,first:p.first,surname:p.sur,name:p.name,sex:p.sex,race,cls:old.house.title>=2||old.flags.knight?'noble':old.cls,by:old.year-p.age,age:p.age,year:old.year,realm:old.realm,village:old.village,st,money,own,job:null,fam:[],flags:{her:0},done:{},pend:[],ann:[],log:[],alive:true,gen:(old.gen||1)+1,bag:mine,tree:[...(old.tree||[]),rec],spHist:[],house,roots:old.roots,hid:newTalents(race,old.hid),world:{...old.world},rel:(old.rel||[]).filter(r=>r.alive&&r.kind==='enemy'&&r.hate>=60).map(r=>({...r,hate:r.hate-15,d:0,why:`Mối thù truyền từ đời ${old.first}`}))};
  if(old.flags.dark){S.flags.darkBlood=1;S.world.cat=null;S.world.last=old.year}
  if(old.flags.hcat){S.world.cat=null;S.world.last=old.year;S.flags.darkBlood=1}
  if(title>=6&&!holder)S.flags.king=1;
  if(wasRuler&&!holder&&title>=5&&old.kd){S.kd={...old.kd,heir:null,genC:null}}
  const sp=old.fam.find(x=>x.alive&&(x.rel==='Vợ'||x.rel==='Chồng'));
  if(sp&&!grand)S.fam.push({...sp,rel:sp.sex==='m'?'Cha':'Mẹ',d:0,bond:R(55,85)});
  for(const k of pool.filter(x=>x.id!==id)){const older=k.age>p.age;S.fam.push({...k,rel:k.sex==='m'?(older?'Anh trai':'Em trai'):(older?'Chị gái':'Em gái'),pid:undefined,d:0})}
  if(p.spouse&&p.spouse.alive){const s2=p.spouse;S.fam.push({id:uid(),rel:s2.sex==='m'?'Chồng':'Vợ',sex:s2.sex,age:s2.age,race:s2.race||race,first:s2.first,sur:s2.sur,name:s2.first+' '+s2.sur,alive:true,bond:R(55,85),d:0});S.spHist.push(s2.first+' '+s2.sur)}
  if(!grand)for(const g of old.fam.filter(x=>x.alive&&x.pid)){if(g.pid===id)S.fam.push({...g,rel:g.sex==='m'?'Con trai':'Con gái',pid:undefined,d:0});else if(pool.some(k=>k.id===g.pid))S.fam.push({...g,d:0})}
  entry();
  log(`Bạn là ${p.name}, ${p.age} tuổi, ${grand?'cháu':'con'} của ${old.name}. Đây là đời thứ ${S.gen} của gia tộc ${S.house.name}.`);
  log(n>1?`Gia sản ${fmt(old.money)} chia đều cho ${n} người thừa kế: bạn nhận ${fmt(money)}.`:`Bạn thừa kế ${fmt(old.money)}.`,'good');
  if(bag.length)log(`Bạn nhận ${mine.length}/${bag.length} bảo vật trong túi đồ gia truyền${given?`; ${given} món còn lại chia cho anh chị em`:''}.`,given?'':'good');
  if(title>=2&&!holder&&wasRuler)log(`Bạn kế thừa tước ${titleName(title,S.sex)} của gia tộc.${S.age<16?' Vì bạn còn nhỏ, '+(sp?'mẹ/cha bạn':'một đại thần')+' làm nhiếp chính cho đến khi bạn trưởng thành.':''}`,'good');
  if(holder){const h=S.fam.find(x=>x.id===holder);log(`Theo ${old.kd&&old.kd.heir===holder?'chiếu chỉ kế vị':'luật trưởng nam'}, ${h?h.rel.toLowerCase()+' '+h.first:'người anh cả'} kế thừa tước ${titleName(title,h?h.sex:'m')} và đất đai. Bạn là ${title>=6?(S.sex==='m'?'hoàng tử':'công chúa'):'thành viên gia tộc'}.`,'')}
  notes.forEach(([t2,tn])=>log(t2,tn));
  if(S.rel.length)log(`Bạn thừa hưởng cả mối thù của cha mẹ: ${S.rel.map(r=>r.name).join(', ')}.`,'bad');
  if(old.flags.dark||old.flags.hcat)log(`Thảm Họa ${old.first} đã chết. Nhưng huyết mạch của bóng tối vẫn chảy trong người bạn.`,'magic');
  if(old.flags.legend)log('Bạn là con của Anh Hùng trong Lời Tiên Tri. Ai cũng chờ đợi điều lớn lao từ bạn.','good');
  if(S.world.cat)log(`Thảm họa ${S.world.cat.id==='player'?'':CATS[S.world.cat.id].n} vẫn đang hoành hành.`,'bad');
  if(S.kd&&S.kd.war)log(`Bạn kế thừa cả cuộc chiến với ${S.kd.war.t}.`,'bad');
  ensureDom();closeModal();save();render();
  if(title>=6&&!holder){announce(title===7?'Tân hoàng đăng cơ':'Tân vương đăng cơ',`${S.first} kế thừa ngai vàng ${S.realm} từ ${old.first}. Vương triều ${S.house.name} bước sang đời thứ ${S.gen}.`,'crown','coronation');if(S.kd&&S.kd.vassals&&tHeir&&order[0]&&tHeir.id!==order[0].id)for(const v of S.kd.vassals)v.loy=Math.max(0,v.loy-12)}
  if(S.ann.length||S.pend.length)showNext();
}

