const AMAJ={blade:'Kiếm thuật',elem:'Ma pháp nguyên tố',ward:'Phòng ngự và kết giới',alch:'Giả kim',lore:'Lịch sử và cổ ngữ',holy:'Thánh thuật và trị liệu',beast:'Ma vật học'};
const ACLUB={kiem:{n:'CLB Kiếm thuật',fx:{health:2},sw:1,d:'Kiếm thuật, thể lực'},phap:{n:'CLB Ma pháp',fx:{magic:3},ar:1,d:'Ma lực, nghiên cứu'},gk:{n:'CLB Giả kim',fx:{smarts:3},d:'Trí tuệ, chế tạo'},tham:{n:'CLB Thám hiểm',fx:{health:1},d:'Trinh sát, vật phẩm'},hoi:{n:'Hội học sinh',fx:{honor:2},d:'Giao tiếp, lãnh đạo'},nghe:{n:'CLB Nghệ thuật',fx:{happy:4,looks:1},d:'Danh tiếng, tâm trạng'},bimat:{n:'Hội bí mật',fx:{magic:2,smarts:1},d:'Kiến thức hiếm · nguy hiểm'}};
const BOOKS=[['Nhập môn Ma lực',{magic:2},'Bạn thử một phép đơn giản: ngọn nến tự bùng sáng.'],['Bảy Thế Kiếm Cổ',{health:1},'Bạn tập theo hình vẽ đến khuya. Tay kiếm vững hơn hẳn.','sw'],['Thân Thể của Chiến Binh',{health:2},'Một giảng viên thấy bạn đọc và mời bạn tập buổi sáng.'],['Biên Niên Sử Bảy Vương Quốc',{smarts:3},'Một dòng nhắc đến một gia tộc thất lạc cùng họ với bạn.'],['Dược Thảo và Độc Tố',{smarts:2},'Bạn chép lại được một công thức thuốc hồi sức.','potion'],['Nghệ Thuật Kết Giới',{magic:2},'Bạn đủ hiểu để vượt qua bài kiểm tra kết giới đầu tiên.'],['Giải Phẫu Ma Vật',{smarts:2},'Bạn tìm thấy một tấm bản đồ hầm ngục kẹp giữa trang sách.','map'],['Tâm Pháp Hộ Thân',{health:2},'Bạn học được cách thở để chịu đòn.'],['Cổ Ngữ của Người Đầu Tiên',{smarts:3},'Bạn giải được một ký tự bí ẩn khắc trên tường thư viện.'],['Lời Thì Thầm Bên Kia Phong Ấn',{magic:3},'Những dòng chữ dường như chuyển động khi bạn không nhìn thẳng vào chúng.','forb']];
const ACWORLD=new Set(['dragon','egg','phoenix','frostknight','darkwake','saint','cult','awaken','magetest','oldmaster','beggarsword','werewolf','prophecy','unicorn','heroDream']);
const isStu=s=>!!(s.ac&&s.ac.st==='student');
const acY=()=>S.ac?Math.max(1,Math.min(6,S.age-S.ac.at+1)):0;
const acLeft=()=>Math.max(0,4-(S.done.acn||0));
const acRank=g=>g>=80?'Xuất sắc':g>=65?'Giỏi':g>=45?'Đạt':'Không đạt';
const acc=(k,v)=>{const A=S.ac;A[k]=Math.max(0,Math.min(100,Math.round((A[k]||0)+v)))};
function roomies(){return(S.rel||[]).filter(r=>r.room&&r.alive)}
function acEnroll(){
  const A=S.ac={st:'student',at:S.age,cls:null,major:null,club:null,council:0,grade:50,disc:60,rep:10,stress:10,books:{},q:{},scores:[]};
  if(S.job){log(`Bạn thôi làm ${jt().toLowerCase()} để nhập học.`);S.job=null}
  S.flags.literate=1;
  for(let i=0;i<2;i++){const r=npc('friend',{age:S.age+R(-1,1),bond:R(40,60)});r.room=1;S.rel.push(r)}
  return A;
}
function acSuggest(){const a=S.hid.arcane,w=S.hid.sword;if(a>=70&&w>=70)return'mix';if(w>=a&&w>=70)return'sword';if(a>=70)return'mage';return S.st.health>=S.st.smarts?'guard':'sage'}
function acYear(){
  const A=S.ac;if(!A)return;
  if(A.st==='student'){
    const y=acY();
    if(A.stress>=80){mod({health:-R(3,8),happy:-5});log('Căng thẳng học hành khiến bạn mất ngủ triền miên.','bad')}
    A.stress=Math.max(0,A.stress-8);
    if(A.disc<=0){A.st='expelled';log('Học viện đuổi học bạn vì vi phạm kỷ luật quá nhiều lần.','bad');announce('Bị đuổi học',`${S.first} bị Hội đồng kỷ luật Học viện Tháp Bạc đuổi học. Bạn có thể xin nhập học lại vào năm sau.`,'scroll');return}
    if(S.age>=13&&S.age<=17)S.pend.push('ac_exam');
    if(y===3&&!A.major)S.pend.push('ac_major');
    if(y===2&&!A.club)log('Năm thứ hai: các câu lạc bộ bắt đầu tuyển thành viên. Bạn có thể đăng ký trong mục Học viện.');
    if(y===5&&!A.q.tourn)S.pend.push('ac_tourn');
    if(y>=3&&A.q.sec==null&&ch(.5)){A.q.sec=0;S.pend.push('acs1')}
    else if(A.q.sec>=1&&A.q.sec<5&&y>=3&&!S.pend.includes('acs'+(A.q.sec+1))){if(A.q.sec<4||S.age>=17)S.pend.push('acs'+(A.q.sec+1))}
    if(A.q.forb==='b1'||A.q.forb==='b2')S.pend.push('acf_'+A.q.forb);
    if(A.q.demon==='d')S.pend.push('acd_hunt');
    if(A.council===1&&A.prom&&A.promY!==S.year){S.pend.push('ac_promise')}
    if(!A.q.bully&&y>=1&&y<=4&&ch(.35))S.pend.push('acb1');
    if(!A.q.demon&&y>=2&&ch(.12))S.pend.push('acd1');
    if(S.world.cat&&S.world.cat.id!=='player'&&ch(.4))S.pend.push('ac_cat');
    if(!A.q.fire&&ch(.03))S.pend.push('ac_fire');
    if(S.age>=18)S.pend.push('ac_grad');
  }
  if(A.st==='expelled'&&S.age<20&&ch(.6))S.pend.push('ac_readmit');
}
function acAct(k){
  const A=S.ac;S.done.acn=(S.done.acn||0)+1;S.done['a_'+k]=1;let t,tone='';
  const cl=A.cls,rm=roomies();
  if(k==='lecture'){acc('grade',R(4,8)+(cl==='sage'?2:0));acc('stress',6);mod({smarts:R(1,3)});t=pick(['Bạn ghi chép kín ba trang giấy da trong buổi giảng về lịch sử phép thuật.','Giảng viên gọi bạn lên bảng và bạn trả lời trôi chảy.','Bạn hỏi một câu khiến cả giảng đường im lặng suy nghĩ.']);tone='good'}
  if(k==='sword'){if(ch(.12)){mod({health:-R(5,12)});acc('stress',4);t='Thanh kiếm gỗ của bạn tập đập trúng cổ tay bạn. Bạn phải băng bó cả tuần.';tone='bad'}else{S.hid.sword=Math.min(100,S.hid.sword+(ch(.5)?1:0)+(cl==='sword'||cl==='mix'?1:0));mod({health:R(1,3),honor:1});acc('grade',cl==='sword'||cl==='guard'?R(3,6):1);acc('stress',3);t='Giảng viên kiếm thuật sửa từng thế đứng của bạn. Đến cuối buổi, đường kiếm của bạn đã gọn hơn.';tone='good'}}
  if(k==='spell'){if(S.st.magic<10&&cl!=='mage'){t='Bạn ngồi cả buổi mà không gọi nổi một tia lửa.';acc('stress',4)}else if(ch(.1)){mod({health:-8});acc('disc',-3);t='Câu thần chú mất kiểm soát, cháy sém rèm phòng ma pháp. Giảng viên ghi tên bạn vào sổ.';tone='bad'}else{S.hid.arcane=Math.min(100,S.hid.arcane+(ch(.5)?1:0)+(cl==='mage'||cl==='mix'?1:0));mod({magic:R(2,5)});acc('grade',cl==='mage'?R(3,6):1);acc('stress',3);t='Bạn giữ được quả cầu ánh sáng lơ lửng suốt một khắc. Giảng viên khẽ gật đầu.';tone='magic'}}
  if(k==='library'){const y=acY(),rd=A.books[y]||(A.books[y]=[]);const av=BOOKS.map((b,i)=>i).filter(i=>!rd.includes(i)&&(i<9||A.q.forb==null));if(!av.length){t='Bạn đã đọc hết những cuốn được phép mượn năm nay.'}else{const i=pick(av),B=BOOKS[i];rd.push(i);mod(B[1]);acc('grade',2);acc('stress',-2);t=`Bạn đọc cuốn "${B[0]}". ${B[2]}`;tone='good';if(B[3]==='sw')S.hid.sword=Math.min(100,S.hid.sword+1);if(B[3]==='potion'&&ch(.4))gainItem('elixir');if(B[3]==='map'&&ch(.5))gainItem('map');if(B[3]==='forb'){A.q.forb='start';S.pend.push('acf1');tone='magic'}}}
  if(k==='group'){acc('grade',R(2,5));acc('stress',-6);for(const r of rm)r.bond=clamp(r.bond+R(4,9));t=rm.length?`Bạn học nhóm với ${rm.map(r=>r.first).join(' và ')} đến khi nến tàn.`:'Bạn học nhóm với vài bạn cùng lớp.';tone='good'}
  if(k==='club'){const C=ACLUB[A.club];mod(C.fx);if(C.sw)S.hid.sword=Math.min(100,S.hid.sword+1);if(C.ar)S.hid.arcane=Math.min(100,S.hid.arcane+(ch(.5)?1:0));acc('rep',3);acc('stress',-3);t=`Buổi sinh hoạt ${C.n} sôi nổi.`;tone='good';
    if(A.club==='tham'&&ch(.2)){gainItem(pick(['gem','map','amulet']));t+=' Cả nhóm tìm được một món đồ lạ trong rừng sau trường.'}
    if(A.club==='bimat'&&ch(.15)&&A.q.forb==null){A.q.forb='start';S.pend.push('acf1');t+=' Đêm ấy, trưởng hội đưa cho bạn một cuốn sách bọc da đen.'}
    if(A.club==='gk'&&ch(.12)){if(ch(.6)){gainItem('elixir');t+=' Nhóm bạn pha được một lọ thuốc quý!'}else{mod({health:-8});t+=' Phòng thí nghiệm nổ một tiếng lớn.';tone='bad'}}}
  if(k==='work'){const g=R(3,9);S.money+=g;acc('stress',5);t=`Bạn làm thêm ở ${pick(['thư viện','nhà bếp','chuồng ngựa của trường','phòng giả kim'])}, kiếm được ${g} xu.`}
  if(k==='explore'){acc('disc',-4);if(ch(.3)){acc('disc',-6);t='Người gác đêm bắt gặp bạn ở tầng hầm cấm. Bạn bị phạt quét sân ba tuần.';tone='bad'}else if(!A.q.chest&&ch(.4)){A.q.chest=1;S.pend.push('ac_chest');t='Trong kho đồ cũ dưới tầng hầm, bạn thấy một chiếc rương bị niêm phong.'}else if(!A.q.demon&&ch(.25)){S.pend.push('acd1');t='Trong một góc tối, bạn nghe thấy tiếng thì thầm gọi tên mình.';tone='magic'}else{mod({magic:2,smarts:1});t='Bạn lần theo những hành lang cũ, vẽ được một phần bản đồ tầng hầm.';tone='magic'}}
  if(k==='rest'){acc('stress',-R(12,20));mod({happy:R(3,6),health:2});t='Bạn ngủ một giấc thật dài. Thế giới bỗng nhẹ nhàng hơn.';tone='good'}
  if(k==='social'){mod({happy:3});acc('rep',2);if(ch(.4)&&rels('friend').length<8){const r=addFriend({age:S.age+R(-1,1)});t=r?`Ở đại sảnh, bạn làm quen với ${r.name}${r.race!==S.race?', một '+RACES[r.race].n.toLowerCase():''}.`:'Bạn trò chuyện rôm rả ở đại sảnh.';tone='good'}else t=pick(['Bạn nghe tin đồn giảng viên giả kim từng là lính đánh thuê.','Bạn ngồi nghe các học viên năm trên kể chuyện giải đấu năm ngoái.'])}
  if(k==='elect'){S.pend.push('ac_elect');t='Bạn ghi tên ứng cử Chủ tịch Hội học sinh.'}
  log(t,tone);note={t,tone};afterSheetAction();
}
function acJoin(k){S.ac.club=k;S.done.acclub=1;const t=`Bạn gia nhập ${ACLUB[k].n}.`;log(t,'good');note={t,tone:'good'};afterSheetAction()}
const ACACTS=[['lecture','Học trên giảng đường','Học lực, trí tuệ · căng thẳng tăng','study'],['sword','Luyện kiếm với giảng viên','Kiếm thuật, sức khỏe · có thể bị thương','dummy'],['spell','Luyện phép với giảng viên','Ma lực, thiên phú phép · có thể mất kiểm soát','spellcast'],['library','Đọc sách thư viện','Mười cuốn sách, mỗi năm không đọc trùng','book'],['group','Học nhóm với bạn cùng phòng','Học lực, tình bạn · giảm căng thẳng','user-group'],['club','Sinh hoạt câu lạc bộ','Theo câu lạc bộ đã chọn','flag'],['work','Làm thêm trong trường','Ít tiền · căng thẳng tăng','sack'],['explore','Khám phá khu cấm, tầng hầm','Bí mật, cổ vật · kỷ luật giảm','crypt'],['rest','Nghỉ ngơi ở ký túc xá','Giảm mạnh căng thẳng','bath'],['social','Giao lưu ở đại sảnh','Bạn bè, tin đồn, danh tiếng','mug'],['elect','Tranh cử Hội học sinh','Từ năm III · cần danh tiếng','scroll']];
function acActWhy(k){const A=S.ac;if(S.done['a_'+k])return'Đã làm năm nay';if(!acLeft())return'Hết lượt năm nay';if(k==='club'&&!A.club)return'Chưa vào câu lạc bộ';if(k==='elect'&&(acY()<3||A.council||A.q.elect===S.year))return acY()<3?'Từ năm III':'Không thể ứng cử năm nay';return''}
/* --- events --- */
const XAC=s=>isStu(s);
const ACADEMY_EV=[
 {id:'ac_letter',queued:true,big:true,art:'study',c:s=>!s.ac&&s.age>=12&&s.age<=14,title:'Thư mời của Học viện Tháp Bạc',
  text:s=>`Một con cú xám đậu trên bậu cửa, chân buộc lá thư niêm sáp bạc. "Học viện Tháp Bạc nhận thấy ở ${s.first} ${s.hid.arcane>=70&&s.hid.sword>=70?'cả thiên phú ma pháp lẫn kiếm thuật':s.hid.arcane>=70?'cảm nhận ma pháp hiếm có':'tài năng kiếm thuật hiếm có'}. Học viện mở cửa cho mọi chủng tộc. Khóa học kéo dài sáu năm, đến tuổi mười tám."`,
  ch:[{t:'Nhập học',f:s=>{acEnroll();s.flags.seenA=1;s.flags.seenS=1;s.pend.push('ac_sort');const rm=roomies();return[`Bạn khăn gói lên đường. Bạn cùng phòng ký túc xá là ${rm.map(r=>r.name+(r.race!==s.race?' ('+RACES[r.race].n.toLowerCase()+')':'')).join(' và ')}.`,'good']}},
      {t:'Từ chối, ở lại làng',f:s=>{s.ac={st:'declined'};return'Bạn cất lá thư vào đáy rương.'}}]},
 {id:'ac_sort',queued:true,big:true,art:'crystal-ball',c:XAC,title:'Viên pha lê phân định thiên phú',
  text:s=>`Bạn đặt tay lên viên pha lê giữa đại sảnh. Nó sáng lên màu ${({sword:'đỏ thép',mage:'xanh sao',guard:'vàng đá',sage:'trắng bạc',mix:'tím ánh kim'})[acSuggest()]}. Giảng viên đọc kết quả: "${ACLS[acSuggest()].n}."`,
  ch:[{t:'Nhận lớp được đề xuất',f:s=>{s.ac.cls=acSuggest();return[`Bạn vào ${ACLS[s.ac.cls].n}.`,'good']}},
      {t:'Xin kiểm tra lại',f:s=>{const k=ch(.35)?'mix':acSuggest();s.ac.cls=k;return k==='mix'&&acSuggest()!=='mix'?['Lần thứ hai, viên pha lê lóe sáng nhiều màu. Bạn được xếp vào Lớp Tổng hợp.','good']:`Viên pha lê vẫn sáng như cũ. Bạn vào ${ACLS[k].n}.`}},
      ...['sword','mage','guard','sage'].map(k=>({t:`Xin chuyển sang ${ACLS[k].n}`,hide:true,req:s=>acSuggest()!==k,f:s=>{s.ac.cls=k;s.ac.off=1;acc('stress',8);return`Giảng viên nhíu mày nhưng đồng ý. Bạn vào ${ACLS[k].n}, dù đó không phải sở trường của bạn.`}}))]},
 {id:'ac_major',queued:true,big:true,art:'book',c:XAC,title:'Chọn chuyên ngành',text:'Năm thứ ba, mỗi học viên phải chọn một chuyên ngành sâu. Các trưởng bộ môn đứng chờ ở đại sảnh.',
  ch:Object.entries(AMAJ).map(([k,n])=>({t:n,f:s=>{s.ac.major=k;if(k==='blade')S.hid.sword=Math.min(100,S.hid.sword+2);if(k==='elem')mod({magic:5});if(k==='holy')mod({piety:4});if(k==='lore')mod({smarts:4});return[`Bạn chọn chuyên ngành ${n}.`,'good']}}))},
 {id:'ac_exam',queued:true,big:true,art:'scroll',c:XAC,title:s=>`Kỳ thi cuối năm ${acY()}`,
  text:s=>{const c=s.ac.cls||'mix';s.ac.ex=s.ac.ex||pick(['atk','def','dodge']);return c==='mage'?`Đề thi ma pháp: ${{atk:'phải phá một kết giới cứng',def:'phải giữ ngọn lửa ổn định thật lâu',dodge:'phải xử lý một phép đang mất kiểm soát'}[s.ac.ex]}. Bạn chọn cách nào?`:c==='sage'?`Đề thi học giả: ${{atk:'một bia đá cổ ngữ',def:'một câu đố logic của trưởng bộ môn',dodge:'giám định ba món cổ vật'}[s.ac.ex]}.`:`Thi đấu kiếm: đối thủ của bạn ${{atk:'tấn công dồn dập',def:'phòng thủ rất chặt',dodge:'di chuyển nhanh, chạy vòng'}[s.ac.ex]}. Bạn đánh thế nào?`},
  ch:[{t:'Tấn công mạnh, phá thế',f:s=>acExam('atk2')},{t:'Phòng thủ, chờ sơ hở',f:s=>acExam('def2')},{t:'Phản đòn, đọc ý đồ',f:s=>acExam('dodge2')},{t:'Gian lận (chép bài, bùa may mắn)',f:s=>acExam('cheat')}]},
 {id:'ac_tourn',queued:true,big:true,art:'crossed',c:XAC,title:'Giải đấu liên học viện',text:s=>`Năm thứ năm, Học viện Tháp Bạc cử đội tuyển dự giải liên học viện. ${s.ac.grade>=60||s.hid.sword>=70||s.hid.arcane>=70?'Tên bạn có trong danh sách.':'Bạn có thể xin thi vòng loại.'} Hoàng gia, Giáo hội và Hiệp hội Thợ săn đều cử người đến xem.`,
  ch:[{t:'Tham gia thi đấu',f:s=>{s.ac.q.tourn=1;let w=0;const pw=.4+Math.max(s.hid.sword,s.hid.arcane)/250+cbB()/300+s.ac.grade/400;const names=['vòng loại','bán kết','chung kết'];let t='';for(const n of names){if(ch(pw-w*.08)){w++;t+=`Thắng ${n}. `}else{t+=`Thua ở ${n}. `;break}}
      if(s.ac.q.bully==='fought'&&w<3&&ch(.5))t+='Cedric đứng trên khán đài cười khẩy khi bạn bị loại. ';
      if(w===3){mod({honor:12});s.house.prestige+=60;acc('rep',25);gainItem(pick(['greatsword','rg_arcane','kite_shield']));return[t+'Bạn vô địch giải liên học viện! Một sứ giả Hoàng gia ghi tên bạn vào sổ.','good']}acc('rep',w*6);mod({honor:w*3});return[t+(w?'Bạn có thành tích đáng nể.':'Bạn rời giải sớm.'),w?'good':'bad']}},
      {t:'Làm cổ động viên',f:s=>{s.ac.q.tourn=1;mod({happy:5});return'Bạn hò hét đến khản cổ cho đội nhà.'}}]},
 {id:'ac_elect',queued:true,big:true,art:'scroll',c:XAC,title:'Tranh cử Chủ tịch Hội học sinh',text:'Cuộc tranh luận trước toàn trường sắp bắt đầu. Đối thủ của bạn là con trai một bá tước, nổi tiếng hào phóng. Bạn đưa ra lời hứa nào?',
  ch:[...[['dorm','Sửa sang ký túc xá'],['schol','Thêm học bổng cho thường dân'],['fest','Tổ chức lễ hội lớn nhất từ trước đến nay']].map(([k,n])=>({t:`Hứa: ${n}`,f:s=>{s.ac.q.elect=s.year;const p=.3+s.ac.rep/150+s.st.looks/400+roomies().length*.05+rels('friend').length*.02;if(ch(p)){s.ac.council=1;s.ac.prom=k;s.ac.promY=s.year;acc('rep',12);mod({honor:5});return[`Bạn thắng cử với lời hứa "${n}". Giờ là lúc phải thực hiện.`,'good']}acc('rep',3);return['Bạn thua sát nút. Ít nhất cả trường đã biết tên bạn.','bad']}})),
      {t:'Bôi nhọ đối thủ',f:s=>{s.ac.q.elect=s.year;if(ch(.45)){s.ac.council=1;s.ac.prom='fest';s.ac.promY=s.year;acc('disc',-8);mod({honor:-6});return['Tin đồn lan nhanh, đối thủ rút lui. Bạn thắng, nhưng không vẻ vang.','bad']}acc('disc',-12);acc('rep',-10);return['Mưu bị lộ. Bạn bị Hội đồng kỷ luật khiển trách.','bad']}}]},
 {id:'ac_promise',queued:true,art:'scroll',c:s=>isStu(s)&&s.ac.council===1,title:'Lời hứa tranh cử',text:s=>`Đã đến lúc thực hiện lời hứa: ${{dorm:'sửa sang ký túc xá',schol:'thêm học bổng',fest:'tổ chức lễ hội'}[s.ac.prom]}.`,
  ch:[{t:'Dồn sức thực hiện',f:s=>{s.ac.promY=s.year;s.ac.prom=null;acc('stress',10);if(ch(.65)){acc('rep',15);mod({honor:5});return['Bạn giữ lời. Học viên gọi bạn là "Chủ tịch nói được làm được".','good']}acc('rep',-5);return'Bạn cố hết sức nhưng ban giám hiệu không duyệt kinh phí.'}},
      {t:'Lờ đi',f:s=>{s.ac.promY=s.year;s.ac.prom=null;acc('rep',-15);return['Học viên dán giấy chế giễu bạn khắp hành lang.','bad']}}]},
 {id:'ac_grad',queued:true,big:true,art:'study',c:s=>isStu(s)&&s.age>=18,title:'Lễ tốt nghiệp',
  text:s=>{const A=s.ac,g=Math.round(A.grade*.8+A.disc*.2);A.final=g;return`Sáu năm trôi qua. Điểm tổng kết của bạn: ${g}/100, xếp loại ${acRank(g)}.${acRank(g)==='Xuất sắc'?' Bạn được mời phát biểu trước toàn trường.':acRank(g)==='Không đạt'?' Bạn chưa đủ điều kiện nhận bằng.':''}`},
  ch:[...[['royal','Ca ngợi Hoàng gia',{honor:6}],['equal','Đề cao bình đẳng các chủng tộc',{happy:4}],['free','Ủng hộ tự do nghiên cứu',{smarts:3}],['unjust','Lên tiếng phản đối bất công',{honor:4}]].map(([k,n,fx])=>({t:`Phát biểu: ${n}`,hide:true,req:s=>acRank(s.ac.final)==='Xuất sắc',f:s=>{acGrad();mod(fx);s.house.prestige+=40;if(k==='royal'&&s.kd)s.kd.legit=Math.min(100,s.kd.legit+3);if(k==='free')s.flags.suspect=(s.flags.suspect||0)+1;return[`Bài phát biểu "${n}" được chép lại và truyền khắp các vương quốc. Bạn tốt nghiệp loại Xuất sắc.`,'good']}})),
      {t:'Nhận bằng tốt nghiệp',hide:true,req:s=>['Giỏi','Đạt'].includes(acRank(s.ac.final)),f:s=>{acGrad();return[`Bạn nhận bằng tốt nghiệp loại ${s.ac.rank}. Mọi cánh cửa nghề nghiệp đã mở.`,'good']}},
      {t:'Học bổ sung thêm một năm',hide:true,req:s=>acRank(s.ac.final)==='Không đạt',f:s=>{s.ac.grade=Math.max(s.ac.grade,46);s.ac.disc=Math.max(s.ac.disc,50);s.ac.at--;return'Bạn ở lại thêm một năm. Năm sau sẽ là lần thi lại cuối cùng.'}},
      {t:'Rời trường không bằng',hide:true,req:s=>acRank(s.ac.final)==='Không đạt',f:s=>{s.ac.st='left';return['Bạn rời Học viện, mang theo những gì đã học và những người bạn đã gặp.','bad']}}]},
 {id:'ac_readmit',queued:true,art:'scroll',c:s=>s.ac&&s.ac.st==='expelled',title:'Xin nhập học lại',text:'Hội đồng Học viện cho phép học viên bị đuổi xin quay lại nếu chứng minh được sự hối cải.',
  ch:[{t:'Nộp đơn và đóng 40 xu',cost:40,f:s=>{s.money-=40;s.ac.st='student';s.ac.disc=45;return['Bạn được nhận lại với điều kiện thử thách một năm.','good']}},
      {t:'Bỏ qua',f:s=>{s.ac.st='left';return'Bạn quyết định con đường của mình không ở Học viện.'}}]},
 /* --- đời thường học đường --- */
 {id:'acl1',ac:1,w:W(4),c:s=>isStu(s)&&roomies().length,title:'Bạn cùng phòng ngủ ngáy',text:s=>`${roomies()[0].first} ngáy như sấm suốt đêm. Bạn đã ba đêm không ngủ được.`,
  ch:[{t:'Nói thẳng',f:s=>{const r=roomies()[0];if(ch(.5)){r.bond=clamp(r.bond+3);return`${r.first} ngượng đỏ mặt, tối đó nằm nghiêng.`}r.bond=clamp(r.bond-6);return`${r.first} giận dỗi cả tuần.`}},{t:'Nhét bông vào tai',f:s=>{acc('stress',4);return'Bông không ăn thua lắm.'}},{t:'Xin chuyển phòng',f:s=>{const r=roomies()[0];r.room=0;r.bond=clamp(r.bond-10);acc('stress',-5);return`Bạn chuyển sang phòng khác. ${r.first} không còn là bạn cùng phòng.`}}]},
 {id:'acl2',ac:1,w:W(3),c:XAC,title:'Thư tình gửi nhầm',text:'Một lá thư tình viết bằng mực hồng được nhét nhầm vào ngăn bàn của bạn. Tên người nhận bị nhòe.',
  ch:[{t:'Tìm người nhận thật',f:s=>{acc('rep',3);mod({happy:2});return['Bạn trả lá thư cho đúng người. Hai người ấy cảm ơn bạn suốt cả năm.','good']}},{t:'Đọc to giữa lớp',f:s=>{acc('rep',-4);addEnemy('Người viết thư tình bị bạn đọc to giữa lớp',{age:s.age,hate:R(40,55)});return['Cả lớp cười ồ. Người viết thư thì không.','bad']}},{t:'Viết thư hồi âm',f:s=>{if(canLove()&&!lover()&&ch(.4)){const c=cand();s.rel.push(npc('lover',{...c,age:s.age,bond:R(55,70)}));return['Một mối tình học trò bắt đầu từ sự nhầm lẫn.','good']}return'Không ai trả lời thư của bạn.'}}]},
 {id:'acl3',ac:1,w:W(3),c:XAC,title:'Mèo ma thuật trộm bài',text:'Con mèo ba màu của thầy giám thị ngậm mất bài luận bạn thức trắng đêm để viết.',
  ch:[{t:'Đuổi theo con mèo',f:s=>{if(ch(.5)){acc('grade',2);return'Bạn giành lại được bài luận, hơi ướt nước dãi mèo.'}mod({health:-3});return'Con mèo biến vào tường. Bạn đâm sầm vào cột.'}},{t:'Thành thật kể với giảng viên',f:s=>{if(ch(.6)){acc('rep',2);return['Giảng viên bật cười: con mèo ấy đã ăn bài của nửa trường.','good']}acc('grade',-3);return'Giảng viên không tin.'}},{t:'Viết lại trong một đêm',f:s=>{acc('stress',10);acc('grade',1);return'Bạn viết lại kịp, mắt thâm quầng.'}}]},
 {id:'acl4',ac:1,w:W(3),c:XAC,title:'Ngủ gật trên lớp',text:'Bài giảng về thuế má của các triều đại cổ kéo dài vô tận. Mí mắt bạn nặng trĩu.',
  ch:[{t:'Cấu tay cho tỉnh',f:s=>{acc('grade',2);return'Bạn chịu đựng đến hết buổi.'}},{t:'Ngủ luôn',f:s=>{acc('stress',-6);if(ch(.5)){acc('disc',-4);return['Giảng viên ném phấn trúng trán bạn.','bad']}return'Không ai để ý. Giấc ngủ ngon nhất tuần.'}}]},
 {id:'acl5',ac:1,w:W(3),c:s=>isStu(s)&&s.race!=='human',title:'Lời kỳ thị',text:s=>`Một nhóm học viên con người chặn bạn ở hành lang: "${RACES[s.race].n} cũng đòi học ở đây à?"`,
  ch:[{t:'Đáp trả bằng lời',f:s=>{if(ch(.4+s.st.smarts/300)){acc('rep',4);return['Câu đáp sắc sảo của bạn khiến cả nhóm cứng họng.','good']}acc('stress',6);return'Chúng cười phá lên rồi bỏ đi.'}},{t:'Báo giảng viên',f:s=>{acc('rep',1);return'Giảng viên phạt cả nhóm chép nội quy một trăm lần.'}},{t:'Ra tay',f:s=>{acc('disc',-8);mod({honor:2});if(ch(.5+s.st.health/300))return['Bạn quật ngã đứa cầm đầu. Cả hai bị phạt, nhưng không ai dám trêu bạn nữa.','good'];mod({health:-8});return['Bạn bị cả nhóm đánh hội đồng.','bad']}}]},
 {id:'acl6',ac:1,w:W(3),c:s=>isStu(s)&&roomies().length,title:'Sinh nhật bạn cùng phòng',text:s=>`Mai là sinh nhật ${roomies()[0].first}.`,
  ch:[{t:'Tổ chức tiệc bất ngờ (5 xu)',cost:5,f:s=>{s.money-=5;for(const r of roomies())r.bond=clamp(r.bond+12);mod({happy:5});return['Cả phòng ăn bánh mật ong đến nửa đêm.','good']}},{t:'Tặng một bài thơ',f:s=>{roomies()[0].bond=clamp(roomies()[0].bond+6);return'Bài thơ dở tệ nhưng chân thành.'}},{t:'Quên mất',f:s=>{roomies()[0].bond=clamp(roomies()[0].bond-10);return['Bạn nhớ ra khi đã quá muộn.','bad']}}]},
 {id:'acl7',ac:1,w:W(2),c:XAC,title:'Thi uống nước trái cây',text:'Học viên năm trên tổ chức thi uống nước táo lên men trong ký túc xá. Ai uống nhiều nhất được miễn trực nhật một tháng.',
  ch:[{t:'Tham gia',f:s=>{if(ch(.4+s.st.health/300)){mod({happy:6});acc('rep',4);return['Bạn vô địch. Cả tầng ký túc xá vỗ tay.','good']}mod({health:-4});acc('disc',-3);return['Bạn nôn ra giày của giám thị.','bad']}},{t:'Làm trọng tài',f:s=>{acc('rep',2);return'Bạn ghi chép kết quả nghiêm túc như một quan tòa.'}},{t:'Về phòng ngủ',f:()=>'Bạn nghe tiếng hò hét vọng qua tường đến tận sáng.'}]},
 {id:'acl8',ac:1,w:W(3),c:XAC,title:'Quà từ gia đình',text:s=>`Gia đình gửi lên một gói quà: ${pick(['bánh mì đen và pho mát','đôi găng len mẹ đan','một con dao nhỏ của cha','thư của em út kèm hình vẽ nguệch ngoạc'])}.`,
  ch:[{t:'Chia cho bạn cùng phòng',f:s=>{for(const r of roomies())r.bond=clamp(r.bond+5);mod({happy:4});return['Cả phòng thấy như ở nhà.','good']}},{t:'Giữ làm kỷ niệm',f:s=>{mod({happy:5});acc('stress',-5);return'Bạn đọc đi đọc lại lá thư nhà mỗi tối.'}}]},
 {id:'acl9',ac:1,w:W(3),c:XAC,title:'Lễ hội Học viện',text:'Lễ hội Đêm Sao Bạc: đèn lồng phép bay khắp sân, các câu lạc bộ dựng quầy.',
  ch:[{t:'Dự tiệc khiêu vũ',f:s=>{mod({happy:6});if(canLove()&&!lover()&&ch(.3)){const c=cand();s.rel.push(npc('lover',{...c,age:s.age,bond:R(55,70)}));return['Bạn nhảy với một người và không muốn buông tay. Mối tình học trò bắt đầu.','good']}return'Bạn nhảy đến khi mỏi chân.'}},{t:'Biểu diễn tài năng',f:s=>{if(ch(.4+s.st.looks/300)){acc('rep',8);return['Tràng pháo tay vang dội.','good']}acc('rep',-2);return'Bạn quên lời giữa chừng.'}},{t:'Phụ quầy câu lạc bộ',f:s=>{s.money+=R(3,8);acc('rep',2);return'Quầy bán hết sạch hàng.'}}]},
 {id:'acl10',ac:1,w:W(2),c:XAC,title:'Hai câu lạc bộ tranh sân tập',text:'CLB Kiếm thuật và CLB Ma pháp cãi nhau to vì cùng muốn dùng sân tập chiều thứ sáu.',
  ch:[{t:'Đứng ra hòa giải',f:s=>{if(ch(.4+s.st.smarts/250)){acc('rep',6);return['Bạn chia lịch hợp lý, hai bên bắt tay.','good']}return'Không ai nghe bạn.'}},{t:'Đứng về phía CLB của mình',f:s=>{acc('rep',2);acc('disc',-2);return'Một trận ẩu đả nhỏ nổ ra.'}},{t:'Mặc kệ',f:()=>'Bạn đi đường vòng.'}]},
 {id:'acl11',ac:1,w:W(2),c:XAC,title:'Giảng viên già nghỉ hưu',text:'Giáo sư Halvard, người dạy ở Tháp Bạc năm mươi năm, nghỉ hưu. Ông tặng một món đồ cho học viên ông quý nhất.',
  ch:[{t:'Đến chào tạm biệt',f:s=>{if(s.ac.grade>=60&&ch(.5)){gainItem(pick(['tome','wand','amulet']));return['Ông đặt vào tay bạn một món đồ cũ: "Ta nhìn thấy ta ngày trẻ trong con."','item']}mod({happy:2});return'Ông vỗ vai bạn và mỉm cười.'}},{t:'Ở lại phòng học',f:()=>'Bạn nghe tiếng vỗ tay vọng lên từ sân trường.'}]},
 {id:'acl12',ac:1,w:W(3),c:XAC,title:'Học nhóm trước kỳ thi',text:'Đêm trước kỳ thi, cả tầng ký túc xá thắp nến học bài.',
  ch:[{t:'Học thâu đêm',f:s=>{acc('grade',4);acc('stress',10);return'Đầu bạn đầy chữ, mắt đầy quầng thâm.'}},{t:'Ngủ sớm',f:s=>{acc('stress',-8);return'Bạn ngủ đủ giấc. Có khi đó là chiến lược đúng.'}},{t:'Lén xem đề thi',f:s=>{if(ch(.4)){acc('grade',6);acc('disc',-6);return'Bạn liếc được đề. Lương tâm cắn rứt.'}acc('disc',-15);return['Bạn bị bắt quả tang trong phòng giảng viên.','bad']}}]},
 {id:'acl13',ac:1,w:W(2),c:s=>isStu(s)&&roomies().length,title:'Bạn cùng phòng nghỉ học',text:s=>`${roomies()[0].first} thu dọn đồ: nhà có biến, phải về quê.`,
  ch:[{t:'Góp tiền giúp đỡ (10 xu)',cost:10,f:s=>{s.money-=10;const r=roomies()[0];r.bond=clamp(r.bond+20);if(ch(.5))return['Nhờ số tiền ấy, cậu ấy ở lại học tiếp. Cậu thề sẽ không quên ơn bạn.','good'];r.room=0;return'Cậu ấy vẫn phải đi, nhưng mang theo tình bạn của bạn.'}},{t:'Tiễn bạn',f:s=>{const r=roomies()[0];r.room=0;mod({happy:-4});return'Bạn đứng ở cổng trường đến khi chiếc xe ngựa khuất bóng.'}}]},
 /* --- chuỗi bắt nạt --- */
 {id:'acb1',queued:true,big:true,art:'enemy',c:XAC,title:'Kẻ bắt nạt Cedric',text:'Cedric, con trai một bá tước, dồn một học viên thường dân vào góc tường, ép nộp tiền ăn.',
  ch:[{t:'Bảo vệ nạn nhân',f:s=>{s.ac.q.bully='fought';const r=addFriend({age:s.age,bond:R(60,75),cls:'serf'});if(r)r.why='victim';if(ch(.45+(s.blade||0)/250+s.st.health/400)){acc('rep',8);mod({honor:5});addEnemy('Cedric, kẻ bắt nạt bị bạn hạ nhục',{sex:'m',first:'Cedric',cls:'noble',age:s.age+1,hate:R(55,70)});return['Bạn thắng Cedric trong một trận đấu tay đôi sau giờ học. Học viên thường dân nhìn bạn như anh hùng.','good']}mod({health:-10});addEnemy('Cedric, kẻ bắt nạt',{sex:'m',first:'Cedric',cls:'noble',age:s.age+1,hate:R(45,60)});return['Bạn bị đám tay chân của Cedric đánh bầm dập, nhưng nạn nhân thoát được.','bad']}},
      {t:'Báo giảng viên',f:s=>{s.ac.q.bully='report';if(ch(.5)){acc('rep',3);return'Giảng viên bắt quả tang Cedric. Hắn bị phạt lao động.'}return['Không có chứng cứ. Cedric thoát tội và để ý đến bạn.','bad']}},
      {t:'Hòa giải',f:s=>{s.ac.q.bully='peace';if(ch(.35+s.st.smarts/250)){acc('rep',5);return['Bạn nói gì đó khiến Cedric chột dạ và bỏ đi.','good']}return'Cedric cười vào mặt bạn.'}},
      {t:'Bỏ đi',f:s=>{s.ac.q.bully='ignore';mod({honor:-2});return'Bạn quay đi. Ánh mắt nạn nhân đi theo bạn mãi.'}},
      {t:'Hùa theo Cedric',f:s=>{s.ac.q.bully='join';mod({honor:-8});s.money+=R(2,6);addFriend({first:'Cedric',sex:'m',cls:'noble',age:s.age+1,bond:R(40,55)});return['Bạn được nhận vào nhóm của Cedric. Danh dự của bạn thì không.','bad']}}]},
 /* --- kho báu trong kho đồ --- */
 {id:'ac_chest',queued:true,big:true,art:'chest',c:XAC,title:'Rương niêm phong trong kho',text:'Chiếc rương gỗ sồi bọc sắt, dán bùa niêm phong có chữ ký của một hiệu trưởng từ hai trăm năm trước.',
  ch:[{t:'Báo quản kho',f:s=>{acc('rep',3);acc('disc',4);return['Quản kho cảm ơn bạn. Ông kể chiếc rương thuộc về một học viên mất tích năm xưa, rồi mở cuộc điều tra.','good']}},
      {t:'Xin phép mở',f:s=>{if(ch(.5)){const k=pick(['tome','gem','rg_ruby','sword_anc']);gainItem(k);return['Ban giám hiệu cho phép. Bên trong có một món đồ, và Học viện tặng nó cho bạn.','item']}return'Ban giám hiệu từ chối và chuyển chiếc rương lên tháp.'}},
      {t:'Lén mở',f:s=>{const v=pick(['real','real','mimic','curse','owned']);if(v==='real'){gainItem(pick(['tome','greatsword','sc_crystal','gem']));return['Báu vật thật! Bạn giấu nó dưới gầm giường.','item']}if(v==='mimic'){mod({health:-14});return['Chiếc rương mọc răng và cắn vào tay bạn. Đó là một con mimic!','bad']}if(v==='curse'){mod({happy:-8,magic:4});s.flags.suspect=(s.flags.suspect||0)+1;return['Một làn khói xám chui vào mũi bạn. Bạn mơ thấy ác mộng suốt một mùa.','bad']}acc('disc',-15);return['Đó là đồ của giảng viên giả kim. Bạn bị bắt và phạt nặng vì tội trộm.','bad']}},
      {t:'Rủ bạn cùng khám phá',f:s=>{for(const r of roomies())r.bond=clamp(r.bond+6);if(ch(.6)){gainItem(pick(['amulet','gem','map']));return['Cả nhóm hồi hộp mở rương và chia nhau chiến lợi phẩm.','item']}mod({health:-6});return['Rương là một con mimic. May mà có bạn kéo bạn ra kịp.','bad']}}]},
 /* --- cấm thư --- */
 {id:'acf1',queued:true,big:true,art:'book',c:XAC,title:'Cấm thư',text:'Cuốn sách thì thầm vào tai bạn mỗi khi đêm xuống: "Mở ta ra. Ta sẽ cho ngươi sức mạnh mà không giảng viên nào dám dạy."',
  ch:[{t:'Nộp cho giảng viên',f:s=>{s.ac.q.forb='done';acc('rep',8);acc('disc',5);return['Giảng viên tái mặt khi thấy cuốn sách. Bạn được khen trước toàn trường vì sự trung thực.','good']}},
      {t:'Nghiên cứu để cảm hóa nó',f:s=>{s.ac.q.forb='a1';s.pend.push('acf_a1');return['Bạn chép lại từng ký tự, tìm cách thanh tẩy cuốn sách.','magic']}},
      {t:'Đọc những bí mật trong sách',f:s=>{s.ac.q.forb='b1';mod({magic:8});acc('disc',-5);s.flags.suspect=(s.flags.suspect||0)+1;return['Những câu chú chảy vào đầu bạn như rượu nóng. Bạn giấu cuốn sách dưới nệm.','magic']}}]},
 {id:'acf_a1',queued:true,big:true,art:'book',c:XAC,title:'Thanh tẩy cấm thư',text:'Ký tự đã giải xong. Giờ phải thanh tẩy lời nguyền trong sách.',
  ch:[{t:'Nhờ giảng viên giúp',f:s=>{s.ac.q.forb='done';acc('rep',5);mod({magic:3});if(ch(.7)){gainItem('tome');return['Giảng viên và bạn cùng thanh tẩy cuốn sách. Nó trở thành một sách phép bình thường, và bạn được giữ nó.','item']}return'Lời nguyền quá mạnh, cuốn sách bị niêm phong trong tháp.'}},
      {t:'Tự mình vượt qua thử thách ý chí',f:s=>{if(ch(.3+s.st.piety/300+s.hid.arcane/300)){s.ac.q.forb='done';gainItem('sc_moon');mod({magic:10});acc('rep',4);return['Bạn đối mặt với giọng nói trong sách suốt một đêm và chiến thắng. Cuốn sách hóa thành một cây trượng bán nguyệt, ngoan ngoãn phục tùng bạn.','magic']}s.ac.q.forb='b1';mod({health:-10});return['Giọng nói trong sách quá mạnh. Một phần của nó đã len vào tâm trí bạn.','bad']}}]},
 {id:'acf_b1',queued:true,big:true,art:'night',c:XAC,title:'Dấu hiệu hắc hóa',text:s=>`Móng tay bạn đen lại, bóng của bạn đôi khi chậm hơn bạn một nhịp. ${roomies()[0]?roomies()[0].first+' bắt đầu nhìn bạn bằng ánh mắt lo lắng.':'Bạn cùng lớp bắt đầu tránh mặt bạn.'}`,
  ch:[{t:'Đọc tiếp, sức mạnh đang đến',f:s=>{s.ac.q.forb='b2';mod({magic:10});acc('disc',-8);for(const r of roomies())r.bond=clamp(r.bond-10);return['Bạn làm được những phép mà cả giảng viên cũng không làm được.','magic']}},
      {t:'Thú nhận với giảng viên',f:s=>{s.ac.q.forb='done';acc('disc',-5);mod({magic:-5,piety:5});return['Giảng viên đốt cuốn sách. Bạn bị phạt, nhưng được cứu.','good']}},
      {t:'Đốt cuốn sách',f:s=>{if(ch(.6)){s.ac.q.forb='done';return['Cuốn sách gào thét trong lửa rồi im bặt.','good']}s.ac.q.forb='b2';return['Ngọn lửa không cháy. Cuốn sách vẫn nằm đó, nguyên vẹn.','bad']}}]},
 {id:'acf_b2',queued:true,big:true,art:'moon',c:XAC,title:'Nghi lễ cuối cùng',text:'Cuốn sách chỉ cho bạn nghi lễ cuối: giữa đêm trăng non, trên nóc Tháp Bạc. Sau đó bạn sẽ không còn là học viên nữa.',
  ch:[{t:'Thực hiện nghi lễ, trở thành Hắc Pháp Sư',f:s=>{s.ac.q.forb='dark';s.ac.st='expelled';s.flags.dark=1;mod({magic:30,piety:-30,honor:-25});s.hid.arcane=Math.min(100,s.hid.arcane+10);if(!hasItem('darkcrown'))gainItem('darkcrown');s.world.cat={id:'player',y:s.year};announce('Hắc Pháp Sư ra đời',`Đêm trăng non, nóc Tháp Bạc bốc lửa đen. ${s.first} ${s.surname} bay khỏi Học viện, để lại những người bạn cũ đứng câm lặng. Một Thảm Họa mới đã ra đời.`,'moon','demon');return['Bạn không còn là học viên. Bạn là Thảm Họa.','magic']}},
      {t:'Dừng lại ở bước cuối',f:s=>{if(ch(.5)){s.ac.q.forb='done';mod({magic:-10,happy:-8});return['Bạn ném cuốn sách xuống từ nóc tháp. Nó vỡ tan thành tro.','good']}mod({health:-20});s.ac.q.forb='b2';return['Cuốn sách không để bạn đi dễ dàng.','bad']}},
      {t:'Gọi bạn bè giúp',req:s=>roomies().length>0,f:s=>{if(ch(.4+roomies().reduce((a,r)=>a+r.bond,0)/300)){s.ac.q.forb='done';for(const r of roomies())r.bond=clamp(r.bond+15);return['Bạn bè giữ chặt tay bạn suốt đêm trăng non. Đến bình minh, giọng nói trong sách tắt lịm.','good']}s.ac.q.forb='b2';return['Bạn không đủ can đảm nói thật với họ.','bad']}}]},
 /* --- ác ma dụ mở phong ấn --- */
 {id:'acd1',queued:true,big:true,art:'demon',c:s=>isStu(s)&&!s.ac.q.demon,title:'Giấc mơ của Ác Ma',text:'Trong mơ, một Ác Ma có sáu con mắt đỏ ngồi trên chiếc ngai xương: "Phong ấn ta nằm ngay dưới chân ngươi, dưới Tháp Bạc. Mở nó ra, ta sẽ cho ngươi quyền lực vô hạn."',
  ch:[{t:'Từ chối',f:s=>{s.ac.q.demon='r';s.pend.push('acd_r');return'Ác Ma cười: "Rồi ngươi sẽ hối hận."'}},
      {t:'Giả vờ đồng ý để lần theo dấu vết',f:s=>{s.ac.q.demon='f';s.pend.push('acd_f');return['Bạn gật đầu trong mơ. Sáng dậy, trên tay bạn có một ấn ký đỏ.','magic']}},
      {t:'Mở phong ấn',f:s=>{s.ac.q.demon='o';s.pend.push('acd_o');mod({magic:15});return['Đêm sau, bạn lẻn xuống tầng hầm và xé lá bùa phong ấn.','bad']}},
      {t:'Đi theo Ác Ma',hide:true,req:s=>s.race==='fiend',f:s=>{s.ac.q.demon='d';mod({magic:20,piety:-20,honor:-10});s.flags.suspect=(s.flags.suspect||0)+3;return['Dòng máu quỷ trong người bạn đáp lời. Bạn quỳ xuống trước Ác Ma.','magic']}}]},
 {id:'acd_r',queued:true,big:true,art:'demon',c:XAC,title:'Ác Ma nổi giận',text:'Đêm ấy, bóng tối trong phòng ngủ đặc quánh lại. Ác Ma hiện hình, móng vuốt lóe sáng.',
  ch:[{t:'Chiến đấu',f:s=>{if(ch(.18+s.st.magic/300+s.hid.arcane/400+cbB()/300)){acc('rep',15);mod({honor:8});return['Bạn đẩy lùi Ác Ma về bóng tối. Cả trường kinh ngạc.','good']}if(ch(.2)){die('dưới móng vuốt của Ác Ma trong ký túc xá');return['Móng vuốt xuyên qua ngực bạn.','bad']}mod({health:-30});return['Bạn bị thương nặng. Ác Ma tan biến khi chuông báo động vang lên.','bad']}},
      {t:'Gọi giảng viên',f:s=>{if(ch(.7)){acc('rep',4);return['Ba giảng viên xông vào, đọc bùa phong ấn. Ác Ma gào thét rồi biến mất.','good']}mod({health:-15});return'Giảng viên đến chậm một nhịp.'}},
      {t:'Gọi bạn cùng phòng',req:s=>roomies().length>0,f:s=>{for(const r of roomies())r.bond=clamp(r.bond+12);if(ch(.5)){return['Ba người cùng ném nước thánh. Ác Ma lùi lại.','good']}const r=pick(roomies());if(ch(.3)){r.alive=false;mod({happy:-20});return[`${r.first} lao lên che cho bạn và không qua khỏi.`,'bad']}mod({health:-12});return['Cả phòng bị thương, nhưng sống sót.','bad']}},
      {t:'Bỏ trốn',f:s=>{acc('disc',-4);mod({happy:-6});return'Bạn chạy ra sân trường đến sáng. Ác Ma không đuổi theo, lần này.'}}]},
 {id:'acd_f',queued:true,big:true,art:'demon',c:XAC,title:'Phục kích Ác Ma',text:'Ấn ký trên tay dẫn bạn đến căn phòng phong ấn. Bạn có thể chuẩn bị phục kích khi Ác Ma lộ diện.',
  ch:[{t:'Phục kích cùng giảng viên',f:s=>{if(ch(.55)){acc('rep',15);mod({honor:6});gainItem('relic');return['Kế hoạch thành công. Ác Ma bị phong ấn sâu hơn bao giờ hết, và Học viện tặng bạn một thánh tích.','good']}mod({health:-20});return['Ác Ma phát hiện bẫy. Cả nhóm bị thương nhưng phong ấn vẫn giữ.','bad']}},
      {t:'Tự mình ra tay',f:s=>{if(ch(.25+s.st.magic/300)){acc('rep',20);s.house.prestige+=40;return['Bạn đâm lưỡi dao bạc vào tim Ác Ma đúng lúc nó vừa thoát ra một nửa.','good']}s.pend.push('acd_o');return['Bạn thất bại. Phong ấn rạn vỡ.','bad']}}]},
 {id:'acd_o',queued:true,big:true,art:'demon',c:XAC,title:'Phong ấn vỡ',text:'Tiếng nổ rung chuyển cả Tháp Bạc. Quỷ nhỏ tràn ra từ tầng hầm. Giảng viên đang tìm kẻ đã xé phong ấn.',
  ch:[{t:'Thú nhận và giúp tái phong ấn',f:s=>{acc('disc',-20);mod({honor:-4,health:-10});if(ch(.6)){acc('rep',5);return['Bạn dẫn giảng viên đến đúng chỗ. Phong ấn được dựng lại. Bạn bị phạt nặng, nhưng được tha.','good']}return['Phong ấn được dựng lại sau ba ngày. Bạn bị đình chỉ một năm.','bad']}},
      {t:'Chiến đấu với quỷ để sửa sai',f:s=>{if(ch(.4+(s.blade||0)/300+s.st.magic/400)){acc('rep',10);return['Bạn chặn quỷ ở cầu thang tầng hầm suốt đêm.','good']}mod({health:-25});return['Bạn bị quỷ cắn nát vai.','bad']}},
      {t:'Im lặng',f:s=>{s.flags.suspect=(s.flags.suspect||0)+2;if(ch(.4)){acc('disc',-40);return['Một nhân chứng khai ra bạn.','bad']}return'Không ai biết. Nhưng bạn biết.'}}]},
 {id:'acd_hunt',queued:true,big:true,art:'demon',c:s=>s.ac&&s.ac.q.demon==='d',title:'Kẻ phản bội Học viện',text:'Ác Ma sai bạn tấn công các giảng viên. Bạn bè cũ đã nghi ngờ, và nghe nói Giáo hội cử một Anh Hùng đến Học viện.',
  ch:[{t:'Tấn công theo lệnh Ác Ma',f:s=>{if(ch(.4)){mod({magic:10});s.ac.st='expelled';s.ac.q.demon='dd';s.flags.dark=1;s.world.cat=s.world.cat||{id:'player',y:s.year};announce('Đứa con của Ác Ma',`${s.first} tấn công Học viện Tháp Bạc rồi biến mất cùng Ác Ma. Một Thảm Họa mới ra đời.`,'moon','demon');return['Tháp Bạc chìm trong lửa đỏ.','magic']}die('dưới lưỡi kiếm của Anh Hùng bảo vệ Học viện');return['Anh Hùng chờ sẵn bạn ở cổng.','bad']}},
      {t:'Phản bội Ác Ma',f:s=>{s.ac.q.demon='done';if(ch(.5)){acc('rep',10);mod({honor:10,magic:-10});return['Bạn dẫn giảng viên đến nơi Ác Ma ẩn náu. Nó bị phong ấn vĩnh viễn, và bạn được tha thứ.','good']}mod({health:-30});return['Ác Ma trừng phạt kẻ phản bội trước khi bị phong ấn.','bad']}},
      {t:'Đào thoát khỏi cả hai',f:s=>{s.ac.st='left';s.ac.q.demon='done';const old=s.realm;s.realm=pick(REALMS.filter(r=>r!==old));return[`Bạn bỏ trốn sang ${s.realm}.`,'bad']}}]},
 /* --- bí mật dưới Tháp Bạc (năm III → tốt nghiệp) --- */
 {id:'acs1',queued:true,big:true,art:'book',c:XAC,title:'Bí mật dưới Tháp Bạc · Cuốn sách không tên',text:'Bạn nhặt được cuốn sổ không tên trong thư viện. Bên trong là sơ đồ các đường hầm dưới Tháp Bạc và một câu: "Phong ấn đang yếu đi."',
  ch:[{t:'Giao nộp',f:s=>{s.ac.q.sec=1;s.ac.q.secT=1;acc('rep',3);return'Giảng viên nhận sổ, không nói gì. Bạn thấy ông lo lắng.'}},{t:'Giữ lại nghiên cứu',f:s=>{s.ac.q.sec=1;s.ac.q.secP=1;mod({smarts:3});return['Bạn đối chiếu sơ đồ với tầng hầm thật.','magic']}},{t:'Giấu đi, quên chuyện này',f:s=>{s.ac.q.sec=99;return'Bạn cất cuốn sổ vào đáy rương.'}}]},
 {id:'acs2',queued:true,big:true,art:'night',c:XAC,title:'Bí mật dưới Tháp Bạc · Học sinh mất tích',text:'Ba học viên năm dưới biến mất trong một đêm. Giường của họ vẫn ấm.',
  ch:[{t:'Điều tra thư viện',f:s=>{s.ac.q.sec=2;s.ac.q.secP=(s.ac.q.secP||0)+1;return'Bạn tìm thấy tên một giáo sư trên phiếu mượn sách cấm cuối cùng.'}},{t:'Điều tra đường hầm',f:s=>{s.ac.q.sec=2;if(ch(.6)){s.ac.q.secP=(s.ac.q.secP||0)+2;acc('rep',5);return['Bạn tìm thấy một học viên mất tích đang bất tỉnh trong đường hầm.','good']}mod({health:-10});return['Bạn lạc trong đường hầm cả đêm.','bad']}},{t:'Rủ bạn bè cùng điều tra',f:s=>{s.ac.q.sec=2;s.ac.q.secA=(s.ac.q.secA||0)+roomies().length;for(const r of roomies())r.bond=clamp(r.bond+6);return'Cả nhóm thề giữ bí mật và cùng nhau tìm kiếm.'}}]},
 {id:'acs3',queued:true,big:true,art:'user',c:XAC,title:'Bí mật dưới Tháp Bạc · Giáo sư đáng ngờ',text:'Giáo sư Morrow của bộ môn Ma vật học hay xuống tầng hầm lúc nửa đêm, tay mang dao găm nghi lễ.',
  ch:[{t:'Tố cáo với Hiệu trưởng',f:s=>{s.ac.q.sec=3;if(s.ac.q.secP>=2){s.ac.q.secA=(s.ac.q.secA||0)+2;acc('rep',6);return['Có đủ bằng chứng, Hiệu trưởng cho người theo dõi Morrow.','good']}acc('disc',-6);return['Không có bằng chứng. Bạn bị khiển trách vì vu khống.','bad']}},{t:'Tìm bằng chứng',f:s=>{s.ac.q.sec=3;s.ac.q.secP=(s.ac.q.secP||0)+1;return'Bạn lén chép được nhật ký của Morrow.'}},{t:'Hợp tác với Morrow',f:s=>{s.ac.q.sec=3;s.ac.q.secM=1;mod({magic:6});return['Morrow kể rằng ông đang cố gia cố phong ấn, không phải phá nó. Hay đó chỉ là lời nói dối?','magic']}}]},
 {id:'acs4',queued:true,big:true,art:'moon',c:XAC,title:'Bí mật dưới Tháp Bạc · Phong ấn rạn nứt',text:'Vết nứt chạy dọc nền tầng hầm. Thứ bên dưới đang thức dậy. Bạn còn một năm.',
  ch:[{t:'Tập hợp bạn bè',f:s=>{s.ac.q.sec=4;s.ac.q.secA=(s.ac.q.secA||0)+roomies().length+Math.min(3,rels('friend').length);return'Bạn bè của bạn đồng ý đứng cạnh bạn.'}},{t:'Thuyết phục giảng viên',f:s=>{s.ac.q.sec=4;if(ch(.4+s.ac.rep/150)){s.ac.q.secA=(s.ac.q.secA||0)+3;return['Ba giảng viên cam kết sẽ có mặt.','good']}return'Không ai tin một học viên.'}},{t:'Tìm vật phẩm phong ấn',f:s=>{s.ac.q.sec=4;s.ac.q.secP=(s.ac.q.secP||0)+2;if(ch(.5))gainItem('relic');return'Bạn tìm được những mảnh bùa cổ trong kho của tháp.'}}]},
 {id:'acs5',queued:true,big:true,art:'demon',c:XAC,title:'Bí mật dưới Tháp Bạc · Đêm trước tốt nghiệp',
  text:s=>`Đêm trước lễ tốt nghiệp, phong ấn vỡ. Bạn có ${s.ac.q.secA||0} đồng minh và mức chuẩn bị ${s.ac.q.secP||0}. Một học viên không thể một mình đánh bại thực thể này.`,
  ch:[{t:'Tái phong ấn cùng tổ đội',f:s=>{s.ac.q.sec=5;const p=.15+(s.ac.q.secA||0)*.08+(s.ac.q.secP||0)*.07+s.st.magic/500;if(ch(p)){acc('grade',10);acc('rep',25);s.house.prestige+=80;mod({honor:10});gainItem('br_rune');return['Phong ấn sáng lên trắng xóa và đóng lại. Bạn và bạn bè được Hiệu trưởng vinh danh trước toàn trường.','good']}mod({health:-30});return['Phong ấn chỉ khép lại được một nửa. Các giảng viên phải gánh phần còn lại, và hai người không qua khỏi.','bad']}},
      {t:'Đánh bại thực thể',f:s=>{s.ac.q.sec=5;if(ch(.08+(s.ac.q.secA||0)*.06+(s.blade||0)/400+s.hid.arcane/400)){acc('rep',30);mod({honor:15});gainItem('h_crown');return['Không ai tin được: tổ đội học viên đã hạ thực thể dưới Tháp Bạc.','good']}if(ch(.3)){die('khi chiến đấu với thực thể dưới Tháp Bạc');return['Thực thể quá mạnh.','bad']}mod({health:-35});return['Bạn bị hất văng. Giảng viên kịp đến cứu.','bad']}},
      {t:'Thương lượng với thực thể',hide:true,req:s=>s.ac.q.secM,f:s=>{s.ac.q.sec=5;mod({magic:12});s.flags.suspect=(s.flags.suspect||0)+2;return['Morrow và bạn ký giao ước với thực thể: nó ngủ thêm trăm năm, đổi lấy một bí mật. Bạn không bao giờ kể cho ai.','magic']}}]},
 /* --- thảm họa tấn công Học viện --- */
 {id:'ac_cat',queued:true,big:true,art:'skull',c:s=>isStu(s)&&s.world.cat&&s.world.cat.id!=='player',title:'Thảm Họa tấn công Học viện',text:s=>`Tin dữ: ${CATS[s.world.cat.id].n.toLowerCase()} đã lan đến Học viện Tháp Bạc. Chuông báo động vang khắp ký túc xá.`,
  ch:[{t:'Trốn vào hầm',f:()=>{mod({happy:-4});return'Bạn ngồi trong bóng tối, nghe tiếng nổ trên đầu.'}},{t:'Cứu bạn cùng phòng',f:s=>{for(const r of roomies())r.bond=clamp(r.bond+12);if(ch(.75)){acc('rep',6);return['Bạn kéo bạn mình ra khỏi phòng đang cháy.','good']}mod({health:-15});return['Bạn cứu được bạn, nhưng bị bỏng nặng.','bad']}},
      {t:'Hỗ trợ giảng viên',f:s=>{acc('rep',8);mod({honor:4,health:-6});return['Bạn chuyền nước thánh và băng gạc cho giảng viên suốt đêm.','good']}},
      {t:'Chiến đấu',req:s=>s.hid.sword>=60||s.hid.arcane>=60,f:s=>{if(ch(.4+Math.max(s.hid.sword,s.hid.arcane)/300)){acc('rep',15);mod({honor:10});s.house.prestige+=30;return['Bạn đứng cạnh giảng viên trên tường thành và đẩy lùi đợt tấn công. Tên bạn được ghi vào sổ vàng.','good']}mod({health:-25});return['Bạn bị thương khi chiến đấu.','bad']}}]}
];
function acExam(k){
  const A=S.ac,c=A.cls||'mix',ex=A.ex||'atk';A.ex=null;
  const best={atk:'dodge2',def:'atk2',dodge:'def2'}[ex];
  const st=c==='mage'?S.hid.arcane:c==='sage'?S.st.smarts:c==='guard'?S.st.health:c==='sword'?S.hid.sword:Math.max(S.hid.arcane,S.hid.sword);
  let sc;if(k==='cheat'){if(ch(.55)){sc=70+R(0,15);acc('disc',-6)}else{sc=10;acc('disc',-20);acc('rep',-8)}}
  else sc=Math.round(A.grade*.5+st*.3+R(0,20)+(k===best?15:-5)-(A.off?5:0)-(A.stress>70?8:0));
  sc=Math.max(0,Math.min(100,sc));A.scores.push(sc);A.grade=Math.round(A.grade*.6+sc*.4);
  if(sc>=80){acc('rep',5);if(ch(.3)){S.money+=15;return[`Bạn đạt ${sc} điểm, đứng đầu khóa và nhận học bổng 15 xu.`,'good']}}
  const t=k==='cheat'&&sc===10?'Bạn bị bắt quả tang gian lận. Bài thi bị hủy.':`Bạn đạt ${sc} điểm${k===best?', đúng cách giải mà giám khảo mong đợi':''}. Học lực hiện tại: ${A.grade}.`;
  return[t,sc>=60?'good':sc<40?'bad':''];
}
function acGrad(){const A=S.ac;A.st='grad';A.rank=acRank(A.final);A.gy=S.year;mod({smarts:5});S.house.prestige+=A.rank==='Xuất sắc'?60:A.rank==='Giỏi'?30:10;for(const r of roomies())r.room=0;log(`Bạn tốt nghiệp Học viện Tháp Bạc, xếp loại ${A.rank}.`,'good')}

/* ===== Học viện: giảng viên → hiệu trưởng ===== */
JOBS.teacher={n:'Giảng viên Học viện Tháp Bạc',min:18,t:['Giảng viên','Trưởng bộ môn','Phó Hiệu trưởng','Hiệu trưởng'],pay:[32,60,95,145],need:[3,5,6],fx:{smarts:1},
  req:s=>s.ac&&s.ac.st==='grad'&&(['Xuất sắc','Giỏi'].includes(s.ac.rank)||Math.max(s.hid.sword,s.hid.arcane,s.st.smarts)>=75),why:'Cần tốt nghiệp Học viện loại Giỏi trở lên, hoặc chuyên môn từ 75',
  gate:(s,r)=>{const tr=(s.ac&&s.ac.tr)||0;if(r===0)return tr>=60?true:'Bạn chưa đủ uy tín để làm Trưởng bộ môn (cần 60).';if(r===1)return tr>=70&&s.st.smarts>=65?true:'Hội đồng chưa đề bạt bạn: cần uy tín 70 và Trí tuệ 65.';return''}};
JIC.teacher='study';
const DEPT=AMAJ;
const MENT=[{first:'Leon',kind:'sword',trait:'kiêu ngạo',tal:91,race:'human',sex:'m'},{first:'Aria',kind:'magic',trait:'tò mò',tal:96,race:'elf',sex:'f'},{first:'Dorin',kind:'smarts',trait:'tham vọng',tal:87,race:'dwarf',sex:'m'}];
const TRAITS=['kiêu ngạo','tò mò','tham vọng','nhút nhát','trung thành','nóng nảy','chăm chỉ'];
const isStaff=s=>!!(s.job&&s.job.id==='teacher');
const stLeft=()=>Math.max(0,3-(S.done.stn||0));
function staffHire(){const A=S.ac;if(A.tr==null){A.tr=30;A.dept=A.major||pick(Object.keys(DEPT));A.men=A.men||[];log(`Bạn về giảng dạy bộ môn ${DEPT[A.dept]} tại Học viện Tháp Bạc.`,'good')}}
function menCands(){const A=S.ac;if(!A.menC||A.menCY!==S.year){A.menCY=S.year;const used=new Set((A.men||[]).map(m=>m.first));A.menC=(A.menFirst?[0,1,2].map(()=>{const sx=pick(['m','f']),race=pick(Object.keys(RACES));return{first:pick(nameList(sx,race)),sex:sx,race,kind:pick(['sword','magic','smarts']),trait:pick(TRAITS),tal:R(65,95)}}):MENT.map(m=>({...m}))).filter(m=>!used.has(m.first));A.menFirst=1}return A.menC}
function takeMentee(i){const A=S.ac,m={...A.menC[i],id:uid(),bond:R(45,65),y:0,fate:null};A.men.push(m);A.menC.splice(i,1);S.done.stmen=1;const t=`Bạn nhận ${m.first} (${RACES[m.race].n.toLowerCase()}, thiên phú ${m.tal}, tính ${m.trait}) làm học trò thân truyền.`;log(t,'good');note={t,tone:'good'};afterSheetAction()}
function staffAct(k){
  const A=S.ac;S.done.stn=(S.done.stn||0)+1;S.done['s_'+k]=1;let t,tone='';const tr=v=>{A.tr=Math.max(0,Math.min(100,(A.tr||0)+v))};
  if(k==='teach'){tr(R(3,6));S.money+=R(2,6);mod({smarts:1});t=pick(['Giảng đường kín chỗ. Học viên chép bài không kịp thở.','Bạn kể một câu chuyện thực địa khiến cả lớp nín thở.']);tone='good'}
  if(k==='tutor'){const m=pick(A.men.filter(m=>!m.fate));m.tal=Math.min(100,m.tal+R(1,3));m.bond=clamp(m.bond+R(5,10));tr(2);t=`Bạn kèm riêng ${m.first} suốt buổi chiều. Học trò tiến bộ rõ rệt.`;tone='good'}
  if(k==='research'){const r=Math.random()+S.st.smarts/400+(A.bud==='res'?.12:0);if(r>.85){tr(10);S.house.prestige+=30;const it=pick(['tome','rg_arcane','elixir','sc_crystal']);gainItem(it);t=`Nghiên cứu của bạn thành công rực rỡ! Bạn công bố phát minh trước Hội đồng và giữ lại ${ITEMS[it].n.toLowerCase()}.`;tone='item'}else if(r<.2){mod({health:-10});tr(-3);t='Thí nghiệm thất bại, phòng nghiên cứu ám khói cả tuần.';tone='bad'}else{mod({smarts:2});tr(2);t='Bạn ghi thêm một chương vào bản thảo nghiên cứu.'}}
  if(k==='exam'){tr(2);if(ch(.3)){S.pend.push('st_cheat');t='Khi chấm bài, bạn phát hiện hai bài thi giống nhau từng chữ.'}else t='Bạn ra đề và chấm xong bài thi cuối kỳ.'}
  if(k==='field'){const r=Math.random();if(r<.15){tr(-5);mod({health:-8});t='Một học viên trượt chân xuống khe núi trong chuyến thực địa. May mà cứu được, nhưng phụ huynh nổi giận.';tone='bad'}else{tr(R(4,8));t='Chuyến thực địa đến di tích cổ diễn ra suôn sẻ.';tone='good';if(r>.85){gainItem(pick(['gem','map','amulet']));t+=' Bạn còn tìm được một cổ vật nhỏ.'}}}
  if(k==='council'){tr(3);mod({honor:2});t='Bạn ngồi Hội đồng kỷ luật, xét xử công bằng một vụ đánh nhau.'}
  log(t,tone);note={t,tone};afterSheetAction();
}
const BUDP={bal:{n:'Cân bằng',d:'Không lệch bên nào'},res:{n:'Ưu tiên nghiên cứu',d:'Dễ có phát minh · chất lượng dạy giảm nhẹ'},schol:{n:'Ưu tiên học bổng',d:'Ít học viên bỏ học · uy tín tăng'},eq:{n:'Ưu tiên thiết bị',d:'Ít tai nạn'},teach:{n:'Ưu tiên giảng dạy',d:'Uy tín giảng dạy tăng mỗi năm'}};
function staffYear(){
  if(!isStaff(S))return;const A=S.ac;staffHire();
  if(A.bud==='teach')A.tr=Math.min(100,A.tr+3);if(A.bud==='schol')A.tr=Math.min(100,A.tr+1);
  if(S.job.rank>=1&&A.bud!=='eq'&&ch(.08)){A.tr=Math.max(0,A.tr-6);log('Thiếu thiết bị, một học viên bị thương trong phòng thực hành. Bộ môn bị khiển trách.','bad')}
  for(const m of A.men){if(m.fate)continue;m.y++;m.tal=Math.min(100,m.tal+R(0,2));m.bond=clamp(m.bond-R(0,3));if(m.y>=4&&!S.pend.includes('st_mentee')){A.menF=m.id;S.pend.push('st_mentee')}}
  if(S.job.rank===1&&ch(.3))S.pend.push(pick(['st_fraud','st_rival']));
  if(S.job.rank===2&&ch(.3))S.pend.push('st_missing');
  if(S.job.rank===2&&A.tr>=80&&S.job.ry>=4&&!S.pend.includes('st_pvote'))S.pend.push('st_pvote');
  if(S.job.rank===3)schYear();
  if(!A.fireY||S.year-A.fireY>=10){if(ch(.03+(S.sch?S.sch.forb/400+(50-S.sch.sec)/500:0))){A.fireY=S.year;S.pend.push('ac_fire')}}
}
/* --- quản trị Học viện (Hiệu trưởng) --- */
const SCHB={dorm:{n:'Ký túc xá mới',c:150,d:'Chất lượng +3',fx:{qual:3}},arena:{n:'Đấu trường',c:200,d:'Danh tiếng +5',fx:{rep:5}},lib:{n:'Thư viện cổ',c:220,d:'Chất lượng +5',fx:{qual:5}},alch:{n:'Phòng giả kim',c:180,d:'Chất lượng +3, phát minh dễ hơn',fx:{qual:3}},infirm:{n:'Bệnh xá',c:160,d:'Giảm thương vong khi có biến',fx:{sec:4}},obs:{n:'Đài quan sát',c:200,d:'Danh tiếng +4',fx:{rep:4}},ward:{n:'Kết giới bảo hộ',c:260,d:'An ninh +15',fx:{sec:15}}};
function ensureSch(){if(!(isStaff(S)&&S.job.rank===3))return null;if(!S.sch)S.sch={rep:55,qual:55,sec:50,bud:300,cou:60,forb:0,bld:{},adm:'normal',schol:0};return S.sch}
const sc=(k,v)=>{const X=S.sch;X[k]=Math.max(0,Math.min(100,Math.round(X[k]+v)))};
function schYear(){
  const X=ensureSch();if(!X)return;
  const inc=150+X.rep*2+(X.adm==='expand'?80:X.adm==='elite'?-30:0),cost=100+Object.keys(X.bld).length*12+(X.schol?60:0);X.bud+=inc-cost;
  const qt=50+Object.keys(X.bld).length*3+(X.adm==='elite'?8:X.adm==='expand'?-8:0)+(X.schol?4:0)+X.forb/10;X.qual=Math.round(X.qual+(qt-X.qual)*.25);
  X.rep=Math.round(X.rep+(X.qual-X.rep)*.2);X.sec=Math.max(0,X.sec-3);
  X.cou=Math.max(0,Math.min(100,Math.round(X.cou+(X.bud<0?-10:2)-(X.forb>=40?5:0)+(X.rep-55)/15)));
  log(`Học viện Tháp Bạc: ngân sách ${X.bud} xu (thu ${inc}, chi ${cost}). Danh tiếng ${X.rep}, chất lượng ${X.qual}, an ninh ${X.sec}, Hội đồng ủng hộ ${X.cou}.`,X.bud<0||X.cou<30?'bad':'');
  if(X.cou<25&&!S.pend.includes('st_noconf'))S.pend.push('st_noconf');
  if(X.forb>=50&&ch(.3))S.pend.push('st_church');
}
const SCHA={
  adm:{n:'Tuyển sinh',d:'Đổi chỉ tiêu tuyển sinh',sub:{normal:'Bình thường',expand:'Mở rộng · ngân sách +80, chất lượng giảm',elite:'Tinh hoa · chất lượng tăng, ngân sách −30'}},
  schol:{n:'Học bổng cho thường dân',d:'60 xu/năm · chất lượng và danh tiếng tăng'},
  hunt:{n:'Thuê Thợ săn bảo vệ trường',d:'80 xu · an ninh +12'},
  forb:{n:'Nghiên cứu cấm thuật',d:'Chất lượng +6 · nguy cơ thảm họa và Giáo hội điều tra'},
  council:{n:'Họp Hội đồng Học viện',d:'Sự ủng hộ của Hội đồng tăng'},
  dip:{n:'Ngoại giao',d:'Hoàng gia, Giáo hội, Hiệp hội Thợ săn, Tháp Ma Pháp',sub:{royal:'Hoàng gia · ngân sách +120, Hội đồng −3',church:'Giáo hội · ngân sách +60, an ninh +5 (chỉ khi cấm thuật thấp)',guild:'Hiệp hội Thợ săn · an ninh +10',tower:'Tháp Ma Pháp · chất lượng +5'}}
};
function schAct(s){
  const[a,arg]=s.split(':'),X=ensureSch();S.done['sc_'+a]=1;let t='',tone='';
  if(a==='adm'){X.adm=arg;if(arg==='expand')X.bud+=80;t=`Bạn đặt chỉ tiêu tuyển sinh: ${SCHA.adm.sub[arg].split(' ·')[0].toLowerCase()}.`}
  if(a==='schol'){X.schol=X.schol?0:1;t=X.schol?'Bạn lập quỹ học bổng cho học viên thường dân.':'Bạn bãi bỏ quỹ học bổng.';if(X.schol)sc('rep',3)}
  if(a==='hunt'){X.bud-=80;sc('sec',12);t='Một tổ đội thợ săn hạng A đóng quân trong trường.'}
  if(a==='forb'){X.forb=Math.min(100,X.forb+15);sc('qual',6);sc('cou',-3);t='Bạn mở khóa tầng sách cấm cho nhóm nghiên cứu bí mật.';tone='magic'}
  if(a==='council'){sc('cou',R(6,12));t='Bạn thuyết phục Hội đồng bằng những con số và một bữa tiệc ngon.'}
  if(a==='build'){const B=SCHB[arg];X.bud-=B.c;X.bld[arg]=S.year;for(const[k,v]of Object.entries(B.fx))sc(k,v);t=`Học viện xây xong ${B.n.toLowerCase()}.`;tone='good'}
  if(a==='dip'){if(arg==='royal'){X.bud+=120;sc('cou',-3);t='Hoàng gia tài trợ 120 xu, đổi lại muốn gửi gắm vài con cháu quý tộc.'}if(arg==='church'){X.bud+=60;sc('sec',5);t='Giáo hội tài trợ khoa Thánh thuật.'}if(arg==='guild'){sc('sec',10);t='Hiệp hội Thợ săn cử người huấn luyện đội bảo vệ.'}if(arg==='tower'){sc('qual',5);t='Tháp Ma Pháp đồng ý trao đổi giảng viên.'}tone='good'}
  log(t,tone);note={t,tone};afterSheetAction();
}
