function extAct2(x){
  const[a,...r]=x.split(':'),arg=r.join(':');
  if(a==='ac')return acAct(arg);
  if(a==='club')return acJoin(arg);
  if(a==='st')return staffAct(arg);
  if(a==='men')return takeMentee(+arg);
  if(a==='bud'){S.ac.bud=arg;S.done.stbud=1;const t=`Bạn phân bổ ngân sách bộ môn: ${BUDP[arg].n.toLowerCase()}.`;log(t);note={t,tone:''};return afterSheetAction()}
  if(a==='vb'){S.ac.vb=arg;const t=`Bạn nhận phụ trách mảng ${arg==='acad'?'Học thuật':'Điều hành'}.`;log(t,'good');note={t,tone:'good'};return afterSheetAction()}
  if(a==='sch')return schAct(arg);
  if(a==='knm')return knMission();
  if(a==='knq')return knQuit();
  if(a==='hnt')return hnTake(arg);
  if(a==='pt')return ptSet(arg);
  if(a==='ptgo')return ptGo();
  return extAct(x);
}

