/* ===== v18: nền móng liên kết — danh tiếng theo phe, ký ức gia tộc, hậu quả trì hoãn ===== */
const REPB={d:50,n:50,m:50,u:30};
const REPN={d:'Dân thường',n:'Quý tộc',m:'Giới pháp thuật',u:'Thế giới ngầm'};
function repV(k){const F=FAC();if(F[k]==null)F[k]=REPB[k];return F[k]}
function rep(k,v){const F=FAC();if(F[k]==null)F[k]=REPB[k];F[k]=clamp(F[k]+v)}
function reps(o){for(const k in o){if(k==='o'||k==='r')fac(k==='o'?o[k]:0,k==='r'?o[k]:0);else rep(k,o[k])}}
function repYear(){
  if(S.age<12)return;
  const d=repV('d'),n=repV('n'),m=repV('m'),u=repV('u');
  if(d>=75)dsat(1);else if(d<=20){dsat(-2);if(ch(.2))log('Dân trong vùng nhìn bạn bằng ánh mắt thù ghét. Có người ném đá vào cửa nhà bạn ban đêm.','bad')}
  if(S.kd&&S.kd.vassals){if(n<=20)for(const v of S.kd.vassals)v.loy=Math.max(0,v.loy-2);else if(n>=75)for(const v of S.kd.vassals)v.loy=Math.min(100,v.loy+1)}
  if(m>=75&&ch(.4)){mod({magic:1});if(ch(.3))log('Một pháp sư quen biết gửi cho bạn vài trang ghi chép về phép thuật.','magic')}
  if(m<=15&&S.st.magic>=40)S.flags.suspect=(S.flags.suspect||0)+1;
  if(u>=70&&ch(.18)){const g=R(10,40);S.money+=g;log(`Người của thế giới ngầm lặng lẽ gửi bạn ${g} xu "chia phần" từ một phi vụ.`,'')}
  else if(u<=10&&S.money>=150&&ch(.1)){const l=R(10,30);S.money-=l;log(`Trộm đột nhập nhà bạn, lấy mất ${l} xu. Không ai trong giới ngầm chịu nói gì.`,'bad')}
}
/* hoạt động thường ngày tác động phe */
const ACTREP={bless:{d:2,o:1},spell:{m:1},pilgrim:{o:2},alchemy:{m:1},court:{n:1},joust:{n:1},tavern:{u:1},wise:{m:1,o:-1},poach:{n:-1,u:1},rite:{r:2,o:-2},confess:{o:1}};

/* --- ký ức gia tộc: thiện cảm / thù hận với các gia tộc khác, giảm dần qua các đời --- */
function hmem(){if(!S.house.mem)S.house.mem={};return S.house.mem}
function remember(h,v,why){if(!h)return;const M=hmem(),o=M[h]||{v:0,why:'',y:S.year,gen:S.gen,first:S.first};o.v=Math.max(-100,Math.min(100,o.v+v));o.why=why;o.y=S.year;o.gen=S.gen;o.first=S.first;M[h]=o;if(Math.abs(o.v)<5)delete M[h]}
function memYear(){
  const M=hmem();for(const[h,o]of Object.entries(M)){if(S.year-o.y>=3&&ch(.3))o.v+=o.v>0?-1:1;if(Math.abs(o.v)<5)delete M[h]}
  if(S.age<16||S.pend.some(x=>/^lg_/.test(x)))return;
  const old=Object.entries(M).filter(([h,o])=>Math.abs(o.v)>=30&&(o.gen<S.gen||S.year-o.y>=6));
  if(!old.length||!ch(.14))return;
  if(!S.evLast)S.evLast={};if(S.evLast.lg&&S.year-S.evLast.lg<5)return;S.evLast.lg=S.year;
  const[h,o]=pick(old);S.lgH=h;
  S.pend.push(o.v>0?pick(['lg_oath','lg_debt']):(S.house.title>=2?pick(['lg_claim','lg_feud']):'lg_feud'));
}
function memHTML(){
  const M=Object.entries(hmem()).sort((a,b)=>Math.abs(b[1].v)-Math.abs(a[1].v));
  if(!M.length)return'<p class="sec">Ký ức gia tộc</p><p class="note">Chưa có gia tộc nào mang ơn hay mang thù với gia tộc bạn. Những việc bạn làm với các gia tộc khác sẽ được ghi nhớ qua nhiều đời.</p>';
  return'<p class="sec">Ký ức gia tộc</p>'+M.slice(0,8).map(([h,o])=>gRow('',o.v>0?'friends':'heart-break',esc(h),`${o.v>0?'Thiện cảm':'Thù hận'} ${Math.abs(o.v)} · ${esc(o.why)} (đời ${o.first}, năm ${o.y})`,'',false,true,o.v>0?'':'foe')).join('')+'<p class="note">Thiện cảm và thù hận nhạt dần theo thời gian và qua mỗi đời, nhưng con cháu các gia tộc ấy vẫn nhớ.</p>';
}

/* --- hàng đợi hậu quả trì hoãn --- */
function later(id,yrs,d,leg){if(!S.dq)S.dq=[];if(S.dq.some(x=>x.id===id))return;S.dq.push({id,y:S.year+yrs,d:d||{},leg:leg?1:0});if(S.dq.length>8)S.dq.shift()}
function dqd(id){return(S.dqd&&S.dqd[id])||{}}
function dqYear(){
  if(!S.dq||!S.dq.length)return;
  const due=S.dq.filter(x=>x.y<=S.year),keep=S.dq.filter(x=>x.y>S.year);S.dq=keep;
  for(const x of due){const e=EVB[x.id];if(!e)continue;if(!S.dqd)S.dqd={};S.dqd[x.id]=x.d;if(e.c&&!e.c(S))continue;if(!S.pend.includes(x.id))S.pend.push(x.id)}
}

/* --- gọi nhiều chư hầu cùng xuất binh --- */
kdA.summon=i=>{const K=S.kd,v=K.vassals[i];v.sy=S.year;if(v.loy<30){S.pend.push('k_vrefuse');K.vref=i;return`${v.t} ${v.first} viện cớ không xuất binh.`}
  const n=K.vassals.filter(x=>x.sy===S.year).length;K.levy=(K.levy||0)+v.power;v.loy=Math.max(0,v.loy-8);
  let t=`${v.t} ${v.first} dẫn ${v.power*100} quân đến tiếp viện cho chiến dịch năm nay.`;
  if(n>=3){for(const o of K.vassals)o.loy=Math.max(0,o.loy-2);t+=' Triệu tập quá nhiều chư hầu cùng lúc khiến các lãnh chúa bắt đầu than phiền.'}return t};
kdA.summonall=()=>{const K=S.kd;let n=0,p=0;const ref=[];
  K.vassals.forEach((v,i)=>{if(v.sy===S.year)return;v.sy=S.year;if(v.loy<30){ref.push(i);return}n++;p+=v.power;v.loy=Math.max(0,v.loy-10)});
  K.levy=(K.levy||0)+p;if(n>=3)for(const v of K.vassals)v.loy=Math.max(0,v.loy-3);
  if(ref.length){K.vref=ref[0];S.pend.push('k_vrefuse')}
  for(const v of K.vassals)if(v.sur)remember('Gia tộc '+v.sur,-2,'bị triệu tập ra trận');
  return`Lệnh tổng động viên: ${n} chư hầu dẫn ${p*100} quân đến tiếp viện.${ref.length?` ${ref.map(i=>K.vassals[i].t+' '+K.vassals[i].first).join(', ')} viện cớ không xuất binh.`:''}${n>=3?' Các lãnh chúa than phiền vì phải bỏ mùa màng.':''}`};
kdA.rsummon=n=>{const K=S.kd,r=K.realms[n];r.sy=S.year;if(r.rel<-30&&ch(.6)){r.rel-=10;return`${r.ruler} của ${n} lấy cớ biên giới bất ổn, không gửi quân.`}
  const p=Math.max(1,Math.round(r.power*.3));K.levy=(K.levy||0)+p;r.rel-=8;return`${n} gửi ${p*100} quân sang tiếp viện theo nghĩa vụ chư hầu.`};
{const s0=kdA.seize;kdA.seize=i=>{const v=S.kd.vassals[i];if(v&&v.sur)remember('Gia tộc '+v.sur,-45,'bị tước đất');rep('n',-6);return s0(i)}}
{const r0=kdA.reward;kdA.reward=i=>{const v=S.kd.vassals[i];if(v&&v.sur)remember('Gia tộc '+v.sur,6,'được ban thưởng');return r0(i)}}
{const g0=kdA.grant;kdA.grant=i=>{const t=g0(i);const v=S.kd.vassals[S.kd.vassals.length-1];if(v&&v.sur)remember('Gia tộc '+v.sur,25,'được phong tước Nam tước');rep('n',2);return t}}
{const w0=kdA.wedrealm;kdA.wedrealm=n=>{const t=w0(n);remember('Hoàng tộc '+n.replace(RPFX,''),30,'kết thông gia');return t}}
{const e0=endWar;endWar=function(m){if(S.kd)S.kd.levy=0;return e0(m)}}

