/* ===== v18: TRIỀU ĐÌNH HỒNG NGUYỆT — sau khi chiếm ngôi ===== */
const RMST={ruling:'Mới chiếm ngôi',defending:'Đang chống liên quân',stable:'Đã đứng vững',exiled:'Đã mất ngôi'};
const RMPATH={theo:{n:'Thần quyền cứng rắn',d:'Tín đồ cuồng nhiệt hơn mỗi năm, dân thường bất an, Chính giáo thù địch hơn'},mod:{n:'Quân chủ Hồng Nguyệt dung hòa',d:'Chính danh và ổn định tăng dần, tín đồ bớt cuồng nhiệt'},multi:{n:'Liên minh nhiều tín ngưỡng',d:'Thù địch của Chính giáo giảm mạnh, nội bộ giáo phái chia rẽ hơn'}};
const RMPOL={tol:{n:'Khoan dung',d:'Ổn định tăng, thù địch giảm, tín đồ bớt hăng hái, nội bộ dễ chia rẽ'},hard:{n:'Cứng rắn',d:'Tín đồ hăng hái, ổn định giảm, Chính giáo thù địch nhanh hơn'}};
function rmOn(){return!!(S.rm&&S.rm.st!=='exiled'&&S.house.title>=6&&rules())}
function rmNpc(){const sx=pick(['m','f','m']);return{first:pick(nameList(sx,'human')),sur:pick(['Nguyệt Huyết','Quạ Đen','Tro Đỏ','Bóng Đêm','Nến Đen']),sex:sx,amb:R(40,90),loy:R(30,70),npc:1}}
const hpName=R0=>R0.hp?`${R0.hp.first} ${R0.hp.sur}`:'Bạn';
function rmStart(){
  const K=ensureKd();
  S.rm={st:'ruling',y:S.year,faith:70,threat:30,schism:10,pol:null,path:null,crowned:null,league:null,cd:S.year+1,hp:S.flags.her>=3?null:rmNpc(),cou:0,guard:0,walls:0,hosp:0,intel:0,won:0};
  S.flags.hcat=0;S.flags.revealed=1;if(S.world.cat&&S.world.cat.id==='player')S.world.cat=null;S.world.last=S.year;
  const C=ensureCult()||(S.cult={fol:3000,sec:100,cells:3,zeal:40});C.sec=100;
  if(K){K.legit=Math.min(K.legit,40);K.stab=Math.min(K.stab,45);addTroops('inf',R(3,6))}
  reps({o:-25,r:20,n:-15,d:-5});ten(-15);
  log('Hồng Nguyệt nắm chính quyền. Giáo phái không còn hoạt động trong bóng tối; từ nay bạn điều hành cả một triều đình.','magic');
  S.pend.push('rm_crown');
}
function rmK(){return ensureKd()}
function lpow(){const L=S.rm.league;if(!L)return 0;return Math.max(6,L.mem*11+(L.hero?10:0)+(L.saint?6:0)-(L.dmg||0))}
function rmDef(siege){const R0=S.rm,K=rmK();let p=kdPower()+R0.guard*4+(siege?R0.walls*6:R0.walls*2)+R0.faith/12+(R0.league&&R0.league.demon?12:0)+(S.flags.orcAlly?4:0);if(K&&K.stab<30)p*=.85;return Math.round(p)}
function rmLeagueYear(){
  const R0=S.rm,L=R0.league;
  if(L.delay){L.delay--;log('Liên quân Thánh chiến vẫn đang tranh cãi, chưa thể xuất quân.','');return}
  L.ph++;
  if(L.ph===2){S.pend.push('rm_kings');if(L.saint)S.pend.push('rm_saint');if(L.mem>=2&&ch(.4))S.pend.push('rm_north')}
  else if(L.ph===3){R0.st='defending';if(L.hero)S.pend.push('rm_hero');S.pend.push('rm_border')}
  else if(L.ph>=4){if(L.bord==='win'&&ch(.5)){rmPeace(true);return}S.pend.push('rm_siege')}
}
function rmPeace(win){
  const R0=S.rm,K=rmK();R0.league=null;R0.cd=S.year+R(5,8);
  if(win){R0.won++;R0.st='stable';R0.threat=clamp(R0.threat-30);if(K)K.legit=clamp(K.legit+10);R0.faith=clamp(R0.faith+8);S.house.prestige+=150;mod({honor:4});
    announce('Liên quân Thánh chiến tan rã',`Cờ trăng đỏ vẫn tung bay trên tường thành ${S.realm}. Các vương quốc Chính giáo rút quân, và lần đầu tiên, sứ giả của họ gọi bạn là "bệ hạ".`,'night','redmoon');
    log('Vương triều Hồng Nguyệt đứng vững trước liên quân Thánh chiến.','good');
    if(!R0.path)S.pend.push('rm_path')}
}
function rmBattle(mf,siege){
  const R0=S.rm,L=R0.league,K=rmK();
  const our=rmDef(siege)*mf*(.8+Math.random()*.4),their=lpow()*(.8+Math.random()*.4),win=our>their;
  kdLose(win?R(6,14)/100:R(14,26)/100);
  let t='';
  if(win){L.dmg=(L.dmg||0)+Math.round(lpow()*.35);K.morale=Math.min(100,K.morale+8);t=`Quân Hồng Nguyệt (sức mạnh ${Math.round(our)}) đánh bật liên quân (sức mạnh ${Math.round(their)}).`}
  else{K.morale=Math.max(0,K.morale-10);K.stab=clamp(K.stab-6);t=`Liên quân (sức mạnh ${Math.round(their)}) áp đảo quân Hồng Nguyệt (sức mạnh ${Math.round(our)}).`}
  if(K.lead==='king'&&S.age>=16){if(ch(.1)){mod({health:-R(15,30)});t+=' Bạn bị thương khi chỉ huy trên tường thành.'}if(ch(.02)){die('tử trận khi chống liên quân Thánh chiến');return[t,'bad']}}
  return[t,win];
}
function rmShort(){
  const K=rmK(),R0=S.rm;const L=[
    ['Các thương nhân phàn nàn về những trạm tuần tra mới của Hồng Vệ Binh.',()=>{K.treas-=R(5,12)}],
    ['Một thành phố tổ chức đêm hội Hồng Nguyệt, hàng nghìn người thả đèn đỏ lên trời.',()=>{R0.faith=clamp(R0.faith+2)}],
    ['Tỉnh trưởng phía Nam xin thêm lương thực sau một mùa hạn.',()=>{K.food=Math.max(0,K.food-6)}],
    ['Hai tư tế tranh nhau quyền chủ trì lễ trăng tròn ngay giữa thánh đường.',()=>{R0.schism=clamp(R0.schism+3)}],
    ['Một quý tộc Chính giáo từ bỏ lời thề cũ, mang quân đến quy phục.',()=>{addTroops('inf',1);K.legit=clamp(K.legit+1)}],
    ['Kho bạc phát hiện một khoản hụt chi. Quan thủ quỹ thề không biết gì.',()=>{K.treas-=R(10,25)}],
    ['Một đoàn người tị nạn đến biên giới xin được che chở.',()=>{K.food=Math.max(0,K.food-5);rep('d',2)}],
    ['Binh sĩ Hồng Vệ Binh đòi tăng lương.',()=>{K.morale=Math.max(0,K.morale-3)}],
    ['Nhà ngoại giao láng giềng yêu cầu bảo đảm tự do cho người theo Chính giáo.',()=>{R0.threat=clamp(R0.threat+1)}],
    ['Một làng ở biên cương lặng lẽ hạ cờ trăng đỏ mà không cần giao chiến.',()=>{K.stab=clamp(K.stab-2)}]];
  const[t,f]=pick(L);f();log(t,'');
}
function rmYear(){
  const R0=S.rm;if(!R0||R0.st==='exiled')return;
  if(!rmOn()){R0.st='exiled';R0.league=null;return}
  const K=rmK();if(!K)return;
  const C=S.cult||(S.cult={fol:3000,sec:100,cells:3,zeal:40});
  let df=(55-R0.faith)*.1,dt=3,ds=R(0,3)-(R0.cou?2:0);
  if(R0.pol==='hard'){df+=2;dt+=2;K.stab=clamp(K.stab-2)}
  if(R0.pol==='tol'){df-=1;dt-=2;K.stab=clamp(K.stab+2);ds+=1}
  if(R0.path==='theo'){df+=2;dt+=2;K.stab=clamp(K.stab-1)}
  if(R0.path==='mod'){K.legit=clamp(K.legit+2);K.stab=clamp(K.stab+1);df-=1}
  if(R0.path==='multi'){dt-=4;ds+=2}
  if(R0.hosp)K.stab=clamp(K.stab+1);
  if(R0.crowned==='priest')df+=1;
  if(K.treas<0)df-=4;
  if(R0.hp&&R0.hp.npc)ds+=2;
  R0.faith=clamp(R0.faith+df);R0.schism=clamp(R0.schism+ds);if(!R0.league)R0.threat=clamp(R0.threat+dt);
  C.fol=Math.max(500,Math.round(C.fol*(1+(R0.faith-50)/1000)));
  if(R0.guard){K.treas-=R0.guard*10}
  if(R0.faith<25)K.stab=clamp(K.stab-3);
  if(R0.league)rmLeagueYear();
  else if(S.year>=R0.cd&&S.year-R0.y>=1&&R0.threat>=40&&ch(.35+R0.threat/250)){R0.league={ph:1,y:S.year,mem:R(2,4),hero:1,saint:1,dmg:0,demon:0};S.pend.push('rm_bull')}
  if(!S.evLast)S.evLast={};
  const cand=[];
  if(R0.schism>=60)cand.push('rm_split');
  if(R0.schism>=40||(R0.cou&&R0.schism>=25))cand.push('rm_betray');
  if(K.food<25)cand.push('rm_famine');
  if(R0.league&&R0.league.ph>=2&&!R0.league.demon&&!R0.demonAsk)cand.push('rm_demon');
  const ok=cand.filter(e=>!(S.evLast[e]&&S.year-S.evLast[e]<4));
  if(ok.length&&ch(.6)){const e=pick(ok);S.evLast[e]=S.year;S.pend.push(e)}
  if(ch(.5))rmShort();
}
const RMA={
  fest:{n:'Tổ chức Đại lễ Hồng Nguyệt',c:40,ic:'night',d:'Ủng hộ tín đồ +6 · Chính giáo thù địch +3',f:(R0,K)=>{R0.faith=clamp(R0.faith+6);R0.threat=clamp(R0.threat+3);return'Hàng vạn ngọn nến đỏ thắp sáng kinh thành. Tín đồ hát thâu đêm dưới trăng.'}},
  alms:{n:'Phát chẩn và chữa bệnh',c:60,ic:'medical-kit',d:'Ổn định +7 · chính danh +2',f:(R0,K)=>{K.stab=clamp(K.stab+7);K.legit=clamp(K.legit+2);rep('d',4);return'Các tư tế áo đỏ phát bánh mì và thuốc ở khắp các quảng trường. Người nghèo bắt đầu gọi bạn là "người cha của dân".'}},
  syn:{n:'Dung hòa tín ngưỡng',c:25,ic:'friends',d:'Ổn định +5 · ủng hộ tín đồ −3 · thù địch −2',f:(R0,K)=>{K.stab=clamp(K.stab+5);R0.faith=clamp(R0.faith-3);R0.threat=clamp(R0.threat-2);return'Bạn cho phép các nhà thờ Thánh Quang mở cửa trở lại, miễn là treo thêm một ngọn đèn đỏ.'}},
  council:{n:'Thành lập Hội đồng Tư tế',c:50,ic:'court',once:'cou',d:'Một lần · nội bộ bớt chia rẽ mỗi năm, nhưng tư tế có thêm quyền lực',f:(R0,K)=>{R0.cou=1;R0.schism=clamp(R0.schism-8);return'Bảy tư tế cao cấp nhất ngồi quanh bàn đá đen. Từ nay mọi quyết sách tôn giáo đều qua tay họ.'}},
  guard:{n:'Huấn luyện Hồng Vệ Binh',c:80,ic:'w-spear',max:['guard',3],d:'Phòng thủ +4 mỗi cấp · tốn 10 xu/năm mỗi cấp · ổn định −2',f:(R0,K)=>{R0.guard++;K.stab=clamp(K.stab-2);return`Hồng Vệ Binh có thêm một đoàn tinh nhuệ (cấp ${R0.guard}/3). Dân chúng tránh xa khi họ đi qua.`}},
  walls:{n:'Củng cố thành lũy',c:100,ic:'castle',max:['walls',3],d:'Phòng thủ khi bị vây +6 mỗi cấp',f:(R0,K)=>{R0.walls++;return`Thợ đá làm việc ngày đêm. Tường kinh thành dày thêm một lớp (cấp ${R0.walls}/3).`}},
  envoy:{n:'Gửi sứ giả cầu hòa',c:40,ic:'scroll',d:'Làm chậm liên quân hoặc giảm thù địch',f:(R0,K)=>{const L=R0.league;if(L&&L.ph<3){if(ch(.3+K.dip/250)){L.delay=(L.delay||0)+1;return'Sứ giả gieo được nghi ngờ trong liên quân. Họ hoãn xuất quân thêm một năm.'}R0.threat=clamp(R0.threat+2);return'Sứ giả bị đuổi về, râu bị cạo trọc như một lời sỉ nhục.'}const g=R(4,9);R0.threat=clamp(R0.threat-g);return`Sứ giả mang quà sang các nước láng giềng. Thù địch giảm ${g}.`}},
  spy:{n:'Cử điệp viên đến Chính giáo',c:35,ic:'hood',d:'Biết thời điểm liên quân tấn công · có thể phá hoại',f:(R0,K)=>{R0.intel=S.year;const L=R0.league;let t=L?`Điệp viên báo về: ${L.mem} vương quốc trong liên quân${L.hero?', có Anh Hùng':''}${L.saint?', có Thánh Nữ':''}, sức mạnh khoảng ${lpow()}.`:`Điệp viên báo về: Chính giáo ${R0.threat>=40?'đang bàn chuyện lập liên quân':'chưa có động tĩnh lớn'}.`;
    if(L&&L.mem>1&&ch(.3)){L.mem--;t+=' Họ còn kịp đốt kho lương của một nước, khiến nước đó rút khỏi liên minh.'}
    if(ch(.25)){R0.threat=clamp(R0.threat+8);t+=' Nhưng một điệp viên bị bắt và treo cổ ở Thánh quốc.'}return t}},
  gov:{n:'Hội nghị các tỉnh trưởng',c:30,ic:'user-group',d:'Ổn định tăng theo trí tuệ của bạn',f:(R0,K)=>{const g=3+Math.round(S.st.smarts/25);K.stab=clamp(K.stab+g);K.legit=clamp(K.legit+1);return`Bạn nghe các tỉnh trưởng than phiền suốt ba ngày và giải quyết từng việc. Ổn định +${g}.`}},
  hosp:{n:'Sửa nhà thờ cũ thành bệnh xá',c:90,ic:'medical-kit',once:'hosp',d:'Một lần · ổn định +4 và +1 mỗi năm',f:(R0,K)=>{R0.hosp=1;K.stab=clamp(K.stab+4);rep('d',5);return'Những thánh đường bỏ hoang trở thành bệnh xá. Cả người theo Thánh Quang cũng đến chữa bệnh.'}},
  nobles:{n:'Thương lượng với quý tộc cũ',c:60,ic:'shield',d:'Chính danh +8 · tín đồ −4 · chia rẽ +3',f:(R0,K)=>{K.legit=clamp(K.legit+8);R0.faith=clamp(R0.faith-4);R0.schism=clamp(R0.schism+3);rep('n',6);return'Bạn trả lại đất cho vài gia tộc cũ, đổi lấy lời thề trung thành. Các tư tế cuồng tín lẩm bẩm phản đối.'}},
  claim:{n:'Giành lại chức Đại tư tế',c:80,ic:'night',d:'Tranh với Đại tư tế đương nhiệm · thất bại làm nội bộ chia rẽ',req:R0=>!!R0.hp,f:(R0,K)=>{if(ch(.25+R0.faith/250+S.st.magic/400+(S.flags.her>=2?.1:0))){const o=R0.hp;R0.hp=null;S.flags.her=3;S.flags.redpope=1;R0.schism=clamp(R0.schism+5);if(!hasItem('h_raven'))gainItem('h_raven');return`Hội đồng tư tế bỏ phiếu phế ${o.first} ${o.sur}. Bạn khoác áo choàng Đại tư tế, vương quyền và giáo quyền lại về một mối.`}R0.schism=clamp(R0.schism+10);R0.hp.loy=Math.max(0,R0.hp.loy-15);return`${R0.hp.first} ${R0.hp.sur} thắng trong cuộc bỏ phiếu. Giáo phái giờ chia làm hai phe.`}}
};
const RMLIM=3;
function rmWhy(k){const A=RMA[k],R0=S.rm,K=rmK();if(!K)return'Chưa có triều đình';if(S.age<16)return'Nhiếp chính đang điều hành';if(A.req&&!A.req(R0))return'Bạn đang là Đại tư tế';if(A.once&&R0[A.once])return'Đã làm';if(A.max&&R0[A.max[0]]>=A.max[1])return'Đã tối đa';if(S.done['rm_'+k])return'Đã làm năm nay';if((S.done.rmn||0)>=RMLIM)return`Đã dùng hết ${RMLIM} quyết sách năm nay`;if(K.treas<A.c)return`Cần ${A.c} xu ngân khố`;return''}
function rmAct(k){
  if(!rmOn())return;
  if(k.startsWith('ed:')){const p=k.slice(3);if(S.done.rmed||S.age<16)return;S.done.rmed=1;S.rm.pol=p==='none'?null:p;const t=p==='none'?'Bạn bãi bỏ sắc lệnh tín ngưỡng.':`Bạn ban sắc lệnh tín ngưỡng ${RMPOL[p].n.toLowerCase()}. ${RMPOL[p].d}.`;log(t);note={t,tone:''};return afterSheetAction()}
  const A=RMA[k];if(!A||rmWhy(k))return;
  const K=rmK();K.treas-=A.c;S.done['rm_'+k]=1;S.done.rmn=(S.done.rmn||0)+1;
  const t=A.f(S.rm,K);log(t,'');note={t,tone:''};afterSheetAction();
}
function rmView(){
  const R0=S.rm,K=rmK(),C=S.cult||{fol:0},L=R0.league,dis=!S.alive;
  let b=`<div class="row"><span class="ri foe">${ic('night',24)}</span><div><b>${prefix()}${esc(S.first)}</b><small>${RMST[R0.st]} · năm thứ ${S.year-R0.y+1} · Đại tư tế: ${R0.hp?esc(hpName(R0)):'chính bạn'}${R0.crowned?` · đăng quang theo nghi thức ${R0.crowned==='priest'?'giáo quyền':'vương quyền'}`:''}</small></div></div>`;
  b+=statGrid([['Chính danh',`${K.legit}/100`],['Ổn định',`${K.stab}/100`],['Ủng hộ tín đồ',`${R0.faith}/100`],['Ngân khố',`${K.treas} xu`],['Quân lực',`${rmDef(false)} · thủ thành ${rmDef(true)}`],['Thù địch Chính giáo',`${R0.threat}/100`],['Chia rẽ nội bộ',`${R0.schism}/100`],['Tín đồ',C.fol.toLocaleString('vi-VN')]]);
  if(L){const seen=R0.intel===S.year||L.ph>=3;b+=`<p class="note bad">Liên quân Thánh chiến · ${['','Tin lan truyền','Tập hợp liên quân','Chiến tranh','Vây hãm kinh đô'][Math.min(4,L.ph)]}${seen?` · ${L.mem} vương quốc${L.hero?' · có Anh Hùng':''}${L.saint?' · có Thánh Nữ':''} · sức mạnh khoảng ${lpow()}`:' · cử điệp viên để biết lực lượng địch'}.</p>`}
  else if(R0.threat>=40)b+=`<p class="note bad">Chính giáo đang tìm cách lập liên quân chống lại bạn${S.year<R0.cd?` (sớm nhất năm ${R0.cd})`:''}.</p>`;
  if(R0.schism>=45)b+='<p class="note bad">Nội bộ giáo phái chia rẽ nặng. Có tư tế đang âm mưu.</p>';
  b+=`<p class="note">Sắc lệnh tín ngưỡng: ${R0.pol?RMPOL[R0.pol].n:'chưa ban'}${R0.path?` · đường lối: ${RMPATH[R0.path].n}`:''}${R0.guard?` · Hồng Vệ Binh cấp ${R0.guard}`:''}${R0.walls?` · thành lũy cấp ${R0.walls}`:''}.</p>`;
  b+=`<p class="sec">Quyết sách · còn ${Math.max(0,RMLIM-(S.done.rmn||0))}/${RMLIM} lượt năm nay · chi từ ngân khố</p>`;
  for(const[k,A]of Object.entries(RMA)){if(A.req&&!A.req(R0))continue;const why=rmWhy(k);b+=gRow(`data-x="rm:${k}"`,A.ic,A.n,why||A.d,A.c?`${A.c} xu`:'',!!why||dis)}
  b+='<p class="sec">Sắc lệnh tín ngưỡng · đổi một lần mỗi năm</p>';
  for(const[p,P]of Object.entries(RMPOL))b+=gRow(`data-x="rm:ed:${p}"`,'scroll',P.n,P.d,R0.pol===p?pill('ĐANG DÙNG',2):'',dis||R0.pol===p||!!S.done.rmed||S.age<16);
  if(R0.pol)b+=gRow('data-x="rm:ed:none"','scroll','Bãi bỏ sắc lệnh','Không theo đường lối nào','',dis||!!S.done.rmed||S.age<16);
  b+='<p class="sec">Triều chính</p>'+gRow('data-open="kd"','crown','Trị Vì Vương Quốc','Quân đội, chiến tranh, ngoại giao, chư hầu','',false);
  b+='<p class="note">Sau khi chiếm ngôi, giáo phái không còn truyền đạo bí mật hay xin tiền dâng cúng trong vương quốc của bạn. Mọi khoản thu chi đều đi qua ngân khố quốc gia.</p>';
  return['Triều đình Hồng Nguyệt',b,'act'];
}
const RM_EV=[
 {id:'rm_crown',queued:true,big:true,art:'crown',c:s=>!!s.rm&&rmOn(),title:'Lễ đăng quang Huyết Nguyệt',
  text:s=>`Thánh đường lớn của ${s.realm} treo cờ trăng đỏ. Các tư tế dâng lên hai thứ: vương miện của vị vua cũ và chiếc mũ quạ của Đại tư tế. Bạn sẽ đăng quang theo nghi thức nào?`,
  ch:[{t:'Nghi thức giáo quyền: Giáo chủ-vua',f:s=>{const R0=s.rm,K=rmK();R0.crowned='priest';R0.faith=clamp(R0.faith+12);K.legit=clamp(K.legit-5);R0.threat=clamp(R0.threat+5);return['Bạn đội cả hai thứ lên đầu. Tín đồ gào thét tên bạn như gọi một vị thần.','magic']}},
      {t:'Nghi thức vương quyền: vị vua bảo hộ Hồng Nguyệt',f:s=>{const R0=s.rm,K=rmK();R0.crowned='king';K.legit=clamp(K.legit+10);R0.faith=clamp(R0.faith-8);R0.schism=clamp(R0.schism+5);rep('n',4);return['Bạn đội vương miện, để chiếc mũ quạ trên bàn thờ. Quý tộc thở phào, còn các tư tế nhìn nhau.','good']}},
      {t:'Lễ giản dị, mời cả quý tộc cũ (60 xu ngân khố)',req:s=>rmK().treas>=60,f:s=>{const R0=s.rm,K=rmK();K.treas-=60;K.legit=clamp(K.legit+5);K.stab=clamp(K.stab+5);R0.faith=clamp(R0.faith-4);R0.threat=clamp(R0.threat-3);R0.crowned='king';return'Bạn mời cả những gia tộc từng chống lại mình. Nhiều người đến, vì tò mò hơn là trung thành.'}}]},
 {id:'rm_bull',queued:true,big:true,art:'holy',c:s=>!!s.rm&&!!s.rm.league,title:'Giáo hoàng ban Đại Sắc Lệnh',
  text:s=>`Từ Thánh quốc, Giáo hoàng tuyên bố ${s.realm} là "đất của quỷ dữ". Mọi tín hữu Thánh Quang được lệnh cầm vũ khí. ${s.rm.league.mem} vương quốc đã nhận chiếu chỉ, và người ta nói Anh Hùng cùng Thánh Nữ sẽ dẫn đầu.`,
  ch:[{t:'Đe dọa: treo cờ trăng đỏ dọc biên giới',f:s=>{s.rm.faith=clamp(s.rm.faith+6);s.rm.threat=clamp(s.rm.threat+5);return'Cờ đỏ phấp phới trên mọi tháp canh. Tín đồ hăng hái, còn các nước láng giềng càng thêm lo sợ.'}},
      {t:'Gửi sứ giả thương lượng (40 xu ngân khố)',req:s=>rmK().treas>=40,f:s=>{const K=rmK();K.treas-=40;if(ch(.25+K.dip/250)){s.rm.league.delay=(s.rm.league.delay||0)+1;return['Sứ giả của bạn khiến hai vị vua cãi nhau ngay trong buổi họp. Liên quân hoãn lại một năm.','good']}s.rm.threat=clamp(s.rm.threat+3);return['Giáo hoàng không tiếp sứ giả.','bad']}},
      {t:'Gia cố phòng thủ (80 xu ngân khố)',req:s=>rmK().treas>=80&&s.rm.walls<3,f:s=>{rmK().treas-=80;s.rm.walls++;return`Thợ đá được gọi về kinh thành. Thành lũy lên cấp ${s.rm.walls}.`}}]},
 {id:'rm_kings',queued:true,big:true,art:'crown',c:s=>!!s.rm&&!!s.rm.league,title:'Hội nghị các Vị Vua',
  text:s=>`Vua của ${s.rm.league.mem} vương quốc họp ở ${pick(['Thánh quốc Lumaris','pháo đài Đá Trắng','tu viện Aster'])} bàn chuyện chia quân và chia đất của bạn sau chiến thắng.`,
  ch:[{t:'Gửi thư và quà cho từng vị vua (60 xu ngân khố)',req:s=>rmK().treas>=60,f:s=>{const K=rmK();K.treas-=60;const L=s.rm.league;if(L.mem>1&&ch(.35+K.dip/300)){L.mem--;return['Một vị vua lấy cớ con trai ốm nặng, rút khỏi liên quân.','good']}return'Các vị vua nhận quà nhưng không đổi ý.'}},
      {t:'Gián điệp gieo nghi kỵ',f:s=>{const K=rmK(),L=s.rm.league,sp=K.council?K.council.spy.skill:40;if(L.mem>1&&ch(.3+sp/250)){L.mem--;return['Thư giả mạo khiến hai vị vua nghi nhau phản bội. Một nước rút quân.','good']}s.rm.threat=clamp(s.rm.threat+8);return['Gián điệp bị bắt. Liên quân càng quyết tâm hơn.','bad']}},
      {t:'Gửi vàng mua chuộc (150 xu ngân khố)',req:s=>rmK().treas>=150,f:s=>{const K=rmK(),L=s.rm.league;K.treas-=150;const n=Math.min(L.mem-1,ch(.6)?2:1);L.mem-=n;K.legit=clamp(K.legit-3);return n?[`Vàng của bạn mua được sự vắng mặt của ${n} vương quốc.`,'good']:'Vàng không đủ để lay chuyển ai.'}},
      {t:'Mặc kệ họ',f:()=>'Bạn để các vị vua tự tranh cãi với nhau.'}]},
 {id:'rm_saint',queued:true,big:true,art:'holy',c:s=>!!s.rm&&!!s.rm.league&&s.rm.league.saint,title:'Thánh Nữ đến biên giới',
  text:s=>`Thánh Nữ ${pick(FN)} dựng lều ở làng biên giới, chữa bệnh miễn phí cho dân của bạn. Mỗi ngày lại có thêm người bỏ dấu trăng đỏ để đeo thánh giá.`,
  ch:[{t:'Để bà chữa bệnh cho dân',f:s=>{rmK().stab=clamp(rmK().stab+4);s.rm.faith=clamp(s.rm.faith-8);rep('d',3);return'Dân được chữa bệnh. Nhưng trong lòng họ, ánh sáng của bà sáng hơn trăng đỏ.'}},
      {t:'Đóng cửa biên giới',f:s=>{rmK().stab=clamp(rmK().stab-4);s.rm.threat=clamp(s.rm.threat+5);s.rm.faith=clamp(s.rm.faith+3);rep('d',-3);return['Hồng Vệ Binh dỡ lều của Thánh Nữ. Người bệnh bị đuổi về.','bad']}},
      {t:'Mời bà vào cung đối thoại',f:s=>{if(ch(.3+s.st.smarts/250+s.st.honor/400)){s.rm.league.saint=0;rmK().stab=clamp(rmK().stab+3);return['Hai người nói chuyện suốt đêm. Sáng ra, Thánh Nữ tuyên bố sẽ không dẫn quân đánh một vị vua biết lắng nghe.','good']}s.rm.faith=clamp(s.rm.faith-5);return['Bà lặng lẽ nghe, rồi đứng dậy: "Tôi sẽ cầu nguyện cho linh hồn người." Cuộc gặp lan truyền như một thất bại của bạn.','bad']}}]},
 {id:'rm_north',queued:true,big:true,art:'scroll',c:s=>!!s.rm&&!!s.rm.league&&s.rm.league.mem>=2,title:'Vương quốc phương Bắc xin hòa',
  text:'Một vương quốc trong liên quân bí mật gửi sứ giả: họ sẽ rút quân nếu được mở cửa thương mại và trao trả tù binh.',
  ch:[{t:'Chấp nhận (50 xu ngân khố)',req:s=>rmK().treas>=50,f:s=>{const K=rmK();K.treas-=50;s.rm.league.mem--;K.dip=Math.min(100,K.dip+5);return['Đoàn thương nhân phương Bắc trở lại chợ kinh thành. Liên quân mất một nước.','good']}},
      {t:'Đòi họ trả tiền chuộc tù binh',f:s=>{if(ch(.4)){rmK().treas+=80;s.rm.league.mem--;return['Họ trả 80 xu và rút quân trong im lặng.','good']}return['Sứ giả bỏ về, cho rằng bạn tham lam.','bad']}},
      {t:'Từ chối',f:s=>{s.rm.faith=clamp(s.rm.faith+3);return'"Không thương lượng với kẻ thù của Mặt Trăng Đỏ." Tín đồ tán thưởng.'}}]},
 {id:'rm_hero',queued:true,big:true,art:'sword',c:s=>!!s.rm&&!!s.rm.league&&s.rm.league.hero,title:'Anh Hùng mang Thánh Kiếm',
  text:s=>`${pick(MN)} ${pick(['Mắt Ưng','Tóc Bạc','Người Mang Ánh Sáng'])} giương thanh kiếm sáng trước liên quân, tuyên bố sẽ "giải phóng" ${s.realm}. Binh sĩ Chính giáo tin rằng hắn không thể bị đánh bại.`,
  ch:[{t:'Đích thân đối đầu',req:s=>s.age>=16,f:s=>{const dr=s.dragon&&s.dragon.alive&&['adult','ancient'].includes(drStage(s.dragon))?.1:0;if(heroNpcFight(.05+dr)){s.rm.league.hero=0;s.house.prestige+=80;mod({magic:4});s.rm.faith=clamp(s.rm.faith+8);return['Thanh Thánh Kiếm vỡ làm đôi trên tường thành. Liên quân mất đi niềm tin lớn nhất.','magic']}if(ch(.3)){die('dưới Thánh Kiếm của Anh Hùng');return['Ánh sáng từ thanh kiếm xuyên qua lớp giáp của bạn.','bad']}mod({health:-30});return['Anh Hùng đánh bạn ngã khỏi tường thành. Hồng Vệ Binh liều chết kéo bạn về.','bad']}},
      {t:'Thuyết phục Anh Hùng',f:s=>{if(ch(.2+s.st.smarts/300+s.st.honor/300)){s.rm.league.hero=0;return['Bạn cho Anh Hùng thấy những bệnh xá và những đứa trẻ được ăn no dưới trăng đỏ. Hắn cắm kiếm xuống đất và rời liên quân.','good']}s.rm.threat=clamp(s.rm.threat+5);return['Anh Hùng không nghe hết câu đã quay ngựa.','bad']}},
      {t:'Sai Hồng Vệ Binh ám sát',f:s=>{if(ch(.3+s.rm.guard*.08)){s.rm.league.hero=0;mod({honor:-10});s.rm.threat=clamp(s.rm.threat+10);return['Anh Hùng gục xuống trong lều. Liên quân thề báo thù.','bad']}s.rm.guard=Math.max(0,s.rm.guard-1);return['Cả đội sát thủ bị Thánh Kiếm chém gục.','bad']}},
      {t:'Phớt lờ',f:()=>'Bạn cho rằng một người không thể quyết định cả cuộc chiến.'}]},
 {id:'rm_border',queued:true,big:true,art:'banner',c:s=>!!s.rm&&!!s.rm.league,title:'Liên quân vượt biên giới',
  text:s=>`Liên quân (sức mạnh khoảng ${lpow()}) tràn qua biên giới. Quân Hồng Nguyệt có sức mạnh ${rmDef(false)} khi dã chiến, ${rmDef(true)} khi giữ thành.`,
  ch:[{t:'Nghênh chiến ở biên cương',f:s=>{const[t,w]=rmBattle(1,false);if(!S.alive)return[t,'bad'];s.rm.league.bord=w?'win':'lose';return[t+(w?' Liên quân phải lùi về chờ viện binh.':' Quân ta rút về kinh thành.'),w?'good':'bad']}},
      {t:'Phục kích hậu cần địch',f:s=>{const[t,w]=rmBattle(.85,false);if(!S.alive)return[t,'bad'];const L=s.rm.league;L.bord=w?'win':'lose';if(w)L.dmg+=6;return[t+(w?' Đoàn xe lương của liên quân cháy rực cả một thung lũng.':' Đoàn phục kích bị phát hiện.'),w?'good':'bad']}},
      {t:'Rút về giữ kinh đô',f:s=>{const K=rmK();s.rm.league.bord='lose';K.provs=Math.max(1,K.provs-1);K.stab=clamp(K.stab-6);return['Bạn bỏ lại các tỉnh biên giới để dồn quân về kinh thành.','bad']}}]},
 {id:'rm_siege',queued:true,big:true,art:'castle',c:s=>!!s.rm&&!!s.rm.league,title:'Cuộc vây hãm Kinh Đô',
  text:s=>`Liên quân bao vây kinh thành (sức mạnh khoảng ${lpow()}). Quân giữ thành: ${rmDef(true)}. Trong thành, lương thực còn ${rmK().food}.`,
  ch:[{t:'Tử thủ',f:s=>{const[t,w]=rmBattle(1.15,true);if(!S.alive)return[t,'bad'];if(w){rmPeace(true);return[t+' Liên quân rút lui trong tuyết đầu mùa.','good']}S.pend.push('rm_fall');return[t+' Cổng thành vỡ.','bad']}},
      {t:'Mở cổng phá vây',f:s=>{const[t,w]=rmBattle(ch(.5)?1.3:.8,true);if(!S.alive)return[t,'bad'];if(w){rmPeace(true);return[t+' Cuộc phá vây táo bạo khiến liên quân tan tác.','good']}S.pend.push('rm_fall');return[t+' Đoàn phá vây bị cắt đứt đường lui.','bad']}},
      {t:'Rút lui về núi',f:s=>{S.pend.push('rm_fall');return['Bạn bỏ kinh thành trong đêm.','bad']}},
      {t:'Đầu hàng',f:s=>{S.pend.push('rm_fall');return['Bạn sai người kéo cờ trắng lên tháp chuông.','bad']}}]},
 {id:'rm_fall',queued:true,big:true,art:'skull',c:s=>!!s.rm&&rmOn(),title:'Đêm Hồng Nguyệt Tàn Lụi',
  text:'Kinh thành thất thủ. Cờ trăng đỏ bị kéo xuống và đốt trên quảng trường. Bạn chỉ còn vài người thân tín bên cạnh.',
  ch:[{t:'Chạy trốn',f:s=>{rmExile('flee');return[`Bạn trốn sang ${s.realm} trong bộ áo nông dân, mang theo một nhúm tín đồ trung thành.`,'bad']}},
      {t:'Thoái vị, trao quyền cho Hội đồng Tư tế',f:s=>{rmExile('abdicate');return['Bạn ký chiếu thoái vị. Liên quân chấp nhận để gia tộc bạn giữ một vùng đất nhỏ làm Bá tước.','bad']}},
      {t:'Đàm phán ân xá',f:s=>{if(ch(.35+s.st.honor/300+s.st.smarts/400)){rmExile('amnesty');return['Bạn quỳ trước Giáo hoàng, từ bỏ Mặt Trăng Đỏ. Gia tộc bạn được giữ tước Nam tước và mạng sống.','bad']}die('bị hỏa thiêu trước thánh đường sau khi đầu hàng');return['Giáo hoàng không tha cho kẻ dị giáo.','bad']}}]},
 {id:'rm_path',queued:true,big:true,art:'night',c:s=>!!s.rm&&rmOn()&&!s.rm.path,title:'Con đường của vương triều',
  text:'Liên quân đã rút. Hội đồng tư tế, quý tộc và các sứ thần đều chờ bạn quyết định vương triều Hồng Nguyệt sẽ đi về đâu.',
  ch:Object.entries(RMPATH).map(([k,P])=>({t:`${P.n}`,f:s=>{s.rm.path=k;if(k==='multi'){s.rm.threat=clamp(s.rm.threat-15);rep('m',5)}if(k==='theo')s.rm.faith=clamp(s.rm.faith+10);if(k==='mod')rep('n',5);return`Bạn chọn đường lối: ${P.n.toLowerCase()}. ${P.d}.`}}))},
 {id:'rm_betray',queued:true,big:true,art:'dagger',c:s=>!!s.rm&&rmOn(),title:'Đại tư tế phản bội',
  text:s=>s.rm.hp?`Đại tư tế ${hpName(s.rm)} bí mật gặp các tướng lĩnh. Tin đồn nói ông ta muốn đặt một vị vua bù nhìn lên ngai.`:'Một tư tế cao cấp đang vận động Hội đồng phế bạn khỏi chức Đại tư tế, nói rằng một vị vua không thể vừa cầm kiếm vừa giữ nến thánh.',
  ch:[{t:'Điều tra trong bóng tối',f:s=>{const K=rmK(),sp=K.council?K.council.spy.skill:40;if(ch(.35+sp/250)){s.rm.schism=clamp(s.rm.schism-15);if(s.rm.hp)s.rm.hp=rmNpc();return['Gián điệp của bạn thu được thư từ âm mưu. Kẻ cầm đầu bị bắt trước khi kịp ra tay.','good']}s.rm.schism=clamp(s.rm.schism+5);return['Không tìm được chứng cứ. Âm mưu vẫn âm ỉ.','bad']}},
      {t:'Nhượng bớt quyền lực',f:s=>{s.rm.schism=clamp(s.rm.schism-10);s.rm.faith=clamp(s.rm.faith-5);if(!s.rm.hp){s.rm.hp=rmNpc();s.flags.redpope=0;return['Bạn nhường chức Đại tư tế cho người khác. Giáo quyền và vương quyền từ nay tách đôi.','bad']}s.rm.hp.loy=Math.min(100,s.rm.hp.loy+20);return'Bạn trao cho Đại tư tế thêm ghế trong Hội đồng. Ông ta tạm hài lòng.'}},
      {t:'Phế truất và xử tử',f:s=>{const K=rmK();mod({honor:-5});if(ch(.55)){s.rm.schism=clamp(s.rm.schism-20);K.stab=clamp(K.stab-5);if(s.rm.hp)s.rm.hp=rmNpc();return['Kẻ phản bội bị treo cổ trước thánh đường. Không ai dám thì thầm nữa.','good']}s.rm.schism=clamp(s.rm.schism+10);K.tw=Math.max(K.tw||0,2);return['Kẻ phản bội trốn thoát và kêu gọi nổi loạn. Nội chiến đến gần.','bad']}}]},
 {id:'rm_split',queued:true,big:true,art:'night',c:s=>!!s.rm&&rmOn(),title:'Giáo phái chia hai',
  text:'Phe cực đoan đòi thiêu sống những người còn giữ thánh giá. Phe khoan dung đòi mở cửa nhà thờ cũ. Hai bên đã đổ máu trên bậc thềm thánh đường.',
  ch:[{t:'Ngả về phe cực đoan',f:s=>{const R0=s.rm,K=rmK();R0.pol='hard';R0.faith=clamp(R0.faith+10);K.stab=clamp(K.stab-8);R0.threat=clamp(R0.threat+6);R0.schism=clamp(R0.schism-20);return['Những giàn hỏa thiêu dựng lên. Tín đồ cuồng nhiệt, dân thường run sợ.','bad']}},
      {t:'Ngả về phe khoan dung',f:s=>{const R0=s.rm,K=rmK();R0.pol='tol';K.stab=clamp(K.stab+6);R0.faith=clamp(R0.faith-10);R0.schism=clamp(R0.schism-20);return['Bạn ra lệnh mở lại các nhà thờ cũ. Phe cực đoan rời kinh thành trong giận dữ.','good']}},
      {t:'Đứng ra làm trung gian',f:s=>{if(ch(.35+s.st.smarts/250)){s.rm.schism=clamp(s.rm.schism-30);return['Bạn soạn một bản giáo luật mà cả hai phe đều chấp nhận được.','good']}s.rm.schism=clamp(s.rm.schism+5);s.rm.faith=clamp(s.rm.faith-3);return['Cả hai phe đều cho rằng bạn đứng về phía bên kia.','bad']}}]},
 {id:'rm_famine',queued:true,big:true,art:'skull',c:s=>!!s.rm&&rmOn(),title:'Nạn đói dưới trăng đỏ',
  text:'Mùa màng thất bát. Dân chúng tụ tập trước cung điện, giơ những chiếc bát rỗng. Có người hô: "Mặt Trăng Đỏ không làm no bụng!"',
  ch:[{t:'Mở kho cứu dân (80 xu ngân khố)',req:s=>rmK().treas>=80,f:s=>{const K=rmK();K.treas-=80;K.food+=30;K.stab=clamp(K.stab+6);s.rm.faith=clamp(s.rm.faith+3);rep('d',4);return['Bánh mì được phát ở mọi quảng trường.','good']}},
      {t:'Thu mua lương từ phương xa (120 xu ngân khố)',req:s=>rmK().treas>=120,f:s=>{const K=rmK();K.treas-=120;K.food+=55;return'Những chuyến thuyền lương cập bến kịp trước mùa đông.'}},
      {t:'Sai Hồng Vệ Binh trưng thu',f:s=>{const K=rmK();K.food+=30;K.stab=clamp(K.stab-12);s.rm.faith=clamp(s.rm.faith-6);rep('d',-6);return['Lính áo đỏ đi từng nhà vét thóc. Lòng dân nguội lạnh.','bad']}}]},
 {id:'rm_demon',queued:true,big:true,art:'demon',c:s=>!!s.rm&&rmOn(),title:'Sứ giả của Ma Vương',
  text:'Một kẻ mặc áo choàng xám, đôi mắt đỏ như than, xin yết kiến. "Chủ nhân ta ghét Thánh Quang như ngài. Ngài ấy sẵn lòng giúp, đổi lấy một lời hứa."',
  ch:[{t:'Nhận viện trợ',f:s=>{s.rm.demonAsk=1;if(s.rm.league)s.rm.league.demon=1;s.rm.threat=clamp(s.rm.threat+15);mod({honor:-10});later('rm_demondebt',3);return['Đêm đó, bóng tối phủ kín doanh trại liên quân. Nhưng bạn biết món nợ này rồi sẽ phải trả.','magic']}},
      {t:'Từ chối',f:s=>{s.rm.demonAsk=1;mod({honor:3});s.rm.faith=clamp(s.rm.faith+2);return'"Mặt Trăng Đỏ không quỳ trước ai." Sứ giả mỉm cười rồi tan vào bóng tối.'}},
      {t:'Bắt sứ giả, gửi cho Giáo hoàng làm quà',f:s=>{s.rm.demonAsk=1;s.rm.threat=clamp(s.rm.threat-10);s.rm.faith=clamp(s.rm.faith-6);return['Giáo hoàng nhận "món quà" và im lặng rất lâu. Tín đồ cuồng tín thì cho rằng bạn đã yếu lòng.','good']}}]},
 {id:'rm_demondebt',queued:true,big:true,art:'demon',c:s=>!!s.rm&&rmOn(),title:'Ma Vương đòi nợ',
  text:'Sứ giả áo xám quay lại, lần này không xin yết kiến. "Đã đến lúc trả nợ."',
  ch:[{t:'Trả bằng vàng (200 xu ngân khố)',req:s=>rmK().treas>=200,f:s=>{rmK().treas-=200;return'Bạn mở kho. Vàng biến mất cùng sứ giả.'}},
      {t:'Trả bằng một tỉnh biên giới',req:s=>rmK().provs>1,f:s=>{const K=rmK();K.provs--;K.stab=clamp(K.stab-8);K.legit=clamp(K.legit-6);return['Một tỉnh biên giới chìm trong sương đen. Không ai dám đặt chân đến đó nữa.','bad']}},
      {t:'Từ chối trả nợ',f:s=>{if(ch(.5)){mod({health:-R(20,35)});rmK().stab=clamp(rmK().stab-10);return['Lời nguyền giáng xuống. Bạn ho ra máu suốt một mùa, và cả kinh thành mất ngủ vì ác mộng.','bad']}return'Sứ giả cười lớn rồi biến mất. Có lẽ Ma Vương còn bận việc khác.'}}]}
];
function rmExile(kind){
  const R0=S.rm,K=S.kd;R0.st='exiled';R0.league=null;S.flags.redpope=0;
  if(kind==='flee'){S.house.title=0;delete S.house.dom;S.kd=null;S.flags.king=0;const old=S.realm;S.realm=pick(REALMS.filter(r=>r!==old));S.money=Math.floor(Math.max(S.money,0)/2);const C=ensureCult();if(C){C.fol=Math.round(C.fol/4);C.sec=40;C.cells=1}reps({o:-10,n:-10})}
  else if(kind==='abdicate'){S.house.title=4;S.kd=null;S.flags.king=0;ensureDom();mod({honor:5})}
  else{S.house.title=2;S.kd=null;S.flags.king=0;S.flags.her=0;S.flags.revealed=0;delete S.cult;ensureDom();reps({o:15,r:-30})}
  S.world.last=S.year;
  announce('Hồng Nguyệt sụp đổ',`Vương triều trăng đỏ của ${S.first} ${S.surname} kết thúc sau ${S.year-R0.y+1} năm.`,'skull','inquisition');
  log(`Vương triều Hồng Nguyệt sụp đổ sau ${S.year-R0.y+1} năm.`,'bad');
}

/* ===== v18: NUÔI RỒNG TỪ TRỨNG + chuỗi Huyết Ước của Long Vương ===== */
const DRSTG={egg:'Trứng rồng',baby:'Rồng non',young:'Rồng trẻ',adult:'Rồng trưởng thành',ancient:'Cổ long'};
const DREL={fire:'Lửa',frost:'Băng',storm:'Sấm',shadow:'Bóng tối'};
const DRPER={gentle:'Hiền hòa',curious:'Hiếu kỳ',proud:'Kiêu hãnh',fierce:'Hung dữ',loyal:'Trung thành'};
const DRROLE={pet:'Bạn đồng hành',guard:'Canh giữ lâu đài',war:'Chiến long',free:'Tự do bay lượn',lent:'Đang ở lâu đài khác'};
const DRNAMES=['Than Hồng','Sương Bạc','Tro Đỏ','Ember','Đuôi Sắt','Bão Xám','Ngọc Lửa','Ashkar','Mây Đen','Vảy Đồng','Kael','Ignis','Lửa Nhỏ','Nyx','Thạch Lân','Rubra'];
function drAge(D){return D.hy==null?-1:S.year-D.hy}
function drStage(D){if(!D||!D.alive)return'dead';if(D.hy==null)return'egg';const a=drAge(D);return a<=2?'baby':a<=6?'young':a<=14?'adult':'ancient'}
const drBig=D=>['young','adult','ancient'].includes(drStage(D));
const drGrown=D=>['adult','ancient'].includes(drStage(D));
function newDragon(o={}){return{name:'Rồng con',ey:S.year,hy:null,el:pick(Object.keys(DREL)),per:pick(Object.keys(DRPER)),hp:80,hunger:25,trust:45,bond:30,tr:{fly:0,obey:0,fire:0,hunt:0},inj:0,away:0,role:'pet',alive:true,abuse:0,q:1,flags:{},...o}}
function drSync(){const D=S.dragon;const on=D&&D.alive&&drBig(D)&&D.role!=='free'&&D.role!=='lent'&&!(D.inj>S.year)&&!(D.away>S.year);if(on)S.own.dragon=1;else delete S.own.dragon}
function drHurt(D,y){D.inj=Math.max(D.inj||0,S.year+y);D.hp=clamp(D.hp-15*y)}
function drGone(why,ret){const D=S.dragon;if(!D)return;S.dragon=null;delete S.own.dragon;if(ret)later('dr_return',R(5,12),{name:D.name,hate:D.abuse>=2||D.trust<20?1:0},1);log(why,'magic')}
const DRSHORT={baby:['Rồng non tha về một chiếc giày, nhất quyết không trả.','Rồng non cuộn tròn bên lò sưởi, cả căn phòng ấm hơn thường lệ.','Rồng non tranh chỗ ngủ với con chó săn trong nhà.','Rồng non làm cháy một cọc rơm. Bạn phải trả 2 xu sửa lại.'],
  young:['Dân làng dâng cho rồng một giỏ cá, mong nó đừng ăn cừu.','Rồng gầm lên mỗi khi nghe tiếng chuông nhà thờ.','Một đứa trẻ vẽ hình con rồng của bạn lên tường thành.','Một bên cánh rồng trầy xước sau chuyến bay quanh núi.'],
  adult:['Thợ rèn xin một chiếc vảy rụng tự nhiên để nghiên cứu.','Bóng rồng lướt qua cánh đồng, lũ quạ bay tán loạn.','Rồng nằm phơi nắng trên mái tháp, cả vùng nhìn thấy từ xa.'],
  ancient:['Con rồng già ngủ suốt mùa đông, hơi thở làm tan tuyết quanh lâu đài.','Các học giả đến xin ghi chép tiếng gầm của con cổ long.']};
function drYear(){
  if(S.own.dragon&&!S.dragon)S.dragon=newDragon({hy:S.year-8,trust:30,bond:20,tr:{fly:50,obey:30,fire:40,hunt:30},q:2,name:pick(DRNAMES)});
  const D=S.dragon;if(!D)return;
  if(!D.alive){S.dragon=null;drSync();return}
  const st=drStage(D);
  if(st==='egg'){if(S.year>D.ey&&!S.pend.includes('dr_crack'))S.pend.push('dr_crack');drSync();return}
  if(D.away&&D.away<=S.year&&D.role==='lent'){D.role='pet';D.away=0;log(`${D.name} được trả về sau thời gian canh giữ lâu đài của người khác. Nó gầy đi và cảnh giác hơn.`,'')}
  D.hunger=clamp(D.hunger+25-(D.role==='free'?25:0));
  if(D.hunger>=70){D.hp=clamp(D.hp-12);D.trust=clamp(D.trust-4);log(`${D.name} đói lả, lục tung chuồng gà của hàng xóm.`,'bad');rep('d',-2)}
  else D.hp=clamp(D.hp+5);
  if(D.role==='guard'){if(S.money>=8){S.money-=8}else{D.role='pet';log(`Bạn không đủ tiền nuôi ${D.name} canh giữ lâu đài, đành để nó về làm bạn đồng hành.`,'bad')}}
  if(D.role==='war')D.bond=clamp(D.bond-3);
  if(D.role==='free'){D.bond=clamp(D.bond+2);if(D.trust<25&&ch(.25)){drGone(`${D.name} bay đi và không trở về nữa.`,true);return}}
  if(D.hp<=0){D.alive=false;log(`${D.name} chết vì đói và bệnh. Cả nhà chôn nó dưới gốc sồi.`,'bad');S.dragon=null;drSync();return}
  if(D.lastSt!==st){if(D.lastSt){const m={young:`${D.name} đã lớn bằng con ngựa. Nó có thể bắt đầu tập bay và phun lửa.`,adult:`${D.name} đã trưởng thành, sải cánh che kín cả sân nhà.`,ancient:`${D.name} giờ là một cổ long. Vảy nó cứng như đá núi, và nó bắt đầu có ý chí của riêng mình.`}[st];if(m)log(m,'magic');if(st==='adult'&&!D.flags.adult)S.pend.push('dr_adult')}D.lastSt=st}
  if(D.trust<10&&D.abuse>=2&&ch(.4)&&!S.pend.includes('dr_flee')){S.pend.push('dr_flee');drSync();return}
  if(!S.evLast)S.evLast={};
  const pool=[];
  if(st!=='baby'&&!D.flags.fire&&D.q<=1)pool.push('dr_fire');
  if(st==='young'&&!D.flags.flight)pool.push('dr_flight');
  if(drBig(D)&&ch(.4))pool.push('dr_poach');
  if(D.q===2&&drBig(D)&&!D.flags.blood)pool.push('dr_blood');
  if(D.q===3&&drGrown(D)&&!D.flags.symbol)pool.push('dr_symbol');
  if(D.q===4&&drGrown(D)&&!D.flags.verm)pool.push('dr_verm');
  if(st==='young'&&!D.flags.tamer)pool.push('dr_tamer');
  if((st==='baby'||st==='young')&&!D.flags.mother)pool.push('dr_mother');
  if(drGrown(D)&&S.house.title>=2&&!D.flags.capfire)pool.push('dr_capfire');
  const ok=pool.filter(e=>!(S.evLast[e]&&S.year-S.evLast[e]<4));
  const pri=ok.find(e=>['dr_fire','dr_flight','dr_blood','dr_symbol','dr_verm'].includes(e));
  if(ok.length&&ch(pri?.55:.3)){const e=pri&&ch(.7)?pri:pick(ok);S.evLast[e]=S.year;S.pend.push(e)}
  else if(ch(.4)){const L=DRSHORT[st]||[];if(L.length){const t=pick(L);log(t.replace('rồng của bạn',D.name),'magic');if(/2 xu/.test(t))S.money-=2}}
  drSync();
}
/* --- hoạt động với rồng --- */
const DRA={
  feed:{n:'Cho ăn',ic:'meat-cooked',d:D=>`${DRA.feed.cost(D)} xu · đói −25, gắn bó +1`,cost:D=>({baby:2,young:5}[drStage(D)]||12),once:'drfeed'},
  pet:{n:'Vuốt ve',ic:'hearts',d:()=>'Gắn bó +2, tin tưởng +1',once:'drpet'},
  play:{n:'Chơi đùa',ic:'star',d:()=>'Chỉ rồng non · gắn bó +5, tin tưởng +2',once:'drplay',st:['baby']},
  obey:{n:'Gọi tên và dạy lệnh',ic:'scroll',d:()=>'Nghe lời +4–7 · có thể thất bại',train:1},
  huntt:{n:'Dạy săn mồi',ic:'hunter',d:()=>'Săn mồi +4–7 · từ rồng trẻ',train:1,st:['young','adult','ancient']},
  fire:{n:'Tập phun lửa',ic:'flame',d:()=>'4 xu · phun lửa +3–6 · có thể làm cháy kho',train:1,cost:()=>4,st:['young','adult','ancient'],need:D=>D.trust>=40?'':'Cần tin tưởng từ 40'},
  fly:{n:'Tập bay',ic:'compass',d:()=>'5 xu · bay +3–6 · có thể bị thương',train:1,cost:()=>5,st:['young','adult','ancient']},
  adv:{n:'Cùng rồng đi săn quái vật',ic:'w-spear',d:()=>'Tiền thưởng theo độ khó · rồng có thể bị thương',once:'dradv',st:['young','adult','ancient'],need:D=>D.tr.hunt>=20?'':'Cần săn mồi từ 20',age:16},
  patrol:{n:'Bay cùng rồng trên vương quốc',ic:'star',d:()=>'3 xu · danh dự, uy danh, gắn bó · có thể gây hoảng loạn',cost:()=>3,once:'drpat',st:['adult','ancient'],need:D=>D.tr.fly>=45?'':'Cần bay từ 45',age:12},
  vet:{n:'Đến thăm pháp sư thú',ic:'medical-kit',d:()=>'10–35 xu · chữa thương cho rồng',once:'drvet',need:D=>D.inj>S.year||D.hp<60?'':'Rồng đang khỏe'},
  rest:{n:'Cho rồng nghỉ ngơi',ic:'tent',d:()=>'Sức khỏe +10',once:'drrest'}
};
function drWhy(k){const A=DRA[k],D=S.dragon;if(!D||!D.alive)return'Không có rồng';const st=drStage(D);if(st==='egg')return'Trứng chưa nở';if(D.role==='lent'||D.away>S.year)return'Rồng đang ở nơi khác';if(A.st&&!A.st.includes(st))return st==='baby'?'Rồng còn quá nhỏ':'Không phù hợp với tuổi rồng';if(A.age&&S.age<A.age)return`Từ ${A.age} tuổi`;if(k!=='vet'&&k!=='rest'&&k!=='feed'&&k!=='pet'&&D.inj>S.year)return'Rồng đang bị thương';if(A.need){const w=A.need(D);if(w)return w}if(A.once&&S.done[A.once])return'Đã làm năm nay';if(A.train&&S.done['drt_'+k])return'Đã tập năm nay';if(A.train&&(S.done.drtn||0)>=2)return'Tối đa 2 buổi huấn luyện mỗi năm';const c=A.cost?A.cost(D):0;if(c&&S.money<c)return`Cần ${c} xu`;return''}
const trUp=(D,k,a,b)=>{const m={proud:k==='obey'?.6:1.1,loyal:k==='obey'?1.3:1,fierce:k==='fire'||k==='hunt'?1.3:.9,gentle:k==='hunt'?.7:1.1,curious:k==='fly'?1.3:1}[D.per]||1;const g=Math.max(1,Math.round(R(a,b)*m));D.tr[k]=Math.min(100,D.tr[k]+g);return g};
function drAct(k){
  const D=S.dragon;if(k==='name'){const el=$('#drname');const v=el&&(el.value||'').trim();if(v&&D){D.name=v.slice(0,20);note={t:`Từ nay con rồng mang tên ${D.name}.`,tone:'good'};save();drawSheet()}return}
  if(k.startsWith('role:')){const r=k.slice(5);if(!D||S.done.drrole)return;if(r==='guard'&&!(drGrown(D)&&D.tr.obey>=50))return;if(r==='war'&&!drGrown(D))return;
    S.done.drrole=1;let t;
    if(r==='pet'&&D.role==='free'&&D.trust<30&&ch(.5)){t=`Bạn huýt sáo gọi ${D.name}, nhưng nó chỉ lượn một vòng trên cao rồi bay đi.`}
    else{D.role=r;t={pet:`${D.name} trở về làm bạn đồng hành của bạn.`,guard:`${D.name} nhận canh giữ lâu đài. Mỗi năm tốn 8 xu thức ăn, nhưng kẻ gian không dám bén mảng.`,war:`${D.name} được huấn luyện làm chiến long, đi theo quân đội. Nó mạnh hơn trong trận mạc nhưng ngày càng xa cách bạn.`,free:`Bạn mở cửa chuồng. ${D.name} vút lên trời, tự do săn mồi trên núi.`}[r]}
    drSync();log(t,'magic');note={t,tone:'magic'};return afterSheetAction()}
  const A=DRA[k];if(!A||drWhy(k))return;
  const c=A.cost?A.cost(D):0;S.money-=c;if(A.once)S.done[A.once]=1;if(A.train){S.done['drt_'+k]=1;S.done.drtn=(S.done.drtn||0)+1}
  let t='',tone='magic';const st=drStage(D);
  if(k==='feed'){D.hunger=clamp(D.hunger-25);D.bond=clamp(D.bond+1);D.hp=clamp(D.hp+3);t=`${D.name} ngấu nghiến ${st==='baby'?'một rổ cá nhỏ':st==='young'?'nửa con cừu':'cả một con bò'}.`}
  else if(k==='pet'){if(D.per==='fierce'&&ch(.15)){mod({health:-5});t=`${D.name} đớp nhẹ vào tay bạn. Có lẽ nó chỉ đùa.`;tone='bad'}else{D.bond=clamp(D.bond+2);D.trust=clamp(D.trust+1);t=`${D.name} dụi đầu vào người bạn, rừ rừ như con mèo khổng lồ.`}}
  else if(k==='play'){D.bond=clamp(D.bond+5);D.trust=clamp(D.trust+2);if(ch(.1)){S.money-=3;t=`Bạn chơi trốn tìm với ${D.name}. Nó húc đổ cả kệ bát đĩa (−3 xu).`}else t=`Bạn ném quả bóng da, ${D.name} lăn lộn đuổi theo đến tận chiều.`}
  else if(k==='obey'){if(ch(D.per==='proud'?.3:.15)){D.trust=clamp(D.trust-1);t=`${D.name} quay lưng, giả vờ không nghe thấy.`;tone='bad'}else{const g=trUp(D,'obey',4,7);t=`${D.name} đã biết ngồi, nằm và quay lại khi nghe gọi tên (nghe lời +${g}).`}}
  else if(k==='huntt'){const g=trUp(D,'hunt',4,7);t=`Bạn thả thỏ trong sân cho ${D.name} vồ (săn mồi +${g}).`}
  else if(k==='fire'){const g=trUp(D,'fire',3,6);t=`${D.name} phun lửa vào hình nộm rơm (phun lửa +${g}).`;if(ch(.08)){const l=R(8,20);S.money-=l;rep('d',-2);D.flags.burn=(D.flags.burn||0)+1;t+=` Gió đổi chiều, lửa bén sang kho thóc nhà bên. Bạn bồi thường ${l} xu.`;tone='bad'}}
  else if(k==='fly'){const g=trUp(D,'fly',3,6);t=`${D.name} lượn ba vòng quanh tháp chuông (bay +${g}).`;if(ch(.08)){drHurt(D,1);t+=' Khi hạ cánh, nó đâm vào vách đá và bị thương, phải nghỉ một năm.';tone='bad'}}
  else if(k==='adv'){const p=.4+D.tr.hunt/200+D.bond/400+(drGrown(D)?.1:0);D.tr.hunt=Math.min(100,D.tr.hunt+2);
    if(ch(p)){const g=R(10,40)*(drGrown(D)?2:1);S.money+=g;S.house.prestige+=10;D.bond=clamp(D.bond+3);t=`Bạn cưỡi ${D.name} truy đuổi ${pick(['một con wyvern','bầy sói xám khổng lồ','con quỷ đầm lầy','một con griffin hoang'])}. Hai người thắng lớn, mang về ${g} xu tiền thưởng.`;tone='good'}
    else{drHurt(D,1);mod({health:-R(5,15)});t=`Con mồi mạnh hơn dự tính. Cả bạn và ${D.name} đều bị thương.`;tone='bad'}}
  else if(k==='patrol'){mod({honor:R(2,4)});S.house.prestige+=10;D.bond=clamp(D.bond+3);t=`Bạn cưỡi ${D.name} bay ngang qua bầu trời ${S.realm}. Dân chúng ngước nhìn, trẻ con reo hò.`;tone='good';if(ch(.05)){rep('d',-3);dsat(-3);t+=' Nhưng một đàn bò hoảng loạn giẫm nát vườn rau của cả làng.';tone='bad'}}
  else if(k==='vet'){const cst=R(10,35);S.money-=cst;D.inj=0;D.hp=clamp(D.hp+20);t=`Pháp sư thú bôi thuốc mỡ lưu huỳnh lên vết thương của ${D.name} (−${cst} xu). Nó đã khỏe lại.`}
  else if(k==='rest'){D.hp=clamp(D.hp+10);t=`${D.name} ngủ suốt mùa đông bên đống rơm khô.`}
  drSync();log(t,tone);note={t,tone};afterSheetAction();
}
function drView(){
  const D=S.dragon,dis=!S.alive;
  if(!D)return['Rồng của bạn','<p class="note">Bạn không nuôi rồng. Trứng rồng đôi khi được tìm thấy trong hang đá sau thác nước.</p>','act'];
  const st=drStage(D);let b='';
  b+=`<div class="row"><span class="ri">${ic(st==='egg'?'egg':'flame',24)}</span><div><b>${esc(D.name)} · ${DRSTG[st]}</b><small>${st==='egg'?'Đang ấp bên lò sưởi':`${drAge(D)} tuổi · nguyên tố ${DREL[D.el]} · tính ${DRPER[D.per].toLowerCase()} · ${DRROLE[D.role]}`}${D.inj>S.year?' · đang bị thương':''}</small></div></div>`;
  if(st!=='egg'){
    b+=statGrid([['Sức khỏe',`${D.hp}/100`],['Đói',`${D.hunger}/100`],['Tin tưởng',`${D.trust}/100`],['Gắn bó',`${D.bond}/100`]]);
    b+='<p class="sec">Huấn luyện</p>'+statGrid([['Bay',D.tr.fly],['Nghe lời',D.tr.obey],['Phun lửa',D.tr.fire],['Săn mồi',D.tr.hunt]]);
    if(D.hunger>=60)b+='<p class="note bad">Rồng đang đói. Không cho ăn, nó sẽ yếu đi và mất lòng tin vào bạn.</p>';
    if(D.trust<20)b+='<p class="note bad">Rồng không còn tin bạn. Nó có thể bỏ đi.</p>';
    b+=`<p class="sec">Chăm sóc · huấn luyện tối đa 2 buổi mỗi năm (đã ${S.done.drtn||0})</p>`;
    for(const[k,A]of Object.entries(DRA)){const why=drWhy(k);if(A.st&&!A.st.includes(st)&&!(k==='play'))continue;if(k==='play'&&st!=='baby')continue;b+=gRow(`data-x="dr:${k}"`,A.ic,A.n,why||A.d(D),'',!!why||dis)}
    if(drBig(D)){b+='<p class="sec">Vai trò · đổi một lần mỗi năm</p>';
      const R2=[['pet','Bạn đồng hành','Gắn bó tốt nhất, không tốn thêm'],['guard','Canh giữ lâu đài','Cần trưởng thành và nghe lời từ 50 · 8 xu/năm'],['war','Chiến long','Cần trưởng thành · mạnh trong chiến tranh · gắn bó giảm dần'],['free','Thả tự do bay lượn','Rồng tự săn mồi, gắn bó tăng · nếu ít tin bạn có thể không về']];
      for(const[r,n,d]of R2){const no=(r==='guard'&&!(drGrown(D)&&D.tr.obey>=50))||(r==='war'&&!drGrown(D));b+=gRow(`data-x="dr:role:${r}"`,r==='war'?'w-spear':r==='guard'?'castle':r==='free'?'compass':'hearts',n,d,D.role===r?pill('ĐANG',2):'',dis||D.role===r||no||!!S.done.drrole||D.role==='lent')}}
  }else b+='<p class="note">Quả trứng ấm dần theo từng tháng. Nó sẽ nở vào năm sau.</p>';
  b+=`<p class="sec">Đổi tên</p><div class="nmrow"><input id="drname" value="${esc(D.name)}" maxlength="20" autocomplete="off"><button class="btn sm pri" data-x="dr:name">Lưu</button></div>`;
  b+='<p class="note">Rồng không phải tài sản sinh tiền. Nó là một người bạn có cá tính riêng: cho ăn, chăm sóc và tôn trọng nó, nó sẽ ở lại với gia tộc qua nhiều đời.</p>';
  return['Rồng của bạn',b,'act'];
}
