function drHatch(hp,bond){const D=S.dragon;D.hy=S.year;D.hp=hp;D.bond=clamp(D.bond+bond);D.lastSt='baby';if(!S.pend.includes('dr_born'))S.pend.push('dr_born')}
function drName(n){const D=S.dragon;D.name=n;D.flags.named=1;announce('Rồng con chào đời',`Gia tộc ${S.house.name} có thêm một thành viên: rồng con ${n}, nguyên tố ${DREL[D.el].toLowerCase()}, tính ${DRPER[D.per].toLowerCase()}.`,'flame','dragonegg');return[`Rồng con có tên ${n}. Nó ngáp một cái, phun ra một làn khói nhỏ.`,'magic']}
function drQ(q,f){const D=S.dragon;if(!D)return;D.q=Math.max(D.q,q);D.flags[f]=1}

/* ===== v18: PHIÊU LƯU RỪNG (chủ yếu sự kiện một dòng) ===== */
function forestAct(s){
  if(!s.flags.foY||s.flags.foY!==s.year){s.flags.foY=s.year;s.flags.foC=0}
  const coin=n=>{const g=Math.max(0,Math.min(n,12-(s.flags.foC||0)));s.flags.foC=(s.flags.foC||0)+g;s.money+=g;return g};
  const r=Math.random();
  if(r<.1){const opts=['fo_lumber','fo_song'];if(s.flags.foGate)opts.push('fo_gate','fo_gate');const e=pick(opts);if(!s.pend.includes(e))s.pend.push(e);return['Bạn đi sâu hơn thường lệ vào rừng…','']}
  if(r<.3)return pick(['Bạn đi một vòng quanh bìa rừng. Không có gì đặc biệt.','Mưa lớn làm ướt hết bó củi, bạn về tay không.','Bầy sói chỉ đi ngang qua rồi biến mất trong sương.','Bạn thấy dấu chân nai bên con suối.']);
  const D=s.dragon;
  const L=[
    ()=>{mod({smarts:1});return'Một bà lão bán nấm chỉ cho bạn con đường tắt về làng.'},
    ()=>{const g=coin(3);return g?[`Bạn tìm thấy ${g} xu trong một túi da ai bỏ quên.`,'good']:'Bạn tìm thấy một túi da rỗng.'},
    ()=>{s.money-=1;return['Một con cáo lẻn trộm mất bữa trưa của bạn.','bad']},
    ()=>{mod({honor:1});return['Bạn gỡ một con chim ưng mắc bẫy. Nó lượn ba vòng trên đầu bạn rồi bay đi.','good']},
    ()=>{s.flags.foSong=1;return['Tiếng hát kỳ lạ vọng ra từ một cây cổ thụ. Bạn đứng nghe đến khi trời tối.','magic']},
    ()=>isHn(s)?'Một thợ săn khác kể về con quỷ đầm lầy đang bị treo thưởng ở Hiệp hội.':'Một thợ săn chia cho bạn miếng thịt nướng và vài tin đồn về Hiệp hội Thợ săn.',
    ()=>{const g=coin(2);return g?[`Bạn hái được một bó cây thuốc quý, bán cho thầy lang ${g} xu.`,'good']:'Bạn hái được một bó cây thuốc, đem về treo trong bếp.'},
    ()=>{s.flags.foGate=1;return['Bạn phát hiện một cổng đá phủ rêu giữa rừng. Bạn đánh dấu chỗ này để lần sau quay lại.','magic']},
    ()=>D&&D.alive&&['baby','young'].includes(drStage(D))?(D.bond=clamp(D.bond+1),[`${D.name} chạy theo đàn đom đóm suốt buổi chiều.`,'magic']):'Đom đóm bay thành vệt sáng dọc lối mòn.',
    ()=>{later('fo_ghost',1);return['Một bóng ma hỏi bạn đường về một ngôi làng đã biến mất từ trăm năm trước.','magic']},
    ()=>{mod({happy:1});return'Bạn tìm được đường tắt và về nhà sớm hơn mọi khi.'},
    ()=>{mod({magic:1});return['Đom đóm xếp thành chữ trên không, nhưng bạn không đọc được.','magic']},
    ()=>{mod({magic:1});return['Một con hươu bạc nhìn bạn rất lâu rồi biến mất.','magic']},
    ()=>{const l=Math.min(Math.max(s.money,0),R(1,4));s.money-=l;return[`Một con quỷ lùn nhỏ xíu móc túi bạn mất ${l} xu rồi cười khanh khách trên cành cây.`,'bad']}
  ];
  return pick(L)();
}
