function actExtra3(){
  let b='';
  if(S.dragon){const D=S.dragon,st=drStage(D);b+='<p class="sec">Rồng</p>'+gRow('data-open="dragon"',st==='egg'?'egg':'flame',st==='egg'?'Trứng rồng':`${D.name} · ${DRSTG[st]}`,st==='egg'?'Đang ấp bên lò sưởi':`${drAge(D)} tuổi · tin tưởng ${D.trust} · gắn bó ${D.bond} · đói ${D.hunger}`,'',!S.alive)}
  if(S.age>=12)b+='<p class="sec">Sông nước</p>'+gRow('data-open="sea"','anchor','Bến thuyền và đánh cá',S.boat?`${BOATS[S.boat.k].n} · độ bền ${S.boat.cond} · còn ${seaLeft()}/2 chuyến`:`Chưa có thuyền · còn ${seaLeft()}/2 chuyến`,'',!S.alive);
  return b;
}
function vasExtra(K,d2){
  let b='';
  const left=K.vassals.filter(v=>v.sy!==S.year).length;
  b+=gRow('data-x="kd:summonall"','banner','Triệu tập tất cả chư hầu',!K.war?'Chỉ khi có chiến tranh':!left?'Tất cả đã được triệu tập năm nay':`${left} chư hầu chưa xuất binh · trung thành giảm, gọi từ 3 nhà trở lên các lãnh chúa sẽ than phiền`,'',d2||!K.war||!left);
  if(K.war&&K.levy)b+=`<p class="note">Quân chư hầu đang tiếp viện cho trận tới: khoảng ${Math.round(K.levy*100)} quân.</p>`;
  return b;
}
function vasRealms(K,d2){
  const vr=Object.entries(K.realms||{}).filter(([n,r])=>r.st==='vassal');if(!vr.length)return'';
  return'<p class="sec">Nước chư hầu</p>'+vr.map(([n,r])=>gRow(`data-x="kd:rsummon:${n}"`,'banner',`Triệu quân ${esc(n)}`,!K.war?'Chỉ khi có chiến tranh':r.sy===S.year?'Đã triệu năm nay':`${esc(r.ruler)} · khoảng ${Math.max(1,Math.round(r.power*.3))*100} quân · quan hệ ${r.rel}`,'',d2||!K.war||r.sy===S.year)).join('');
}
function drawExt3(v){
  if(v==='cult'&&rmOn())return rmView();
  if(v==='rm'){if(!rmOn())return['Triều đình Hồng Nguyệt','<p class="note">Bạn không còn cai trị vương quốc Hồng Nguyệt.</p>','act'];return rmView()}
  if(v==='dragon')return drView();
  if(v==='sea')return seaView();
  return null;
}
function extAct3(x){
  const[a,...r]=x.split(':'),arg=r.join(':');
  if((a==='ca'||a==='rise')&&rmOn()){note={t:'Giáo phái đã nắm chính quyền. Truyền đạo bí mật, xin tiền dâng cúng hay bạo động không còn phù hợp ở vương quốc của bạn.',tone:'bad'};return drawSheet()}
  if(a==='rm')return rmAct(arg);
  if(a==='dr')return drAct(arg);
  if(a==='sea')return seaAct(arg);
  return extAct2(x);
}
