function rtGo(id){
  if(rtWhy())return;const k=S.fam.find(x=>x.id===id&&x.alive);if(!k||!/^Con /.test(k.rel)||k.bast)return;
  try{if(acfg().ev)autoPut('gen',`trước khi ${S.first} lui về`)}catch(e){}
  const old=S,me={first:old.first,sur:old.surname,sex:old.sex,age:old.age,race:old.race,gen:old.gen,y:old.year};
  S.flags.retiring=1;S.cause='';
  log(`${S.first} lui về ở ẩn, trao lại gia nghiệp cho ${k.rel.toLowerCase()} ${k.first}.`,'good');
  const D=old.dragon&&old.dragon.alive&&old.dragon.hy!=null?old.dragon:null;if(D)old.dragon=null;
  closeSheet();inherit(id);
  if(S===old){delete S.flags.retiring;if(D)old.dragon=D;return}
  const p={id:uid(),rel:me.sex==='m'?'Cha':'Mẹ',sex:me.sex,age:me.age,race:me.race,first:me.first,sur:me.sur,name:me.first+' '+me.sur,alive:true,bond:clamp(k.bond+R(0,10)),d:0,retired:me.gen};
  S.fam.unshift(p);
  if(D){S.dragon={...D,bond:Math.round(D.bond*.75),trust:Math.round(D.trust*.8),flags:{...D.flags,saved:0}};S.dq=(S.dq||[]).filter(x=>x.id!=='dr_return');drSync();log(`${D.name} vẫn ở lại lâu đài. Nó quen hơi ${me.first}, nhưng dần dần cũng chịu nghe lời bạn.`,'magic')}
  /* biên niên đời trước ghi là lui về, không phải qua đời */
  const rec=S.tree[S.tree.length-1];if(rec){rec.ret=1;rec.cause=''}
  log(`${me.sex==='m'?'Cha':'Mẹ'} ${me.first} vẫn sống trong nhà, ngày ngày ngồi bên lò sưởi kể chuyện năm xưa.`);
  save();render();
}
