{const d0=doAct;doAct=function(id){if(id==='spell'&&S.world.ban>S.year&&!(S.job&&JOBS[S.job.id].magicJob)&&!isStu(S)){S.flags.suspect=(S.flags.suspect||0)+1;rep('m',1)}return d0(id)}}
/* hàng đợi hậu quả trì hoãn rộng hơn cho nhiệm vụ nhiều giai đoạn */
later=function(id,yrs,d,leg){if(!S.dq)S.dq=[];if(S.dq.some(x=>x.id===id))return;S.dq.push({id,y:S.year+yrs,d:d||{},leg:leg?1:0});if(S.dq.length>12){const i=S.dq.findIndex(x=>!/^q/.test(x.id));S.dq.splice(i<0?0:i,1)}};
/* thừa kế */
function v19Inherit(old,p){
  S.mkh=old.mkh||{};S.q={};
  for(const[id,Q]of Object.entries(old.q||{})){if(!S.world.qdone)S.world.qdone=[];S.world.qdone.push({id,n:Q.d.who||'',y:old.year,t:'bỏ dở khi người theo đuổi qua đời.',who:`${old.first} (đời ${old.gen})`})}
  S.dq=(S.dq||[]).filter(x=>!/^q/.test(x.id));
  if(old.om&&old.om.rk>=2)log(`${ORGS[old.om.k].n} gửi lời chia buồn và nhắn rằng cửa hội luôn mở với con cháu của ${old.first}.`);
  if(p){
    if(p.bap===1){mod({piety:5});S.flags.bap=1}
    if(p.pi)S.st.piety=clamp(S.st.piety+Math.round(p.pi/4));
    if(p.lit)S.flags.literate=1;else if(p.lp)S.flags.lp=p.lp;
    if(p.red&&!S.flags.her){S.flags.her=1;log('Từ thuở nhỏ bạn đã được làm lễ dưới trăng đỏ. Hồng Nguyệt coi bạn là người của họ.','magic')}
    if(p.vow&&(p.race||S.race)==='human'&&!S.job&&S.age>=14&&S.house.title<6){S.job={id:'church',rank:1,yr:0,ry:0,perf:50};S.flags.literate=1;log('Bạn vẫn đang khấn dòng trong tu viện. Gia sản và gia tộc giờ đặt lên vai một tu sĩ.','')}
    if(p.bap||p.pi||p.lit)log(`Những năm theo cha mẹ đến nhà thờ để lại dấu ấn: ${[p.bap===1?'bạn đã được rửa tội':'',p.lit?'bạn biết đọc biết viết':'',p.pi>=40?'lòng đạo của bạn rất sâu':''].filter(Boolean).join(', ')||'bạn vẫn nhớ tiếng thánh ca thuở bé'}.`,'good');
  }
}
{const i0=inherit;inherit=function(id){const old=S,p=old.fam.find(x=>x.id===id);i0(id);if(S===old)return;try{v19Inherit(old,p)}catch(e){console.error(e)}save();render()}}
for(const e of V19_EV){EV.push(e);EVB[e.id]=e}
