const cleanName=v=>String(v||'').normalize('NFC').replace(/[<>&"`\\{}\[\]]/g,'').replace(/\s+/g,' ').trim();
{const p0=portrait;portrait=function(race,sex,alive=true){
  if(race!=='skeleton')return p0(race,sex,alive);
  const o='#c88d59',b='#d9d0bb';
  return`<svg viewBox="0 0 64 64" aria-hidden="true" style="${alive?'':'filter:grayscale(1) brightness(.6)'}"><path d="M8 66c0-15 11-23 24-23s24 8 24 23z" fill="#0b1020" stroke="${o}" stroke-width="1.2"/><path d="M27 44v6M32 44v8M37 44v6M22 50h20" stroke="${b}" stroke-width="1.6" stroke-linecap="round"/><path d="M21.5 23c0-7 4.7-11.5 10.5-11.5S42.5 16 42.5 23c0 4-1.6 6.6-4 8v4h-13v-4c-2.4-1.4-4-4-4-8z" fill="${b}" stroke="${o}" stroke-width="1"/><ellipse cx="28" cy="23.5" rx="2.8" ry="3.2" fill="#0b1020"/><ellipse cx="36" cy="23.5" rx="2.8" ry="3.2" fill="#0b1020"/><circle cx="28" cy="23.5" r="1" fill="#7fe3ff"/><circle cx="36" cy="23.5" r="1" fill="#7fe3ff"/><path d="M32 27l-1.5 3h3z" fill="#0b1020"/><path d="M28 33v2M31 33v2M34 33v2M37 33v2" stroke="#0b1020" stroke-width=".8"/></svg>`}}
{const d0=deathRoll;deathRoll=function(){if(isSk()){if(S.st.health<=0)die('bộ xương vỡ vụn');else if(S.st.health<10&&ch(.15))die('bộ xương vỡ vụn');return}return d0()}}

/* ---------- 1. Đặt tên con khi chào đời ---------- */
{const b0=baby;baby=function(){
  if(isSk()){S.done.baby=1;const t='Một bộ xương không thể có con. Nếu muốn có người nối dõi, bạn phải nhận con nuôi.';note={t,tone:'bad'};return drawSheet()}
  const n0=S.fam.length;b0();if(!S.alive)return;
  const k=S.fam[S.fam.length-1];if(S.fam.length>n0&&k&&/^Con /.test(k.rel)&&k.age===0){S.nameK=k.id;view='kname';note=null;$('#sheet').hidden=false;drawSheet()}}}
function knView(){
  const k=S.fam.find(x=>x.id===S.nameK&&x.alive);if(!k)return['Đặt tên','<p class="note">Không còn em bé nào chờ đặt tên.</p>','rel'];
  const sp=spouse();const surs=[...new Set([S.surname,sp&&sp.sur].filter(Boolean))];
  let b=`<p class="note good">${k.rel} chào đời${k.race!==S.race?`, mang dòng máu ${RACES[k.race].n}`:''}. Hãy đặt tên cho bé.</p>`;
  b+=`<label class="fl" for="kn">Tên gọi</label><div class="nmrow"><input id="kn" value="${esc(k.first)}" maxlength="20" autocomplete="off"><button class="btn sm" data-x="kn:rand">Gợi ý</button></div>`;
  if(surs.length>1)b+=`<p class="fl">Họ</p><div class="seg">${surs.map(x=>`<button class="opt ${k.sur===x?'on':''}" data-x="kn:sur:${esc(x)}">${esc(x)}</button>`).join('')}</div>`;
  b+=`<p class="note">Tên đầy đủ: <b id="knfull">${esc(k.first+' '+k.sur)}</b></p><div class="choices"><button class="btn pri" data-x="kn:ok">Đặt tên</button></div>`;
  return['Đặt tên cho con',b,'rel:love'];
}
function knAct(a,v){
  const k=S.fam.find(x=>x.id===S.nameK&&x.alive);if(!k)return;const inp=$('#kn');const cur=String(inp?inp.value:k.first).normalize('NFC').replace(/\s+/g,' ').trim();
  if(a==='rand'){const used=new Set(S.fam.filter(x=>x.alive).map(x=>x.first));const L=nameList(k.sex,k.race).filter(n=>!used.has(n));k.first=pick(L.length?L:nameList(k.sex,k.race));k.name=k.first+' '+k.sur;note=null;return drawSheet()}
  if(a==='sur'){if(okName(cur))k.first=cur;k.sur=v;k.name=k.first+' '+k.sur;return drawSheet()}
  if(a==='ok'){if(!okName(cur)){note={t:'Tên phải có 1–20 chữ cái, chỉ gồm chữ, khoảng trắng, dấu nháy hoặc gạch nối.',tone:'bad'};return drawSheet()}
    const old=k.first;k.first=cur;k.name=cur+' '+k.sur;S.nameK=null;if(old!==cur){for(const y of S.log.slice(-1))for(const it of y.items)if(it.t.includes(old)&&it.t.includes('chào đời'))it.t=it.t.replace(old,cur)}
    const t=`Bạn đặt tên con là ${k.name}.`;log(t,'good');note={t,tone:'good'};view='p:'+k.id;save();render();return drawSheet()}
}
document.addEventListener('input',e=>{if(e.target.id==='kn'){const k=S&&S.fam.find(x=>x.id===S.nameK);const f=$('#knfull');if(k&&f)f.textContent=cleanName(e.target.value)+' '+k.sur}});

/* ---------- 2. Tiên tộc: sang 5 năm ---------- */
let skipping=false;
const canSkip=()=>!!(S&&S.alive&&S.race==='elf');
function skipRun(){
  if(!S||!S.alive){if(S)S.skipLeft=0;return}
  skipping=true;
  try{while(S.skipLeft>0&&S.alive&&!S.pend.length&&!S.ann.length&&$('#modal').hidden){S.skipLeft--;ageUp()}}finally{skipping=false}
  if(!S.alive)S.skipLeft=0;
  save();render();
  if(S.skipLeft>0&&S.alive&&(S.pend.length||S.ann.length))toast(`Dừng lại để bạn quyết định · còn ${S.skipLeft} năm`);
}
function skip5(){if(!canSkip())return;if(!S.skipLeft)S.skipLeft=5;skipRun()}
{const s0=showNext;showNext=function(){s0();if(!skipping&&S&&S.skipLeft>0&&S.alive&&!S.pend.length&&!S.ann.length&&$('#modal').hidden&&$('#sheet').hidden)setTimeout(skipRun,300)}}

