function rgView(v){
  const G=RG();
  if(v==='rg'){let b='<p class="note">Sáu vương quốc cũ là đất của loài người. Tiên tộc, Người Lùn, Orc và Thú Nhân có quốc gia quê hương của riêng mình, có vua chúa, chiến tranh và luật lệ riêng. Bán quỷ không có nước, chỉ có vùng đất lưu vong. Người đồng tộc qua cửa ải tự do, người ngoài phải nộp phí thông hành cho đến khi được tin cậy. Mỗi năm bạn chỉ đi xa được một chuyến.</p>';
    const row=k=>{const R0=REG[k],g=G[k],rs=R0.nat?WD().rs[R0.own]:null,st=rs?rs.stab:g.stab;return gRow(`data-open="rg:${k}"`,R0.ic,R0.n+(S.done.rgv===k?' · bạn đang ở đây':S.realm===R0.own?' · quê bạn':''),`${rs?esc(rs.ruler)+(rs.war?` · ${rs.war.vs==='nội chiến'?'nội chiến':'đánh nhau với '+rs.war.vs.replace(RPFX,'')}`:''):esc(R0.own)} · ${st>=60?'yên ổn':st>=35?'bất an':'rối loạn'}${g.crisis?' · '+CRS[g.crisis].n.toLowerCase():''} · uy tín của bạn ${rgRep(k)}`,'',false,false,g.crisis?'foe':'')};
    b+='<p class="sec">Quốc gia của các tộc</p>'+Object.keys(REG).filter(k=>REG[k].nat).map(row).join('');
    b+='<p class="sec">Vùng đất trong các vương quốc loài người</p>'+Object.keys(REG).filter(k=>!REG[k].nat&&rgSeen(k)).map(row).join('');
    return['Các tộc và quốc gia',b,'act']}
  const k=v.slice(3),R0=REG[k];if(!R0||!rgSeen(k))return['Vùng đất','<p class="note">Không tìm thấy vùng đất này.</p>','rg'];
  const g=G[k],here=S.done.rgv===k,dis=!S.alive;let b=imgBanner(R0.img);
  if(R0.nat){const rs=WD().rs[R0.own];b+=statGrid([['Quốc gia','Độc lập'],['Trị vì',esc(S.realm===R0.own&&kingMe()&&rules()?'Bạn':rs.ruler)],['Ổn định',rs.stab+'/100'],['Thịnh vượng',g.pros+'/100'],['Chiến sự',rs.war?(rs.war.vs==='nội chiến'?'Nội chiến':'Với '+esc(rs.war.vs.replace(RPFX,''))):'Hòa bình'],['Uy tín của bạn',rgRep(k)+'/100']])}else b+=statGrid([['Thuộc về',esc(g.own)],['Ổn định',g.stab+'/100'],['Thịnh vượng',g.pros+'/100'],['Uy tín của bạn',rgRep(k)+'/100']]);
  b+=`<p class="note">${R0.d}.${g.crisis?` Nơi này đang chịu ${CRS[g.crisis].n.toLowerCase()}.`:''}</p>`;
  if(!here){const why=rgWhy(k),toll=rgToll(k);b+=gRow(`data-x="rg:go:${k}"`,'horse',`Du hành đến ${R0.n}`,why||`${8+toll} xu${toll?' (gồm phí thông hành)':''} · mở các hoạt động ở vùng này năm nay`,'',!!why||dis)}
  else{b+='<p class="sec">Hoạt động ở đây · mỗi việc một lần</p>';RGA[k].forEach((A,i)=>{const dn=S.done['rga'+k+i];b+=gRow(`data-x="rg:do:${k}:${i}"`,A[0],A[1],dn?'Đã làm năm nay':A[2],'',!!dn||dis)})}
  return[R0.n,b,'rg'];
}
function rgAct(a,k,i){
  const R0=REG[k];if(!R0)return;let t='',tone='';
  if(a==='go'){if(rgWhy(k)||S.done.rgv)return;const c=8+rgToll(k);S.money-=c;S.done.rgv=k;rgAdd(k,1);t=`Bạn lên đường đến ${R0.n}${rgToll(k)?`, nộp ${rgToll(k)} xu phí thông hành ở ${R0.nat?'biên giới':'cửa ải'}`:''}.`;if(S.race===R0.race)t+=' Về với đất tổ, lòng bạn nhẹ hẳn.';tone='good'}
  else if(a==='do'){if(S.done.rgv!==k||S.done['rga'+k+i])return;const A=RGA[k][+i];if(!A)return;const r=A[3](S);if(r===null){note={t:A[4]||'Bạn chưa đủ điều kiện.',tone:'bad'};return drawSheet()}S.done['rga'+k+i]=1;[t,tone]=arr(r)}
  log(t,tone);note={t,tone};afterSheetAction();
}
function rgYear(){const G=RG();for(const[k,g]of Object.entries(G)){if(REG[k].nat){g.own=REG[k].own;g.auto=0}g.stab=Math.round(Math.max(5,Math.min(95,g.stab+(58-g.stab)*.12+R(-3,3)-(g.crisis?6:0))));g.pros=Math.round(Math.max(5,Math.min(95,g.pros+(55-g.pros)*.1+R(-3,3)-(g.crisis?5:0))))}
  if(MK().i.wood>=140)G.beastwood.stab=Math.max(5,G.beastwood.stab-3);if(MK().i.iron>=150)G.irondeep.stab=Math.max(5,G.irondeep.stab-2);for(const[k,g]of Object.entries(G))if(REG[k].nat){const rs=WD().rs[REG[k].own];if(rs){rs.stab=Math.round((rs.stab+g.stab)/2);g.stab=rs.stab}}}

