/* ---------- 7. Danh hiệu ---------- */
const HON={
  kiemthanh:{n:'Kiếm Thánh',ic:'sword',img:'sword_stone',d:'Bậc thầy kiếm thuật đương thời, có thể bị thách đấu',rep:{n:3,d:3}},
  daiphapsu:{n:'Đại Pháp Sư',ic:'wand',img:'manatest',d:'Được Hội Đồng Pháp Thuật công nhận',rep:{m:8}},
  thanren:{n:'Thợ Rèn Thần Khí',ic:'anvil',img:'irondeep',d:'Rèn thành công báu vật Rune',rep:{n:2,d:2}},
  thanhy:{n:'Đại Thánh Y',ic:'medical-kit',img:'plague',d:'Cứu sống nhiều người qua dịch bệnh',rep:{d:6}},
  longkysi:{n:'Long Kỵ Sĩ',ic:'flame',img:'dragon',d:'Cưỡi rồng trưởng thành, cùng bay và chiến đấu',rep:{n:4,d:3}},
  dietrong:{n:'Kẻ Diệt Rồng',ic:'skull',img:'dragon',d:'Hạ được rồng lớn, có thể bị rồng khác trả thù',rep:{d:4}},
  thanhhiepsi:{n:'Thánh Hiệp Sĩ',ic:'shield',img:'crusade',d:'Hiệp sĩ của Chính giáo, dẫn đoàn bảo hộ',rep:{n:3},o:6},
  daitute:{n:'Đại Tư Tế Hồng Nguyệt',ic:'night',img:'redmoon',d:'Lãnh đạo tinh thần của Hồng Nguyệt',r:6},
  vuanui:{n:'Vua Núi',ic:'mountain',img:'dwarfrev',d:'Thống nhất các thị tộc Người Lùn',rep:{}},
  chuate:{n:'Chúa Tể Bóng Tối',ic:'demon',img:'demon',d:'Điều hành phe hắc ám, bị liên minh khác săn đuổi',rep:{d:-5}},
  archlich:{n:'Archlich',ic:'skull',img:'lich',d:'Hoàn tất con đường Lich, nắm giữ Hộp Linh Hồn',rep:{m:3}},
  hoauoc:{n:'Người Gìn Giữ Hòa Ước',ic:'scroll',img:'ennoble',d:'Đình chiến thành công giữa hai phe',rep:{n:4,d:4}}
};
const HONS=()=>{if(!S.hon)S.hon=[];return S.hon};
const hasHon=id=>!!(S&&S.hon&&S.hon.some(h=>h.id===id&&h.st!=='stripped'));
function honAward(id,by){if(HONS().some(h=>h.id===id))return false;const H=HON[id];HONS().push({id,y:S.year,by,st:'held'});mod({honor:5});S.house.prestige+=50;for(const k in H.rep||{})rep(k,H.rep[k]);if(H.o)fac(H.o,0);if(H.r)fac(0,H.r);if(!S.honP)S.honP=id;
  announce(`Danh hiệu: ${H.n}`,`${S.first} ${S.surname} được ${by} công nhận là ${H.n}. ${H.d}.`,H.ic,'ennoble');log(`Bạn được ${by} công nhận danh hiệu ${H.n}.`,'good');news(`${S.first} ${S.surname} được công nhận là ${H.n}.`,'',true);return true}
function honSet(id,st,why){const h=HONS().find(x=>x.id===id);if(!h)return;h.st=st;if(st==='stripped'){if(S.honP===id)S.honP=(HONS().find(x=>x.st!=='stripped')||{}).id||null;log(`Bạn bị tước danh hiệu ${HON[id].n}: ${why}.`,'bad')}else if(st==='contested')log(`Danh hiệu ${HON[id].n} của bạn đang bị tranh cãi: ${why}.`,'bad');else log(`Danh hiệu ${HON[id].n} của bạn được công nhận trở lại.`,'good')}
function honYear(){
  if(S.age<14)return;const D=S.dragon;
  const A=[['thanren',s=>s.flags.runeForged&&(s.job&&['smith','runesmith'].includes(s.job.id)),'Đại Lò Rune Irondeep'],['thanhy',s=>(s.flags.cured||0)>=3,'các giáo xứ khắp vương quốc'],['longkysi',s=>D&&D.alive&&drGrown(D)&&D.bond>=70&&(D.tr&&D.tr.fly||0)>=60,'triều đình'],['dietrong',s=>s.flags.dragonslayer,'dân chúng khắp nơi'],['thanhhiepsi',s=>(s.flags.knight||s.kn)&&FAC().o>=75&&s.st.honor>=70,'Giáo hội Thánh Quang'],['daitute',s=>s.flags.her>=3,'Hội đồng Tư tế Hồng Nguyệt'],['vuanui',s=>s.flags.vuanui,'bảy thị tộc Irondeep'],['chuate',s=>s.flags.dark&&s.house.title>=2,'các thế lực hắc ám'],['archlich',s=>s.sk&&s.sk.br==='mage'&&s.sk.rk>=4,'Vua Bất Tử Morvain'],['hoauoc',s=>s.flags.peace,'các bên ký hòa ước']];
  for(const[id,f,by]of A){try{if(!HONS().some(h=>h.id===id)&&f(S)){honAward(id,by);break}}catch(e){}}
  if(hasHon('daitute')&&!S.flags.her)honSet('daitute','stripped','bạn đã rời bỏ Hồng Nguyệt');
  if(hasHon('chuate')&&!S.flags.dark)honSet('chuate','stripped','bóng tối đã rời bỏ bạn');
  if(hasHon('longkysi')&&!(D&&D.alive))honSet('longkysi','stripped','rồng của bạn không còn bên cạnh');
  if(hasHon('kiemthanh')&&S.world.ks&&!S.world.ks.me)honSet('kiemthanh','stripped','danh hiệu đã về tay người khác');
}
const HONACT={
  kiemthanh:['Mở lớp dạy kiếm','Tiền học, danh dự',()=>{const g=R(20,50);S.money+=g;mod({honor:2});return`Bạn dạy kiếm cho con em các nhà quý tộc, thu ${g} xu học phí.`}],
  daiphapsu:['Dựng phép bảo vệ thành','Lòng dân hoặc tiền cố vấn',()=>{if(S.house.dom&&rules()){dsat(5);return['Vòm phép ánh bạc bao quanh thành của bạn suốt một năm.','magic']}const g=R(25,60);S.money+=g;return[`Một lãnh chúa trả bạn ${g} xu để dựng phép bảo vệ lâu đài.`,'magic']}],
  thanren:['Rèn báu vật theo đơn đặt hàng','2 lô sắt hoặc 80 xu',()=>{const H=MKH();if(H.iron&&H.iron.n>=2){H.iron.n-=2;H.iron.cost=Math.round(H.iron.cost*(H.iron.n)/(H.iron.n+2));if(!H.iron.n)delete H.iron}else if(S.money>=80)S.money-=80;else return null;if(ch(.6)){gainItem(pick(['greatsword','warhammer','halberd']));return['Lưỡi thép tôi xong phát ra tiếng ngân như chuông.','item']}const g=R(60,140);S.money+=g;return[`Một bá tước mua báu vật ngay khi nó còn ấm, trả ${g} xu.`,'good']},'Cần 2 lô sắt trong kho hoặc 80 xu'],
  thanhy:['Mở viện trị bệnh','Gia đình khỏe hơn, lòng dân',()=>{for(const p of S.fam)if(p.alive)p.bond=clamp(p.bond+2);mod({health:5});rep('d',3);return['Bạn chữa miễn phí cho dân nghèo một tuần mỗi tháng.','good']}],
  longkysi:['Tuần tra trên lưng rồng','Lòng dân, tiền thưởng',()=>{const g=R(15,40);S.money+=g;rep('d',2);if(S.dragon)S.dragon.bond=clamp(S.dragon.bond+3);return[`Bạn bay dọc biên giới, đuổi một toán cướp. Triều đình thưởng ${g} xu.`,'good']}],
  dietrong:['Kể chuyện diệt rồng ở yến tiệc','Uy danh gia tộc',()=>{S.house.prestige+=20;if(ch(.07)&&!S.pend.includes('hn_dragonfeud'))S.pend.push('hn_dragonfeud');return'Cả bàn tiệc nín thở nghe bạn kể. Ngoài cửa sổ, có bóng gì đó lướt qua mây.'}],
  thanhhiepsi:['Hộ tống đoàn hành hương','Uy tín Chính giáo, danh dự',()=>{fac(3,0);mod({honor:2,piety:2});return['Bạn dẫn ba trăm người hành hương qua rừng có sói, không mất một ai.','good']}],
  daitute:['Chủ trì đại lễ trăng đỏ','Tín đồ tăng · nguy hiểm',()=>{if(S.cult)S.cult.fol+=R(100,300);fac(0,3);S.flags.suspect=(S.flags.suspect||0)+1;return['Hàng nghìn ngọn nến đen thắp sáng hang đá.','magic']}],
  vuanui:['Triệu tập Hội Nghị Bảy Gia Tộc','Uy tín Irondeep, quà sắt',()=>{rgAdd('irondeep',5);const H=MKH();if(mkHeld()<mkCap()){H.iron=H.iron||{n:0,cost:0};H.iron.n++}return['Bảy trưởng thị tộc gõ búa xuống đe ba lần để chào bạn.','good']}],
  chuate:['Ban chiếu thư bóng tối','Ma lực, uy danh',()=>{mod({magic:4});S.house.prestige+=20;return['Ba lãnh chúa vùng biên quỳ gối trước chiếu thư của bạn.','magic']}],
  archlich:['Nghi thức tử linh cổ','Ma lực tăng · linh hồn hao mòn',()=>{mod({magic:6});if(S.soul!=null)S.soul=Math.max(1,S.soul-8);return['Bạn đọc những câu thần chú mà người sống không thể phát âm.','magic']}],
  hoauoc:['Làm trung gian hòa giải','Danh dự, uy tín quý tộc',()=>{mod({honor:3});rep('n',2);S.house.prestige+=15;return['Hai nhà quý tộc đem tranh chấp đất đến nhờ bạn phân xử.','good']}]
};
function honView(){
  let b='<p class="note">Danh hiệu là sự công nhận thành tựu, khác với tước vị và chức quan. Danh hiệu không truyền cho con cháu, có thể bị tranh cãi hoặc bị tước. Mỗi danh hiệu mở một việc riêng mỗi năm.</p>';
  const L=HONS();
  if(!L.length)b+='<p class="note">Bạn chưa có danh hiệu nào.</p>';
  for(const h of L){const H=HON[h.id],A=HONACT[h.id],held=h.st!=='stripped';
    b+=gRow(held?`data-x="hn:pri:${h.id}"`:'',H.ic,H.n+(S.honP===h.id?' · hiển thị dưới tên':''),`${h.st==='held'?'Đang giữ':h.st==='contested'?'Đang bị tranh cãi':'Đã bị tước'} · từ năm ${h.y} · ${esc(h.by)}${held&&S.honP!==h.id?' · chạm để hiển thị dưới tên':''}`,'',false,!held,h.st==='stripped'?'foe':'');
    if(held&&A){const dn=S.done['hn'+h.id];b+=gRow(`data-x="hn:do:${h.id}"`,H.ic,A[0],dn?'Đã làm năm nay':A[1],'',!!dn||!S.alive)}}
  b+='<p class="sec">Những danh hiệu trong thiên hạ</p>';
  b+=Object.entries(HON).filter(([k])=>!L.some(h=>h.id===k)).map(([k,H])=>gRow('',H.ic,H.n,H.d+(k==='kiemthanh'&&S.world.ks?` · đương thời: ${esc(S.world.ks.name)}`:''),'',false,true)).join('');
  return['Danh hiệu',b,'menu'];
}
function honAct(a,id){
  if(a==='pri'){if(hasHon(id))S.honP=id;render();return drawSheet()}
  if(a==='do'){if(!hasHon(id)||S.done['hn'+id])return;const A=HONACT[id];const r=A[2]();if(r===null){note={t:A[3]||'Chưa đủ điều kiện.',tone:'bad'};return drawSheet()}S.done['hn'+id]=1;const[t,tone]=arr(r);log(t,tone);note={t,tone};afterSheetAction()}
}
const KSN=()=>{if(!S.world.ks)S.world.ks={name:`${pick(MN)} ${pick(['Tuyết Sơn','Gió Bắc','Một Tay','Sương Mai'])}`,y:S.year-R(5,20)};return S.world.ks};
const HON_EV=[
 {id:'hn_snow',w:W(5),cd:8,big:true,art:'sword',img:'sword_stone',c:s=>s.age>=18&&s.age<=70&&s.flags.seenS&&s.hid.sword>=80&&s.st.honor>=40&&!HONS().some(h=>h.id==='kiemthanh'),title:'Trận Quyết Đấu Trên Đỉnh Tuyết',text:s=>`Kiếm Thánh đương thời ${KSN().name} nghe danh bạn và gửi lời mời: một trận đấu trên đỉnh núi tuyết, không nhân chứng ngoài gió. Kẻ thắng mang danh Kiếm Thánh.`,
  ch:[{t:'Lên đỉnh tuyết',f:s=>{if(ch(.28+(s.blade||0)/300+cbB()/250+s.st.health/600)){const old=KSN().name;s.world.ks={name:`${s.first} ${s.surname}`,y:s.year,me:1};honAward('kiemthanh',`${old} trên đỉnh tuyết`);return['Kiếm của bạn dừng cách cổ họng đối thủ một sợi tóc. Ông ta mỉm cười, quỳ một gối xuống tuyết.','good']}if(ch(.08)){die('trận quyết đấu trên đỉnh tuyết');return['Lưỡi kiếm của Kiếm Thánh nhanh hơn ánh mắt bạn.','bad']}mod({health:-R(15,30)});return['Bạn thua, nhưng Kiếm Thánh để lại một câu: "Mười năm nữa, quay lại."','bad']}},
      {t:'Từ chối, kiếm thuật không phải để tranh danh',f:s=>{mod({honor:2});return'Bạn gửi lại một cành mai thay câu trả lời.'}}]},
 {id:'hn_fake',w:s=>hasHon('kiemthanh')?6:0,cd:6,big:true,art:'crossed',c:s=>hasHon('kiemthanh')&&s.alive,title:'Kẻ Tự Xưng Kiếm Thánh',text:s=>`Một kiếm khách trẻ đi khắp các thành tự xưng là Kiếm Thánh thật sự, thách bạn đấu công khai ở quảng trường. Cả thành đang chờ.`,
  ch:[{t:'Nhận lời thách đấu',f:s=>{const h=HONS().find(x=>x.id==='kiemthanh');if(ch(.4+(s.blade||0)/300+cbB()/300-(s.age>55?.15:0))){if(h.st==='contested')honSet('kiemthanh','held');mod({honor:4});return['Ba chiêu. Chỉ ba chiêu, kiếm của kẻ thách đấu bay lên mái nhà.','good']}if(h.st==='contested'){s.world.ks={name:'kiếm khách trẻ phương Nam',y:s.year};honSet('kiemthanh','stripped','thua kẻ thách đấu lần thứ hai')}else honSet('kiemthanh','contested','thua một trận công khai');mod({health:-R(10,25)});return['Bạn thua trước mặt cả thành.','bad']}},
      {t:'Lờ đi',f:s=>{honSet('kiemthanh','contested','né tránh lời thách đấu');return'Người ta bắt đầu hỏi nhau: Kiếm Thánh sợ rồi sao?'}}]},
 {id:'hn_council',w:W(5),cd:10,big:true,art:'wand',img:'manatest',c:s=>s.st.magic>=80&&s.hid.arcane>=65&&s.st.smarts>=50&&((s.job&&['wizard','teacher'].includes(s.job.id)&&s.job.rank>=1)||(s.ac&&s.ac.st==='grad'))&&!HONS().some(h=>h.id==='daiphapsu')&&!(s.sk&&s.sk.rk>=2&&s.sk.br==='mage'),title:'Hội Đồng Pháp Thuật',text:'Hội Đồng Pháp Thuật của Học viện Tháp Bạc mời bạn trình bày công trình nghiên cứu. Nếu được chấp thuận, bạn sẽ mang danh Đại Pháp Sư.',
  ch:[{t:'Trình bày đại phép phong ấn',f:s=>{if(ch(.35+s.st.smarts/250+s.hid.arcane/300)){honAward('daiphapsu','Hội Đồng Pháp Thuật Tháp Bạc');return['Vòng phép của bạn giữ được một ngọn lửa trong lồng băng suốt buổi. Cả hội đồng đứng dậy.','magic']}mod({magic:3});return['Vòng phép vỡ ở phút cuối. Hội đồng hẹn bạn vài năm sau.','bad']}},
      {t:'Xin hoãn để nghiên cứu thêm',f:()=>{mod({smarts:2,magic:2});return'Bạn quay lại thư viện với ba chồng sách mới.'}}]},
 {id:'hn_dragonfeud',queued:true,big:true,art:'flame',img:'dragon',c:s=>s.alive&&hasHon('dietrong'),title:'Huyết Thù Long Tộc',text:'Một con rồng đỏ khổng lồ đáp xuống đồi gần nhà bạn. Nó ngửi thấy mùi máu của đồng loại trên thanh kiếm của bạn.',
  ch:[{t:'Rút kiếm',f:s=>{if(ch(.3+(s.blade||0)/300+cbB()/200)){mod({honor:8});s.house.prestige+=80;s.money+=R(100,250);return['Con rồng thứ hai gục xuống. Cả vương quốc gọi bạn là Kẻ Diệt Rồng hai lần.','good']}if(ch(.25)){die('móng vuốt rồng đỏ báo thù');return['Con rồng không quên.','bad']}mod({health:-R(25,45)});return['Bạn sống sót nhờ nhảy xuống sông.','bad']}},
      {t:'Bỏ kiếm xuống, xin hòa giải',f:s=>{if(ch(.35+s.st.honor/300)){mod({honor:4,magic:3});return['Con rồng nhìn bạn rất lâu rồi bay đi. Nó để lại một chiếc vảy như lời thề đình chiến.','magic']}const l=Math.min(Math.max(s.money,0),R(30,100));s.money-=l;return['Con rồng đốt kho thóc rồi bay đi.','bad']}}]}
];

/* ---------- 8. Nhánh nghề ẩn ---------- */
const HC={
  trade:{n:'Thương Gia Bóng Tối',ic:'hood',jobs:['trade','blackmarket'],call:'Một người đàn ông không có bóng ngồi xuống bàn bạn trong quán rượu: "Ta có những món hàng không chợ nào bán, và những người mua không ai dám hỏi tên. Ngươi muốn làm ăn lớn không?"',train:['Gây dựng mối quan hệ chợ đen','Mạng lưới ngầm · dễ bị truy quét'],fx:{smarts:1},perk:'Mở Mạng lưới Bóng Tối: cổ vật cấm, môi giới bí mật, hàng lậu'},
  surgeon:{n:'Y Sư Bất Tử',ic:'medical-kit',jobs:['surgeon'],call:'Bạn mổ tử thi một nạn nhân dịch bệnh và thấy những thứ không có trong sách. Một cuốn sổ tay da người được giấu trong áo của ông ta.',train:['Thử bí thuật y học','Đức tin giảm · cứu được người hơn'],fx:{smarts:1,piety:-1},perk:'Cứu được người nhà khỏi dịch · có thể tự cứu mình một lần'},
};
const HCRK=['Tập sự','Thành thạo','Đại sư'],HCXP=[0,35,80];
const hcOf=()=>S.job&&Object.keys(HC).find(k=>HC[k].jobs.includes(S.job.id));
function hcYear(){
  const H=S.hc;
  if(!H){const k=hcOf();if(k&&S.job.yr>=3&&S.age>=16&&!(S.hcNo&&S.hcNo[k])&&ch(.12)&&!S.pend.includes('hc_call')){S.hcK=k;S.pend.push('hc_call')}return}
  const D=HC[H.k];if(H.rk>=1)mod(D.fx);
  if(H.k==='surgeon'&&H.rk>=2&&(S.world.cat&&S.world.cat.id==='plague'||myRealm().pl)){S.flags.cured=(S.flags.cured||0)+1;rep('d',2);log('Bạn chữa khỏi hàng chục người mắc dịch bằng phương thuốc không ai dám hỏi nguồn gốc.','good')}
}
/* hoạt động riêng của từng nghề ẩn: [biểu tượng, tên, mô tả, bậc tối thiểu, hàm, lý do khi không làm được] */
const HCA={
  trade:[['message','Gây dựng quan hệ chợ đen','Mối quan hệ ngầm',0,()=>{DMK().con++;DMK().heat+=3;rep('u',2);return'Bạn uống rượu với tay buôn lậu trong hầm quán, học được ám hiệu của ba chợ đen.'}],
    ['map','Mở một đường dây buôn mới','Tiền · dễ bị truy quét',1,()=>{const g=R(20,50);S.money+=g;DMK().heat+=8;DMK().con++;return[`Bạn mở đường buôn rượu lậu qua đèo, lời ${g} xu ngay chuyến đầu.`,'good']}],
    ['crown','Thâu tóm một chợ đen','Tiền lớn, uy tín thế giới ngầm · kẻ thù mới',2,()=>{const g=R(50,120);S.money+=g;DMK().heat+=15;rep('u',6);if(ch(.3))addEnemy('trùm chợ đen bị bạn hất cẳng',{cls:'merchant',hate:R(55,75)});return[`Bạn mua lại món nợ của trùm chợ đen cũ và thay hắn ngồi ghế đầu. Năm nay lời ${g} xu.`,'good']}]],
  surgeon:[['skull','Mổ tử thi nghiên cứu','Trí tuệ · đức tin giảm',0,()=>{mod({smarts:3,piety:-2});S.flags.suspect=(S.flags.suspect||0)+1;return'Bạn mổ xác dưới ánh nến trong hầm nhà, ghi chép từng mạch máu.'}],
    ['medical-kit','Thử bí thuật lên người bệnh nặng','Cứu người hoặc mang tội',1,()=>{if(ch(.6+S.hc.rk*.08)){S.flags.cured=(S.flags.cured||0)+1;rep('d',3);mod({honor:2});return['Người bệnh mà mọi thầy lang đã bó tay ngồi dậy được sau ba ngày.','good']}mod({honor:-4,happy:-6});return['Người bệnh không qua khỏi. Gia đình họ nhìn bạn như nhìn kẻ sát nhân.','bad']}],
    ['potion','Điều chế thuốc trường sinh','Có thể ra thuốc quý',2,()=>{if(ch(.35)&&ITEMS.elixir){gainItem('elixir');return['Thứ nước trong bình sáng lên màu hổ phách và ấm như máu người.','item']}mod({magic:2});return'Mẻ thuốc đông lại thành một khối đen. Bạn ghi chép lại sai sót.'}]],
};
/* câu đố thử thách cuối: [câu hỏi, đáp án đúng, sai, sai] */
const HCQ={
  trade:[['Ông trùm chợ đen hỏi: "Kẻ làm ra nó thì bán nó, kẻ mua nó thì không dùng, kẻ dùng nó thì không bao giờ biết. Đó là món hàng gì?"','Cỗ quan tài','Thuốc độc','Bản hợp đồng'],['Ông trùm hỏi: "Hai người cha và hai người con chia ba đồng vàng, mỗi người được đúng một đồng, không ai cắt đồng nào. Làm sao được?"','Họ là ông, cha và con','Một người nói dối','Một người không nhận']],
  surgeon:[['Lão y sư hỏi: "Thứ gì càng lấy đi thì càng lớn?"','Cái hố','Vết thương','Món nợ'],['Lão y sư hỏi: "Thứ gì phải vỡ ra thì mới dùng được?"','Quả trứng','Lọ thuốc','Khúc xương']],
};
const hcLeft=()=>Math.max(0,2-(S.done.hca||0));
const hcOK=()=>!!(S.hc&&HC[S.hc.k]&&(HC[S.hc.k].free||S.job&&HC[S.hc.k].jobs.includes(S.job.id)));
function hcView(){
  const H=S.hc;if(!H)return['Nghề ẩn','<p class="note">Bạn chưa bước vào nhánh nghề ẩn nào.</p>','act'];const D=HC[H.k],dis=!S.alive;
  const need=H.rk<2?HCXP[H.rk+1]:120;let b=`<div class="row"><span class="ri">${ic(D.ic,24)}</span><div><b>${H.rk?hcName():'Đang tìm hiểu: '+D.n}</b><small>Bậc ${H.rk}/3 · ${H.rk>=3?'Đã đạt bậc cao nhất':`kinh nghiệm ${H.xp}/${need}`}</small><div class="bond"><i style="width:${H.rk>=3?100:Math.min(100,Math.round(H.xp/need*100))}%"></i></div></div></div>`;
  b+=`<p class="note">${D.perk}.${H.rk===2?' Đủ 120 kinh nghiệm sẽ mở thử thách cuối: một câu đố với ba lời đáp.':''}${!hcOK()?' Bạn đã rời nghề gốc nên tạm thời không luyện được nhánh này.':''}</p>`;
  b+=`<p class="sec">Hoạt động riêng · còn ${hcLeft()}/2 việc năm nay</p>`;
  HCA[H.k].forEach((A,i)=>{const lock=H.rk<A[3];const why=lock?`Mở khi thành ${hqTier(H,A[3])}`:!hcOK()?'Cần làm nghề gốc':S.done['hca'+i]?'Đã làm năm nay':!hcLeft()?'Đã hết lượt năm nay':'';b+=gRow(`data-x="hc:do:${i}"`,A[0],A[1],why||A[2],'',dis||!!why)});
  if(H.rk===2&&H.xp>=120&&!S.pend.includes('hc_trial'))b+=gRow('data-x="hc:trial"','star','Đối mặt thử thách cuối','Một câu đố, ba lời đáp, chỉ một lời đúng','',dis);
  if(H.k==='trade'&&H.rk>=1)b+=gRow('data-open="dm"','hood','Mạng lưới Bóng Tối',`${DMK().con} mối quan hệ · bị truy quét ${DMK().heat}/100`,'',dis);
  return[D.n,b,'act'];
}
function hcDo(i){
  const H=S.hc;if(!H||!hcOK()||!hcLeft())return;const A=HCA[H.k][+i];if(!A||H.rk<A[3]||S.done['hca'+i])return;
  const r=A[4]();if(r===null){note={t:A[5]||'Chưa đủ điều kiện.',tone:'bad'};return drawSheet()}
  S.done.hca=(S.done.hca||0)+1;S.done['hca'+i]=1;let[t,tone]=arr(r);
  if(H.rk<3){H.xp+=R(8,14)+A[3]*3;if(H.rk<2&&H.xp>=HCXP[H.rk+1]){H.rk++;t+=` Bạn trở thành ${hcName()}.`;tone='good'}else if(H.rk===2&&H.xp>=120&&!S.pend.includes('hc_trial')){S.pend.push('hc_trial');t+=' Bạn cảm thấy mình đã chạm tới ngưỡng cuối cùng.'}}
  log(t,tone);note={t,tone};afterSheetAction();
}
function hcTrain(){}
const hcName=()=>S.hc?(S.hc.leg?'Thánh Ma Kiếm Sư':hqTitle(S.hc)):'';
function hcHTML(){
  const H=S.hc;if(!H)return'';const D=HC[H.k];
  return'<p class="sec">Nhánh nghề ẩn</p>'+gRow('data-open="hc"',D.ic,H.rk?hcName():'Đang tìm hiểu: '+D.n,`Bậc ${H.rk}/3 · ${HCA[H.k].length} hoạt động riêng trong mục Hoạt động`,'',false);
}
const HC_EV=[
 {id:'hc_call',queued:true,big:true,art:s=>HC[s.hcK].ic,c:s=>!!s.hcK&&!s.hc,title:s=>HC[s.hcK].n,text:s=>HC[s.hcK].call,
  ch:[{t:'Bước vào con đường ấy',f:s=>{s.hc={k:s.hcK,rk:0,xp:0,y:s.year};return[`Bạn bắt đầu con đường của ${HC[s.hcK].n}. Các hoạt động riêng của nhánh này nằm trong mục Hoạt động.`,'magic']}},
      {t:'Từ chối',f:s=>{if(!s.hcNo)s.hcNo={};s.hcNo[s.hcK]=1;return'Bạn quay lại với công việc thường ngày.'}}]},
 {id:'hc_trial',queued:true,big:true,art:s=>s.hc?HC[s.hc.k].ic:'star',c:s=>s.hc&&s.hc.rk===2,
  prep:s=>{const L=HCQ[s.hc.k];const qi=R(0,L.length-1);const ord=[0,1,2].sort(()=>Math.random()-.5);s.hcQ={qi,ord};s.tmp=1},
  title:s=>`Thử thách cuối: ${HC[s.hc.k].n}`,text:s=>`${HCQ[s.hc.k][s.hcQ?s.hcQ.qi:0][0]} Chỉ một lời đáp đúng.`,
  ch:[0,1,2].map(j=>({t:s=>{const Q=HCQ[s.hc.k][s.hcQ?s.hcQ.qi:0];return Q[1+(s.hcQ?s.hcQ.ord[j]:j)]},f:s=>{const H=s.hc,D=HC[H.k],Q=HCQ[H.k][s.hcQ.qi],pick0=s.hcQ.ord[j];s.hcQ=null;
    if(pick0===0){H.rk=3;mod({honor:5,happy:8});S.house.prestige+=40;if(H.k==='surgeon')s.flags.cured=(s.flags.cured||0)+2;announce(D.n,`${s.first} ${s.surname} trả lời đúng câu đố cuối cùng và trở thành ${hcName()}.`,D.ic,null);return[`"${Q[1]}." Bạn trả lời không chút do dự. Người ra đề gật đầu: từ nay bạn là ${hcName()}.`,'good']}
    H.xp=95;mod({happy:-4});return[`"${Q[1+pick0]}" không phải lời đáp đúng. Bạn phải rèn luyện thêm rồi mới được thử lại.`,'bad']}}))}
];

/* ---------- 9. Bộ Xương và tử linh ---------- */
const SKBR={war:{n:'Nhánh chiến binh',t:['Skeleton Warrior','Death Knight','Dread Knight']},mage:{n:'Nhánh pháp thuật',t:['Skeleton Mage','Necromancer','Lich','Archlich']}};
const SKX=()=>{if(!S.sk)S.sk={br:null,rk:0,xp:0,leg:0,mor:0};return S.sk};
const skTitle=()=>{const K=SKX();return K.br&&K.rk?SKBR[K.br].t[K.rk-1]:'Bộ Xương'};
function skBecome(){
  const old=S.race;S.race='skeleton';S.flags.skelFrom=old;S.flags.curse=3;S.soul=70;SKX();S.st.health=Math.max(S.st.health,60);S.st.looks=5;mod({magic:10,piety:-15,happy:-10});
  announce('Lời Nguyền Hầm Mộ',`${S.first} ${S.surname} đã chết, nhưng không rời đi. Một bộ xương mang ký ức, tên gọi và tình thân của người ấy vẫn đứng dậy.`,'skull','skelcurse');
  log('Thịt da bạn rơi rụng như lá mùa thu. Bạn vẫn nhớ tên mình, tên vợ con, và mùi bánh mì buổi sáng. Bạn là một bộ xương.','magic');
  if(S.job&&['church','mission','court'].includes(S.job.id)){log(`Bạn không thể tiếp tục ${jt().toLowerCase()} trong hình hài này.`,'bad');if(S.job.id==='court')S.co=null;S.job=null}
  later('sk_wife',1);later('sk_exorcist',R(2,4));
}
function skYear(){
  if(S.flags.curse===1||S.flags.curse===2){mod({health:-R(1,4)});return}
  if(!isSk())return;const K=SKX();
  S.soul=Math.max(0,(S.soul==null?70:S.soul)-R(2,5)+(K.br==='mage'&&K.rk>=3?2:0));
  if(S.soul<=0){if(S.phy&&S.phy.ok&&!S.phy.stolen){S.soul=30;S.phy.hp-=30;log('Linh hồn bạn tan rã, nhưng Hộp Linh Hồn kéo nó về. Hộp rạn thêm một vết.','magic');if(S.phy.hp<=0){S.phy.ok=0;log('Hộp Linh Hồn vỡ vụn. Lần sau sẽ không còn gì níu giữ bạn nữa.','bad')}}else die('linh hồn tiêu tán');return}
  if(S.soul<20)log('Ánh lửa xanh trong hốc mắt bạn chập chờn. Linh hồn bạn đang mỏng dần.','bad');
  S.flags.suspect=(S.flags.suspect||0)+(ch(.3)?1:0);
  if(K.leg)K.leg=Math.max(0,K.leg-R(0,3));
  if(ch(.06)&&!S.pend.some(x=>x.startsWith('sk_')))S.pend.push(pick(['sk_child','sk_exorcist','sk_morvain']));
  if(S.phy&&S.phy.ok&&!S.phy.stolen&&ch(.04)){S.phy.stolen=1;S.pend.push('sk_phystolen')}
  if(K.br==='mage'&&K.rk>=3&&S.house.title>=2&&K.leg>=60&&!S.flags.deathKing&&ch(.15)&&!S.pend.includes('sk_empire'))S.pend.push('sk_empire');
}
const skLeft=()=>Math.max(0,2-(S.done.sk||0));
const SKA=[
  ['gravestone','Hấp thu linh hồn ở nghĩa địa','Linh hồn +20 · nghi vấn và tội lỗi',()=>{S.soul=Math.min(100,S.soul+20);S.flags.suspect=(S.flags.suspect||0)+2;mod({piety:-3});if(ch(.15)){rep('d',-4);return['Người gác nghĩa địa nhìn thấy bạn. Cả làng đồn có ma.','bad']}return['Bạn đứng giữa những nấm mồ, hút lấy hơi lạnh còn sót lại.','magic']}],
  ['candle','Thiền định trong hầm mộ','Linh hồn +8, an toàn',()=>{S.soul=Math.min(100,S.soul+8);return'Bạn ngồi yên trong bóng tối một tháng liền. Ngọn lửa xanh trong mắt bạn sáng hơn.'}],
  ['diamond','Mua đá linh hồn (30 xu)','Linh hồn +15',()=>{if(S.money<30)return null;S.money-=30;S.soul=Math.min(100,S.soul+15);DMK().heat+=3;return'Một thương nhân bóng tối bán cho bạn viên đá xanh lạnh như băng.'},'Cần 30 xu'],
  ['bone','Thay xương bằng vật liệu hiếm (60 xu)','Sức khỏe hồi lại · có thể thất bại',()=>{if(S.money<60)return null;S.money-=60;if(ch(.75)){S.st.health=Math.min(100,S.st.health+40);return['Thợ rèn Rune thay ba xương sườn của bạn bằng thép khắc chữ cổ.','good']}mod({health:-10});return['Xương mới không chịu gắn vào. Bạn đau theo cách một bộ xương không nên biết đau.','bad']},'Cần 60 xu']
];
function skView(){
  if(!isSk()&&!S.flags.curse)return['Tử linh','<p class="note">Bạn vẫn là người sống.</p>','act'];
  const K=SKX(),dis=!S.alive;let b='';
  if(!isSk()){b+=`<p class="note bad">Lời nguyền hầm mộ đang ngấm vào xương bạn (giai đoạn ${S.flags.curse}/3). Có thể tìm cách chữa trước khi quá muộn.</p>`;
    b+=gRow('data-x="sk:cure:priest"','church','Nhờ Giáo hội trừ tà (40 xu)',S.money<40?'Cần 40 xu':'Đức tin giúp tăng cơ hội','',dis||S.money<40||!!S.done.skc);
    b+=gRow('data-x="sk:cure:mage"','tower','Nhờ Học viện Tháp Bạc (60 xu)',S.money<60?'Cần 60 xu':'Ma lực giúp tăng cơ hội','',dis||S.money<60||!!S.done.skc);
    return['Lời nguyền hầm mộ',b,'act']}
  b+=imgBanner(K.br==='mage'&&K.rk>=3?'lich':K.br==='mage'&&K.rk>=2?'necro':'skelcurse');
  b+=statGrid([['Thân phận',skTitle()],['Ổn định linh hồn',S.soul+'/100'],['Quân đoàn xác sống',K.leg],['Hộp Linh Hồn',S.phy?(S.phy.stolen?'Bị đánh cắp':S.phy.ok?`Nguyên vẹn ${S.phy.hp}/100`:'Đã vỡ'):'Chưa có']]);
  b+=`<p class="note">Bộ xương không chết vì tuổi già, nhưng linh hồn hao mòn mỗi năm. Linh hồn về 0 là tiêu tán vĩnh viễn${S.phy&&S.phy.ok?', trừ khi Hộp Linh Hồn còn níu giữ':''}.</p>`;
  b+=`<p class="sec">Giữ linh hồn · còn ${skLeft()}/2 việc năm nay</p>`;SKA.forEach((A,i)=>{b+=gRow(`data-x="sk:a:${i}"`,A[0],A[1],!skLeft()?'Đã hết lượt':A[2],'',dis||!skLeft())});
  b+='<p class="sec">Con đường tiến hóa</p>';
  if(!K.br){b+=gRow('data-x="sk:br:war"','sword','Nhánh chiến binh: Skeleton Warrior','Giáp, kiếm nguyền, dẫn cận vệ · cần thiên phú kiếm','',dis);b+=gRow('data-x="sk:br:mage"','wand','Nhánh pháp thuật: Skeleton Mage','Tử thuật, nghiên cứu linh hồn, Hộp Linh Hồn · cần ma lực','',dis);b+='<p class="note">Không bắt buộc. Bạn vẫn có thể sống như một thợ rèn, thương nhân hay thư lại mang hình hài bộ xương.</p>'}
  else{const T=SKBR[K.br].t,mx=T.length;b+=`<p class="note">${SKBR[K.br].n}: ${T.map((x,i)=>i<K.rk?`<b>${x}</b>`:x).join(' → ')}</p>`;
    if(K.rk<mx){const need=[0,30,70,120][K.rk],why=S.done.skt?'Đã luyện năm nay':K.br==='war'&&(S.blade||0)<40+K.rk*10?`Cần kiếm thuật ${40+K.rk*10}`:K.br==='mage'&&S.st.magic<40+K.rk*12?`Cần ma lực ${40+K.rk*12}`:'';b+=gRow('data-x="sk:train"',K.br==='war'?'sword':'wand',K.br==='war'?'Luyện kiếm nguyền':'Nghiên cứu tử thuật',why||`Tiến độ ${K.xp}/${need||30} · linh hồn −5`,'',dis||!!why)}
    if(K.br==='mage'&&K.rk>=2||K.br==='war'&&K.rk>=2)b+=gRow('data-x="sk:raise"','skull',K.br==='mage'?'Gọi xác sống dậy':'Chiêu mộ cận vệ xương','Quân đoàn +10 · dân sợ hãi',S.done.skr?'Đã làm năm nay':'',dis||!!S.done.skr)}
  b+='<p class="note">Người thân có thể tin, sợ hãi, che giấu hoặc tố cáo bạn. Chính giáo luôn để mắt tới bộ xương biết đi.</p>';
  return[skTitle(),b,'act'];
}
function skAct(a,v){
  const K=SKX();let t='',tone='';
  if(a==='cure'){if(S.done.skc||isSk())return;const c=v==='priest'?40:60;if(S.money<c)return;S.money-=c;S.done.skc=1;const p=v==='priest'?.3+S.st.piety/200:.3+S.st.magic/200;if(ch(p)){S.flags.curse=0;S.dq=(S.dq||[]).filter(x=>!/^sk_/.test(x.id));t=v==='priest'?'Cha xứ rảy nước thánh lên ngực bạn. Hơi lạnh rút đi như sương tan.':'Ba pháp sư Tháp Bạc đọc thần chú suốt đêm. Lời nguyền bị bóc ra khỏi xương bạn.';tone='good'}else{t='Phương pháp không có tác dụng. Hơi lạnh vẫn lan dần.';tone='bad'}}
  else if(a==='a'){if(!skLeft())return;const A=SKA[+v];const r=A[3]();if(r===null){note={t:A[4],tone:'bad'};return drawSheet()}S.done.sk=(S.done.sk||0)+1;[t,tone]=arr(r)}
  else if(a==='br'){if(K.br)return;K.br=v;K.rk=1;K.xp=0;t=v==='war'?'Bạn khoác bộ giáp gỉ tìm thấy trong hầm mộ và nhặt thanh kiếm của một hiệp sĩ đã chết. Bạn là Skeleton Warrior.':'Bạn bắt đầu đọc những cuốn sách viết bằng mực xương. Bạn là Skeleton Mage.';tone='magic'}
  else if(a==='train'){if(S.done.skt||!K.br)return;S.done.skt=1;S.soul=Math.max(1,S.soul-5);K.xp+=R(12,22);const need=[0,30,70,120][K.rk];t=K.br==='war'?'Bạn luyện kiếm với những bộ xương khác đến khi xương tay mòn vẹt.':'Bạn nghiên cứu cách linh hồn bám vào xương thịt.';tone='magic';
    if(K.rk<SKBR[K.br].t.length&&K.xp>=need){if(K.br==='mage'&&K.rk===1){S.pend.push('sk_necro')}else if(K.br==='mage'&&K.rk===2){S.pend.push('sk_lich')}else if(K.br==='mage'&&K.rk===3){if(S.phy&&S.phy.ok&&!S.phy.stolen)S.pend.push('sk_archlich');else{t+=' Muốn thành Archlich, Hộp Linh Hồn phải nguyên vẹn trong tay bạn.';K.xp=need-5}}else{K.rk++;K.xp=0;mod({health:10,honor:-2});t+=` Bạn tiến hóa thành ${skTitle()}.`;tone='good';if(K.rk===3)announce('Dread Knight',`${S.first} khoác giáp đen, trở thành Dread Knight. Những bộ xương khác quỳ xuống khi nó đi qua.`,'skull','skelcurse')}}}
  else if(a==='raise'){if(S.done.skr)return;S.done.skr=1;K.leg+=10;S.flags.suspect=(S.flags.suspect||0)+2;rep('d',-3);fac(-3,0);t=K.br==='mage'?'Bạn đứng giữa nghĩa địa cổ, giơ tay. Mười bộ xương bò lên khỏi mộ, quỳ chờ lệnh.':'Mười hiệp sĩ xương trong hầm mộ đứng dậy theo tiếng gọi của bạn.';tone='magic'}
  log(t,tone);note={t,tone};afterSheetAction();
}
/* Lich hồi sinh từ Hộp Linh Hồn */
{const d0=die;die=function(cause){if(S&&S.alive&&isSk()&&S.phy&&S.phy.ok&&!S.phy.stolen&&!/linh hồn/.test(cause)&&S.phy.hp>25){S.phy.hp-=25;S.st.health=40;S.soul=Math.max(10,(S.soul||0)-15);log(`Bạn bị hủy diệt vì ${cause}. Nhưng ở nơi cất giấu, Hộp Linh Hồn sáng lên. Xương cốt bạn tự ráp lại trong bóng tối.`,'magic');announce('Lich tái sinh',`${S.first} trở về từ cõi chết nhờ Hộp Linh Hồn. Hộp đã rạn thêm một vết.`,'skull','lich');return}return d0(cause)}}
{const p0=prefix;prefix=function(){if(S&&S.flags.deathKing&&S.house.title>=2&&rules())return'Vua Tử Vong ';return p0()}}
{const r0=roleOf;roleOf=function(){if(S&&S.alive&&isSk()&&!S.job&&!(S.house.title>=2&&rules()))return skTitle().toLowerCase();return r0()}}
const SK_EV=[
 {id:'sk_coffin',queued:true,big:true,art:'skull',img:'skelcurse',c:s=>s.alive&&!isSk()&&!s.flags.curse,title:'Lời Nguyền Trong Hầm Mộ',text:'Sâu dưới hầm mộ, bạn tìm thấy một quan tài niêm phong bằng xích bạc. Trên nắp có một viên đá đỏ đang đập chậm rãi như một trái tim: Trái Tim Bất Tử.',
  ch:[{t:'Mở quan tài, chạm vào cổ vật',f:s=>{s.flags.curse=1;mod({magic:8});later('sk_cold',R(1,2));const g=R(30,90);s.money+=g;return[`Viên đá lạnh buốt trong lòng bàn tay rồi tan vào da bạn. Trong quan tài có ${g} xu vàng cổ.`,'magic']}},
      {t:'Mang về cho pháp sư nghiên cứu',f:s=>{rep('m',4);const g=R(40,80);s.money+=g;return`Học viện Tháp Bạc trả ${g} xu và cấm bạn kể lại chuyện này với ai.`}},
      {t:'Phá phong ấn',f:s=>{if(ch(.5)){mod({health:-R(10,25)});return['Phong ấn nổ tung. Bạn bị hất văng vào vách đá.','bad']}mod({piety:4,honor:3});return['Bạn đập vỡ viên đá. Một tiếng thét xa xăm vang lên rồi tắt lịm.','good']}},
      {t:'Rút lui',f:()=>'Bạn quay lưng, không ngoái lại.'}]},
 {id:'sk_cold',queued:true,big:true,art:'snowflake',c:s=>s.alive&&s.flags.curse===1,title:'Hơi lạnh trong xương',text:'Giữa mùa hè, bạn vẫn run lập cập. Vết thương không chảy máu. Con chó trong nhà sủa mỗi khi bạn đi qua.',
  ch:[{t:'Tìm cách chữa',f:s=>{s.flags.curse=2;later('sk_turn',R(1,3));return'Bạn bắt đầu tìm thầy. Lời nguyền đã sang giai đoạn hai. Có thể chữa trong mục Hoạt động trước khi quá muộn.'}},
      {t:'Đón nhận nó',f:s=>{s.flags.curse=2;later('sk_turn',1);mod({magic:5});return['Bạn để hơi lạnh lan đi. Nó không đau như bạn tưởng.','magic']}}]},
 {id:'sk_turn',queued:true,big:true,art:'skull',img:'skelcurse',c:s=>s.alive&&s.flags.curse===2&&!isSk(),title:'Linh hồn bị níu giữ',text:'Một đêm, tim bạn ngừng đập. Nhưng bạn vẫn mở mắt được. Bạn nhìn xuống bàn tay mình, và thấy xương.',
  ch:[{t:'Chấp nhận thân phận mới',f:s=>{skBecome();return['Bạn đứng dậy. Bạn là một bộ xương.','magic']}},
      {t:'Cầu nguyện đến hơi thở cuối',f:s=>{if(ch(.2+s.st.piety/250)){s.flags.curse=0;mod({piety:10,health:-20});return['Bình minh đến. Tim bạn đập lại, yếu ớt nhưng ấm áp. Lời nguyền đã buông tha.','good']}skBecome();return['Lời cầu nguyện không đủ. Bạn mở mắt lần nữa, trong hình hài bộ xương.','magic']}}]},
 {id:'sk_wife',queued:true,big:true,art:'heart-break',c:s=>s.alive&&isSk()&&!!spouse(),title:'Người Bạn Đời Nhận Ra Bộ Xương',text:s=>`${spouse().first} thức dậy giữa đêm và nhìn thấy bạn đứng bên cửa sổ dưới ánh trăng. Không còn da thịt nào có thể che giấu.`,
  ch:[{t:'Nói hết sự thật',f:s=>{const p=spouse();if(ch(p.bond/110)){p.bond=clamp(p.bond+10);return['Người ấy khóc rất lâu, rồi nắm lấy bàn tay xương của bạn. "Ta lấy người, không phải lấy da thịt."','good']}p.bond=clamp(p.bond-40);if(p.bond<15){p.alive=false;p.gone=1;return['Người ấy bỏ đi trước khi trời sáng, không mang theo gì.','bad']}return['Người ấy không nói gì suốt một tháng.','bad']}},
      {t:'Giấu thân phận',f:s=>{s.flags.skHide=1;spouse().bond=clamp(spouse().bond-10);return'Bạn quấn khăn kín mặt, nói rằng mình bị bệnh phong. Lời nói dối nặng hơn bộ xương.'}},
      {t:'Rời nhà',f:s=>{const p=spouse();p.bond=clamp(p.bond-20);mod({happy:-15});return['Bạn để lại thư và ra đi. Người ấy sẽ nghĩ bạn đã chết, và có lẽ như thế lại tốt hơn.','bad']}}]},
 {id:'sk_child',queued:true,big:true,art:'baby',c:s=>s.alive&&isSk()&&kids().length>0,prep:s=>{s.tmpK=pick(kids()).id;s.tmp=1},title:'Đứa Con Sợ Hãi',text:s=>{const k=s.fam.find(x=>x.id===s.tmpK);return`${k?k.first:'Con bạn'} không dám nhìn bạn nữa. Mỗi khi bạn bước vào phòng, con lùi sát vào tường.`},
  ch:[{t:'Kiên nhẫn ở bên con mỗi ngày',f:s=>{const k=s.fam.find(x=>x.id===s.tmpK);if(k)k.bond=clamp(k.bond+(ch(.6)?15:-5));return['Bạn kể cho con những câu chuyện mà chỉ cha mẹ thật mới biết. Dần dần con ngồi gần bạn hơn.','good']}},
      {t:'Gửi con sang nhà họ hàng',f:s=>{const k=s.fam.find(x=>x.id===s.tmpK);if(k)k.bond=clamp(k.bond-15);mod({happy:-6});return'Có lẽ con sẽ an toàn hơn khi xa bạn.'}}]},
 {id:'sk_exorcist',queued:true,big:true,art:'church',img:'inquisition',c:s=>s.alive&&isSk(),title:'Thầy Trừ Tà Đến Gõ Cửa',text:'Ba thầy dòng áo trắng đứng trước cửa với nước thánh và xích bạc. Có người đã tố cáo nhà bạn chứa xác sống.',
  ch:[{t:'Thương lượng, chứng minh bạn vô hại',f:s=>{if(ch(.3+s.st.honor/250+FAC().o/300)){s.flags.skTol=1;return['Bạn để họ ở lại một tuần, xem bạn làm việc, cầu nguyện, chăm con. Họ ra về, mang theo một bản tường trình kỳ lạ.','good']}fac(-5,0);return['Họ không tin một lời nào. Bạn phải bỏ trốn qua cửa sau.','bad']}},
      {t:'Trốn vào hầm mộ',f:s=>{mod({happy:-5});s.soul=Math.min(100,s.soul+5);return'Bạn sống dưới lòng đất ba tháng. Khi bạn trở về, họ đã đi.'}},
      {t:'Đối đầu',f:s=>{if(ch(.4+SKX().leg/200+(SKX().br==='war'?SKX().rk*.1:0))){fac(-8,0);mod({honor:-3});return['Bạn đánh đuổi ba thầy dòng. Giáo hội sẽ không bỏ qua chuyện này.','']}mod({health:-R(25,45)});return['Nước thánh làm xương bạn bốc khói.','bad']}}]},
 {id:'sk_morvain',queued:true,big:true,art:'crown',img:'lich',c:s=>s.alive&&isSk(),title:'Vua Bất Tử Morvain Mời Gia Nhập',text:'Vua Bất Tử Morvain ngự trên ngai xương, vương miện cắm sâu vào sọ. Giọng hắn vang trong đầu bạn: "Ngươi là một trong chúng ta. Quỳ xuống, ta sẽ cho ngươi quân đoàn."',
  ch:[{t:'Thần phục Morvain',f:s=>{const K=SKX();K.leg+=25;K.mor=1;mod({magic:8,honor:-6});fac(-6,0);return['Bạn quỳ xuống. Hai mươi lăm hiệp sĩ xương bước ra khỏi bóng tối, đứng sau lưng bạn.','magic']}},
      {t:'Giả vờ thần phục, làm gián điệp cho Giáo hội',f:s=>{if(ch(.45+s.st.smarts/250)){fac(10,0);SKX().mor=2;s.flags.skTol=1;mod({honor:5});return['Bạn gửi bản đồ hầm mộ cho Giáo hội. Một nửa quân đoàn của Morvain bị thánh hỏa thiêu rụi.','good']}mod({health:-R(20,40)});return['Morvain đọc được ý nghĩ của bạn. Hắn cười, và xương bạn nứt ra.','bad']}},
      {t:'Từ chối',f:s=>{SKX().mor=-1;return'Bạn quay lưng. Morvain không ngăn bạn. Hắn có cả vĩnh hằng để chờ.'}}]},
 {id:'sk_necro',queued:true,big:true,art:'wand',img:'necro',c:s=>s.alive&&isSk()&&SKX().br==='mage'&&SKX().rk===1,title:'Thức Tỉnh Necromancer',text:'Bạn đọc xong trang cuối cuốn sách mực xương. Dưới chân bạn, đất nghĩa địa bắt đầu chuyển động. Những người chết đang chờ lệnh.',
  ch:[{t:'Ra lệnh cho họ đứng dậy',f:s=>{const K=SKX();K.rk=2;K.xp=0;K.leg+=10;mod({magic:10});if(hasHon('daiphapsu'))honSet('daiphapsu','stripped','Học viện Tháp Bạc thu hồi vì dùng tử thuật');announce('Necromancer',`${s.first} thức tỉnh tử thuật. Người chết nghe theo tiếng gọi của nó.`,'skull','necro');return['Mười bộ xương đứng dậy. Bạn là Necromancer.','magic']}},
      {t:'Đóng sách, giữ mình trong sạch',f:s=>{SKX().xp=20;mod({piety:3});return'Bạn đóng cuốn sách lại. Có những cánh cửa không nên mở.'}}]},
 {id:'sk_lich',queued:true,big:true,art:'skull',img:'lich',c:s=>s.alive&&isSk()&&SKX().br==='mage'&&SKX().rk===2,title:'Tiến Hóa Thành Lich',text:'Nghi thức Lich đòi bạn tách một phần linh hồn, giam vào một chiếc hộp. Nếu thân xác bị hủy, hộp sẽ kéo bạn về. Nếu hộp vỡ, bạn chết thật.',
  ch:[{t:'Tạo Hộp Linh Hồn (100 xu)',cost:100,f:s=>{s.money-=100;const K=SKX();if(ch(.65+s.st.magic/400)){K.rk=3;K.xp=0;s.phy={ok:1,hp:100,y:s.year,stolen:0};s.soul=Math.min(100,s.soul+20);announce('Lich',`${s.first} hoàn tất nghi thức Lich. Một phần linh hồn nó nằm trong chiếc hộp không ai biết ở đâu.`,'skull','lich');return['Chiếc hộp đen khép lại, giữ một phần của bạn bên trong. Bạn là Lich.','magic']}s.soul=Math.max(5,s.soul-25);return['Linh hồn bạn rách ra nhưng không chịu vào hộp. Bạn mất một phần bản thân vĩnh viễn.','bad']}},
      {t:'Chưa sẵn sàng',f:s=>{SKX().xp=50;return'Bạn hoãn nghi thức.'}}]},
 {id:'sk_archlich',queued:true,big:true,art:'crown',img:'lich',c:s=>s.alive&&isSk()&&SKX().rk===3&&s.phy&&s.phy.ok,title:'Nghi Thức Archlich',text:'Hộp Linh Hồn của bạn đã ổn định. Nghi thức cuối cùng sẽ hợp nhất tử thuật của bạn với chính cái chết.',
  ch:[{t:'Thực hiện nghi thức',f:s=>{const K=SKX();if(ch(.5+s.st.magic/300)){K.rk=4;mod({magic:15});s.phy.hp=100;return['Ngọn lửa xanh trong mắt bạn hóa trắng. Bạn là Archlich.','magic']}s.phy.hp-=40;if(s.phy.hp<=0)s.phy.ok=0;return['Nghi thức thất bại. Hộp Linh Hồn rạn một vết dài.','bad']}},
      {t:'Dừng lại ở Lich',f:()=>'Bạn quyết định quyền năng hiện tại đã đủ.'}]},
 {id:'sk_phystolen',queued:true,big:true,art:'chest',c:s=>s.alive&&isSk()&&s.phy&&s.phy.stolen,title:'Hộp Linh Hồn Bị Đánh Cắp',text:'Bạn tỉnh dậy với cảm giác trống rỗng. Nơi cất Hộp Linh Hồn chỉ còn dấu chân của ai đó mang ủng có đinh bạc: thợ săn của Giáo hội.',
  ch:[{t:'Truy lùng kẻ trộm',f:s=>{if(ch(.4+s.st.smarts/250+SKX().leg/250)){s.phy.stolen=0;return['Bạn đuổi kịp kẻ trộm ở bến sông và giành lại chiếc hộp.','good']}s.phy.ok=0;s.phy.stolen=0;s.soul=Math.max(5,s.soul-20);return['Bạn đến muộn. Chiếc hộp bị ném vào lò thánh hỏa. Bạn cảm thấy một phần mình bốc cháy.','bad']}},
      {t:'Thuê Mắt Quạ tìm (60 xu)',cost:60,f:s=>{s.money-=60;if(ch(.65)){s.phy.stolen=0;return['Con quạ mang về một mẩu giấy ghi địa chỉ. Hộp Linh Hồn trở về tay bạn.','good']}s.phy.ok=0;s.phy.stolen=0;return['Mắt Quạ chỉ tìm được những mảnh vỡ.','bad']}}]},
 {id:'sk_return',w:s=>isSk()&&s.soul>=60&&FAC().o>=50?2:0,cd:30,big:true,art:'holy',img:'saint',c:s=>isSk()&&!s.flags.deathKing,title:'Lựa Chọn Trở Lại Làm Người',text:'Một Thánh Nữ già tìm đến. Bà biết một nghi thức cổ có thể trả lại thân xác cho bộ xương còn giữ được linh hồn. Cái giá rất lớn, và không chắc thành công.',
  ch:[{t:'Thực hiện nghi thức (200 xu)',cost:200,f:s=>{s.money-=200;if(ch(.4+s.st.piety/300)){s.race=s.flags.skelFrom||'human';s.flags.curse=0;s.soul=null;s.sk=null;s.phy=null;s.st.looks=R(30,60);s.st.health=50;mod({piety:10,magic:-20,happy:15});announce('Trở lại làm người',`${s.first} có lại hơi thở, nhịp tim và hơi ấm.`,'holy','saint');return['Bạn cảm thấy gió trên da mình lần đầu sau nhiều năm. Bạn bật khóc, và nước mắt là thật.','good']}s.soul=Math.max(5,s.soul-30);return['Nghi thức thất bại. Bạn vẫn là bộ xương, và mất thêm một phần linh hồn.','bad']}},
      {t:'Giữ hình hài hiện tại',f:()=>'Bạn đã quen với mình như thế này.'}]},
 {id:'sk_empire',queued:true,big:true,art:'skull',img:'lich',c:s=>s.alive&&isSk()&&!s.flags.deathKing,title:'Đế Chế Xương Trắng',text:s=>`Quân đoàn ${SKX().leg} xác sống đã đứng chờ trong lãnh địa của bạn. Chúng chỉ cần một lời: dựng cờ Đế Chế Xương Trắng, và bạn sẽ là Vua Tử Vong.`,
  ch:[{t:'Dựng cờ Đế Chế Xương Trắng',f:s=>{s.flags.deathKing=1;s.flags.dark=1;s.world.cat=s.world.cat||{id:'player',y:s.year};if(s.house.title<5)grantTitle(5);news(`${s.first} dựng Đế Chế Xương Trắng. Các vương quốc và Anh Hùng chuẩn bị liên minh.`,'bad',true);announce('Vua Tử Vong',`${s.first} tự xưng Vua Tử Vong. Quân đoàn xương trắng đứng kín các ngọn đồi.`,'skull','lich');return['Bạn giơ quyền trượng. Hàng vạn hốc mắt xanh cùng sáng lên.','magic']}},
      {t:'Giải tán quân đoàn, sống yên bình',f:s=>{SKX().leg=0;mod({honor:5});return'Bạn để những người chết nằm xuống trở lại.'}}]}
];

/* ---------- 10. Mạng lưới Bóng Tối ---------- */
const DMK=()=>{if(!S.dm)S.dm={con:0,heat:0,vic:[],freed:0,tr:0};return S.dm};
const SLAVELAW=()=>{const w=S.world;if(!w.slv)w.slv={};for(const n of REALMS)if(!w.slv[n])w.slv[n]=NATIONS[n]?NATIONS[n].slv:/Thánh quốc|Liên minh/.test(n)?'ban':ch(.5)?'ban':'allow';return w.slv};
const dmOn=()=>!!(S.hc&&S.hc.k==='trade'&&S.hc.rk>=1)||(S.job&&S.job.id==='blackmarket');
const dmLeft=()=>Math.max(0,2-(S.done.dm||0));
function dmYear(){const D=S.dm;if(!D)return;D.heat=Math.max(0,D.heat-5);
  if(D.heat>=70&&ch(.35)&&!S.pend.includes('dm_raid'))S.pend.push('dm_raid');
  for(const v of D.vic){if(v.st!=='held')continue;v.y2=(v.y2||0)+1;if(ch(.12)){v.st='escaped';log(`${v.name} đã trốn thoát khỏi nơi bạn bán họ đến. Người ấy biết tên bạn.`,'bad');later('dm_hero',R(5,12),{name:v.name,first:v.first,bad:1},1)}}
  if(D.vic.filter(v=>v.st==='held').length>=4&&ch(.2)&&!S.pend.includes('dm_revolt'))S.pend.push('dm_revolt');
  if(SLAVELAW()[S.realm]==='allow'&&(S.flags.saint||isKing())&&ch(.06)&&!S.pend.includes('dm_saint'))S.pend.push('dm_saint');
}
const DMA=[
  ['crystal-ball','Buôn cổ vật cấm','Lời cao · có thể bị tịch thu · bất ổn phép thuật',()=>{const D=DMK();D.heat+=10;ten(1);if(ch(.18)){const l=Math.min(Math.max(S.money,0),R(20,60));S.money-=l;return[`Lính hải quan mở hòm, tịch thu cả lô cổ vật. Bạn mất ${l} xu.`,'bad']}const g=R(30,80)+D.con*3;S.money+=g;rep('u',2);if(ch(.08)){S.flags.cryptMap=1;return[`Bạn bán bộ đồ tùy táng được ${g} xu. Người mua gửi lại cho bạn một tấm bản đồ hầm mộ cũ.`,'magic']}return[`Một pháp sư giấu mặt mua chiếc gương cổ với giá ${g} xu.`,'good']}],
  ['message','Môi giới bí mật','Đầu mối trong giới quý tộc · có thể bị phản gián',()=>{const D=DMK();D.con++;D.heat+=6;if(ch(.15)){mod({health:-R(5,15)});rep('n',-3);return['Người bán tin hóa ra là chim mồi của Mắt Quạ.','bad']}const g=R(15,40);S.money+=g;rep('u',2);const r=pick((S.rel||[]).filter(x=>x.alive&&x.kind!=='lover'));if(r&&ch(.4)){npcInit(r);return`Bạn bán một tin về hôn sự nhà bá tước, được ${g} xu, và mua được một tin về ${r.first}: ${clueRoll(r)}`}return[`Bạn bán tin cho đúng người, được ${g} xu.`,'good']}],
  ['anchor','Vận chuyển hàng lậu','Lời theo chiến tranh và thuyền · có thể bị truy quét',()=>{const D=DMK();D.heat+=12;const war=Object.values(WD().rs).filter(r=>r.war).length;const boat=S.boat?BOATS[S.boat.k].lv:0;if(ch(.2-boat*.03)){fine(30);D.heat+=10;return['Đội tuần cảng chặn thuyền. Bạn phải nộp phạt và mất hàng.','bad']}const g=R(20,50)+war*10+boat*8;S.money+=g;return[`Bạn chở muối và rượu qua biên giới trong đêm, lời ${g} xu.`,'good']}],
  ['user-remove','Nhận vận chuyển tù binh bị bán làm nô lệ','Tiền bẩn · danh dự, lòng dân giảm mạnh · có thể bị truy tố',()=>{const D=DMK();const banned=SLAVELAW()[S.realm]==='ban';D.heat+=banned?25:15;D.tr++;const sx=pick(['m','f']),race=pick(RPUB()),first=pick(nameList(sx,race)),sur=surFor(race,'serf');D.vic.push({first,name:`${first} ${sur}`,race,st:'held',y:S.year});mod({honor:-15,happy:-5,piety:-5});rep('d',-8);rep('n',-2);const g=R(20,45);S.money+=g;if(banned&&ch(.25)){fine(80);mod({honor:-10});return[`Bạn bị bắt quả tang khi đang áp giải ${first}. Luật ${S.realm} cấm buôn người: bạn bị phạt nặng.`,'bad']}return[`Bạn nhận ${g} xu để áp giải ${first} ${sur}, một tù binh ${RACES[race].n}, đến điền trang của một lãnh chúa. Suốt đường đi, ${first} không nói một lời, chỉ nhìn bạn.`,'bad']}],
  ['user-check','Chuộc và giải phóng một người bị nô dịch','Tốn tiền · danh dự, lòng dân, có thêm một người bạn',()=>{const c=60;if(S.money<c)return null;S.money-=c;const D=DMK();const own=D.vic.find(v=>v.st==='held');const sx=pick(['m','f']),race=own?own.race:pick(RPUB());const first=own?own.first:pick(nameList(sx,race));if(own)own.st='freed';D.freed++;S.flags.freed=(S.flags.freed||0)+1;mod({honor:8,piety:3,happy:5});rep('d',5);const r=addFriend({first,race,cls:'serf',bond:R(70,90),sex:own?undefined:sx});if(ch(.3))later('dm_hero',R(5,12),{name:r?r.name:first,first,bad:0},1);return[own?`Bạn quay lại chuộc ${first}, người bạn từng áp giải. ${first} nhìn bạn rất lâu, rồi nhận lấy giấy tự do.`:`Bạn trả ${c} xu chuộc ${first} khỏi chợ nô lệ và trao giấy tự do. ${first} quỳ xuống rồi đứng dậy, lần đầu tiên tự chọn đi đâu.`,'good']},'Cần 60 xu'],
  ['protect','Tố giác đường dây buôn người','Lòng dân, Chính giáo · mạng lưới ngầm thù bạn',()=>{const D=DMK();if(ch(.4+S.st.smarts/250)){rep('d',5);fac(4,0);rep('u',-6);mod({honor:6});D.con=Math.max(0,D.con-2);news(`Một đường dây buôn người ở ${S.realm} bị triệt phá nhờ tin tố giác.`,'good',true);return['Lính triều đình đột kích chợ đen lúc nửa đêm, giải thoát ba mươi người.','good']}D.heat+=10;addEnemy('trùm buôn người bị bạn tố giác',{cls:'merchant',hate:R(60,80)});return['Tin của bạn bị lộ trước khi lính kịp tới.','bad']}]
];
function dmView(){
  if(!dmOn())return['Mạng lưới Bóng Tối','<p class="note">Chỉ Thương Gia Bóng Tối hoặc thương nhân chợ đen mới với tới mạng lưới này.</p>','act'];
  const D=DMK(),dis=!S.alive,L=SLAVELAW();let b=imgBanner('slavemarket');
  b+=statGrid([['Mối quan hệ',D.con],['Bị truy quét',D.heat+'/100'],['Người đã giải phóng',D.freed],['Luật ở '+S.realm.replace(RPFX,''),L[S.realm]==='ban'?'Cấm buôn người':'Chưa cấm']]);
  b+='<p class="note">Thế giới này vẫn còn những chợ nô lệ, một hệ thống áp bức mà người bị bán là những con người có tên tuổi, có ký ức, và có thể quay lại đòi công lý. Mọi giao dịch ngầm đều để lại dấu vết.</p>';
  b+=`<p class="sec">Việc ngầm · còn ${dmLeft()}/2 việc năm nay</p>`;
  DMA.forEach((A,i)=>{b+=gRow(`data-x="dm:${i}"`,A[0],A[1],!dmLeft()?'Đã hết lượt':A[2],'',dis||!dmLeft(),false,i===3?'foe':'')});
  const held=D.vic.filter(v=>v.st==='held');if(D.vic.length)b+=`<p class="sec">Những người bạn đã áp giải</p><p class="note">${D.vic.map(v=>`${esc(v.name)}: ${v.st==='held'?'vẫn bị giam giữ':v.st==='freed'?'đã được tự do':'đã trốn thoát'}`).join('<br>')}</p>`;
  return['Mạng lưới Bóng Tối',b,'act'];
}
function dmAct(i){if(!dmOn()||!dmLeft())return;const A=DMA[+i];if(!A)return;const r=A[3]();if(r===null){note={t:A[4],tone:'bad'};return drawSheet()}S.done.dm=(S.done.dm||0)+1;const[t,tone]=arr(r);log(t,tone);note={t,tone};afterSheetAction()}
const DM_EV=[
 {id:'dm_raid',queued:true,big:true,art:'anchor',c:s=>s.alive&&!!s.dm,title:'Đoàn Thuyền Bị Truy Quét',text:'Lính cảng, thủy thủ bị mua chuộc và một quan triều đình cùng ập vào kho hàng của bạn lúc rạng sáng. Họ có danh sách tên những người trong mạng lưới.',
  ch:[{t:'Đút lót viên quan (60 xu)',cost:60,f:s=>{s.money-=60;s.dm.heat=Math.max(0,s.dm.heat-30);return'Viên quan đếm tiền, gạch tên bạn khỏi danh sách.'}},
      {t:'Bỏ trốn, cắt đứt mạng lưới',f:s=>{s.dm.con=Math.max(0,s.dm.con-3);s.dm.heat=20;mod({happy:-5});return'Bạn đốt sổ sách và trốn sang làng bên. Mạng lưới tan rã một nửa.'}},
      {t:'Đầu thú',f:s=>{fine(100);mod({honor:-5});s.dm.heat=0;s.dm.con=0;if(s.dm.tr){mod({honor:-10});rep('d',-5);return['Tòa xét xử bạn công khai. Tội buôn người bị đọc trước cả quảng trường.','bad']}return['Bạn bị phạt nặng nhưng giữ được mạng.','bad']}}]},
 {id:'dm_revolt',queued:true,big:true,art:'flame',img:'slavemarket',c:s=>s.alive&&!!s.dm,title:'Cuộc Nổi Dậy Của Những Người Bị Nô Dịch',text:'Những người bị bán đến các điền trang trong vùng đồng loạt phá xích, đốt kho và kéo về chợ đen. Họ biết rõ ai đã đưa họ đến đây.',
  ch:[{t:'Đứng về phía họ, mở kho giải phóng',f:s=>{const D=s.dm;for(const v of D.vic)if(v.st==='held')v.st='freed';D.freed+=3;D.con=0;D.heat=30;mod({honor:10});rep('d',6);SLAVELAW()[S.realm]='ban';news(`Cuộc nổi dậy ở ${S.realm} buộc triều đình cấm chợ nô lệ.`,'good',true);return['Bạn đập vỡ ổ khóa đầu tiên. Đám đông im lặng nhìn bạn, rồi để bạn đi.','good']}},
      {t:'Gọi lính dập tắt',f:s=>{rep('d',-8);mod({honor:-8});s.dm.heat+=20;for(const v of s.dm.vic)if(v.st==='held'&&ch(.4)){v.st='escaped';later('dm_hero',R(5,10),{name:v.name,first:v.first,bad:1},1)}return['Cuộc nổi dậy bị dập tắt trong máu. Nhiều người trốn được vào rừng.','bad']}},
      {t:'Bỏ chạy',f:s=>{s.dm.con=Math.max(0,s.dm.con-4);const l=Math.min(Math.max(s.money,0),R(20,80));s.money-=l;return[`Kho hàng của bạn bị đốt. Bạn mất ${l} xu.`,'bad']}}]},
 {id:'dm_saint',queued:true,big:true,art:'holy',img:'slavemarket',c:s=>s.alive&&SLAVELAW()[S.realm]==='allow',title:'Thánh Nữ Lên Án Chợ Nô Lệ',text:s=>s.flags.saint?'Bạn đứng giữa chợ nô lệ và cảm thấy Thánh Quang nóng rực trong ngực. Cả quảng trường đang nhìn bạn.':'Thánh Nữ đứng giữa chợ nô lệ, chỉ tay lên ban công cung điện: "Vương quốc nào bán con người, vương quốc ấy đã bán linh hồn mình." Cả triều đình chờ nhà vua lên tiếng.',
  ch:[{t:s=>s.flags.saint?'Lên án công khai':'Ban lệnh cấm buôn người',f:s=>{SLAVELAW()[S.realm]='ban';fac(6,0);rep('d',6);rep('n',-4);mod({honor:6});if(s.kd)s.kd.stab=clamp((s.kd.stab||60)-3);news(`${S.realm} cấm chợ nô lệ.`,'good',true);return['Chợ nô lệ đóng cửa. Vài lãnh chúa bất mãn, nhưng dân chúng reo hò.','good']}},
      {t:s=>s.flags.saint?'Im lặng':'Duy trì chế độ',f:s=>{fac(-6,0);rep('d',-3);if(s.flags.saint&&s.saint)s.saint.doubt=clamp(s.saint.doubt+10);return['Chợ nô lệ vẫn họp. Thánh Nữ rời kinh thành trong im lặng.','bad']}}]},
 {id:'dm_hero',queued:true,big:true,art:'sword',c:s=>s.alive&&s.age>=14,title:'Người Từng Bị Nô Dịch Trở Thành Anh Hùng',text:s=>{const d=dqd('dm_hero');return d.bad?`${d.name}, người bạn từng áp giải đến chợ nô lệ, giờ là thủ lĩnh một đoàn chiến binh tự do. Người ấy đứng trước cửa nhà bạn, tay cầm kiếm.`:`${d.name}, người bạn từng chuộc khỏi chợ nô lệ, giờ là người được cả vùng kính trọng. Người ấy đến tìm bạn.`},
  ch:[{t:s=>dqd('dm_hero').bad?'Quỳ xuống xin lỗi':'Mời vào nhà',f:s=>{const d=dqd('dm_hero');if(d.bad){if(ch(.5+s.st.honor/300)){mod({honor:5,happy:-5});return['Người ấy nhìn bạn rất lâu rồi tra kiếm vào bao. "Ta không tha thứ, nhưng ta không giết người quỳ."','']}mod({health:-R(20,40)});return['Lưỡi kiếm để lại một vết sẹo dài trên mặt bạn. "Để ngươi nhớ."','bad']}const g=R(30,80);s.money+=g;mod({happy:8,honor:4});rep('d',3);return[`Người ấy mang theo ${g} xu và một lời mời: khi bạn cần, đoàn chiến binh tự do sẽ có mặt.`,'good']}},
      {t:s=>dqd('dm_hero').bad?'Rút kiếm':'Từ chối gặp',f:s=>{const d=dqd('dm_hero');if(d.bad){if(ch(.4+(s.blade||0)/300)){mod({honor:-5});addEnemy('người từng bị bạn bán làm nô lệ',{first:d.first,hate:90});return['Bạn đẩy lùi được người ấy. Nhưng người ấy sẽ quay lại.','bad']}if(ch(.25)){die('dưới lưỡi kiếm của người từng bị bán làm nô lệ');return['Công lý đến muộn, nhưng vẫn đến.','bad']}mod({health:-R(20,35)});return['Bạn thua.','bad']}return'Bạn sai người hầu nói mình đi vắng.'}}]},
 {id:'dm_pow',queued:true,big:true,art:'w-halberd',img:'slavemarket',c:s=>s.alive&&(isKing()||isMil(s)&&s.co.rk>=3),title:'Tù Binh Sau Chiến Tranh',text:'Sau chiến thắng, hàng trăm tù binh bị dồn trong trại. Các lãnh chúa muốn bán họ làm nô lệ để bù chi phí chiến tranh.',
  ch:[{t:'Trao đổi tù binh với đối phương',f:s=>{mod({honor:5});rep('n',2);s.flags.peace=s.flags.peace||ch(.3)?1:0;return['Hai bên đổi tù binh ở cầu biên giới. Lời đồn về lòng khoan dung của bạn lan sang cả nước địch.','good']}},
      {t:'Thả về sau khi chiến tranh kết thúc',f:s=>{mod({honor:4});rep('n',-2);rep('d',2);return'Bạn cho tù binh làm việc sửa đường đến khi hòa bình rồi thả về.'}},
      {t:'Để các lãnh chúa bán họ',f:s=>{const g=R(40,120);s.money+=g;mod({honor:-12});rep('d',-6);fac(-5,0);later('dm_hero',R(6,12),{name:'một tù binh năm xưa',first:'Người tù binh',bad:1},1);return[`Ngân khố thu về ${g} xu. Các tù binh bị xích dắt đi về phía chợ.`,'bad']}}]}
];
/* dò bản đồ hầm mộ */
DM_EV.push({id:'dm_map',w:s=>dmOn()?3:0,cd:20,big:true,art:'map',c:s=>dmOn()&&!s.flags.cryptMap&&s.age>=16,title:'Chiếc Bản Đồ Hầm Mộ',text:'Một thương nhân bóng tối chìa ra tấm bản đồ da: đường vào Hầm Mộ Vương Triều Thất Lạc. Hắn thề nó là thật.',
  ch:[{t:'Mua bản đồ (40 xu)',cost:40,f:s=>{s.money-=40;if(ch(.65)){s.flags.cryptMap=1;return['Bản đồ khớp với những ngọn núi bạn biết. Hầm Mộ Vương Triều Thất Lạc giờ hiện ra trong mục Vùng đất các tộc.','magic']}return['Bản đồ là đồ giả vẽ trên da lợn.','bad']}},{t:'Không mua',f:()=>'Bạn không tin những thứ quá tốt để là thật.'}]});

/* ---------- 11. Bang hội của riêng bạn ---------- */
const GCLS={war:{n:'Chiến binh',ic:'sword'},tank:{n:'Hộ vệ khiên',ic:'shield'},mage:{n:'Pháp sư',ic:'wand'},heal:{n:'Mục sư',ic:'bless'},scout:{n:'Trinh sát',ic:'bow'}};
const GTR={loyal:{n:'trung thành',loy:2},greedy:{n:'tham lam',loy:-2,wage:3},brave:{n:'dũng cảm',pw:6},timid:{n:'nhút nhát',pw:-4,safe:1},hot:{n:'nóng nảy',pw:3,loy:-1},calm:{n:'điềm tĩnh',loy:1},keen:{n:'ham học',xp:1}};
const GHALL=[{n:'Gian phòng thuê ở quán rượu',cap:4,up:5},{n:'Hội quán gỗ',cap:6,c:200,up:12},{n:'Hội quán đá',cap:9,c:450,up:25},{n:'Pháo đài bang hội',cap:12,c:900,up:45},{n:'Đại sảnh huyền thoại',cap:16,c:1800,up:80}];
const GFOC={hunt:{n:'Săn quái vật',ic:'bow'},merc:{n:'Đánh thuê',ic:'crossed'},arc:{n:'Nghiên cứu ma pháp',ic:'wand'},trade:{n:'Thương đoàn',ic:'coins'}};
const GSPLIT={hall:{n:'Quỹ hội giữ phần lớn',d:'70% vào quỹ, 30% chia thành viên',hall:.7,me:0,loy:-1},fair:{n:'Chia đều cho anh em',d:'40% vào quỹ, 60% chia thành viên',hall:.4,me:0,loy:3},lead:{n:'Hội trưởng hưởng nhiều',d:'50% vào túi bạn, 50% vào quỹ',hall:.5,me:.5,loy:-4}};
const GRANK=[[0,'Hội vô danh'],[100,'Hội có tiếng'],[300,'Hội lừng danh'],[600,'Đại bang hội'],[900,'Bang hội huyền thoại']];
const DUNG=[
  {k:'goblin',n:'Hang Goblin',fl:3,rec:35,loot:[40,90],boss:'Vua Goblin Mũ Sắt',r:1,d:'Hợp với hội mới lập'},
  {k:'crypt',n:'Hầm Mộ Cổ',fl:4,rec:80,undead:1,loot:[80,180],boss:'Hiệp Sĩ Xương',r:1,d:'Xác sống, pháp sư rất có ích'},
  {k:'redfort',n:'Pháo Đài Hồng Nguyệt',fl:4,rec:130,loot:[120,260],boss:'Đại Tư Tế Máu',r:2,d:'Tín đồ cuồng tín, cạm bẫy phép'},
  {k:'lair',n:'Hang Rồng Núi Lửa',fl:5,rec:200,loot:[220,480],boss:'Rồng Lửa Già',r:2,d:'Cần hộ vệ khiên và mục sư'},
  {k:'lost',n:'Hầm Mộ Vương Triều Thất Lạc',fl:5,rec:280,undead:1,loot:[300,650],boss:'Thống Lĩnh Của Morvain',r:3,d:'Hầm ngục nguy hiểm nhất thiên hạ'}
];
const GD=()=>S.gd;
const gdAlive=()=>GD().mem.filter(m=>m.alive);
const gdCap=()=>GHALL[GD().lv].cap;
const gdRank=()=>GRANK.filter(x=>GD().fame>=x[0]).pop()[1];
const gmPw=m=>!m.alive||(m.inj&&m.inj>S.year)?0:m.lv*10+((GTR[m.tr]||{}).pw||0)+(m.off?3:0);
const mePw=()=>Math.round(20+(S.blade||0)/2+cbB()+S.st.magic/5+S.st.health/10);
function gdWhyFound(){if(S.gd)return'Bạn đã có bang hội';if(S.age<20)return'Từ 20 tuổi';if(isSk())return'Không ai đăng ký bang hội cho một bộ xương';if(S.money<300)return`Cần 300 xu (150 lệ phí lập hội, 150 làm quỹ ban đầu), bạn có ${S.money}`;
  const okRep=S.st.honor>=50||S.house.prestige>=250||Math.max(repV('d'),repV('n'),repV('u'),repV('m'))>=60||(S.hon||[]).some(h=>h.st!=='stripped');if(!okRep)return'Cần danh tiếng: danh dự từ 50, uy danh gia tộc từ 250, uy tín 60 với một phe, hoặc có một danh hiệu';return''}
function gNew(lvMin){const fame=S.gd?S.gd.fame:0;const sx=pick(['m','f']),race=pick(RPUB()),first=pick(nameList(sx,race)),sur=surFor(race,pick(['serf','craft','merchant']));const c=pick(Object.keys(GCLS));const lv=Math.max(1,Math.min(10,(lvMin||R(1,3))+Math.floor(fame/250)+(ch(.15)?1:0)));const tr=pick(Object.keys(GTR));return{id:uid(),first,sur,sex:sx,race,c,lv,xp:0,loy:R(45,70),wage:3+lv*3+((GTR[tr]||{}).wage||0),tr,inj:0,alive:true,off:0,y:S.year,kills:0}}
function gdBoard(){const G=GD();if(G.bd&&G.bd.y===S.year)return G.bd.L;const T={hunt:[['Diệt bầy sói ăn thịt người','Làng ven rừng treo thưởng'],['Truy dấu quái vật đầm lầy','Hội Thợ săn nhờ tiếp sức'],['Bắt sống một con bằng sư','Một bá tước muốn nuôi làm cảnh']],merc:[['Hộ tống đoàn xe muối','Qua đèo có cướp'],['Giữ cầu cho một nam tước','Ba ngày, ba đêm'],['Dẹp loạn ở một thị trấn','Lãnh chúa trả hậu']],arc:[['Phong ấn một ngôi nhà ma','Gia chủ trả bằng vàng'],['Thu thập nguyên liệu phép ở Vực Tro Tàn','Học viện đặt hàng'],['Giải lời nguyền cho một giếng làng','Dân làng góp tiền']],trade:[['Áp tải hàng sang nước láng giềng','Lãi chia theo chuyến'],['Mở đường buôn qua Thảo Nguyên','Tù trưởng Orc đòi lễ vật'],['Thu mua lúa trước mùa đói','Hội Thương nhân để mắt']]};
  const L=[0,1,2].map(i=>{const pool=ch(.6)?T[G.foc]:T[pick(Object.keys(T))];const[n,d]=pick(pool);const df=Math.round((25+R(0,40))*(1+G.fame/400)*(i===2?1.6:i===1?1.15:.8));return{n,d,df,rew:Math.round(df*R(8,12)/10),fame:Math.round(df/6),risk:i===2?2:1,sl:i===2?4:i===1?3:2,done:0}});G.bd={y:S.year,L};return L}
function gdFound(){
  const why=gdWhyFound();if(why)return;const inp=$('#gdn');const nm=cleanName(inp?inp.value:'');
  if(!/^[\p{L}][\p{L}\p{N} '\-]{1,27}$/u.test(nm)){note={t:'Tên hội cần 2–28 ký tự, chỉ gồm chữ, số, khoảng trắng, dấu nháy hoặc gạch nối.',tone:'bad'};return drawSheet()}
  const foc=S.gdFoc||'hunt';S.money-=300;if(S.om){log(`Bạn rời ${ORGS[S.om.k].n} để lập hội riêng.`);S.om=null}
  S.gd={n:nm,y:S.year,lv:0,cash:150,fame:10,foc,mem:[],split:'hall',ry:0,wy:0,hist:[],rc:null,bd:null,raid:null,dead:0};
  S.gd.rc={y:S.year,L:[gNew(1),gNew(1),gNew(2)]};
  news(`${S.first} ${S.surname} lập bang hội "${nm}".`,'',true);announce('Lập bang hội',`Bang hội "${nm}" ra đời, chuyên ${GFOC[foc].n.toLowerCase()}. Hội trưởng: ${S.first} ${S.surname}.`,GFOC[foc].ic,'merit');
  const t=`Bạn nộp 150 xu lệ phí cho tòa thị chính và lập bang hội "${nm}". Quỹ hội có 150 xu.`;log(t,'good');note={t,tone:'good'};view='gd';afterSheetAction();
}
function gdView(v){
  if(v==='gd:new'){const why=gdWhyFound();let b='<p class="note">Bang hội của riêng bạn: tuyển người, nhận hợp đồng, kéo nhau đi đánh hầm ngục. Quỹ hội phải trả lương thành viên và phí hội quán mỗi năm. Thành viên có tên, tính cách, có thể bị thương, chết, bỏ đi hoặc phản bội.</p>';
    if(why)return['Lập bang hội',b+`<p class="note bad">${why}.</p>`,'org'];
    const f=S.gdFoc||'hunt';b+=`<label class="fl" for="gdn">Tên bang hội</label><div class="nmrow"><input id="gdn" value="${esc(S.gdName||'Hội '+S.surname)}" maxlength="28" autocomplete="off"></div>`;
    b+=`<p class="fl">Sở trường</p><div class="seg asg2">${Object.entries(GFOC).map(([k,F])=>`<button class="opt ${f===k?'on':''}" data-x="gd:foc:${k}">${F.n}</button>`).join('')}</div>`;
    b+='<div class="choices"><button class="btn pri" data-x="gd:found">Lập hội (300 xu)</button></div>';return['Lập bang hội',b,'org']}
  const G=GD();if(!G)return['Bang hội','<p class="note">Bạn chưa có bang hội.</p>','org'];const dis=!S.alive;
  if(v==='gd'){const al=gdAlive(),wage=al.reduce((a,m)=>a+m.wage,0),up=GHALL[G.lv].up;
    let b=`<div class="house">${crest(S.house,56)}<div><h3>${esc(G.n)}</h3><i>${gdRank()} · ${GFOC[G.foc].n} · lập năm ${G.y}</i></div></div>`;
    b+=statGrid([['Quỹ hội',G.cash+' xu'],['Danh tiếng',G.fame],['Thành viên',`${al.length}/${gdCap()}`],['Hội quán',GHALL[G.lv].n],['Lương và phí mỗi năm',`${wage+up} xu`],['Chia chiến lợi phẩm',GSPLIT[G.split].n]]);
    if(G.cash<wage+up)b+='<p class="note bad">Quỹ hội không đủ trả lương năm tới. Thành viên sẽ mất lòng tin, có người bỏ đi.</p>';
    b+='<p class="sec">Hoạt động</p>';
    b+=gRow('data-open="gd:raid"','skull','Tập hợp đánh hầm ngục',G.raid?`Đang ở tầng ${G.raid.fl}/${DUNG.find(d=>d.k===G.raid.d).fl} ${DUNG.find(d=>d.k===G.raid.d).n}`:G.ry===S.year?'Đã đánh hầm ngục năm nay':'Một chuyến mỗi năm · chọn đội, mang thuốc, xuống từng tầng','',dis);
    b+=gRow('data-open="gd:board"','scroll','Bảng hợp đồng',`${2-(S.done.gdc||0)} lượt nhận năm nay`,'',dis);
    b+=gRow('data-open="gd:rec"','user-add','Tuyển thành viên',al.length>=gdCap()?'Hội quán đã đầy, cần nâng cấp':'Ba ứng viên đang chờ','',dis);
    b+='<p class="sec">Thành viên</p>';b+=al.length?al.map(m=>gRow(`data-open="gd:m:${m.id}"`,GCLS[m.c].ic,`${esc(m.first)}${m.off?' · phó hội':''}`,`${GCLS[m.c].n} cấp ${m.lv} · ${GTR[m.tr].n} · lương ${m.wage} xu${m.inj>S.year?' · đang dưỡng thương':''}`,`<span class="satpill s${m.loy<35?0:m.loy<60?1:2}">${m.loy}</span>`,false)).join(''):'<p class="note">Hội chưa có ai. Hãy tuyển thành viên đầu tiên.</p>';
    b+='<p class="sec">Quản lý</p>';
    const nx=GHALL[G.lv+1];if(nx)b+=gRow('data-x="gd:hall"','castle',`Nâng cấp lên ${nx.n}`,G.cash<nx.c?`Cần ${nx.c} xu trong quỹ`:`Sức chứa ${nx.cap} người · phí ${nx.up} xu/năm`,`${nx.c} xu`,dis||G.cash<nx.c);
    b+=gRow('data-x="gd:dep"','coins','Góp 50 xu vào quỹ',S.money<50?'Không đủ tiền':'Tiền túi của bạn chuyển vào quỹ hội','',dis||S.money<50);
    const wd=Math.floor(G.cash/4);b+=gRow('data-x="gd:wd"','sack','Rút tiền từ quỹ',G.wy===S.year?'Đã rút năm nay':wd<10?'Quỹ quá ít':`Rút ${wd} xu (một phần tư quỹ) · thành viên không vui`,'',dis||G.wy===S.year||wd<10);
    b+=`<p class="fl">Chia chiến lợi phẩm</p><div class="seg asg3">${Object.entries(GSPLIT).map(([k,X])=>`<button class="opt ${G.split===k?'on':''}" data-x="gd:split:${k}">${X.n}</button>`).join('')}</div><p class="note">${GSPLIT[G.split].d}.</p>`;
    if(G.hist.length)b+='<p class="sec">Biên niên bang hội</p>'+G.hist.slice(-6).reverse().map(x=>`<p class="note">Năm ${x.y}: ${esc(x.t)}</p>`).join('');
    b+=gRow('data-open="gd:end"','door','Giải tán bang hội','Thành viên ra đi, quỹ còn lại về tay bạn','',dis);
    return['Bang hội',b,'org']}
  if(v==='gd:end'){return['Giải tán bang hội?',`<p class="note bad">Bang hội "${esc(G.n)}" sẽ giải tán. ${gdAlive().length} thành viên ra đi, ${G.cash} xu trong quỹ về tay bạn sau khi trả lương lần cuối.</p>`+rowBtn('data-x="gd:disband"','Giải tán','',''),'gd']}
  if(v==='gd:rec'){const G2=G;if(!G2.rc||G2.rc.y!==S.year)G2.rc={y:S.year,L:[gNew(),gNew(),gNew()]};let b=`<p class="note">Ứng viên giỏi chỉ muốn vào hội có danh tiếng. Phí ký kết bằng hai năm lương, trả từ quỹ hội. Quỹ: ${G2.cash} xu.</p>`;
    const full=gdAlive().length>=gdCap();
    G2.rc.L.forEach((m,i)=>{if(!m)return;const fee=m.wage*2;b+=gRow(`data-x="gd:hire:${i}"`,GCLS[m.c].ic,`${esc(m.first+' '+m.sur)}`,`${GCLS[m.c].n} cấp ${m.lv} · ${RACES[m.race].n} · ${GTR[m.tr].n} · đòi ${m.wage} xu/năm${full?' · hội quán đã đầy':G2.cash<fee?` · cần ${fee} xu phí ký kết`:''}`,`${fee} xu`,dis||full||G2.cash<fee)});
    b+=gRow('data-x="gd:post"','scroll','Dán cáo thị tuyển mộ mới (15 xu)',S.done.gdp?'Đã dán năm nay':'Đổi lại danh sách ứng viên','',dis||!!S.done.gdp||G2.cash<15);
    return['Tuyển thành viên',b,'gd']}
  if(v.startsWith('gd:m:')){const m=G.mem.find(x=>x.id===v.slice(5));if(!m||!m.alive)return['Thành viên','<p class="note">Người này không còn trong hội.</p>','gd'];
    let b=`<div class="row"><span class="ri">${ic(GCLS[m.c].ic,24)}</span><div><b>${esc(m.first+' '+m.sur)}${m.off?' · phó hội':''}</b><small>${GCLS[m.c].n} cấp ${m.lv} · ${RACES[m.race].n} · tính ${GTR[m.tr].n} · vào hội năm ${m.y} · ${m.kills} chiến công</small><div class="bond"><i style="width:${m.loy}%"></i></div></div><span class="tag">${m.loy}</span></div>`;
    b+=statGrid([['Sức chiến đấu',gmPw(m)],['Kinh nghiệm',`${m.xp}/${m.lv*20}`],['Lương',m.wage+' xu/năm'],['Tình trạng',m.inj>S.year?`Dưỡng thương đến năm ${m.inj}`:'Khỏe mạnh']]);
    const dn=S.done['gm'+m.id];
    b+=gRow(`data-x="gd:train:${m.id}"`,'study','Huấn luyện',dn?'Đã lo cho người này năm nay':`${m.lv*8} xu từ quỹ · kinh nghiệm tăng`,'',dis||!!dn||G.cash<m.lv*8);
    b+=gRow(`data-x="gd:raise:${m.id}"`,'coins','Tăng lương thêm 2 xu',dn?'Đã lo cho người này năm nay':'Trung thành tăng mạnh','',dis||!!dn);
    b+=gRow(`data-x="gd:gift:${m.id}"`,'gift','Tặng quà riêng (10 xu tiền túi)',dn?'Đã lo cho người này năm nay':'Trung thành tăng','',dis||!!dn||S.money<10);
    if(!m.off)b+=gRow(`data-x="gd:off:${m.id}"`,'flag','Phong làm phó hội','Chỉ một phó hội · người cũ trở lại làm thành viên · trung thành tăng','',dis);
    b+=gRow(`data-x="gd:kick:${m.id}"`,'user-remove','Trục xuất khỏi hội','Những người khác sẽ bất an','',dis);
    return[esc(m.first),b,'gd']}
  if(v==='gd:board'){const L=gdBoard();let b=`<p class="note">Mỗi năm nhận tối đa 2 hợp đồng. Phái những thành viên khỏe mạnh đi; sức đội càng vượt yêu cầu càng dễ thành công. Còn ${2-(S.done.gdc||0)} lượt.</p>`;
    L.forEach((c,i)=>{b+=gRow(`data-open="gd:c:${i}"`,c.risk>1?'skull':'scroll',c.n,c.done?'Đã nhận':`${c.d} · cần sức ${c.df} · ${c.sl} người · thưởng ${c.rew} xu`,'',dis||!!c.done||(S.done.gdc||0)>=2)});
    return['Bảng hợp đồng',b,'gd']}
  if(v.startsWith('gd:c:')){const i=+v.slice(5),c=gdBoard()[i];if(!c||c.done)return['Hợp đồng','<p class="note">Hợp đồng này không còn.</p>','gd:board'];const T=G.sel||[];const pw=T.map(id=>G.mem.find(m=>m.id===id)).filter(Boolean).reduce((a,m)=>a+gmPw(m),0);
    let b=`<p class="note">${c.n}: ${c.d}. Yêu cầu sức ${c.df}, tối đa ${c.sl} người. Đội đã chọn: <b>${pw}</b>.</p>`;
    for(const m of gdAlive()){const on=T.includes(m.id),hurt=m.inj>S.year;b+=gRow(`data-x="gd:sel:${m.id}:c${i}"`,GCLS[m.c].ic,`${on?'✓ ':''}${esc(m.first)}`,`${GCLS[m.c].n} cấp ${m.lv} · sức ${gmPw(m)}${hurt?' · đang dưỡng thương':''}`,'',dis||hurt||(!on&&T.length>=c.sl))}
    b+=`<div class="choices"><button class="btn pri" data-x="gd:send:${i}" ${!T.length||dis?'disabled':''}>Phái đội đi</button></div>`;return[c.n,b,'gd:board']}
  if(v==='gd:raid')return gdRaidView();
  return null;
}
function gdRaidView(){
  const G=GD(),dis=!S.alive;let b='';
  if(G.raid){const R0=G.raid,D=DUNG.find(d=>d.k===R0.d);b+=imgBanner(D.undead?'cryptfight':D.k==='lair'?'dragon':D.k==='redfort'?'redmoon':'ruins');
    b+=statGrid([['Hầm ngục',D.n],['Tầng',`${R0.fl}/${D.fl}`],['Sinh lực đoàn',`${R0.hp}/100`],['Chiến lợi phẩm',`${R0.loot} xu${R0.items.length?' · '+R0.items.length+' bảo vật':''}`],['Thuốc hồi phục',R0.pots],['Đoàn',`${R0.party.length} người${R0.me?' + bạn':''}`]]);
    b+=`<div class="bond" style="height:8px"><i style="width:${R0.hp}%"></i></div>`;
    b+='<p class="sec">Nhật ký</p>'+R0.log.slice(-6).map(x=>`<p class="note ${x[1]}">${esc(x[0])}</p>`).join('');
    if(!R0.end){b+='<div class="choices">';b+=`<button class="btn pri" data-x="gd:rd:go" ${dis?'disabled':''}>${R0.fl+1>=D.fl?`Tiến vào hang của ${D.boss}`:`Xuống tầng ${R0.fl+1}`}</button>`;if(R0.pots)b+=`<button class="btn" data-x="gd:rd:pot" ${dis?'disabled':''}>Uống thuốc hồi phục (+30)</button>`;b+=`<button class="btn" data-x="gd:rd:out" ${dis?'disabled':''}>Rút lui, mang theo chiến lợi phẩm</button></div>`}
    else b+=`<div class="choices"><button class="btn pri" data-x="gd:rd:close">Trở về hội quán</button></div>`;
    return['Đánh hầm ngục',b,'gd']}
  if(G.ry===S.year)return['Đánh hầm ngục','<p class="note">Bang hội đã đánh hầm ngục năm nay. Anh em cần nghỉ ngơi.</p>','gd'];
  const T=G.party||[],pw=T.map(id=>G.mem.find(m=>m.id===id)).filter(m=>m&&m.alive).reduce((a,m)=>a+gmPw(m),0)+(G.me?mePw():0);
  b+=`<p class="note">Chọn tối đa 5 thành viên. Hộ vệ khiên đỡ đòn, mục sư giảm thương vong, trinh sát tránh bẫy và tìm kho báu, pháp sư mạnh trước xác sống và phép cấm. Sức đoàn hiện tại: <b>${pw}</b>.</p>`;
  b+='<p class="sec">Đội hình</p>';
  for(const m of gdAlive()){const on=T.includes(m.id),hurt=m.inj>S.year;b+=gRow(`data-x="gd:pt:${m.id}"`,GCLS[m.c].ic,`${on?'✓ ':''}${esc(m.first)}`,`${GCLS[m.c].n} cấp ${m.lv} · sức ${gmPw(m)}${hurt?' · đang dưỡng thương':''}`,'',dis||hurt||(!on&&T.length>=5))}
  b+=gRow('data-x="gd:me"','crown',`${G.me?'✓ ':''}Đích thân dẫn đoàn`,`Sức của bạn ${mePw()} · bạn cũng có thể bị thương hoặc chết`,'',dis||S.age>60);
  b+=gRow('data-x="gd:pots"','potion',`Thuốc hồi phục: ${G.pots||0}`,'10 xu mỗi bình từ quỹ hội · chạm để thêm, tối đa 3','',dis);
  b+='<p class="sec">Chọn hầm ngục</p>';
  for(const D of DUNG){const lock=D.k==='lost'&&!(S.flags.cryptMap||isSk());const why=lock?'Cần bản đồ Hầm Mộ Vương Triều Thất Lạc':!T.length&&!G.me?'Chưa chọn đội':G.cash<(G.pots||0)*10?'Quỹ không đủ mua thuốc':'';b+=gRow(`data-x="gd:rd:start:${D.k}"`,'skull',D.n,why||`${D.fl} tầng · khuyến nghị sức ${D.rec} · ${D.d}`,pw>=D.rec?'<span class="satpill s2">VỪA SỨC</span>':pw>=D.rec*.7?'<span class="satpill s1">MẠO HIỂM</span>':'<span class="satpill s0">QUÁ SỨC</span>',dis||!!why)}
  return['Đánh hầm ngục',b,'gd'];
}
function rdComp(){const G=GD(),R0=G.raid;const P=R0.party.map(id=>G.mem.find(m=>m.id===id)).filter(m=>m&&m.alive&&!(m.inj>S.year));const cnt=c=>P.filter(m=>m.c===c).length;return{P,pw:P.reduce((a,m)=>a+gmPw(m),0)+(R0.me?mePw():0),tank:cnt('tank'),heal:cnt('heal'),scout:cnt('scout'),mage:cnt('mage')}}
function rdHurt(dmg,R0,C){R0.hp=Math.max(0,R0.hp-dmg);if(C.P.length&&ch(dmg/45)){const m=pick(C.P);if(R0.hp<25&&ch(.35-C.heal*.1)){m.alive=false;GD().dead++;R0.log.push([`${m.first} ngã xuống và không đứng dậy nữa.`,'bad']);GD().hist.push({y:S.year,t:`${m.first} hy sinh ở ${DUNG.find(d=>d.k===R0.d).n}.`})}else{m.inj=S.year+1;R0.log.push([`${m.first} bị thương nặng, phải dìu đi.`,'bad'])}}
  if(R0.me&&ch(dmg/60)){mod({health:-R(5,15)});if(S.st.health<=0){R0.log.push(['Bạn gục xuống giữa hầm ngục.','bad']);die(`trận đánh trong ${DUNG.find(d=>d.k===R0.d).n}`)}}}
function rdFloor(){
  const G=GD(),R0=G.raid,D=DUNG.find(d=>d.k===R0.d);if(!R0||R0.end)return;const C=rdComp();if(!C.pw){R0.log.push(['Không còn ai đủ sức đi tiếp.','bad']);return rdEnd(false)}
  R0.fl++;const boss=R0.fl>=D.fl;const Dd=D.rec*(.75+R0.fl*.1)*(boss?1.35:1);const ratio=Dd/Math.max(10,C.pw);
  if(boss){const p=Math.max(.05,Math.min(.92,.55-(ratio-1)*.7+C.tank*.05+C.heal*.05+(D.undead?C.mage*.06:C.mage*.03)));
    if(ch(p)){const g=R(D.loot[0],D.loot[1]);R0.loot+=g;const rr=D.r;const pool=Object.keys(ITEMS).filter(k=>ITEMS[k].r===rr&&!ITEMS[k].use&&!ITEMS[k].ev&&ITEMS[k].v>0);if(pool.length&&ch(.7))R0.items.push(pick(pool));if(D.r>=2&&ch(.25)){const p2=Object.keys(ITEMS).filter(k=>ITEMS[k].r===3&&!ITEMS[k].use&&ITEMS[k].v>0);if(p2.length)R0.items.push(pick(p2))}
      rdHurt(Math.round(R(10,25)*ratio)-C.tank*3,R0,C);for(const m of C.P)m.kills++;R0.boss=1;R0.log.push([`${D.boss} gục ngã! Đoàn thu được ${g} xu${R0.items.length?' và bảo vật':''}.`,'good']);return rdEnd(true)}
    rdHurt(Math.round(R(25,45)*ratio)-C.tank*4-C.heal*4,R0,C);R0.log.push([`${D.boss} quá mạnh. Cả đoàn bị đánh bật ra khỏi hang.`,'bad']);if(R0.hp<=0||!S.alive)return rdEnd(false);R0.fl--;return}
  const ev=pick(['mob','mob','trap','chest','altar']);
  if(ev==='mob'){const dmg=Math.max(3,Math.round(R(12,26)*ratio)-C.tank*4-C.heal*3-(D.undead?C.mage*3:0));const g=R(5,20)*D.r;R0.loot+=g;R0.log.push([`Tầng ${R0.fl}: ${pick(D.undead?['Một bầy xác sống tràn ra từ các hốc tường.','Ba hiệp sĩ xương chắn lối đi.']:D.k==='lair'?['Lũ thằn lằn lửa phun khói từ các khe đá.','Một con rồng non lao ra từ đống tro.']:D.k==='redfort'?['Tín đồ áo đỏ xông ra với dao găm.','Một pháp sư máu dựng vòng phép chắn đường.']:['Một toán goblin hò hét lao tới.','Goblin cưỡi sói phục kích ở ngã ba.'])} Đoàn mất ${dmg} sinh lực, nhặt được ${g} xu.`,dmg>20?'bad':'']);rdHurt(dmg,R0,C)}
  else if(ev==='trap'){if(C.scout&&ch(.5+C.scout*.2)){const g=R(10,30)*D.r;R0.loot+=g;R0.log.push([`Tầng ${R0.fl}: Trinh sát phát hiện bẫy sập và tìm ra lối đi bí mật dẫn tới một hòm ${g} xu.`,'good'])}else{const dmg=Math.round(R(10,22)*Math.max(.7,ratio)/(C.tank?1.2:1));R0.log.push([`Tầng ${R0.fl}: Một tảng đá rơi từ trần xuống. Đoàn mất ${dmg} sinh lực.`,'bad']);rdHurt(dmg,R0,C)}}
  else if(ev==='chest'){if(ch(.18)&&!C.scout){const dmg=R(10,20);rdHurt(dmg,R0,C);R0.log.push([`Tầng ${R0.fl}: Chiếc rương mọc răng và cắn người mở! Mất ${dmg} sinh lực.`,'bad'])}else{const g=R(15,40)*D.r+(C.scout?R(5,20):0);R0.loot+=g;R0.log.push([`Tầng ${R0.fl}: Một gian kho cũ còn nguyên ${g} xu.`,'good'])}}
  else{if(C.mage){if(ch(.35)){const pool=Object.keys(ITEMS).filter(k=>ITEMS[k].r===D.r&&!ITEMS[k].ev&&ITEMS[k].v>0);if(pool.length)R0.items.push(pick(pool));R0.log.push([`Tầng ${R0.fl}: Pháp sư giải được ký tự trên bàn thờ cổ. Một ngăn bí mật mở ra.`,'magic'])}else{R0.hp=Math.min(100,R0.hp+10);R0.log.push([`Tầng ${R0.fl}: Pháp sư đọc lời chúc phúc trên bàn thờ. Cả đoàn thấy khỏe lại.`,'good'])}}else{const dmg=R(5,15);rdHurt(dmg,R0,C);R0.log.push([`Tầng ${R0.fl}: Ai đó chạm vào bàn thờ cổ. Một luồng hơi lạnh quét qua đoàn.`,'bad'])}}
  if(R0.hp<=0)return rdEnd(false);
}
function rdEnd(win){
  const G=GD(),R0=G.raid,D=DUNG.find(d=>d.k===R0.d);R0.end=1;
  if(R0.hp<=0&&!win){R0.loot=Math.round(R0.loot*.3);R0.items=[];R0.log.push(['Đoàn tan tác. Những người còn sống lết ra khỏi hầm ngục, bỏ lại phần lớn chiến lợi phẩm.','bad']);G.fame=Math.max(0,G.fame-10)}
  const X=GSPLIT[G.split],tot=R0.loot,hall=Math.round(tot*X.hall),me=Math.round(tot*X.me);G.cash+=hall;S.money+=me;
  const al=R0.party.map(id=>G.mem.find(m=>m.id===id)).filter(m=>m&&m.alive);
  for(const m of al){m.xp+=(win?20:8)*D.r+((GTR[m.tr]||{}).xp?8:0);while(m.xp>=m.lv*20&&m.lv<10){m.xp-=m.lv*20;m.lv++;m.wage+=2;R0.log.push([`${m.first} lên cấp ${m.lv}.`,'good'])}m.loy=clamp(m.loy+X.loy+(win?4:-2))}
  for(const it of R0.items)gainItem(it);
  if(win){G.fame+=10+D.r*15;G.hist.push({y:S.year,t:`Hạ ${D.boss} ở ${D.n}.`});news(`Bang hội "${G.n}" hạ ${D.boss} ở ${D.n}.`,'good',D.r>=2);if(R0.me){mod({honor:4});S.house.prestige+=10*D.r}if(D.k==='lair'){S.flags.dragonslayer=1}}
  R0.log.push([`Chiến lợi phẩm ${tot} xu: ${hall} xu vào quỹ hội${me?`, ${me} xu vào túi bạn`:''}, phần còn lại chia anh em.`,'']);
  log(`Bang hội "${G.n}" ${win?`chinh phục ${D.n}`:`rút khỏi ${D.n}`}, mang về ${tot} xu.`,win?'good':'');
}
function gdAct(a,x,y){
  const G=GD();let t='',tone='';
  if(a==='foc'){S.gdFoc=x;const i=$('#gdn');if(i)S.gdName=i.value;return drawSheet()}
  if(a==='found')return gdFound();
  if(!G)return;
  if(a==='hire'){const m=G.rc&&G.rc.L[+x];if(!m||gdAlive().length>=gdCap())return;const fee=m.wage*2;if(G.cash<fee)return;if(!ch(.55+G.fame/600-m.lv*.06+(S.st.honor-50)/300)){G.rc.L[+x]=null;t=`${m.first} lắc đầu: "Hội của ngài còn chưa ai biết tên."`;tone='bad'}else{G.cash-=fee;m.y=S.year;G.mem.push(m);G.rc.L[+x]=null;t=`${m.first} ${m.sur} ký giao ước gia nhập "${G.n}" (−${fee} xu từ quỹ).`;tone='good'}}
  else if(a==='post'){if(S.done.gdp||G.cash<15)return;G.cash-=15;S.done.gdp=1;G.rc={y:S.year,L:[gNew(),gNew(),gNew()]};note={t:'Cáo thị mới được dán khắp quán rượu. Ba ứng viên mới tìm đến.',tone:'good'};return drawSheet()}
  else if(['train','raise','gift','off','kick'].includes(a)){const m=G.mem.find(z=>z.id===x&&z.alive);if(!m)return;
    if(a==='train'){if(S.done['gm'+m.id]||G.cash<m.lv*8)return;G.cash-=m.lv*8;S.done['gm'+m.id]=1;m.xp+=R(12,22);m.loy=clamp(m.loy+3);let up='';while(m.xp>=m.lv*20&&m.lv<10){m.xp-=m.lv*20;m.lv++;m.wage+=2;up=` ${m.first} lên cấp ${m.lv}.`}t=`${m.first} luyện tập cùng các thầy giỏi nhất vùng.${up}`;tone='good'}
    if(a==='raise'){if(S.done['gm'+m.id])return;S.done['gm'+m.id]=1;m.wage+=2;m.loy=clamp(m.loy+12);t=`${m.first} được tăng lương lên ${m.wage} xu/năm.`;tone='good'}
    if(a==='gift'){if(S.done['gm'+m.id]||S.money<10)return;S.done['gm'+m.id]=1;S.money-=10;m.loy=clamp(m.loy+8);t=`Bạn tặng ${m.first} ${pick(['một con dao găm khảm bạc','một bình rượu mạnh xứ núi','một chiếc áo choàng lông'])}.`;tone='good'}
    if(a==='off'){for(const z of G.mem)if(z.off){z.off=0;z.loy=clamp(z.loy-8)}m.off=1;m.loy=clamp(m.loy+15);t=`${m.first} được phong làm phó hội.`;tone='good'}
    if(a==='kick'){m.alive=false;m.gone=1;for(const z of gdAlive())z.loy=clamp(z.loy-3);t=`${m.first} bị trục xuất khỏi hội. Anh em nhìn nhau lo lắng.`;view='gd';if(m.loy<30&&ch(.4))addEnemy(`bị trục xuất khỏi bang hội "${G.n}"`,{first:m.first,race:m.race,sex:m.sex,hate:R(45,65)})}}
  else if(a==='hall'){const nx=GHALL[G.lv+1];if(!nx||G.cash<nx.c)return;G.cash-=nx.c;G.lv++;G.fame+=15;t=`Bang hội chuyển về ${nx.n}.`;tone='good';G.hist.push({y:S.year,t:`Chuyển về ${nx.n}.`})}
  else if(a==='dep'){if(S.money<50)return;S.money-=50;G.cash+=50;t='Bạn góp 50 xu vào quỹ hội.'}
  else if(a==='wd'){if(G.wy===S.year)return;const w=Math.floor(G.cash/4);if(w<10)return;G.cash-=w;S.money+=w;G.wy=S.year;for(const m of gdAlive())m.loy=clamp(m.loy-4);t=`Bạn rút ${w} xu từ quỹ hội. Có tiếng xì xào trong hội quán.`}
  else if(a==='split'){G.split=x;return drawSheet()}
  else if(a==='disband'){const pay=gdAlive().reduce((s0,m)=>s0+m.wage,0);const left=Math.max(0,G.cash-pay);S.money+=left;news(`Bang hội "${G.n}" giải tán.`,'',true);S.gd=null;t=`Bang hội giải tán. Sau khi trả lương lần cuối, bạn nhận lại ${left} xu.`;view='org'}
  else if(a==='sel'){const T=G.sel=G.sel||[];const i=T.indexOf(x);if(i>=0)T.splice(i,1);else T.push(x);view='gd:'+y.replace(/^c/,'c:');return drawSheet()}
  else if(a==='send'){const c=gdBoard()[+x];if(!c||c.done||(S.done.gdc||0)>=2)return;const T=(G.sel||[]).map(id=>G.mem.find(m=>m.id===id)).filter(m=>m&&m.alive&&!(m.inj>S.year));if(!T.length)return;
    S.done.gdc=(S.done.gdc||0)+1;c.done=1;G.sel=[];const pw=T.reduce((s0,m)=>s0+gmPw(m),0);const p=Math.max(.08,Math.min(.95,.5+(pw-c.df)/c.df*.8));
    if(ch(p)){const X=GSPLIT[G.split];G.cash+=Math.round(c.rew*X.hall);S.money+=Math.round(c.rew*X.me);G.fame+=c.fame;for(const m of T){m.xp+=10*c.risk;m.loy=clamp(m.loy+2+X.loy);m.kills++;while(m.xp>=m.lv*20&&m.lv<10){m.xp-=m.lv*20;m.lv++;m.wage+=2}}t=`Đội của ${T.map(m=>m.first).join(', ')} hoàn thành "${c.n}", mang về ${c.rew} xu.`;tone='good'}
    else{G.fame=Math.max(0,G.fame-Math.round(c.fame/2));const m=pick(T);if(ch(.08*c.risk)){m.alive=false;G.dead++;G.hist.push({y:S.year,t:`${m.first} hy sinh khi làm hợp đồng "${c.n}".`});t=`Hợp đồng "${c.n}" thất bại. ${m.first} không trở về.`}else{m.inj=S.year+1;t=`Hợp đồng "${c.n}" thất bại. ${m.first} bị thương nặng.`}tone='bad';for(const z of T)z.loy=clamp(z.loy-3)}
    view='gd:board'}
  else if(a==='pt'){const T=G.party=G.party||[];const i=T.indexOf(x);if(i>=0)T.splice(i,1);else if(T.length<5)T.push(x);return drawSheet()}
  else if(a==='me'){G.me=!G.me;return drawSheet()}
  else if(a==='pots'){G.pots=((G.pots||0)+1)%4;return drawSheet()}
  else if(a==='rd'){
    if(x==='start'){if(G.raid||G.ry===S.year)return;const D=DUNG.find(d=>d.k===y);if(!D)return;if(D.k==='lost'&&!(S.flags.cryptMap||isSk()))return;const T=(G.party||[]).filter(id=>{const m=G.mem.find(z=>z.id===id);return m&&m.alive&&!(m.inj>S.year)});if(!T.length&&!G.me)return;const pc=(G.pots||0)*10;if(G.cash<pc)return;G.cash-=pc;G.ry=S.year;G.raid={d:D.k,fl:0,hp:100,loot:0,items:[],pots:G.pots||0,party:T,me:!!G.me,log:[[`Đoàn ${T.length+(G.me?1:0)} người bước vào ${D.n}.`,'']],end:0};return drawSheet()}
    const R0=G.raid;if(!R0)return;
    if(x==='go'){rdFloor();save();render();if(!S.alive){closeSheet();return showDeath()}return drawSheet()}
    if(x==='pot'){if(!R0.pots)return;R0.pots--;R0.hp=Math.min(100,R0.hp+30);R0.log.push(['Cả đoàn uống thuốc hồi phục. Vết thương khép lại.','good']);return drawSheet()}
    if(x==='out'){R0.log.push(['Đoàn quyết định rút lui.','']);rdEnd(false);save();return drawSheet()}
    if(x==='close'){G.raid=null;view='gd';return afterSheetAction()}}
  log(t,tone);note={t,tone};afterSheetAction();
}
function gdYear(){
  const G=S.gd;if(!G)return;G.mem=G.mem.filter(m=>m.alive);G.hist=G.hist.slice(-25);
  if(G.raid){if(!G.raid.end){G.raid.log.push(['Một năm đã qua, đoàn buộc phải rút về.','']);rdEnd(false)}G.raid=null}
  const al=gdAlive(),wage=al.reduce((a,m)=>a+m.wage,0),up=GHALL[G.lv].up,cost=wage+up;
  G.cash+=Math.round(G.fame/20);
  if(G.cash>=cost){G.cash-=cost;log(`Bang hội "${G.n}" trả ${wage} xu lương và ${up} xu phí hội quán.`)}
  else{const paid=Math.max(0,G.cash);G.cash=0;for(const m of al)m.loy=clamp(m.loy-15);log(`Quỹ bang hội "${G.n}" cạn. Chỉ trả được ${paid}/${cost} xu, anh em bất mãn.`,'bad')}
  G.fame=Math.max(0,G.fame-2);
  for(const m of al){m.loy=clamp(m.loy+((GTR[m.tr]||{}).loy||0)+(G.fame>=300?1:0)-(m.wage<3+m.lv*3?2:0));
    if(m.loy<20&&ch(.5)){m.alive=false;m.gone=1;log(`${m.first} bỏ bang hội "${G.n}" mà không một lời từ biệt.`,'bad');G.hist.push({y:S.year,t:`${m.first} bỏ hội.`});continue}
    if(S.year-m.y>=25&&ch(.12)){m.alive=false;m.gone=1;log(`${m.first} xin giải nghệ sau ${S.year-m.y} năm gắn bó với "${G.n}".`);G.hist.push({y:S.year,t:`${m.first} giải nghệ.`})}}
  for(const k in ORG())if(ORG()[k]&&k!=='red'&&ch(.01))ORG()[k].pow=Math.max(5,ORG()[k].pow-1);
  if(S.age>=16&&!S.pend.some(x=>/^gd_/.test(x))&&gdAlive().length&&ch(.22)){const L=[['gd_thief',()=>gdAlive().some(m=>m.tr==='greedy'&&m.loy<55)&&G.cash>=40],['gd_poach',()=>gdAlive().some(m=>m.lv>=4)],['gd_quarrel',()=>gdAlive().length>=3],['gd_famous',()=>G.fame>=150&&gdAlive().length<gdCap()],['gd_rival',()=>G.fame>=80],['gd_city',()=>!!(CR()||S.world.cat)],['gd_tax',()=>G.cash>=100]].filter(([,f])=>f());if(L.length)S.pend.push(pick(L)[0])}
}
