/* ===== v21: SỬA LỖI LOGIC, CHUẨN HÓA SAVE, HẬU QUẢ ĐẠI BIẾN, SỰ KIỆN NGHỀ ẨN ===== */

/* ---------- 1. Chuẩn hóa save: chạy cho mọi bản lưu, kể cả bản lưu v4 ---------- */
function normalizeSave(s){
  if(!s||typeof s!=='object')return s;
  const arrs=['fam','rel','bag','tree','log','pend','ann','spHist'];for(const k of arrs)if(!Array.isArray(s[k]))s[k]=[];
  for(const k of['flags','done','own','st','house','world','hid'])if(!s[k]||typeof s[k]!=='object')s[k]={};
  for(const[k]of STATS)if(typeof s.st[k]!=='number'||isNaN(s.st[k]))s.st[k]=50;
  if(typeof s.money!=='number'||isNaN(s.money))s.money=0;
  if(!s.log.length)s.log.push({age:s.age||0,year:s.year||0,items:[]});
  if(!RACES[s.race])s.race='human';
  if(!REALMS.includes(s.realm)&&!(s.world.wd&&s.world.wd.rs&&s.world.wd.rs[s.realm]))s.realm=pick(HUMAN_REALMS);
  s.bag=s.bag.filter(i=>i&&ITEMS[i.k]);
  const seen=new Set();for(const p of s.fam){if(!p.id||seen.has(p.id))p.id=uid();seen.add(p.id);if(!p.race)p.race=s.race;if(p.bond==null)p.bond=50}
  for(const r of s.rel){if(!r.id||seen.has(r.id))r.id=uid();seen.add(r.id)}
  if(s.job&&!JOBS[s.job.id])s.job=null;
  if(s.job){for(const k of['rank','yr','ry'])if(typeof s.job[k]!=='number')s.job[k]=0;const n=(JOBS[s.job.id].t||[]).length;if(n&&s.job.rank>=n)s.job.rank=n-1}
  if(s.job&&s.job.id==='court'&&!s.co)s.job=null;
  if(s.co&&!(s.job&&s.job.id==='court'))s.co=null;
  if(s.hc&&!HC[s.hc.k])s.hc=null;if(s.hcK&&!HC[s.hcK]){s.hcK=null;if(s.pend)s.pend=s.pend.filter(x=>x!=='hc_call')};
  if(s.race==='skeleton'){if(typeof s.soul!=='number')s.soul=50;if(!s.sk)s.sk={br:null,rk:0,xp:0,leg:0,mor:0}}else{s.soul=null;if(s.sk&&!s.flags.curse)s.sk=null}
  if(s.gd){s.gd.mem=(s.gd.mem||[]).filter(m=>m&&m.alive);s.gd.hist=(s.gd.hist||[]).slice(-25);if(!GHALL[s.gd.lv])s.gd.lv=0;if(s.gd.raid&&!DUNG.some(d=>d.k===s.gd.raid.d))s.gd.raid=null}
  if(s.om&&!ORGS[s.om.k])s.om=null;
  if(s.hon)s.hon=s.hon.filter(h=>HON[h.id]);
  s.pend=s.pend.filter(id=>EVB[id]);
  if(s.dq)s.dq=s.dq.filter(x=>x&&EVB[x.id]);
  if(s.world.cat&&s.world.cat.id!=='player'&&!CATS[s.world.cat.id])s.world.cat=null;
  if(s.world.cr&&!CRS[s.world.cr.id])s.world.cr=null;
  s.v=4;return s;
}
{const m0=migrate;migrate=function(s){const r=m0(s);return r?normalizeSave(r):r}}

