endCat=function(){
  const W0=S.world,c=W0.cat,C=CATS[c.id],yrs=S.year-c.y,res=(c.res||0)+(isMil(S)&&S.co.rk>=3?2:0);
  let who,kind;
  if(res>=4){who=`${S.first} ${S.surname}`;kind='me'}
  else if(c.fw){who=c.fw;kind='new'}else{const L=[];if(S.gd&&gdAlive().length>=3)L.push([`bang hội "${S.gd.n}" của bạn`,'gd']);const fr=rels('friend').find(r=>r.ach==='glory'||r.ach==='title');if(fr)L.push([`${fr.name}, bạn cũ của bạn`,'fr']);if(W0.ks&&!W0.ks.me)L.push([`Kiếm Thánh ${W0.ks.name}`,'ks']);const nat=pick(Object.keys(NATIONS));const rs=WD().rs[nat];if(rs)L.push([`${rs.ruler} và quân đội ${nat}`,'nat']);L.push([`${pick(MN)} ${pick(HERO_EP)}`,'new']);[who,kind]=pick(L)}
  if(kind==='new'){if(!W0.heroes)W0.heroes=[];W0.heroes.push({name:who,y:S.year,cat:c.id,k:'npc'});W0.heroes=W0.heroes.slice(-30)}
  if(kind==='gd'){S.gd.fame+=40;S.gd.hist.push({y:S.year,t:`Góp công đánh bại ${C.boss}.`})}
  if(kind==='fr'){const fr=rels('friend').find(r=>r.ach==='glory'||r.ach==='title');if(fr)fr.bond=clamp(fr.bond+10)}
  if(kind==='me'){mod({honor:15,happy:10});S.house.prestige+=150;rep('d',8);rep('n',5);if(!S.flags.legend){S.flags.cmerit=(S.flags.cmerit||0)+1}}
  /* vết sẹo để lại theo độ dài thảm họa */
  const scar=yrs>=5?'nặng nề':yrs>=3?'đáng kể':'nhẹ';const r=myRealm();
  if(yrs>=3){r.stab=Math.max(5,r.stab-(yrs>=5?20:10));const k={demon:'grain',undead:'herb',dragon:'wood',heresy:'arc',plague:'herb'}[c.id]||'grain';if(!W0.scar)W0.scar=[];W0.scar.push({k,v:yrs>=5?35:20,until:S.year+R(3,6),why:C.n})}
  if(c.id==='undead')RG().crypts.stab=Math.max(5,RG().crypts.stab-15);
  const txt=`${C.n} chấm dứt sau ${yrs} năm. ${kind==='me'?`Chính ${who} là người dẫn đầu cuộc kháng cự cuối cùng và hạ được ${C.boss}.`:`${who[0].toUpperCase()+who.slice(1)} đã hạ ${C.boss}.`} Thiệt hại ${scar}.`;
  announce('Thảm Họa chấm dứt',txt,'sword',kind==='me'?'merit':null);log(txt,'good');news(txt,'good',true);
  W0.cat=null;W0.last=S.year;S.flags.hero=null;
};
