    const nat=REG[D.rg].own,rs=WD().rs[nat];if(rs){if(out==='free'){const old=rs.ruler;rs.ruler=C.lead;rs.ra=R(40,80);news(`${C.lead} lên ngôi ${nat} sau chiến thắng, thay ${old}.`,'',true)}if(out==='crushed'||out==='repelled'){rs.ruler=rulerName(nat,ch(.35)?'f':'m');rs.ra=R(30,60);news(`${C.lead} bại trận và bị phế truất. ${rs.ruler} lên thay ở ${nat}.`,'',true)}if(S.kd&&S.kd.realms&&S.kd.realms[nat])S.kd.realms[nat].ruler=rs.ruler}
