/* ---------- 6. Lich: Hộp Linh Hồn cứu thân xác, không cứu linh hồn ---------- */
{const d1=die;die=function(cause){if(S&&S.alive&&isSk()&&S.phy&&S.phy.ok&&!S.phy.stolen){const holy=/linh hồn|thánh hỏa|hỏa thiêu|nước thánh|Anh Hùng|xử tử|phản nghịch/.test(cause);if(holy||S.phy.ry===S.year||(S.soul||0)<15){const ok=S.phy;S.phy={...ok,ok:0};try{return d1(cause)}finally{if(S.alive)S.phy=ok}}S.phy.ry=S.year}return d1(cause)}}

/* ---------- 7. Bổ nhiệm cấp cao: có đối thủ, cần lòng tin của nhà vua và thời thế ---------- */
{const e=EVB.co_appt;e.prep=s=>{const sx=pick(['m','f']);s.coRival={name:`${pick(nameList(sx,'human'))} ${surFor('human','noble')}`,sc:R(35,80)+s.co.rk*3,tag:pick(['được phe hoàng hậu đỡ đầu','xuất thân danh gia vọng tộc','từng lập công ở biên giới','có anh trai làm Giám mục'])};s.tmp=1};
  e.text=s=>{const C=s.co,R0=s.coRival||{name:'một đại thần',tag:''};const war=C.br==='vo'&&C.rk>=3?(atWar()?' Chiến sự đang căng, nhà vua cần một người cầm quân giỏi.':' Thời bình, nhà vua e ngại trao binh quyền lớn cho một người.'):'';return`${myRealm().ruler} cho gọi bạn vào điện. Ghế ${(C.br==='vo'?COVO:COVAN)[C.rk+1]} đang để trống. Đối thủ của bạn là ${R0.name}, người ${R0.tag}.${war} Lòng tin của nhà vua dành cho bạn: ${C.ab.loy>=70?'rất cao':C.ab.loy>=50?'vừa phải':'thấp'}.`};
  e.ch[0].f=s=>{const C=s.co,R0=s.coRival||{name:'đối thủ',sc:60};const key=coKey(C)[0];let sc=C.ab.inf*.35+C.ab.loy*.35+C.ab[key]*.3+Math.min(15,(C.merit-CONEED[C.rk])/4);if(C.br==='vo'&&C.rk>=3)sc+=atWar()?C.ab.cmd*.15+8:-10;
    if(sc+R(0,25)>=R0.sc){coPromote();return[`Nhà vua chọn bạn thay vì ${R0.name}. Ấn tín được trao tận tay.`,'good']}C.merit=Math.round(C.merit*.7);coAb('loy',-2);if(ch(.3))addEnemy(`đối thủ tranh ghế ${(C.br==='vo'?COVO:COVAN)[C.rk+1]}`,{first:R0.name.split(' ')[0],cls:'noble',hate:R(40,60)});return[`Phút cuối, nhà vua chọn ${R0.name}. Bạn cúi đầu lui ra.`,'bad']};}

