/* bật sự kiện nghề ẩn: mỗi sự kiện một lần mỗi đời */
{const h1=hcYear;hcYear=function(){h1();const H=S.hc;if(!H||!hcOK()||S.age<16)return;if(!S.hceD)S.hceD={};if(S.hceY&&S.year-S.hceY<3)return;
  const L=HCE_EV.filter(e=>/^hce_[a-z]+\d$/.test(e.id)&&!S.hceD[e.id]&&e.c(S));if(L.length&&ch(.35)){const e=pick(L);S.hceD[e.id]=1;S.hceY=S.year;S.pend.push(e.id)}}}
