  oF=(n,b,ok,no,x)=>({k:'fight',n,b,ok,no,...x}),oW=(n,ok,x)=>({k:'work',n,ok,...x}),oM=(n,ok,x)=>({k:'men',n,ok,...x}),
  oT=(n,yrs,ok,x)=>({k:'time',n,yrs,ok,...x}),oQ=(n,q,ok,why,x)=>({k:'req',n,q,ok,why,...x});
