  if(m){if(m.alive&&!m.gone&&open)b+=gRow(`data-x="hq:m:${k}"`,'user',`Thăm ${esc(m.n)}`,S.done['hqm'+k]?'Đã thăm năm nay':`${esc(m.t)} · tin cậy ${m.tr}/100`,'',dis||!!S.done['hqm'+k]);
    else b+=gRow('','user',esc(m.n),`${esc(m.t)} · ${!m.alive?'đã qua đời':m.gone?'đã rời bỏ bạn':'tin cậy '+m.tr+'/100'}`,'',false,true)}
  if(r)b+=gRow('','rival',esc(r.n),`${esc(r.t)} · ${r.fallen?'đã bị bạn đánh bại':r.done?`đã thành ${HC[k].n} năm ${r.y}`:`đi được khoảng ${Math.min(99,r.p)}% con đường${r.ally?' · đồng minh':r.foe?' · kẻ thù':''}`}`,'',false,true);
  if(!m&&!r)b+='<p class="note">Chưa có ai khác trong câu chuyện này.</p>';
  if(open){b+='<p class="sec">Manh mối chưa giải mã</p>'+`<p class="note">${esc(qtx(C.clue,q)||'')}${N-q.ch-1>0?` Còn ${N-q.ch-1} chương chưa lộ diện.`:' Đây là chương cuối.'}</p>`}
  if(q.st==='done'&&q.br){const B=HQB[k][q.br];b+=`<p class="sec">Hướng tiến hóa</p><p class="note">${B.t.map((t,i)=>S.hc&&S.hc.k===k&&i<S.hc.rk?'<b>'+t+'</b>':t).join(' → ')}. ${B.d}.</p>`;if(S.hc&&S.hc.k===k)b+=gRow('data-open="hc"',HC[k].ic,'Mở nghề ẩn của bạn',hcName(),'',false)}
  if(q.hist.length)b+='<p class="sec">Lịch sử lựa chọn</p>'+q.hist.slice().reverse().map(h=>`<p class="note">Năm ${h.y} · ${esc(h.t)}</p>`).join('');
  if(q.st==='act')b+='<p class="sec">Quyết định</p>'+gRow(`data-x="hq:off:${k}"`,'bookmark','Gác lại chuỗi này','Ghi nhớ để sau. Đối thủ và thời gian thì không chờ.','',dis);
  if(q.st==='known'||q.st==='diary'){const w=hqOnWhy(k);b+='<p class="sec">Quyết định</p>'+gRow(`data-x="hq:on:${k}"`,'star','Theo đuổi chuỗi này',w||(hqOK(k)?'Tiếp tục từ chương đang dở':`Có thể theo đuổi, nhưng cần làm ${hqJobs(k)} mới đi tiếp được`),'',dis||!!w)}
