/* truyền đời: con cháu nhận nhật ký, không nhận sức mạnh */
function v22Inherit(old){const Q=old.hq||{};S.hq={};S.hqx={};S.hqPre=null;S.hqDrop=null;S.hqLeg=null;S.hqDia=null;
  const from=`${old.first} ${old.surname}`;let first=null;
  for(const q of Object.values(Q)){if(!q||!HQ[q.k]||!['act','known','diary'].includes(q.st))continue;
    const n={...q,st:'diary',ch:Math.max(0,q.ch-1),o:{},due:0,late:0,ex:null,pz:0,blk:0,from,yk:S.year,yc:S.year,la:S.year,y0:S.year,seen:[],
      hist:[...(q.hist||[]).slice(-8),{y:S.year,t:`Nhật ký của ${from} truyền lại cho ${S.first}`}],npc:{m:q.npc&&q.npc.m?{...q.npc.m}:null,r:q.npc&&q.npc.r?{...q.npc.r}:null},fl:{...(q.fl||{}),debt:null}};
    if(n.npc.m&&n.npc.m.alive&&ch(.3))n.npc.m.alive=0;if(!n.npc.m||!n.npc.m.alive)n.fl.books=1;S.hq[q.k]=n;if(!first)first=q.k}
  if(old.hc&&HQ[old.hc.k]&&(old.hc.rk||0)>=1)S.hqLeg={k:old.hc.k,who:from};
  if(first){S.hqDia=first;later('hq_diary',1)}}
{const i0=inherit;inherit=function(id){const old=S;i0(id);if(S===old)return;try{v22Inherit(old)}catch(e){console.error(e)}save();render()}}
function hqNorm(s){
  if(s.hq&&(typeof s.hq!=='object'||Array.isArray(s.hq)))s.hq={};
  if(s.hq)for(const k of Object.keys(s.hq)){const q=s.hq[k];if(!HQ[k]||!q||typeof q!=='object'){delete s.hq[k];continue}q.k=k;if(!HQST[q.st])q.st='known';const N=HQ[k].ch.length;
    if(typeof q.ch!=='number'||isNaN(q.ch))q.ch=0;q.ch=Math.max(0,Math.min(q.st==='done'?N:N-1,Math.floor(q.ch)));
    for(const f of['o','fl','npc'])if(!q[f]||typeof q[f]!=='object')q[f]={};if(!Array.isArray(q.hist))q.hist=[];if(!Array.isArray(q.seen))q.seen=[];
    for(const f of['y0','yc','yk','la'])if(typeof q[f]!=='number')q[f]=s.year||0;if(q.br&&!HQB[k][q.br])q.br=null;if(q.npc.m&&typeof q.npc.m.tr!=='number')q.npc.m.tr=40}
  if(s.hc&&s.hc.br&&!(HQB[s.hc.k]&&HQB[s.hc.k][s.hc.br]))delete s.hc.br;
  if(s.world&&s.world.hcLeg)s.world.hcLeg=Array.isArray(s.world.hcLeg)?s.world.hcLeg.filter(e=>e&&HQ[e.k]&&HQB[e.k]).slice(-30):[];
  if(s.hqLeg&&!HQ[s.hqLeg.k])s.hqLeg=null;
  if(s.hqx&&typeof s.hqx!=='object')s.hqx={};
}
{const n0=normalizeSave;normalizeSave=function(s){const r=n0(s);if(r&&typeof r==='object')try{hqNorm(r)}catch(e){console.error(e)}return r}}



