function ncYear(){if(!isNc()||!S.alive||S.pend.some(x=>x.startsWith('nc_')))return;
  if(S.world.cat&&BOSST[S.world.cat.id]&&S.world.cat.id!=='plague'&&!S.flags.hero&&ch(.3))S.pend.push('nc_battle');
  else if(atWar()&&ch(.15))S.pend.push('nc_field');else if(UD().length>=2&&ch(.08))S.pend.push('nc_paladin')}
{const y0=extYear3;extYear3=function(){y0();try{ncYear();ctYear()}catch(e){console.error(e)}}}

