{const i0=inherit;inherit=function(id){const old=S;i0(id);if(S===old)return;try{v24Inherit(old)}catch(e){console.error(e)}save();render()}}
function v24Norm(s){if(s.ct&&(typeof s.ct!=='object'||!CTO[s.ct.o]))s.ct=null;if(s.ct){for(const f of['rk','pay','y','dn','dy','warn','ry'])if(typeof s.ct[f]!=='number')s.ct[f]=0;s.ct.rk=Math.max(0,Math.min(CTO[s.ct.o].roles.length-1,s.ct.rk))}
  if(s.ctOf&&!(Array.isArray(s.ctOf)&&CTO[s.ctOf[0]]))s.ctOf=null;if(s.ctOf2&&!(Array.isArray(s.ctOf2)&&CTO[s.ctOf2[0]]))s.ctOf2=null;
  if(s.ud&&!Array.isArray(s.ud))s.ud=[];if(s.ud)s.ud=s.ud.filter(u=>u&&typeof u.pw==='number'&&u.n).slice(0,8);if(s.imb&&!(s.imb.el&&IMBN[s.imb.el]))s.imb=null}
{const n0=normalizeSave;normalizeSave=function(s){const r=n0(s);if(r&&typeof r==='object')try{v24Norm(r)}catch(e){console.error(e)}return r}}

