for(const[k,D]of Object.entries(MQ2)){HQ[k]={...D,mv:true,mvId:D.mvIds[0],cc:()=>true};HC[k]={n:D.hn,ic:D.ic,jobs:[]};hqReg(k)}
{const w0=hqAwaken;hqAwaken=function(k){const D=HQ[k];if(!D||!D.mv||!D.mvIds)return w0(k);const q=S.hq[k];q.st='done';q.ye=S.year;q.ch=D.ch.length;const L=D.mvIds.filter(x=>!S.mv[x]);for(const x of L)mvLearn(x,true);
  q.hist.push({y:S.year,t:`Lĩnh ngộ ${mqNames(k)}`});let t=`Bạn lĩnh ngộ ${L.length?L.map(x=>MV[x].n).join(', '):'trọn vẹn những chiêu đã biết'}.`;
  if(k==='mq_tmks'&&S.hc&&S.hc.k==='mks'){S.hc.leg=1;mod({honor:10,happy:10});S.house.prestige+=120;S.hid.sword=Math.min(100,(S.hid.sword||0)+5);S.hid.arcane=Math.min(100,(S.hid.arcane||0)+5);
    announce('Thánh Ma Kiếm Sư',`${S.first} ${S.surname} làm chủ cả kiếm thuật lẫn ma pháp và trở thành Thánh Ma Kiếm Sư đầu tiên sau ba trăm năm.`,'sword','spellblade');news(`${S.first} ${S.surname} trở thành Thánh Ma Kiếm Sư đầu tiên sau ba trăm năm.`,'good',true);t+=' Bạn nhận danh hiệu Thánh Ma Kiếm Sư.'}
  else announce(`Lĩnh Ngộ: ${D.n}`,`${S.first} ${S.surname} hoàn tất "${D.n}" và học được ${mqNames(k)}.`,D.ic,D.img||'awaken');
  mod({happy:6});return t}}
{const e=EVB.mq_call;e.text=s=>`${HQ[s.mqK].x({npc:{m:s.hqPre&&s.hqPre.m}})} Hoàn thành hành trình "${HQ[s.mqK].n}", bạn sẽ học được: ${mqNames(s.mqK)}.`}
/* Anh Hùng học chiêu trong hai năm huấn luyện */
{const e=EVB.herotrain;if(e){const L=['rh1','rh3','rh2'];e.ch.forEach((c,i)=>{const f0=c.f;c.f=s=>{const r=arr(f0(s));const id=L[i];if(id&&!s.mv[id]){mvLearn(id);r[0]+=` Bạn học được chiêu ${MV[id].n}.`}return r}});
  e.ch[0].t='Học kiếm với Kiếm Thánh trên núi Tuyết · học Thánh Kiếm Phá Ma';e.ch[1].t='Học phép ở Tháp Tinh Tú · học Ánh Sáng Tiên Tri';e.ch[2].t='Rèn thân thể với các chiến binh Orc · học Ý Chí Bất Khuất'}}
/* lời gọi chuỗi học chiêu theo danh hiệu */
{const y0=mvYear;mvYear=function(){y0();if(!S.alive||S.age<14||S.pend.includes('mq_call'))return;if(!S.mqNo)S.mqNo={};
  const want=k=>!(S.hq&&S.hq[k])&&!S.mqNo[k]&&HQ[k].mvIds.some(x=>!S.mv[x]);
  let k=null;if(S.flags.legend&&want('mq_hero'))k='mq_hero';else if(S.flags.saint&&want('mq_saint'))k='mq_saint';else if(S.flags.dark&&want('mq_dark'))k='mq_dark';
  else if(S.hc&&S.hc.k==='mks'&&S.hc.rk>=3&&!S.hc.leg&&(S.blade||0)>=75&&S.st.magic>=75&&S.mv.mk6&&S.mv.mk6.lv>=3&&want('mq_tmks'))k='mq_tmks';
  if(k&&ch(k==='mq_tmks'?.2:.35)){S.mqK=k;S.pend.push('mq_call')}}}

/* mục Các tộc và quốc gia: thêm các vương quốc loài người */
function hkRow(n,i){const rs=WD().rs[n];if(!rs)return'';const st=rs.stab;return gRow(`data-open="rg:hk:${i}"`,'castle',n+(S.realm===n?' · quê bạn':''),`${esc(rs.ruler)}${rs.war?` · ${rs.war.vs==='nội chiến'?'nội chiến':'đánh nhau với '+String(rs.war.vs).replace(RPFX,'')}`:''} · ${st>=60?'yên ổn':st>=35?'bất an':'rối loạn'}${rs.fam?' · mất mùa':''}${rs.pl?' · có dịch':''}`,'',false)}
function hkView(i){const n=HUMAN_REALMS[+i],rs=n&&WD().rs[n];if(!rs)return['Vương quốc','<p class="note">Không tìm thấy vương quốc này.</p>','rg'];
  const RI=typeof RLINFO!=='undefined'&&RLINFO[n];let b=RI?imgBanner(RI.img)+`<p class="note">${RI.d}</p><p class="note">Huy hiệu: ${RI.em}</p>`:imgBanner(/Thánh quốc/.test(n)?'saint':/Đế chế/.test(n)?'throne':'coronation');
  b+=gRow('','castle',n,S.realm===n?'Quê hương của bạn':'Vương quốc của loài người','',false,true);
  b+=statGrid([['Người cai trị',esc(rs.ruler)],['Tình hình',rs.stab>=60?'yên ổn':rs.stab>=35?'bất an':'rối loạn'],['Chiến tranh',rs.war?(rs.war.vs==='nội chiến'?'nội chiến':String(rs.war.vs).replace(RPFX,'')):'không'],['Mùa màng, dịch bệnh',[rs.fam?'mất mùa':'',rs.pl?'có dịch':''].filter(Boolean).join(', ')||'bình thường']]);
  if(rs.red&&(S.flags.her>=1||rmOn()||(S.ct&&S.ct.o==='red')))b+=`<p class="note">Tín đồ Hồng Nguyệt trong nước (chỉ người trong giáo phái mới biết): ${rs.red}.</p>`;
  {const sc=(S.world.scars||[]).filter(x=>x.rl===n);if(sc.length)b+='<p class="sec">Vết sẹo thảm họa</p>'+sc.map(x=>`<p class="note bad">${esc(DHSCAR[x.k]||x.k)} (từ năm ${x.y})</p>`).join('')}
  const R2=Object.keys(REG).filter(k=>!REG[k].nat&&REG[k].own===n&&rgSeen(k));if(R2.length)b+='<p class="sec">Vùng đất trong vương quốc</p>'+R2.map(k=>gRow(`data-open="rg:${k}"`,REG[k].ic,REG[k].n,REG[k].d,'',false)).join('');
  const N=(WD().news||[]).filter(x=>x.t.includes(n)).slice(-6).reverse();if(N.length)b+='<p class="sec">Tin tức gần đây</p>'+N.map(x=>`<p class="note">Năm ${x.y} · ${esc(x.t)}</p>`).join('');
  return[n,b,'rg']}
{const v0=rgView;rgView=function(v){if(v.startsWith('rg:hk:'))return hkView(v.slice(6));const r=v0(v);if(v==='rg'){r[1]=r[1].replace(/^<p class="note">Sáu vương quốc cũ[\s\S]*?<\/p>/,'');r[1]='<p class="sec">Các vương quốc loài người</p>'+HUMAN_REALMS.map(hkRow).join('')+r[1]}return r}}



