flavorYear=function(){
  if(!S.seenF)S.seenF=[];
  if(S.age>3&&!ch(.75))return;
  const pool=FLAV.filter(f=>!S.seenF.includes(f[0])&&f[1](S));if(!pool.length)return;
  const own=pool.filter(f=>f[0][0]==='x');const f=pick(own.length&&ch(.65)?own:pool);S.seenF.push(f[0]);
  log(typeof f[2]==='function'?f[2](S):f[2],'');if(f[3])mod(f[3]);
};



/* ---------- V10: tài năng cố định, kiếm thuật và ma lực luyện được; bang hội mới ---------- */
/* thiên phú kiếm thuật và cảm nhận ma pháp cố định từ lúc sinh; mọi mức tăng cũ chuyển thành kiếm thuật hoặc ma lực */
const tgf=t=>.4+(t||0)/80;
function tAdd(v,t){const x=Math.max(0,v)*tgf(t);return Math.floor(x)+(ch(x%1)?1:0)}
function talSync(){if(!S||!S.hid)return;
  if(!S.tal||typeof S.tal!=='object')S.tal={sword:S.hid.sword||0,arcane:S.hid.arcane||0};
  if(typeof S.blade!=='number'||isNaN(S.blade))S.blade=S.age>=10?Math.round((S.hid.sword||0)*.6):0;
  const dS=(S.hid.sword||0)-S.tal.sword;if(dS){if(dS>0)S.blade=Math.min(100,S.blade+tAdd(dS,S.tal.sword));S.hid.sword=S.tal.sword}
  const dA=(S.hid.arcane||0)-S.tal.arcane;if(dA){if(dA>0&&S.st)S.st.magic=Math.min(100,S.st.magic+tAdd(dA,S.tal.arcane));S.hid.arcane=S.tal.arcane}}
const bladeAdd=n=>{talSync();S.blade=Math.max(0,Math.min(100,S.blade+(n>0?tAdd(n,S.tal.sword):n)))};
{const m0=mod;mod=function(c){if(c&&c.magic>0&&S){talSync();c={...c,magic:tAdd(c.magic,S.tal.arcane)}}return m0(c)}}
/* tai nạn trong trận ít hay nhiều tùy thiên phú */
const talMul=()=>{const t=S.tal?Math.max(S.tal.sword,S.tal.arcane):50;return 1.25-t/200};
{const h0=cbHurt;cbHurt=function(F,m){return h0(F,(m||1)*talMul())}}
{const r0=render;render=function(){talSync();r0();if(!S)return;const b=$('#sw'),t=$('#swt');if(b){b.style.width=(S.blade||0)+'%';t.textContent=`Kiếm thuật ${S.blade||0}/100`}}}
{const n0=newLife;newLife=function(o){n0(o);if(S){S.tal=null;S.blade=0;talSync();save();render()}}}
{const i0=inherit;inherit=function(id){const old=S;i0(id);if(S===old)return;S.tal=null;S.blade=0;talSync();if(S.age>=10)S.blade=Math.min(45,Math.round((S.age-9)*1.2*tgf(S.tal.sword)));save();render()}}
/* luyện chiêu thức cũng rèn kiếm thuật và ma lực */
