/* ---------- V11: ô trang bị, dược phẩm, Mục Hồng Giáo ---------- */
const EQN={hat:'Mũ',armor:'Giáp',weapon:'Vũ khí',acc:'Phụ kiện'};
const ISLOT={crown:'hat',darkcrown:'hat',vm_curse:'hat',starstaff:'weapon',wand:'weapon',sc_royal:'weapon',sc_crystal:'weapon',sc_moon:'weapon',sword_anc:'weapon',holy_sword:'weapon',lightsword:'weapon',rune_blade:'weapon',dagger:'weapon',mw_blade:'weapon',mw_armor:'armor',mail:'armor',plate:'armor',cloak_shadow:'armor'};
function islot(k){const I=ITEMS[k];if(!I||I.use)return null;if(I.sl)return I.sl;if(ISLOT[k])return ISLOT[k];const c=I.ic||'';if(c.startsWith('H-'))return'hat';if(c.startsWith('A-'))return'armor';if(c.startsWith('w-')||c.startsWith('L-'))return/shield|kite/.test(c)?'acc':'weapon';return'acc'}
const EQ=()=>{if(!S.eq||typeof S.eq!=='object')S.eq={hat:null,armor:null,weapon:null,acc:[null,null,null]};if(!Array.isArray(S.eq.acc))S.eq.acc=[null,null,null];return S.eq};
const eqIds=()=>{const E=EQ();return[E.hat,E.armor,E.weapon,...E.acc].filter(Boolean)};
const eqHas=id=>eqIds().includes(id);
const eqItems=()=>{const L=eqIds();return(S.bag||[]).filter(x=>L.includes(x.id)&&ITEMS[x.k])};
function eqClean(){const E=EQ(),ids=new Set((S.bag||[]).map(x=>x.id));for(const s of['hat','armor','weapon'])if(E[s]&&!ids.has(E[s]))E[s]=null;E.acc=E.acc.map(a=>a&&ids.has(a)?a:null)}
const iScore=k=>{const I=ITEMS[k];return(I.cb||0)+Object.values(I.fx||{}).reduce((a,v)=>a+v*3,0)};
function eqAuto(){const E=EQ();const free=(S.bag||[]).filter(x=>islot(x.k)&&!eqHas(x.id)).sort((a,b)=>iScore(b.k)-iScore(a.k));
  for(const x of free){const s=islot(x.k);if(s==='acc'){const i=E.acc.indexOf(null);if(i>=0)E.acc[i]=x.id}else if(!E[s])E[s]=x.id}}
function eqAct(a,id){const it=S.bag.find(x=>x.id===id);if(!it)return drawSheet();const E=EQ(),s=islot(it.k),I=ITEMS[it.k];let t='';
  if(a==='on'){if(!s)return;if(s==='acc'){const i=E.acc.indexOf(null);if(i<0){note={t:'Ba ô phụ kiện đã đầy. Hãy tháo một phụ kiện trước.',tone:'bad'};return drawSheet()}E.acc[i]=id}else{const old=E[s]&&S.bag.find(x=>x.id===E[s]);E[s]=id;if(old)t=` Bạn tháo ${ITEMS[old.k].n.toLowerCase()} ra.`}t=`Bạn trang bị ${I.n.toLowerCase()} vào ô ${EQN[s].toLowerCase()}.`+t}
  else{for(const k of['hat','armor','weapon'])if(E[k]===id)E[k]=null;E.acc=E.acc.map(x=>x===id?null:x);t=`Bạn tháo ${I.n.toLowerCase()} ra.`}
  note={t,tone:''};save();render();drawSheet()}
function eqHTML(){const E=EQ();const cell=(id,lab)=>{const x=id&&S.bag.find(y=>y.id===id);return x?`<button class="slot r${ITEMS[x.k].r} ${sel===x.id?'sel':''} eqd" data-sel="${x.id}" aria-label="${esc(ITEMS[x.k].n)}">${itemIcon(x.k,256)}</button>`:`<div class="slot empty eqe"><span>${lab}</span></div>`};
  return`<p class="sec">Trang bị · chỉ đồ đang mang mới cộng chỉ số</p><div class="bag">${cell(E.hat,'Mũ')}${cell(E.armor,'Giáp')}${cell(E.weapon,'Vũ khí')}${E.acc.map(a=>cell(a,'Phụ kiện')).join('')}</div>`}
{const x0=extAct3;extAct3=function(x){const[a,b,c]=x.split(':');if(a==='eq')return eqAct(b,c);return x0(x)}}
{const r0=render;render=function(){if(S&&S.bag){if(!S.eq){EQ();eqAuto()}else eqClean()}r0()}}

