/* Chính Giáo săn lùng: mỗi lần thoát được, kẻ đến sau mạnh hơn; cuối cùng là Giáo Hoàng thân chinh */
const HUNT=()=>{if(!S.hunt||typeof S.hunt!=='object')S.hunt={lv:0,y:0,esc:0};return S.hunt};
const popeN=()=>{const rs=WD().rs['Thánh quốc Lumaris'];return rs?String(rs.ruler).replace(/^Giáo hoàng-vua\s*/,''):'Innocent'};
function hrEscape(t){const H=HUNT();H.lv++;H.esc++;H.y=S.year;return`${t} Bạn thoát được. Tòa Dị Giáo sẽ cử kẻ mạnh hơn.`}
function hrCaught(t){const H=HUNT();H.y=S.year;
  if(H.lv<=1){fine(R(20,40));mod({piety:-2});S.flags.suspect=(S.flags.suspect||0)+2;H.lv=Math.max(0,H.lv-1);return[`${t} Bạn bị bắt quả tang, phải nộp phạt và đọc kinh sám hối trước cả giáo xứ.`,'bad']}
  if(ch(.15+H.lv*.06)){die('bị thiêu trên giàn hỏa vì tội dị giáo');return[`${t} Tòa Dị Giáo kết án bạn. Giàn hỏa dựng giữa quảng trường.`,'bad']}
  const l=Math.floor(Math.max(S.money,0)/2);S.money-=l;mod({health:-R(15,25),happy:-10});H.lv=1;return[`${t} Bạn bị giam trong ngục tối của Tòa Dị Giáo hai năm, mất ${l} xu tiền chuộc. Khi được thả, cuộc săn lùng bắt đầu lại từ đầu.`,'bad']}
