/* trận với Giáo Hoàng: nhiều hiệp như trận Anh Hùng với Thảm Họa */
const POPEMV=['giáng Thánh Quang Phán Quyết xuống đầu bạn','dựng Kết Giới Mười Hai Thánh rồi ép nó lại','gọi Thiên Sứ Giáng Lâm, một luồng sáng xuyên qua vai bạn','đọc Lời Nguyền Trục Xuất, máu trăng đỏ trong người bạn sôi lên'];
const POPET=['phep','nguoi','giap'];
function popeHit(lo,hi){const d=Math.round(R(lo,hi)*talMul()*(1+((S.pf&&S.pf.round)||0)*.05));mod({health:-d});const m=pick(POPEMV);if(S.st.health<=0){die(`dưới tay Giáo Hoàng ${popeN()}`);return` Giáo Hoàng ${m}. Bạn gục xuống.`}return` Giáo Hoàng ${m}, bạn mất ${d} sức khỏe.`}
function popeWin(){const n=popeN();S.pf=null;const H=HUNT();H.done=1;H.lv=0;fac(-25,25);mod({honor:-5,magic:5});S.house.prestige+=150;S.flags.popeSlain=1;if(S.flags.her<3)S.flags.her=Math.min(3,(S.flags.her||0)+1);
  const rs=WD().rs['Thánh quốc Lumaris'];if(rs){rs.stab=Math.max(0,rs.stab-30);rs.ruler=`Giáo hoàng-vua ${pick(nameList('m','human'))}`}
  announce('Giáo Hoàng Tử Trận',`Giáo Hoàng ${n} ngã xuống trước ${S.first} ${S.surname}. Thánh Quân tan rã, mặt trăng đêm ấy đỏ như máu trên khắp các vương quốc.`,'night','redmoon');news(`Giáo Hoàng ${n} tử trận trước một thủ lĩnh Hồng Nguyệt. Thánh quốc Lumaris rơi vào hỗn loạn.`,'bad',true);
  return' Giáo Hoàng gục ngã. Thánh Quân vứt cờ bỏ chạy.'}
function popeRound(kind,id){const F=S.pf;F.round++;let p=.05+((S.blade||0)+S.st.magic)/600+cbB()/300+((S.flags.her||0)>=2?.05:0)+(F.bonus||0);F.bonus=0;let t='',lab='';
  if(kind==='mv'){const M=MV[id],lv=(S.mv[id]||{lv:1}).lv;let low=false;if(M.mp){if(S.st.magic>=M.mp)mod({magic:-M.mp});else low=true}if(M.hp)mod({health:-M.hp});if(M.pc)mod({piety:-M.pc});
    if(M.ty==='heal'||M.ty==='esc'){mvRead(F,id);if(M.ty==='heal'){const h=R(M.h[0],M.h[1]);mod({health:h});t=`Bạn dùng ${M.n}: ${M.x}, hồi ${h} sức khỏe.`}else t=`Bạn dùng ${M.n}: ${M.x}. Bạn lùi ra tìm sơ hở.`;F.bonus=.15;F.last='guard';mvXP(id,true);if(ch(.4))t+=popeHit(4,10);if(S.alive)S.pend.push('pope_fight');return[t,'']}
    p+=M.pw+(lv-1)*.04+mvTal(id)+mvMatch(id,POPET)-(low?.15:0);lab=`Bạn tung ${M.n}: ${M.x}.`;mvXP(id,true)}
  else if(kind==='blade'){p+=(S.blade||0)/400;lab='Lưỡi kiếm của bạn chém vào giáp thánh.'}
  else if(kind==='spell'){mod({magic:-8});p+=S.st.magic/500+.03;lab='Ngọn lửa trăng đỏ trong tay bạn xé toạc kết giới.'}
  else if(kind==='ud'){const u=udBest();p+=u.pw+SKX().rk*.03;lab=`${u.n} lao vào Giáo Hoàng.`;if(!ch(p)&&ch(.35)){UD().splice(UD().indexOf(u),1);lab+=` ${u.n} tan thành tro dưới thánh quang.`}}
  else if(kind==='call'){F.call=1;p+=.2;lab='Hàng trăm tín đồ đeo khăn đỏ từ bốn phía lao vào Thánh Quân.'}
  p=Math.max(.06,Math.min(.75,p));const rd=mvRead(F,kind==='mv'?id:kind);
  if(!rd&&ch(p)){F.hp=Math.max(0,F.hp-(kind==='mv'&&MV[id].ty==='ult'&&ch(.3)?2:1));F.last='hit';t=`${lab} Giáo Hoàng còn ${F.hp}/${F.max} sinh lực.`;if(F.hp<=0)return[lab+popeWin(),'good'];if(ch(.4))t+=popeHit(6,12)}
  else{F.last='miss';t=rd?`${lab} Nhưng Giáo Hoàng đã đọc được đòn này sau ${F.rep+1} lần bạn dùng liên tiếp, né sang bên rồi phản đòn.`:`${lab.replace(/\.$/,'')}, nhưng Giáo Hoàng gạt đi.`+popeHit(13,26)}
  if(S.alive&&S.pf)S.pend.push('pope_fight');return[t,F.last==='hit'?'good':'bad']}
HR_EV.push({id:'pope_fight',queued:true,big:true,art:'holy',img:'saint',c:s=>!!(s.alive&&s.pf),title:s=>`Giáo Hoàng ${popeN()} · Hiệp ${s.pf.round+1}`,
  text:s=>{const F=s.pf;return`${F.last==='miss'?'Bạn vừa trúng đòn và đang ở thế bất lợi. ':F.last==='hit'?'Bạn vừa giành được lợi thế. ':''}Giáo Hoàng: ${'■'.repeat(F.hp)+'□'.repeat(F.max-F.hp)} · Sức khỏe của bạn: ${s.st.health}/100 · Ma lực: ${s.st.magic}/100. Bạn làm gì tiếp theo?`},
  ch:[0,1,2,3].map(i=>({t:s=>cbLabel(s.mvL[i],POPET),hide:true,req:s=>!!(s.mvL&&s.mvL[i]&&MV[s.mvL[i]]&&s.mv[s.mvL[i]]),f:s=>popeRound('mv',s.mvL[i])})).concat([
   {t:'Tấn công bằng vũ khí',f:s=>popeRound('blade')},
   {t:'Thi triển phép trăng đỏ (−8 ma lực)',req:s=>s.st.magic>=8,f:s=>popeRound('spell')},
   {t:s=>{const u=udBest();return u?`Sai ${u.n} ra trận`:''},hide:true,req:s=>!!(isNc()&&udBest()),f:s=>popeRound('ud')},
   {t:'Gọi tín đồ Hồng Nguyệt xông lên',hide:true,req:s=>!s.pf.call&&((s.flags.her||0)>=2||!!s.cult),f:s=>popeRound('call')},
   {t:'Phòng thủ, chờ sơ hở',f:s=>{s.pf.bonus=.15;s.pf.last='guard';mod({health:4});let t='Bạn lùi lại, nhìn từng cử động của Giáo Hoàng.';if(ch(.4))t+=popeHit(3,8);if(s.alive)s.pend.push('pope_fight');return[t,'']}},
   {t:'Rút lui, bỏ trốn',f:s=>{s.pf=null;const H=HUNT();H.lv=4;H.y=s.year+2;mod({honor:-4});s.realm=pick(HUMAN_REALMS.filter(r=>r!=='Thánh quốc Lumaris'&&r!==s.realm));s.village=pick(VILL);return[`Bạn rút khỏi chiến trường, trốn sang ${s.realm}. Giáo Hoàng sẽ quay lại.`,'bad']}}])});
for(const e of HR_EV){EV.push(e);EVB[e.id]=e;if(e.img)EIMG[e.id]=e.img}
/* kết quả các trận săn lùng */
{const e0=cbEnd;cbEnd=function(res,t,low){const F=S.cb;if(F&&F.ctx==='hr'){S.cb=null;if(res==='win')S.cbw=(S.cbw||0)+1;if(low)t+=' (Ma lực cạn nên chiêu thức yếu đi.)';
    if(res==='win'||res==='esc')return[hrEscape(t+(res==='win'?` ${F.n} bị đánh lui.`:'')),'good'];const h=cbHurt(F);if(!S.alive)return[t+h,'bad'];const r=hrCaught(t+h);return r}
  return e0(res,t,low)}}
function hrYear(){if(!S.alive||S.age<14||!isRed(S)||(typeof rmOn==='function'&&rmOn()))return;const H=HUNT();if(H.done||S.year<H.y+1||S.pend.some(x=>x.startsWith('hr_')||x==='pope_fight'))return;
  if(ch(Math.min(.5,.18+(S.flags.suspect||0)*.03+H.lv*.04)))S.pend.push(H.lv>=5?'hr_pope':'hr_'+Math.min(4,H.lv))}
{const y0=extYear3;extYear3=function(){y0();try{hrYear()}catch(e){console.error(e)}}}
{const i0=inherit;inherit=function(id){const old=S;i0(id);if(S===old)return;S.hunt=old.hunt&&old.hunt.lv>=3&&isRed(S)?{lv:Math.max(1,old.hunt.lv-2),y:S.year,esc:0}:null;S.pf=null;save()}}
function v29Norm(s){if(s.hunt&&typeof s.hunt!=='object')s.hunt=null;if(s.pf&&(typeof s.pf!=='object'||typeof s.pf.hp!=='number'))s.pf=null}
