/* ---------- an toàn: sự kiện lỗi không được làm kẹt game ---------- */

/* ---------- V30: Kho đời (IndexedDB), tự lưu từng năm, màn hình chính ---------- */
const VDB={db:null,q:[],ok:true};
function vdbOpen(){return new Promise(res=>{if(VDB.db)return res(VDB.db);if(!VDB.ok||!window.indexedDB)return res(null);
  try{const r=indexedDB.open('doi-trung-co-kho',1);
    r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'id'});if(!d.objectStoreNames.contains('data'))d.createObjectStore('data');if(!d.objectStoreNames.contains('kv'))d.createObjectStore('kv')};
    r.onsuccess=()=>{VDB.db=r.result;res(VDB.db)};r.onerror=()=>{VDB.ok=false;res(null)};r.onblocked=()=>res(null)}catch(e){VDB.ok=false;res(null)}})}
function vdbTx(stores,mode,fn){return vdbOpen().then(d=>new Promise(res=>{if(!d)return res(null);try{const t=d.transaction(stores,mode);let out=null;const st=stores.map(s=>t.objectStore(s));Promise.resolve(fn(...st)).then(v=>out=v);t.oncomplete=()=>res(out);t.onerror=t.onabort=()=>res(null)}catch(e){res(null)}}))}
const vreq=r=>new Promise(res=>{r.onsuccess=()=>res(r.result);r.onerror=()=>res(null)});
function vMeta(s,kind,why){return{id:Date.now().toString(36)+uid(),t:Date.now(),lid:s.lid||'?',kind,why:why||'',name:(s.house&&s.house.title>=2?prefix():'')+s.name,first:s.first,gen:s.gen||1,age:s.age,year:s.year,house:s.house?s.house.name:'',alive:!!s.alive,race:s.race,sex:s.sex}}
const VKEEP={year:15,life:4,event:6,rescue:3};
function vSnap(kind,why,s){s=s||S;if(!s||!s.house)return Promise.resolve(null);if(!s.lid)s.lid=uid();
  let js;try{js=JSON.stringify(s)}catch(e){return Promise.resolve(null)}const m=vMeta(s,kind,why);
  return vdbTx(['meta','data'],'readwrite',(M,D)=>{M.put(m);D.put(js,m.id);return m.id}).then(id=>{if(id)vPrune(m.lid);return id})}
function vMetaAll(){return vdbTx(['meta'],'readonly',M=>vreq(M.getAll())).then(a=>(a||[]).sort((x,y)=>y.t-x.t))}
function vPrune(lid){return vMetaAll().then(all=>{const del=[];const mine=all.filter(m=>m.lid===lid);
  for(const k in VKEEP)mine.filter(m=>m.kind===k).slice(VKEEP[k]).forEach(m=>del.push(m.id));
  /* chỉ giữ 30 dòng tộc gần nhất */
  const lids=[...new Set(all.map(m=>m.lid))];if(lids.length>15)for(const l of lids.slice(15))all.filter(m=>m.lid===l).forEach(m=>del.push(m.id));
  if(del.length)return vdbTx(['meta','data'],'readwrite',(M,D)=>{for(const id of del){M.delete(id);D.delete(id)}})})}
function vData(id){return vdbTx(['data'],'readonly',D=>vreq(D.get(id))).then(js=>{if(!js)return null;try{return JSON.parse(js)}catch(e){return{__raw:js}}})}
function vDel(ids){return vdbTx(['meta','data'],'readwrite',(M,D)=>{for(const id of ids){M.delete(id);D.delete(id)}})}
function vKvPut(k,v){return vdbTx(['kv'],'readwrite',K=>{K.put(v,k)})}
function vKvGet(k){return vdbTx(['kv'],'readonly',K=>vreq(K.get(k)))}
/* bản chính: localStorage + bản dự phòng trong IndexedDB */
let vMainT=null;
function vMainNow(){clearTimeout(vMainT);vMainT=null;if(S&&S.house){try{vKvPut('main',JSON.stringify(S))}catch(e){}}}
{const s0=save;save=function(){s0();if(!S)return;if(!S.lid)S.lid=uid();clearTimeout(vMainT);vMainT=setTimeout(vMainNow,700)}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')vMainNow()});
window.addEventListener('pagehide',vMainNow);
