{const i0=inherit;inherit=function(id){const old=S,l=old&&old.lid;i0(id);if(S&&S!==old){S.lid=l||uid();save();vSnap('event',`đời thứ ${S.gen}: ${S.first} kế nghiệp`)}}}
{const n0=normalizeSave;normalizeSave=function(s){const r=n0(s);if(r&&typeof r==='object'&&!r.lid)r.lid=uid();return r}}
/* mỗi năm một bản trong Kho đời; qua đời và sự kiện lớn có bản riêng */
{const a0=ageUp;ageUp=function(){const y=S&&S.year;a0();if(!S||S.year===y)return;
  if(!S.alive)vSnap('event',`${S.first} qua đời`);else if(S.ann.length)vSnap('event',S.ann[0].title||`năm ${S.year}`);vSnap('year',`${S.age} tuổi`)}}
/* không bao giờ xóa đời: luôn cất vào Kho trước */
{const r0=restart;restart=function(){if(S){try{slotPut('auto',S)}catch(e){}vSnap('life','trước khi bắt đầu đời mới')}return r0()}}
