function tmCont(){closeModal();if(!S)return showTitle();render();if(!S.alive)showDeath();else if(S.ann.length||S.pend.length)showNext()}
function tmLoadObj(s,label){let m=null;try{m=migrate(JSON.parse(JSON.stringify(s)))}catch(e){console.error(e)}
  if(!m){TMS.msg={t:'Bản lưu này không đọc được.',tone:'bad'};return tmDraw()}
  if(S&&S.house&&S.lid!==m.lid)vSnap('life','trước khi tải bản khác');
  S=m;try{postLoad()}catch(e){console.error(e)}if(!S.lid)S.lid=uid();save();vMainNow();closeModal();render();log(`Cuộc đời được tải lại từ ${label}.`);render();
  if(!S.alive)showDeath();else if(S.ann.length||S.pend.length)showNext();toast('Đã mở '+label)}
function tmImport(){const inp=document.createElement('input');inp.type='file';inp.accept='.json,.txt,application/json,text/plain';inp.style.display='none';document.body.appendChild(inp);
  inp.onchange=()=>{const f=inp.files&&inp.files[0];inp.remove();if(!f)return;const rd=new FileReader();rd.onload=()=>{const s=svUnpack(String(rd.result));if(!s){TMS.msg={t:'Không đọc được file. Hãy chọn đúng file .json xuất từ Đời Trung Cổ.',tone:'bad'};return tmDraw()}tmLoadObj(s,'file')};rd.readAsText(f)};inp.click()}
function tmAct(a){if(!$('#sheet').hidden){$('#sheet').hidden=true;view=null;note=null}const i=a.indexOf(':'),k=i<0?a:a.slice(0,i),arg=i<0?'':a.slice(i+1);TMS.msg=null;
  if(k==='cont')return tmCont();
  if(k==='go'){TMS.v=arg;return tmDraw()}
  if(k==='home')return showTitle();
  if(k==='new'){if(S){TMS.v='newq';return tmDraw()}closeModal();draft=randDraft();return renderIntro()}
  if(k==='newgo'){closeModal();return restart()}
  if(k==='rec'){const o=TMS.idbMain;TMS.idbMain=null;if(o)return tmLoadObj(o,'bản dự phòng');return}
  if(k==='vault'){TMS.v='vault';tmRefresh();return tmDraw()}
  if(k==='life'){TMS.lid=arg;TMS.v='life';return tmDraw()}
  if(k==='pick'){TMS.pick=arg;TMS.v='pick';return tmDraw()}
  if(k==='open'){const m=(TMS.meta||[]).find(x=>x.id===arg);return vData(arg).then(s=>{if(!s||s.__raw){TMS.msg={t:'Bản lưu này bị hỏng, hãy chọn mốc khác.',tone:'bad'};return tmDraw()}tmLoadObj(s,m?`Kho đời (${m.first||m.name}, ${m.age} tuổi)`:'Kho đời')})}
  if(k==='dellife'){const ids=(TMS.meta||[]).filter(m=>m.lid===arg).map(m=>m.id);return vDel(ids).then(()=>{TMS.v='vault';return tmRefresh()}).then(tmDraw)}
  if(k==='slot'){const x=slotGet(arg);if(x)return tmLoadObj(x.S,slotLabel(arg).toLowerCase());return}
  if(k==='file'){TMS.v='file';return tmDraw()}
  if(k==='export'){note=null;return svExport().then(()=>{TMS.msg=note;note=null;tmDraw()})}
  if(k==='code'){TMS.v='code';return tmDraw()}
  if(k==='copy'){const tx=$('#svcode');if(!tx)return;tx.select();let ok=false;try{if(navigator.clipboard){navigator.clipboard.writeText(tx.value);ok=true}else ok=document.execCommand('copy')}catch(e){}TMS.msg={t:ok?'Đã sao chép mã lưu.':'Hãy giữ ngón tay lên ô mã để chọn và sao chép.',tone:ok?'good':''};return tmDraw()}
  if(k==='import')return tmImport();
  if(k==='paste'){TMS.v='paste';return tmDraw()}
  if(k==='readpaste'){const tx=$('#tmpaste');const s=svUnpack(tx&&tx.value);if(!s){TMS.msg={t:'Mã lưu không hợp lệ. Hãy dán đầy đủ, bắt đầu bằng DTC1:',tone:'bad'};const v=tx&&tx.value;tmDraw();const t2=$('#tmpaste');if(t2)t2.value=v||'';return}return tmLoadObj(s,'mã lưu')}
}
{const x0=extAct3;extAct3=function(x){if(x.startsWith('tm:'))return tmAct(x.slice(3));return x0(x)}}
