/* ---------- V31: luyện với giảng viên tăng năng lực thật; giữ bản lưu qua các lần cập nhật ---------- */
{const a0=acAct;acAct=function(k){if(k!=='sword'&&k!=='spell')return a0(k);talSync();const b0=S.blade||0,m0=S.st.magic,cl=S.ac&&S.ac.cls;
  const _as=afterSheetAction;let held=false;afterSheetAction=function(){held=true};try{a0(k)}finally{afterSheetAction=_as}
  const ok=note&&(note.tone==='good'||note.tone==='magic');
  if(ok&&k==='sword')bladeAdd(R(3,5)+(cl==='sword'||cl==='mix'||cl==='guard'?1:0));
  if(ok&&k==='spell')mod({magic:R(2,4)+(cl==='mage'||cl==='mix'?1:0)});
  talSync();const gb=(S.blade||0)-b0,gm=S.st.magic-m0;const ex=[gb>0?`Kiếm thuật +${gb}.`:'',gm>0?`Ma lực +${gm}.`:''].filter(Boolean).join(' ');
  if(ex&&note){note.t+=' '+ex;const it=S.log[S.log.length-1].items;if(it.length)it[it.length-1].t+=' '+ex}
  if(held)afterSheetAction()}}

