/* ---------- Kết nối chơi chung: máy chủ phòng là trình duyệt của người tạo phòng (PeerJS/WebRTC) ---------- */
const PEERJS_URL='https://unpkg.com/peerjs@1.5.4/dist/peerjs.min.js';
let peerLoad=null;
function loadPeer(){if(window.Peer)return Promise.resolve(true);if(peerLoad)return peerLoad;peerLoad=new Promise(res=>{const s=document.createElement('script');s.src=PEERJS_URL;s.async=true;s.onload=()=>res(!!window.Peer);s.onerror=()=>{peerLoad=null;res(false)};document.head.appendChild(s);setTimeout(()=>res(!!window.Peer),15000)});return peerLoad}
const peerId=code=>'dtc-coop-'+code.toLowerCase();
const hostKey=code=>`${KEY}-coophost-${code}`;
function netDb(N){
  const snap=(path,d)=>({id:path.split('/').pop(),exists:d!==undefined,data:()=>d,metadata:{fromCache:false,hasPendingWrites:false}});
  const docRef=path=>({id:path.split('/').pop(),path,
    get:async()=>snap(path,N.store[path]),
    set:d=>N.op({op:'set',path,data:d}),update:d=>N.op({op:'update',path,data:d}),delete:()=>N.op({op:'delete',path}),
    acquire:async()=>({acquired:!!N.host}),
    onSnapshot:next=>{const f=()=>next(snap(path,N.store[path]));N.subs.add(f);setTimeout(f,0);return()=>N.subs.delete(f)},
    collection:p=>coll(path+'/'+p)});
  const coll=(path,flt=[],ord=null,lim=0)=>{const n=path.split('/').length+1;
    const run=()=>{let L=Object.keys(N.store).filter(k=>k.startsWith(path+'/')&&k.split('/').length===n).map(k=>[k,N.store[k]]);
      for(const[f,,v]of flt)L=L.filter(x=>x[1][f]===v);if(ord)L.sort((a,b)=>((a[1][ord[0]]||0)-(b[1][ord[0]]||0))*(ord[1]==='desc'?-1:1));if(lim)L=L.slice(0,lim);
      const docs=L.map(([k,d])=>snap(k,d));return{docs,size:docs.length,empty:!docs.length,docChanges:()=>[],metadata:{fromCache:false}}};
    return{path,where:(f,o,v)=>coll(path,[...flt,[f,o,v]],ord,lim),orderBy:(f,d)=>coll(path,flt,[f,d||'asc'],lim),limit:x=>coll(path,flt,ord,x),
      get:async()=>run(),onSnapshot:next=>{const f=()=>next(run());N.subs.add(f);setTimeout(f,0);return()=>N.subs.delete(f)},
      doc:id=>docRef(path+'/'+(id||uid()+uid())),add:async d=>{const r=docRef(path+'/'+Date.now().toString(36)+uid());await r.set(d);return r}}};
  return{doc:docRef,collection:p=>coll(p)}}
function netMerge(a,b){for(const k in b){const v=b[k];if(v&&typeof v==='object'&&!Array.isArray(v)&&a[k]&&typeof a[k]==='object'&&!Array.isArray(a[k]))netMerge(a[k],v);else a[k]=v}}
/* chủ phòng */
function netHost(code,myUid){return new Promise(res=>{
  const N={host:true,code,store:{},subs:new Set(),conns:new Map(),online:()=>[myUid,...[...N.conns.values()].map(c=>c.uid).filter(Boolean)],onOnline:null,ok:true};
  try{N.store=JSON.parse(localStorage.getItem(hostKey(code))||'{}')}catch(e){N.store={}}
  let bt=null;const fire=()=>{for(const f of[...N.subs])try{f()}catch(e){console.error(e)}};
  const persist=()=>{try{localStorage.setItem(hostKey(code),JSON.stringify(N.store))}catch(e){}};
  const bcast=()=>{clearTimeout(bt);bt=setTimeout(()=>{const msg={t:'store',data:N.store,online:N.online()};for(const c of N.conns.keys())try{c.open&&c.send(msg)}catch(e){}},40)};
  const apply=o=>{const S0=N.store,p=o.path;
    if(o.op==='set')S0[p]=JSON.parse(JSON.stringify(o.data));
    else if(o.op==='update'){if(!S0[p])throw{code:'invalid_argument'};netMerge(S0[p],JSON.parse(JSON.stringify(o.data)))}
    else if(o.op==='delete')delete S0[p];
    if(/\/chat\//.test(p)){const base=p.slice(0,p.lastIndexOf('/'));const L=Object.keys(S0).filter(k=>k.startsWith(base+'/')).sort((a,b)=>(S0[b].t||0)-(S0[a].t||0));for(const k of L.slice(40))delete S0[k]}
    if(/\/tx\//.test(p)&&S0[p]&&S0[p].done)delete S0[p];
    persist();fire();bcast()};
  N.op=async o=>apply(o);
  N.onlineChanged=()=>{if(N.onOnline)N.onOnline(N.online());bcast()};
  N.close=()=>{N.ok=false;try{N.peer.destroy()}catch(e){}};
  let tries=0;const start=()=>{const P=new Peer(peerId(code),window.__peerOpts||{});N.peer=P;
    P.on('open',()=>{res(N)});
    P.on('connection',c=>{N.conns.set(c,{uid:null});
      c.on('data',m=>{if(!m||typeof m!=='object')return;
        if(m.t==='hello'){N.conns.get(c).uid=String(m.uid||'');c.send({t:'store',data:N.store,online:N.online()});N.onlineChanged();return}
        if(m.t==='op'){try{apply(m.o);c.send({t:'ack',id:m.id})}catch(e){c.send({t:'ack',id:m.id,err:(e&&e.code)||'error'})}}});
      c.on('close',()=>{N.conns.delete(c);N.onlineChanged()});c.on('error',()=>{N.conns.delete(c);N.onlineChanged()})});
    P.on('error',e=>{if(e&&e.type==='unavailable-id'&&tries++<8){try{P.destroy()}catch(x){}setTimeout(start,3000);return}if(!N.peer.open)res(null);console.error(e)});
    P.on('disconnected',()=>{if(N.ok)setTimeout(()=>{try{P.reconnect()}catch(e){}},2000)})};
  start();setTimeout(()=>res(null),30000)})}
/* người vào phòng */
function netJoin(code,myUid){return new Promise(res=>{
  const N={host:false,code,store:{},subs:new Set(),wait:new Map(),onOnline:null,onConn:null,connected:false,ok:true};
  const fire=()=>{for(const f of[...N.subs])try{f()}catch(e){console.error(e)}};
  let first=true,c=null;
  N.op=o=>new Promise((ok,bad)=>{if(!c||!c.open)return bad({code:'unavailable'});const id=uid()+uid();N.wait.set(id,[ok,bad]);c.send({t:'op',id,o});setTimeout(()=>{if(N.wait.has(id)){N.wait.delete(id);bad({code:'unavailable'})}},10000)});
  N.close=()=>{N.ok=false;try{N.peer.destroy()}catch(e){}};
  const P=new Peer(window.__peerOpts||{});N.peer=P;
  const link=()=>{if(!N.ok)return;c=P.connect(peerId(code),{reliable:true});
    c.on('open',()=>{c.send({t:'hello',uid:myUid})});
    c.on('data',m=>{if(!m||typeof m!=='object')return;
      if(m.t==='store'){N.store=m.data||{};if(!N.connected){N.connected=true;N.onConn&&N.onConn(true)}if(N.onOnline&&m.online)N.onOnline(m.online);fire();if(first){first=false;res(N)}}
      if(m.t==='ack'){const w=N.wait.get(m.id);if(w){N.wait.delete(m.id);m.err?w[1]({code:m.err}):w[0]()}}});
    c.on('close',()=>{if(N.connected){N.connected=false;N.onConn&&N.onConn(false)}if(N.ok)setTimeout(link,4000)});
    c.on('error',()=>{})};
  P.on('open',link);
  P.on('error',e=>{if(e&&e.type==='peer-unavailable'){if(first){first=false;N.close();res(null)}else if(N.ok)setTimeout(link,4000);return}console.error(e)});
  P.on('disconnected',()=>{if(N.ok)setTimeout(()=>{try{P.reconnect()}catch(e){}},2000)});
  setTimeout(()=>{if(first){first=false;N.close();res(null)}},20000)})}
/* ================= CHƠI CÙNG BẠN BÈ (thử nghiệm) =================
   Mỗi người giữ nhân vật của mình trong máy. Trình duyệt của người tạo phòng giữ dữ liệu phòng (năm thế giới, người chơi,
   trò chuyện, chuyển vàng, sự kiện chung) và nối thẳng với các máy khác qua PeerJS. Chủ phòng phải mở game thì phòng mới chạy. */
var COOP_BY=null;
const CO={code:null,uid:null,db:null,user:null,room:null,nr:null,rd:null,pl:{},online:null,chat:[],un:[],adv:0,q:Promise.resolve(),last:'',txq:[],txSeen:new Set(),msg:null,v:'home',ok:null};
const cpKey=c=>`${KEY}-coop-${c}`;
const CODECH='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const cpGen=()=>Array.from({length:5},()=>CODECH[Math.floor(Math.random()*CODECH.length)]).join('');
async function cpInit(){if(CO.ok)return true;try{CO.uid=localStorage.getItem(KEY+'-coop-uid');if(!CO.uid){CO.uid='p'+uid()+uid();localStorage.setItem(KEY+'-coop-uid',CO.uid)}}catch(e){CO.uid=CO.uid||'p'+uid()+uid()}
  CO.ok=await loadPeer();return CO.ok}
const cpIsHost=c=>{try{return localStorage.getItem(hostKey(c))!=null}catch(e){return false}};
async function cpConnect(code,asHost){if(CO.net&&CO.net.code===code&&CO.net.ok)return true;if(CO.net){CO.net.close();CO.net=null}
  CO.msg={t:asHost?'Đang mở phòng…':'Đang kết nối tới chủ phòng…',tone:''};cpDraw();
  const N=asHost?await netHost(code,CO.uid):await netJoin(code,CO.uid);
  if(!N){CO.msg={t:asHost?'Không mở được phòng. Kiểm tra mạng rồi thử lại.':`Không kết nối được phòng ${code}. Kiểm tra mã phòng, và nhờ chủ phòng mở game.`,tone:'bad'};return false}
  CO.net=N;CO.db=netDb(N);CO.msg=null;
  N.onOnline=ids=>{CO.online=new Set(ids);CO.online.add(CO.uid);render();cpCheck();cpPanelRefresh()};
  N.onConn=on=>{toast(on?'Đã kết nối lại với chủ phòng':'Mất kết nối với chủ phòng, đang thử lại…');render();cpPanelRefresh()};return true}
const cpRoom=c=>CO.db.doc('rooms/'+c);
const cpPl=c=>CO.db.collection('rooms/'+c+'/players');
const cpMe=()=>CO.pl[CO.uid];
function cpW(fn){CO.q=CO.q.then(fn).catch(e=>{console.error(e);if(e&&e.code==='unavailable'){toast('Chưa gửi được: đang mất kết nối với chủ phòng')}else if(e&&e.code==='invalid_argument'){CO.msg={t:'Thao tác bị từ chối.',tone:'bad'}}});return CO.q}
/* --- lưu riêng cho phòng, không đụng tới đời chơi đơn --- */
{const m0=vMainNow;vMainNow=function(){if(CO.code)return;return m0()}}
{const s0=save;save=function(){if(!CO.code)return s0();if(!S)return;try{localStorage.setItem(cpKey(CO.code),JSON.stringify(S));saveFailed=0}catch(e){saveFail()}cpPushSoon()}}
{const w0=wipe;wipe=function(){if(!CO.code)return w0();try{localStorage.removeItem(cpKey(CO.code))}catch(e){}}}
