{const l0=tmLoadObj;tmLoadObj=function(s,label){if(CO.code){TMS.msg={t:'Hãy rời phòng chơi chung trước khi mở bản lưu khác.',tone:'bad'};return tmDraw()}return l0(s,label)}}
/* --- đồng bộ thông tin nhân vật lên phòng --- */
let cpT=null;function cpPushSoon(){clearTimeout(cpT);cpT=setTimeout(cpPush,1200)}
function cpSnap(){const s=S;return{uid:CO.uid,name:s.name,first:s.first,house:s.house.name,gen:s.gen||1,age:s.age,year:s.year,by:s.by,race:s.race,sex:s.sex,money:Math.round(s.money),health:Math.round(s.st.health),alive:!!s.alive,job:s.job?jt():(s.kn?knTitle():''),rdy:CO.myRdy||0,t:0}}
function cpPush(){if(!CO.code||!S||!S.house||!CO.db)return;if(CO.rd&&CO.rd.away&&CO.rd.away[CO.uid]){CO.rd.away[CO.uid]=false;const c=CO.code;cpW(()=>cpRoom(c).update({away:{[CO.uid]:false}}))}const d=cpSnap();const k=JSON.stringify(d);if(k===CO.last)return;CO.last=k;d.t=Date.now();return cpW(()=>cpPl(CO.code).doc(CO.uid).set(d))}
/* --- năm chung --- */
function cpNeed(){const aw=(CO.rd&&CO.rd.away)||{};return Object.values(CO.pl).filter(p=>p.alive&&p.house&&(p.uid===CO.uid||(!aw[p.uid]&&(!CO.online||CO.online.has(p.uid)))))}
function cpWaiting(){const y=CO.rd&&CO.rd.year;return cpNeed().filter(p=>!(p.rdy>=y&&p.year>=y))}
function cpReady(){if(!S||!S.alive||S.pend.length||S.ann.length||!CO.rd)return;if(S.year<CO.rd.year)return;CO.myRdy=CO.rd.year;CO.last='';cpPush();render();cpCheck()}
function cpCheck(){const R0=CO.rd;if(!R0||!CO.code)return;const need=cpNeed();if(!need.length||cpWaiting().length)return;if(CO.net&&CO.net.host)cpAdvance(R0.year)}
let cpAdv=0;async function cpAdvance(y){if(cpAdv===y)return;cpAdv=y;try{const ref=cpRoom(CO.code);const L=await ref.acquire({holder:CO.uid,ttlMs:5000});if(!L.acquired)return;const g=await ref.get();if(!g.exists||g.data().year!==y)return;
  const up={year:y+1};if(Math.random()<.35)up.wev={[y+1]:pick(Object.keys(COW))};await ref.update(up)}catch(e){console.error(e);cpAdv=0}}
/* chạy năm cho nhân vật khi phòng đã sang năm (từng năm một, kể cả khi bạn vắng mặt nhiều năm) */
