  CO.un.push(cpPl(code).onSnapshot(q=>{CO.pl={};q.docs.forEach(d=>{CO.pl[d.id]=d.data()});render();cpCheck();cpPanelRefresh()},e=>console.error(e)));
  CO.un.push(CO.db.collection('rooms/'+code+'/chat').orderBy('t','desc').limit(30).onSnapshot(q=>{CO.chat=q.docs.map(d=>d.data()).reverse();cpPanelRefresh()},e=>console.error(e)));
