/* ---------- V37: Cận Vệ sa ngã bị trục xuất; Phố đèn đỏ; bệnh phong tình; con rơi ---------- */
function knFall(){if(S&&S.kn&&S.kn.t==='orth'&&S.flags&&(S.flags.dark||S.flags.hcat)){const t=knTitle();S.kn=null;mod({honor:-10});log(`Giáo hội Chính Giáo tước danh hiệu ${t} và trục xuất bạn khỏi dòng hiệp sĩ. Lệnh truy nã được dán trước mọi nhà thờ.`,'bad')}}
{const s0=save;save=function(){try{knFall()}catch(e){}return s0()}}
const VD={lau:{n:'bệnh lậu',cure:.6,hp:[2,5]},giang:{n:'bệnh giang mai',cure:.3,hp:[3,8]},sui:{n:'bệnh sùi mào gà',cure:.45,hp:[1,3]}};
function vdYear(){const V=S.vd;if(!V||!VD[V.k])return;const D=VD[V.k];mod({health:-R(D.hp[0],D.hp[1]),happy:-R(1,3)});if(V.k==='sui')mod({looks:-R(1,3)});
  if(V.k==='giang'&&S.year-V.y>=5&&ch(.05)){die('bệnh giang mai giai đoạn cuối');return}
  if(ch(.3))log(V.k==='giang'?'Những vết lở trên người bạn lan rộng. Thầy lang lắc đầu khi nhìn thấy chúng.':V.k==='lau'?'Mỗi lần đi tiểu là một lần bạn nghiến răng vì rát buốt.':'Những nốt sùi lại mọc thêm. Bạn ngại cả đi nhà tắm hơi.','bad')}
{const d0=deathRoll;deathRoll=function(){if(S.alive)vdYear();if(S.alive)d0()}}
{const B=ACTS.find(a=>a.id==='barber'),f0=B.f;B.f=s=>{const[t,tone]=arr(f0(s));if(!s.vd||!VD[s.vd.k])return[t,tone];const D=VD[s.vd.k];
  if(ch(D.cure)){s.vd=null;return[`${t} Thầy lang bôi thuốc thủy ngân và bắt bạn kiêng khem suốt mùa đông. Bạn đã khỏi ${D.n}.`,'good']}return[`${t} Thầy lang chưa chữa được ${D.n} của bạn. Năm sau hãy thử lại.`,'bad']}}
/* con rơi: không tính là con chính thức, không có quyền thừa kế */
function rlBastard(mother){const sx=pick(['m','f']);const k=person('Con rơi',sx,0,pick(SUR.serf),pick([S.race,'human']));k.bast=1;k.mom=mother;k.bond=R(10,35);S.fam.push(k);return k}
const rlWho=()=>S.sex==='m'?'cô':'anh';
function spLeave(sp){const old=sp.rel;sp.rel=old+' cũ';mod({happy:-15,honor:-5});log(`${old} ${sp.first} thu dọn đồ đạc và bỏ đi. Cuộc hôn nhân của bạn đã chấm dứt.`,'bad');return` ${sp.first} thu dọn đồ đạc và bỏ đi.`}
function rlSus(p,why){const sp=spouse();if(sp&&ch(p)&&!S.pend.includes('rl_caught')){S.rlC=why;S.pend.push('rl_caught')}}
function rlNight(g){S.money-=40;S.rlx={...g,adj:pick(['nồng thắm','ướt át','say đắm','cuồng nhiệt'])};S.rlN=(S.rlN||0)+1;S.rlLast=S.year;S.rlFav={...g};S.pend.push('rl_after');
  return`${rlWho()[0].toUpperCase()+rlWho().slice(1)} ${g.n} nắm tay dắt bạn lên lầu.`}
function rlConseq(stay){const g=S.rlx||{n:'?',lk:50,sk:50};let t='',tone='good';
  mod({happy:Math.round((g.lk+g.sk)/20)+R(0,4)+(stay?3:0),piety:-3});
  if(ch(.1-g.sk/2000)&&!S.vd){const k=pick(['lau','lau','giang','sui']);S.vd={k,y:S.year};S.pend.push('rl_sick')}
  if(ch(.04)){const c=rlBastard(g.n);mod({honor:-4});t+=S.sex==='m'?` Một năm sau, ${g.n} bế đến trước cửa nhà bạn một đứa bé tên ${c.first}, nói đó là con của bạn.`:` Vài tháng sau, bạn biết mình có mang. ${c.first} chào đời, không ai biết cha là ai.`;t+=' Đứa bé được ghi vào mục Con rơi trong Quan hệ.';tone=''}
  rlSus(stay?.25:.12,stay?'late':'perfume');return[t,tone]}
