/* ủy thác Hẻm Vực Than xuất hiện với thợ săn Hiệp hội, cách nhau ít nhất 2 năm */
{const y0=extYear3;extYear3=function(){y0();kkYear();}}
{const b0=hnBoard;hnBoard=function(){const B=b0(),H=HN();if(H.kkY!==S.year){H.kkY=S.year;if(S.alive&&!S.kk&&S.age>=16&&!(S.kkJob&&S.year-S.kkJob<2)&&ch(.3))B.push('kk')}return B}}
{const g0=rgAct;rgAct=function(a,k,i){const r=g0(a,k,i);if(a==='go'&&S.kk&&S.done.rgv===k&&!S.kk.vis.includes(k))S.kk.vis.push(k);return r}}
{const d0=drawExt3;drawExt3=function(v){if(v==='kk')return kkView();return d0(v)}}
{const x0=extAct3;extAct3=function(x){if(x.startsWith('kk:')){const[,k,id]=x.split(':');return kkAct(k,id)}return x0(x)}}
{const a0=actExtra3;actExtra3=function(){const b=a0();if(!S.kk)return b;const T=S.kk,h=T.rk===0||T.rk<5&&T.st.h;
  return'<p class="sec">Class ẩn</p>'+gRow('data-open="kk"','night',T.rk?KKRK[T.rk-1]:'Đáy vực có bầu trời',`Bậc ${T.rk}/5 · Dư Âm ${T.da}${h?` · ${kkQLeft()}/2 lượt ${T.rk?'theo lời gợi ý':'dưới đáy vực'}`:''}`,'',!S.alive)+b}}
/* Bước Lệch: né đòn chí mạng, Dư Âm càng cao càng khó */
{const d0=die;die=function(cause){const T=S&&S.kk;if(S&&S.alive&&T&&T.rk>=1&&T.da<80&&/trận|giao tranh|chiến|phục kích|tên|giáo|rìu|kiếm|chém|móng|nanh|quái|ám sát|bẫy|ngã/.test(cause||'')&&ch(.3)){T.da=Math.min(100,T.da+20);S.st.health=Math.max(S.st.health,15);log(`Đòn ấy lẽ ra đã giết bạn ${cause}. Bạn bước lệch qua một khe hở trong khoảnh khắc và thoát ra. Dư Âm Khư Không dâng lên.`,'magic');return}return d0(cause)}}
{const n0=normalizeSave;normalizeSave=function(s){const r=n0(s);if(r&&typeof r==='object'&&r.kk!=null){const T=r.kk;
  if(typeof T!=='object'||Array.isArray(T))r.kk=null;else{T.rk=Math.max(0,Math.min(5,Math.floor(+T.rk)||0));T.res=Math.max(0,Math.min(100,+T.res||0));T.da=Math.max(0,Math.min(100,+T.da||0));
    if(!T.st||typeof T.st!=='object')T.st={};if(!Array.isArray(T.ord))T.ord=[];if(!Array.isArray(T.vis))T.vis=[];if(!KKS[T.sc]||!(r.pend||[]).includes('kk_sc'))T.sc=null}}return r}}

/* ---------- Chuỗi: Người Không Còn Tên Trong Sổ (bị bắt cóc, bị giam, đấu trường) ---------- */
const CAPL={cho:{n:'chợ bán người ở cảng Greyhaven',who:'gã buôn người Skarr',exit:'',time:'',dest:''},
  dien:{n:'điền trang Vết Tro',who:'lãnh chúa Corvane',boss:'bà quản gia Hesk',exit:'Bức tường đá phía vườn táo có một chỗ sụt, che bằng bụi gai.',ex2:'chỗ tường sụt ở vườn táo',time:'Xe tiếp tế tới vào đêm rằm; cổng sau mở lâu nhất lúc dỡ hàng.'},
  quan:{n:'quán trọ Ngựa Xám',who:'chủ quán Odo',boss:'bà bếp Marl',exit:'Cửa hầm rượu thông ra bờ sông, khóa bằng một then gỗ mục.',ex2:'cửa hầm rượu ra bờ sông',time:'Đêm chợ phiên, quán đông tới mức không ai đếm người làm.'},
  phu:{n:'phủ nhà Ellery',who:'phu nhân Ellery',boss:'lão quản gia Dunstan',exit:'Lối của người đổ bô dẫn ra ngõ sau, chỉ khóa vào ban ngày.',ex2:'lối đổ bô ra ngõ sau',time:'Mỗi khi nhà nguyện đổ chuông, sân sau không còn ai gác.'},
  arena:{n:'đoàn đấu trường Hố Cát',who:'ông bầu Varro',boss:'người canh phòng chờ'}};
const CAPBUY={dien:'Bà quản gia của một điền trang lớn: nhiều đất, nhiều lối ra, nhưng gác rất nghiêm.',quan:'Chủ một quán trọ bên sông: khách lạ ra vào suốt ngày.',phu:'Lão quản gia của một nhà quý tộc: bà chủ nổi tiếng hay mềm lòng.'};
const capLoc=()=>CAPL[S.cap.loc];
const capJ=t=>{const C=S.cap;if(!C.j.includes(t))C.j.push(t)};
const capCl=(k,t)=>{S.cap.cl[k]=1;if(t)capJ(t)};
const capNext=sc=>{S.cap.sc=sc;S.pend.push('cap_sc')};
const capEnd=()=>{const C=S.cap;if(!C)return;if(C.q&&C.q.length){C.sc=C.q.shift();S.pend.push('cap_sc')}else C.sc=null};
const capQLeft=()=>Math.max(0,2-(S.done.capq||0));
const capYrs=()=>S.year-S.cap.y0;
function capStart(){
  const C=S.cap={y0:S.year,loc:'cho',job:S.job||null,bag:S.bag||[],eq:S.eq||null,cl:{},j:[],tr:30,al:0,q:['buy'],sc:null,fl:{},ar:{f:0}};
  S.job=null;S.bag=[];S.eq=null;
  if(S.age<12&&(S.fam||[]).some(p=>p.alive&&/Cha|Mẹ/.test(p.rel)))C.fl.search=1;
  capJ('Bạn bị bắt cóc trên đường về. Trong sổ hàng hóa của cỗ xe, tên bạn bị thay bằng một con số.');
  return C;
}
function capFree(how,t){
  const C=S.cap;const yrs=capYrs();
  const allB=[...(C.bag||[]),...(S.bag||[])];S.bag=allB.slice(0,BAGMAX);if(allB.length>BAGMAX)log(`Túi đầy, bạn phải bỏ lại ${allB.length-BAGMAX} món: ${allB.slice(BAGMAX).map(x=>ITEMS[x.k]?ITEMS[x.k].n:'?').join(', ')}.`,'bad');if(C.eq)S.eq=C.eq;
  if(C.job&&JOBS[C.job.id]&&(!JOBS[C.job.id].races||JOBS[C.job.id].races.includes(S.race))&&S.age>=JOBS[C.job.id].min)S.job=C.job;
  if(!S.capHist)S.capHist=[];S.capHist.push({y0:C.y0,y1:S.year,yrs,how,loc:C.loc,ar:C.ar.f});
  S.cap=null;mod({happy:15});
  log(`Bạn được tự do sau ${yrs} năm bị giam.${S.job?' Bạn quay lại với nghề cũ.':' Bạn có thể xin việc làm mới.'} Những món đồ bị tịch thu được trả lại.`,'good');
  return[t,'good'];
}
