  for(const id of['sword','spell']){const a=ACTS.find(x=>x.id===id);if(!a)continue;const why=S.age<a.min?`Từ ${a.min} tuổi`:a.req&&!a.req(S)?a.why:S.done[id]?'Đã làm năm nay':'';b+=gRow(`data-act="${id}"`,id==='sword'?'w-sword':'wand',a.n,why||a.d,'',!S.alive||!!why)}
  if(C.bag&&C.bag.length)b+='<p class="sec">Đồ bị tịch thu</p><p class="note">'+C.bag.map(i=>ITEMS[i.k]?ITEMS[i.k].n:'').filter(Boolean).join(', ')+'. Sẽ được trả lại khi bạn tự do.</p>';
  return['Bị giam',b,'act'];
