const mtCan=()=>S&&S.alive&&!S.cap&&!clsHas(S)&&S.age>=16&&S.job&&S.job.id==='bard'&&S.st.smarts>=40&&!(S.mtRun&&S.year-S.mtRun<3)&&!S.pend.includes('mt_call');
