  if(n<=5){const [sm,res]=MTREQ[n];b+=`<p class="note">Bậc kế: ${MTRK[n-1]}. Cần Trí tuệ ${sm} (hiện ${S.st.smarts}) và Vang âm ${res}. Đủ điều kiện sẽ nhận lời gợi ý vào năm sau; bạn vẫn phải giải câu chuyện để lên bậc.</p>`;
    if(T.st.h){b+=`<p class="sec">Lời gợi ý</p><p class="note">“${MTHINT[n]}”</p>`;for(const[id,icon,nm,d]of mtQRows())b+=gRow(`data-x="mt:q:${id}"`,icon,nm,S.done.mtTrial?'Năm nay đã thử rồi':d,'',dis||!mtQLeft()||!!S.done.mtTrial)}}
