{const n0=normalizeSave;normalizeSave=function(s){const r=n0(s);if(!r||typeof r!=='object')return r;
  if(!Array.isArray(r.clDuelSeen))r.clDuelSeen=[];r.clDuelSeen=r.clDuelSeen.filter(k=>CD_CLASSES[k]);
  if(r.clDuel){const D=r.clDuel;if(typeof D!=='object'||!CD_CLASSES[D.k]||!r.alive)r.clDuel=null;
    else{D.rk=Math.max(1,Math.min(5,Math.floor(+D.rk)||1));D.max=Math.max(20,Math.min(90,+D.max||32));D.hp=Math.max(1,Math.min(D.max,+D.hp||D.max));D.round=Math.max(0,Math.floor(+D.round)||0);D.prep=Math.max(0,Math.min(2,+D.prep||0));D.name=CD_CLASSES[D.k][0];
      if(!(r.pend||[]).some(id=>id==='cd_call'||id==='cd_fight'))r.pend=(r.pend||[]).concat('cd_fight')}}return r}}

