hqReg('mem');

/* Lời mời đặc biệt cho Người Buôn Ký Ức — chỉ kích hoạt khi đủ điều kiện */
HC.mem.call='Bạn nhặt được một viên pha lê trên mộ một người lạ. Bên trong có một đốm sáng đang chuyển động chậm như khói. Khi bạn chạm vào, bạn nghe thấy tiếng của một người đã chết.';

/* Đăng ký pop-up event mở khóa riêng của nghề mới (thay thế hc_call chung cho mem) */
Object.assign(EVB,{
  hc_call_mem:{
    id:'hc_call_mem', queued:true, big:true, art:'crystal-ball', img:'ghost',
    c:s=>!!(s.alive&&!s.cap&&!clsOther(s,'mem')&&!s.hc&&!s.hq?.mem&&s.age>=16&&s.job&&HC.mem.jobs.includes(s.job.id)&&s.job.yr>=3&&(s.st.smarts>=40||s.flags.literate)),
    title:'Giọt Nước Mắt Của Người Chết',
    text:'Bạn tìm thấy bên cạnh một ngôi mộ mới một viên pha lê nhỏ, bên trong có một đốm sáng đang chuyển động chậm như khói. Đêm ấy, bạn mơ thấy một người đàn bà lạ mặt nói: "Con tôi chết trẻ. Tôi không còn nhớ mặt nó nữa. Ngài có ký ức nào về nó không?"',
    ch:[
      {t:'Đi tìm người buôn ký ức',f:s=>{hqStart('mem','act');
        return['Bạn bắt đầu hành trình "Người Buôn Ký Ức". Mục tiêu nằm trong phần Hành Trình Bí Ẩn (Hoạt động).','magic']}},
      {t:'Ghi nhớ, để sau',f:s=>{hqStart('mem','known');return'Bạn cất viên pha lê vào rương. Nhưng bí mật không chờ ai mãi.'}},
      {t:'Vứt viên pha lê đi',f:s=>{if(!s.hcNo)s.hcNo={};s.hcNo.mem=1;return'Bạn vứt viên pha lê xuống sông. Đêm ấy bạn ngủ ngon, lần đầu sau nhiều tuần.'}}
    ]
  }
});
EV.push(EVB.hc_call_mem); EIMG.hc_call_mem='ghost';

{const h0=hcYear; hcYear=function(){
  h0();
  if(S&&!S.cap&&!clsOther(S,'mem')&&!S.hc&&S.job&&HC.mem.jobs.includes(S.job.id)&&S.job.yr>=3&&!(S.hq?.mem)&&S.alive
     &&!S.pend.includes('hc_call')&&!S.pend.includes('hc_call_mem')
     &&(S.st.smarts>=40||S.flags.literate)&&ch(.1)){
    S.pend.push('hc_call_mem');
  }
}}

